    static int
calc_percentage(long part, long whole)
{
    return (part > 1000000L)
        ? (int)(part / (whole / 100L))
        : (int)((part * 100L) / whole);
}

    static int
read_buffer(int         read_stdin, exarg_T     *eap, int         flags)
{
    int         retval = OK;
    linenr_T    line_count;

    line_count = curbuf->b_ml.ml_line_count;
    retval = readfile(read_stdin ? NULL : curbuf->b_ffname, read_stdin ? NULL : curbuf->b_fname, line_count, (linenr_T)0, (linenr_T) LONG_MAX , eap, flags | READ_BUFFER);
    if (retval == OK)
    {
        while (--line_count >= 0)
        {
            ml_delete((linenr_T)1);
        }
    }
    else
    {
        while (curbuf->b_ml.ml_line_count > line_count)
        {
            ml_delete(line_count);
        }
    }
    curwin->w_cursor.lnum = 1;
    curwin->w_cursor.col = 0;

    if (read_stdin)
    {
        if (!readonlymode && ! (curbuf->b_ml.ml_line_count == 1 && *ml_get((linenr_T)1) == NUL) )
        {
            changed();
        }
        else if (retval == OK)
        {
            unchanged(curbuf, FALSE, TRUE);
        }

        if (retval == OK)
        {
        }
    }
    return retval;
}

    static int
open_buffer(int         read_stdin, exarg_T     *eap, int         flags_arg)
{
    int         flags = flags_arg;
    int         retval = OK;
    bufref_T    old_curbuf;
    int         read_fifo = FALSE;

    if (readonlymode && curbuf->b_ffname != NULL && (curbuf->b_flags & BF_NEVERLOADED))
    {
        curbuf->b_p_ro = TRUE;
    }

    if (ml_open(curbuf) == FAIL)
    {
        close_buffer(curwin, curbuf, 0, FALSE, FALSE, FALSE);
        emsg(_(e_cannot_allocate_any_buffer_exiting));

        v_dying = 2;
        getout(2);
    }

    if (curbuf->b_ml.ml_mfp != NULL)
    {
        curbuf->b_ml.ml_mfp->mf_dirty = MF_DIRTY_YES_NOSYNC;
    }

    set_bufref(&old_curbuf, curbuf);
    curbuf->b_modified_was_set = false;

    curwin->w_valid = 0;

    if (curbuf->b_ffname != NULL)
    {
        int old_msg_silent = msg_silent;
        int perm;
        perm = mch_getperm(curbuf->b_ffname);
        if (perm >= 0 && (S_ISFIFO(perm) || S_ISSOCK(perm)))
        {
                read_fifo = TRUE;
        }
        if (shortmess(SHM_FILEINFO))
        {
            msg_silent = 1;
        }
        retval = readfile(curbuf->b_ffname, curbuf->b_fname, (linenr_T)0, (linenr_T)0, (linenr_T) LONG_MAX , eap, flags | READ_NEW | (read_fifo ? READ_FIFO : 0));
        if (read_fifo)
        {
            if (retval == OK)
            {
                retval = read_buffer(FALSE, eap, flags);
            }
        }
        msg_silent = old_msg_silent;
        if (bt_help(curbuf))
        {
            fix_help_buffer();
        }
    }
    else if (read_stdin)
    {
        retval = readfile(NULL, NULL, (linenr_T)0, (linenr_T)0, (linenr_T) LONG_MAX , NULL, flags | (READ_NEW + READ_STDIN));
        if (retval == OK)
        {
            retval = read_buffer(TRUE, eap, flags);
        }
    }

    if (curbuf->b_ml.ml_mfp != NULL && curbuf->b_ml.ml_mfp->mf_dirty == MF_DIRTY_YES_NOSYNC)
    {
        curbuf->b_ml.ml_mfp->mf_dirty = MF_DIRTY_YES;
    }

    if (curbuf->b_flags & BF_NEVERLOADED)
    {
        (void)buf_init_chartab(curbuf, FALSE);
    }

    if ((got_int && vim_strchr(p_cpo, CPO_INTMOD) != NULL) || curbuf->b_modified_was_set)
    {
        changed();
    }
    else if (retval == OK && !read_stdin && !read_fifo)
    {
        unchanged(curbuf, FALSE, TRUE);
    }

    curbuf->b_last_changedtick =  ((curbuf)->b_ct_di.di_tv.vval.v_number) ;
    curbuf->b_last_changedtick_i =  ((curbuf)->b_ct_di.di_tv.vval.v_number) ;
    curbuf->b_last_changedtick_pum =  ((curbuf)->b_ct_di.di_tv.vval.v_number) ;

    if (got_int)
    {
        curbuf->b_flags |= BF_READERR;
    }

    if (!(curwin->w_valid & VALID_TOPLINE))
    {
        curwin->w_topline = 1;
    }

    if (retval != OK)
    {
        return retval;
    }

    if (bufref_valid(&old_curbuf) && old_curbuf.br_buf->b_ml.ml_mfp != NULL)
    {
        curbuf->b_flags &= ~(BF_CHECK_RO | BF_NEVERLOADED);
    }

    return retval;
}

    static void
set_bufref(bufref_T *bufref, buf_T *buf)
{
    bufref->br_buf = buf;
    bufref->br_fnum = buf == NULL ? 0 : buf->b_fnum;
    bufref->br_buf_free_count = buf_free_count;
}

    static int
bufref_valid(bufref_T *bufref)
{
    return bufref->br_buf_free_count == buf_free_count
        ? TRUE : buf_valid(bufref->br_buf)
                                  && bufref->br_fnum == bufref->br_buf->b_fnum;
}

    static int
buf_valid(buf_T *buf)
{
    return buf == curbuf;
}

static hashtab_T buf_hashtab;

    static void
buf_hashtab_add(buf_T *buf)
{
    vim_snprintf((char *)buf->b_key, sizeof(buf->b_key), "%x", buf->b_fnum);
    if (hash_add(&buf_hashtab, buf->b_key, "create buffer") == FAIL)
    {
        emsg(_(e_buffer_cannot_be_registered));
    }
}

    static void
buf_hashtab_remove(buf_T *buf)
{
    hashitem_T *hi = hash_find(&buf_hashtab, buf->b_key);

    if (! ((hi)->hi_key == NULL || (hi)->hi_key == &hash_removed) )
    {
        hash_remove(&buf_hashtab, hi, "close buffer");
    }
}

    static int
can_unload_buffer(buf_T *buf)
{
    int     can_unload = !buf->b_locked;

    if (can_unload && updating_screen)
    {

        if (curwin->w_buffer == buf)
        {
            can_unload = FALSE;
        }
    }
    if (can_unload && buf->b_saving)
    {
        can_unload = FALSE;
    }

    if (!can_unload)
    {
        char_u *fname = buf->b_fname != NULL ? buf->b_fname : buf->b_ffname;

        semsg(_(e_attempt_to_delete_buffer_that_is_in_use_str), fname != NULL ? fname : (char_u *)"[No Name]");
    }
    return can_unload;
}

    static int
close_buffer(win_T       *win, buf_T       *buf, int         action, int         abort_if_last, int         ignore_abort, int         set_context)
{
    int         hiding_buf;
    bufref_T    bufref;
    int         unload_buf = (action != 0);
    int         wipe_buf = (action == DOBUF_WIPE || action == DOBUF_WIPE_REUSE);
    int         del_buf = (action == DOBUF_DEL || wipe_buf);
    int         win_valid = win_valid_any_tab(win);
    int         closed_popup = win && !win_valid &&  0 ;

    if ((del_buf || wipe_buf) && !can_unload_buffer(buf))
    {
        return FALSE;
    }

    if (set_context && win_valid && win->w_buffer == buf)
    {
        if (buf->b_nwindows == 1)
        {
            set_last_cursor(win);
        }
        buflist_setfpos(buf, win, win->w_cursor.lnum == 1 ? 0 : win->w_cursor.lnum, win->w_cursor.col, TRUE);
    }

    set_bufref(&bufref, buf);

    if ((win_valid || closed_popup) && win->w_buffer == buf && buf->b_nwindows == 1)
    {
        if (abort_if_last)
        {
            emsg(_(e_autocommands_caused_command_to_abort));
            return FALSE;
        }
        win_valid = win_valid && win_valid_any_tab(win);
    }

    hiding_buf = buf->b_nwindows <= 0 || ((win_valid || closed_popup) && win->w_buffer == buf && buf->b_nwindows == 1);

    if (!hiding_buf || !unload_buf)
    {
        return FALSE;
    }

    if (buf->b_ffname == NULL)
    {
        del_buf = TRUE;
    }

    if (!buf_freeall(buf, (del_buf ? BFA_DEL : 0) + (wipe_buf ? BFA_WIPE : 0) + (ignore_abort ? BFA_IGNORE_ABORT : 0)))
    {
        return FALSE;
    }

    win_valid = win_valid && win_valid_any_tab(win);
    if ((win_valid || closed_popup) && win->w_buffer == buf)
    {
        --buf->b_nwindows;
        win->w_buffer = NULL;
    }

    if (del_buf)
    {
        free_buffer_stuff(buf, TRUE);

        buf->b_flags = BF_CHECK_RO | BF_NEVERLOADED;

        buf->b_p_initialized = false;
    }
    buf_clear_file(buf);

    return TRUE;
}

    static void
buf_clear_file(buf_T *buf)
{
    buf->b_ml.ml_line_count = 1;
    unchanged(buf, TRUE, TRUE);
    buf->b_shortname = false;
    buf->b_ml.ml_mfp = NULL;
    buf->b_ml.ml_flags = ML_EMPTY;
}

    static int
buf_freeall(buf_T *buf, int flags)
{
    int         is_curbuf = (buf == curbuf);
    bufref_T    bufref;

    ++buf->b_locked;
    ++buf->b_locked_split;
    set_bufref(&bufref, buf);
    if (buf->b_ml.ml_mfp != NULL)
    {
    }
    if (flags & BFA_WIPE)
    {
    }
    --buf->b_locked;
    --buf->b_locked_split;

    if (buf == curbuf && !is_curbuf)
    {
        return FALSE;
    }

    if (buf == curbuf && VIsual_active)
    {
        end_visual_mode();
    }

    ml_close(buf, TRUE);
    buf->b_ml.ml_line_count = 0;
    if ((flags & BFA_KEEP_UNDO) == 0)
    {
        u_clearallandblockfree(buf);
    }
    buf->b_flags &= ~BF_READERR;
    return TRUE;
}

    static void
free_buffer(buf_T *buf)
{
    ++buf_free_count;
    free_buffer_stuff(buf, TRUE);

    buf_hashtab_remove(buf);

    vim_free(buf);
    if (curbuf == buf)
    {
        curbuf = NULL;
    }
}

    static void
init_changedtick(buf_T *buf)
{
    dictitem_T *di = (dictitem_T *)&buf->b_ct_di;

    di->di_flags = DI_FLAGS_FIX | DI_FLAGS_RO;
    di->di_tv.v_type = VAR_NUMBER;
    di->di_tv.v_lock = VAR_FIXED;
    di->di_tv.vval.v_number = 0;

}

    static void
clear_wininfo(buf_T *buf)
{
    wininfo_T   *wip;

    while (buf->b_wininfo != NULL)
    {
        wip = buf->b_wininfo;
        buf->b_wininfo = wip->wi_next;
        free_wininfo(wip);
    }
}

    static void
free_buffer_stuff(buf_T       *buf, int         free_options)
{
    if (free_options)
    {
        clear_wininfo(buf);
        free_buf_options(buf, TRUE);
    }
    map_clear_mode(buf, MAP_ALL_MODES, TRUE, FALSE);
    map_clear_mode(buf, MAP_ALL_MODES, TRUE, TRUE);
}

    static void
free_wininfo(wininfo_T *wip)
{
    if (wip->wi_optset)
    {
        clear_winopt(&wip->wi_opt);
    }
    vim_free(wip);
}

    static void
set_curbuf(buf_T *buf, int action)
{
    buf_T       *prevbuf;
    int         unload = (action == DOBUF_UNLOAD || action == DOBUF_DEL || action == DOBUF_WIPE || action == DOBUF_WIPE_REUSE);
    bufref_T    newbufref;
    bufref_T    prevbufref;

    setpcmark();

    VIsual_reselect = FALSE;

    prevbuf = curbuf;
    set_bufref(&prevbufref, prevbuf);
    set_bufref(&newbufref, buf);

    if (bufref_valid(&prevbufref))
    {
        if (prevbuf == curbuf && ((State & MODE_INSERT) == 0 || curbuf->b_nwindows <= 1))
        {
            u_sync(FALSE);
        }
        close_buffer(curwin, prevbuf, unload ? action : (action == DOBUF_GOTO && !bufIsChanged(prevbuf)) ? DOBUF_UNLOAD : 0, FALSE, FALSE, TRUE);
    }
    if (curwin->w_buffer == NULL)
    {
        enter_buffer(buf);
    }
}

    static void
enter_buffer(buf_T *buf)
{
    if (VIsual_active)
    {
        end_visual_mode();
    }

    if (curwin->w_buffer != NULL)
    {
        --curwin->w_buffer->b_nwindows;
    }

    curwin->w_buffer = buf;
    curbuf = buf;
    ++curbuf->b_nwindows;

    buf_copy_options(buf, BCO_ENTER | BCO_NOHELP);
    if (!buf->b_help)
    {
        get_winopts(buf);
    }

    curwin->w_cursor.lnum = 1;
    curwin->w_cursor.col = 0;
    curwin->w_cursor.coladd = 0;
    curwin->w_set_curswant = true;
    curwin->w_topline_was_set = false;

    curwin->w_valid = 0;

    if (curbuf->b_ml.ml_mfp == NULL)
    {
        open_buffer(FALSE, NULL, 0);
    }
    else
    {
        if (!msg_silent && !shortmess(SHM_FILEINFO))
        {
            need_fileinfo = TRUE;
        }

        curwin->w_topline = 1;
    }

    if (curwin->w_cursor.lnum == 1 && inindent(0))
    {
        buflist_getfpos();
    }

    if (curwin->w_topline == 1 && !curwin->w_topline_was_set)
    {
        scroll_cursor_halfway(FALSE, FALSE);
    }

    redraw_later(UPD_NOT_VALID);
}

    static void
no_write_message(void)
{
        emsg(_(e_no_write_since_last_change_add_bang_to_override));
}

    static void
no_write_message_nobang(buf_T *buf  __attribute__((unused)) )
{
        emsg(_(e_no_write_since_last_change));
}

    static int
curbuf_reusable(void)
{
    return (curbuf != NULL && curbuf->b_ffname == NULL && curbuf->b_nwindows <= 1 && (curbuf->b_ml.ml_mfp == NULL ||  (curbuf->b_ml.ml_line_count == 1 && *ml_get((linenr_T)1) == NUL) ) && !curbufIsChanged());
}

    static buf_T *
buflist_new(char_u      *ffname_arg, char_u      *sfname_arg, linenr_T    lnum, int         flags)
{
    char_u      *ffname = ffname_arg;
    char_u      *sfname = sfname_arg;
    buf_T       *buf;
    stat_T      st;

    if (top_file_num == 1)
    {
        hash_init(&buf_hashtab);
    }

    fname_expand(curbuf, &ffname, &sfname);

    if (sfname == NULL ||  stat(((char *)sfname), (&st))  < 0)
    {
        st.st_dev = ( dev_t )-1;
    }
    if (ffname != NULL && !(flags & (BLN_DUMMY | BLN_NEW)) && (buf = buflist_findname_stat(ffname, &st)) != NULL)
    {
        vim_free(ffname);
        if (lnum != 0)
        {
            buflist_setfpos(buf, (flags & BLN_NOCURWIN) ? NULL : curwin, lnum, (colnr_T)0, FALSE);
        }

        if ((flags & BLN_NOOPT) == 0)
        {
            buf_copy_options(buf, 0);
        }

        return buf;
    }

    buf = NULL;
    if ((flags & BLN_CURBUF) && curbuf_reusable())
    {
        bufref_T bufref;

        buf = curbuf;
        set_bufref(&bufref, buf);
        buf_freeall(buf, BFA_WIPE | BFA_DEL);
        if (!bufref_valid(&bufref))
        {
            buf = NULL;
        }
    }
    if (buf != curbuf || curbuf == NULL)
    {
        buf =  (buf_T *)alloc_clear(sizeof(buf_T)) ;
        if (buf == NULL)
        {
            vim_free(ffname);
            return NULL;
        }
        init_changedtick(buf);
    }

    if (ffname != NULL)
    {
        buf->b_ffname = ffname;
        buf->b_sfname = vim_strsave(sfname);
    }

    clear_wininfo(buf);
    buf->b_wininfo =  (wininfo_T *)alloc_clear(sizeof(wininfo_T)) ;

    if ((ffname != NULL && (buf->b_ffname == NULL || buf->b_sfname == NULL)) || buf->b_wininfo == NULL)
    {
        if (buf->b_sfname != buf->b_ffname)
        {
             vim_free(buf->b_sfname);
             (buf->b_sfname) = NULL;
        }
        else
        {
            buf->b_sfname = NULL;
        }
         vim_free(buf->b_ffname);
         (buf->b_ffname) = NULL;
        if (buf != curbuf)
        {
            free_buffer(buf);
        }
        return NULL;
    }

    if (buf == curbuf)
    {
        free_buffer_stuff(buf, FALSE);

        buf->b_p_initialized = false;
        buf_copy_options(buf, BCO_ENTER);

    }
    else
    {
        buf->b_fnum = top_file_num++;
        if (top_file_num < 0)
        {
            emsg(_("W14: Warning: List of file names overflow"));
            if (emsg_silent == 0 && !in_assert_fails)
            {
                out_flush();
                ui_delay(3001L, TRUE);
            }
            top_file_num = 1;
        }
        buf_hashtab_add(buf);

        buf_copy_options(buf, BCO_ALWAYS);
    }

    buf->b_wininfo->wi_fpos.lnum = lnum;
    buf->b_wininfo->wi_win = curwin;

    buf->b_fname = buf->b_sfname;
    if (st.st_dev == ( dev_t )-1)
    {
        buf->b_dev_valid = false;
    }
    else
    {
        buf->b_dev_valid = true;
        buf->b_dev = st.st_dev;
        buf->b_ino = st.st_ino;
    }
    buf->b_u_synced = true;
    buf->b_flags = BF_CHECK_RO | BF_NEVERLOADED;
    if (flags & BLN_DUMMY)
    {
        buf->b_flags |= BF_DUMMY;
    }
    buf_clear_file(buf);
    clrallmarks(buf);
    if (!(flags & BLN_DUMMY))
    {
        bufref_T bufref;

        set_bufref(&bufref, buf);
    }

    return buf;
}

    static void
free_buf_options(buf_T       *buf, int         free_p_ff)
{
    if (free_p_ff)
    {
    }
    clear_string_option(&buf->b_p_mps);
    clear_string_option(&buf->b_p_isk);
    clear_string_option(&buf->b_p_nf);
    clear_string_option(&buf->b_p_qe);
    buf->b_p_fs = -1;
    buf->b_p_ul =  (-123456) ;
}

    static void
buflist_getfpos(void)
{
    pos_T       *fpos;

    fpos = buflist_findfpos(curbuf);

    curwin->w_cursor.lnum = fpos->lnum;
    check_cursor_lnum();

    if (p_sol)
    {
        curwin->w_cursor.col = 0;
    }
    else
    {
        curwin->w_cursor.col = fpos->col;
        check_cursor_col();
        curwin->w_cursor.coladd = 0;
        curwin->w_set_curswant = true;
    }
}

    static buf_T *
buflist_findname_stat(char_u      *ffname, stat_T      *stp)
{
    if ((curbuf->b_flags & BF_DUMMY) == 0 && !otherfile_buf(curbuf, ffname, stp))
    {
        return curbuf;
    }
    return NULL;
}

    static buf_T *
buflist_findnr(int nr)
{
    char_u      key[VIM_SIZEOF_INT * 2 + 1];
    hashitem_T  *hi;

    vim_snprintf((char *)key, sizeof(key), "%x", nr);
    hi = hash_find(&buf_hashtab, key);

    if (! ((hi)->hi_key == NULL || (hi)->hi_key == &hash_removed) )
    {
        return (buf_T *)(hi->hi_key - ((unsigned)(curbuf->b_key - (char_u *)curbuf)));
    }
    return NULL;
}

    static void
buflist_setfpos(buf_T       *buf, win_T       *win, linenr_T    lnum, colnr_T     col, int         copy_options)
{
    wininfo_T   *wip;

     for ((wip) = (buf)->b_wininfo; (wip) != NULL; (wip) = (wip)->wi_next) 
     {
        if (wip->wi_win == win)
        {
            break;
        }
     }
    if (wip == NULL)
    {
        wip =  (wininfo_T *)alloc_clear(sizeof(wininfo_T)) ;
        if (wip == NULL)
        {
            return;
        }
        wip->wi_win = win;
        if (lnum == 0)
        {
            lnum = 1;
        }
    }
    else
    {
        if (wip->wi_prev)
        {
            wip->wi_prev->wi_next = wip->wi_next;
        }
        else
        {
            buf->b_wininfo = wip->wi_next;
        }
        if (wip->wi_next)
        {
            wip->wi_next->wi_prev = wip->wi_prev;
        }
        if (copy_options && wip->wi_optset)
        {
            clear_winopt(&wip->wi_opt);
        }
    }
    if (lnum != 0)
    {
        wip->wi_fpos.lnum = lnum;
        wip->wi_fpos.col = col;
    }
    if (win != NULL)
    {
        wip->wi_changelistidx = win->w_changelistidx;
    }
    if (copy_options && win != NULL)
    {
        copy_winopt(&win->w_onebuf_opt, &wip->wi_opt);
        wip->wi_optset = TRUE;
    }

    wip->wi_next = buf->b_wininfo;
    buf->b_wininfo = wip;
    wip->wi_prev = NULL;
    if (wip->wi_next)
    {
        wip->wi_next->wi_prev = wip;
    }
}

    static wininfo_T *
find_wininfo(buf_T       *buf, int         need_options, int         skip_diff_buffer  __attribute__((unused)) )
{
    wininfo_T   *wip;

     for ((wip) = (buf)->b_wininfo; (wip) != NULL; (wip) = (wip)->wi_next) 
     {
        if (wip->wi_win == curwin && (!need_options || wip->wi_optset))
        {
            break;
        }
     }

    if (wip != NULL)
    {
        return wip;
    }

        wip = buf->b_wininfo;
    return wip;
}

    static void
get_winopts(buf_T *buf)
{
    wininfo_T   *wip;

    clear_winopt(&curwin->w_onebuf_opt);

    wip = find_wininfo(buf, TRUE, TRUE);
    if (wip != NULL && wip->wi_win != NULL && wip->wi_win != curwin && wip->wi_win->w_buffer == buf)
    {
        win_T *wp = wip->wi_win;

        copy_winopt(&wp->w_onebuf_opt, &curwin->w_onebuf_opt);
    }
    else if (wip != NULL && wip->wi_optset)
    {
        copy_winopt(&wip->wi_opt, &curwin->w_onebuf_opt);
    }
    else
    {
        copy_winopt(&curwin->w_allbuf_opt, &curwin->w_onebuf_opt);
    }
    if (wip != NULL)
    {
        curwin->w_changelistidx = wip->wi_changelistidx;
    }

    after_copy_winopt(curwin);
}

    static pos_T *
buflist_findfpos(buf_T *buf)
{
    wininfo_T   *wip;
    static pos_T no_position = {1, 0, 0};

    wip = find_wininfo(buf, FALSE, FALSE);
    if (wip != NULL)
    {
        return &(wip->wi_fpos);
    }
    else
    {
        return &no_position;
    }
}

    static linenr_T
buflist_findlnum(buf_T *buf)
{
    return buflist_findfpos(buf)->lnum;
}

    static int
buflist_name_nr(int         fnum, char_u      **fname, linenr_T    *lnum)
{
    buf_T       *buf;

    buf = buflist_findnr(fnum);
    if (buf == NULL || buf->b_fname == NULL)
    {
        return FAIL;
    }

    *fname = buf->b_fname;
    *lnum = buflist_findlnum(buf);

    return OK;
}

    static int
setfname(buf_T       *buf, char_u      *ffname_arg, char_u      *sfname_arg, int         message)
{
    char_u      *ffname = ffname_arg;
    char_u      *sfname = sfname_arg;
    buf_T       *obuf = NULL;
    stat_T      st;

    if (ffname == NULL || *ffname == NUL)
    {
        if (buf->b_sfname != buf->b_ffname)
        {
             vim_free(buf->b_sfname);
             (buf->b_sfname) = NULL;
        }
        else
        {
            buf->b_sfname = NULL;
        }
         vim_free(buf->b_ffname);
         (buf->b_ffname) = NULL;
        st.st_dev = ( dev_t )-1;
    }
    else
    {
        fname_expand(buf, &ffname, &sfname);
        if (ffname == NULL)
        {
            return FAIL;
        }

        if ( stat(((char *)ffname), (&st))  < 0)
        {
            st.st_dev = ( dev_t )-1;
        }
        if (!(buf->b_flags & BF_DUMMY))
        {
            obuf = buflist_findname_stat(ffname, &st);
        }
        if (obuf != NULL && obuf != buf)
        {
            win_T       *win;
            int         in_use = FALSE;

             win = curwin;
        if (win->w_buffer == obuf)
        {
            in_use = TRUE;
        }

            if (obuf->b_ml.ml_mfp != NULL || in_use)
            {
                if (message)
                {
                    emsg(_(e_buffer_with_this_name_already_exists));
                }
                vim_free(ffname);
                return FAIL;
            }
            close_buffer(NULL, obuf, DOBUF_WIPE, FALSE, FALSE, FALSE);
        }
        sfname = vim_strsave(sfname);
        if (ffname == NULL || sfname == NULL)
        {
            vim_free(sfname);
            vim_free(ffname);
            return FAIL;
        }
        if (buf->b_sfname != buf->b_ffname)
        {
            vim_free(buf->b_sfname);
        }
        vim_free(buf->b_ffname);
        buf->b_ffname = ffname;
        buf->b_sfname = sfname;
    }
    buf->b_fname = buf->b_sfname;
    if (st.st_dev == ( dev_t )-1)
    {
        buf->b_dev_valid = false;
    }
    else
    {
        buf->b_dev_valid = true;
        buf->b_dev = st.st_dev;
        buf->b_ino = st.st_ino;
    }

    buf->b_shortname = false;

    buf_name_changed(buf);
    return OK;
}

    static void
buf_name_changed(buf_T *buf)
{
    if (buf->b_ml.ml_mfp != NULL)
    {
    }

    if (curwin->w_buffer == buf)
    {
    }
    status_redraw_all();
    ml_timestamp(buf);
}

    static char_u  *
getaltfname(int         errmsg)
{
    char_u      *fname;
    linenr_T    dummy;

    if (buflist_name_nr(0, &fname, &dummy) == FAIL)
    {
        if (errmsg)
        {
            emsg(_(e_no_alternate_file));
        }
        return NULL;
    }
    return fname;
}

    static int
buflist_add(char_u *fname, int flags)
{
    buf_T       *buf;

    buf = buflist_new(fname, NULL, (linenr_T)0, flags);
    if (buf != NULL)
    {
        return buf->b_fnum;
    }
    return 0;
}

    static int
otherfile(char_u *ffname)
{
    return otherfile_buf(curbuf, ffname, NULL);
}

    static int
otherfile_buf(buf_T               *buf, char_u              *ffname, stat_T            *stp)
{
    if (ffname == NULL || *ffname == NUL || buf->b_ffname == NULL)
    {
        return TRUE;
    }
    if ( vim_fnamecmp((char_u *)(ffname), (char_u *)(buf->b_ffname))  == 0)
    {
        return FALSE;
    }
    {
        stat_T      st;

        if (stp == NULL)
        {
            if (!buf->b_dev_valid ||  stat(((char *)ffname), (&st))  < 0)
            {
                st.st_dev = ( dev_t )-1;
            }
            stp = &st;
        }
        if (buf_same_ino(buf, stp))
        {
            buf_setino(buf);
            if (buf_same_ino(buf, stp))
            {
                return FALSE;
            }
        }
    }
    return TRUE;
}

    static void
buf_setino(buf_T *buf)
{
    stat_T      st;

    if (buf->b_fname != NULL &&  stat(((char *)buf->b_fname), (&st))  >= 0)
    {
        buf->b_dev_valid = true;
        buf->b_dev = st.st_dev;
        buf->b_ino = st.st_ino;
    }
    else
    {
        buf->b_dev_valid = false;
    }
}

    static int
buf_same_ino(buf_T       *buf, stat_T      *stp)
{
    return (buf->b_dev_valid && stp->st_dev == buf->b_dev && stp->st_ino == buf->b_ino);
}

    static void
fileinfo(int fullname, int shorthelp, int dont_truncate)
{
    char_u      *name;
    char        *buffer;
    size_t      bufferlen = 0;

    buffer = alloc( (1024+1) );
    if (buffer == NULL)
    {
        return;
    }

    if (fullname > 1)
    {
        bufferlen = vim_snprintf_safelen(buffer,  (1024+1) , "buf %d: ", curbuf->b_fnum);
    }

    buffer[bufferlen++] = '"';

    name = buf_spname(curbuf);
    if (name != NULL)
    {
        bufferlen += vim_snprintf_safelen(buffer + bufferlen,  (1024+1)  - bufferlen, "%s", name);
    }
    else
    {
        if (!fullname && curbuf->b_fname != NULL)
        {
            name = curbuf->b_fname;
        }
        else
        {
            name = curbuf->b_ffname;
        }
        bufferlen += home_replace(shorthelp ? curbuf : NULL, name, (char_u *)buffer + bufferlen,  (1024+1)  - (int)bufferlen, TRUE);
    }

    bufferlen += vim_snprintf_safelen(buffer + bufferlen,  (1024+1)  - bufferlen, "\"%s%s%s%s%s%s", curbufIsChanged() ? (shortmess(SHM_MOD) ?  " [+]" : _(" [Modified]")) : " ", (curbuf->b_flags & BF_NOTEDITED) ? _("[Not edited]") : "", (curbuf->b_flags & BF_NEW) ? new_file_message() : "", (curbuf->b_flags & BF_READERR) ? _("[Read errors]") : "", curbuf->b_p_ro ? (shortmess(SHM_RO) ? _("[RO]") : _("[readonly]")) : "", (curbufIsChanged() || (curbuf->b_flags &  (BF_NOTEDITED + BF_NEW + BF_READERR) ) || curbuf->b_p_ro) ? " " : "");

    if (curbuf->b_ml.ml_flags & ML_EMPTY)
    {
        bufferlen += vim_snprintf_safelen(buffer + bufferlen,  (1024+1)  - bufferlen, "%s", _((char *)no_lines_msg));
    }
    else if (p_ru)
    {
        bufferlen += vim_snprintf_safelen(buffer + bufferlen,  (1024+1)  - bufferlen, NGETTEXT("%ld line --%d%%--", "%ld lines --%d%%--", curbuf->b_ml.ml_line_count), (long)curbuf->b_ml.ml_line_count, calc_percentage(curwin->w_cursor.lnum, curbuf->b_ml.ml_line_count));
    }
    else
    {
        bufferlen += vim_snprintf_safelen(buffer + bufferlen,  (1024+1)  - bufferlen, _("line %ld of %ld --%d%%-- col "), (long)curwin->w_cursor.lnum, (long)curbuf->b_ml.ml_line_count, calc_percentage(curwin->w_cursor.lnum, curbuf->b_ml.ml_line_count));

        validate_virtcol();
        bufferlen += col_print((char_u *)buffer + bufferlen,  (1024+1)  - bufferlen, (int)curwin->w_cursor.col + 1, (int)curwin->w_virtcol + 1);
    }

    if (dont_truncate)
    {
        int     n;

        msg_start();
        n = msg_scroll;
        msg_scroll = TRUE;
        msg(buffer);
        msg_scroll = n;
    }
    else
    {
        char    *p = msg_trunc_attr(buffer, FALSE, 0);
        if (restart_edit != 0 || (msg_scrolled && !need_wait_return))
        {
            set_keep_msg((char_u *)p, 0);
        }
    }

    vim_free(buffer);
}

    static int
col_print(char_u  *buf, size_t  buflen, int     col, int     vcol)
{
    if (col == vcol)
    {
        return (int)vim_snprintf_safelen((char *)buf, buflen, "%d", col);
    }

    return (int)vim_snprintf_safelen((char *)buf, buflen, "%d-%d", col, vcol);
}

    static int
get_rel_pos(win_T       *wp, char_u      *buf, int         buflen)
{
    long        above;
    long        below;

    if (buflen < 3)
    {
        return 0;
    }
    above = wp->w_topline - 1;
    below = wp->w_buffer->b_ml.ml_line_count - wp->w_botline + 1;
    if (below <= 0)
    {
        return (int)vim_snprintf_safelen((char *)buf, buflen, "%s", (above == 0) ? _("All") : _("Bot"));
    }

    if (above <= 0)
    {
        return (int)vim_snprintf_safelen((char *)buf, buflen, "%s", _("Top"));
    }

    int perc = calc_percentage(above, above + below);
    char tmp[8];
    vim_snprintf(tmp, sizeof(tmp), _("%d%%"), perc);
    return (int)vim_snprintf_safelen((char *)buf, buflen, _("%3s"), tmp);
}

    static char_u  *
fix_fname(char_u  *fname)
{
    return FullName_save(fname, TRUE);
}

    static void
fname_expand(buf_T       *buf  __attribute__((unused)) , char_u      **ffname, char_u      **sfname)
{
    if (*ffname == NULL)
    {
        return;
    }
    if (*sfname == NULL)
    {
        *sfname = *ffname;
    }
    *ffname = fix_fname(*ffname);

}

enum { VIM_VERSION_MAJOR = 9 };
enum { VIM_VERSION_MINOR = 2 };
static const char VIM_VERSION_DATE_ONLY[] = "2026 Feb 14";

static const char VIM_VERSION_SHORT[] = {'0' + VIM_VERSION_MAJOR, '.', '0' + VIM_VERSION_MINOR, NUL};
static const char VIM_VERSION_LONG_ONLY[] = {'V', 'I', 'M', ' ', '-', ' ', 'V', 'i', ' ', 'I', 'M', 'p', 'r', 'o', 'v', 'e', 'd', ' ', '0' + VIM_VERSION_MAJOR, '.', '0' + VIM_VERSION_MINOR, NUL};

    static int
bt_help(buf_T *buf)
{
    return buf != NULL && buf->b_help;
}

    static char_u *
buf_spname(buf_T *buf)
{
    if (buf->b_fname == NULL)
    {
        return buf_get_fname(buf);
    }
    return NULL;
}

    static char_u *
buf_get_fname(buf_T *buf)
{
    if (buf->b_fname == NULL)
    {
        return (char_u *)_("[No Name]");
    }
    return buf->b_fname;
}

enum { SMALLBUFSIZE = 256 };

struct bw_info
{
    int         bw_fd;
    char_u      *bw_buf;
    int         bw_len;
    int         bw_flags;
    int         bw_restlen;
    int         bw_conv_error;
    linenr_T    bw_conv_error_lnum;
    linenr_T    bw_start_lnum;
    iconv_t     bw_iconv_fd;
};

    static int
buf_write_bytes(struct bw_info *ip)
{
    int         wlen;
    char_u      *buf = ip->bw_buf;
    int         len = ip->bw_len;

    if (ip->bw_fd < 0)
    {
        return OK;
    }

    wlen = write_eintr(ip->bw_fd, buf, len);
    return (wlen < len) ? FAIL : OK;
}

    static int
check_mtime(buf_T *buf, stat_T *st)
{
    if (buf->b_mtime_read != 0 && time_differs(st, buf->b_mtime_read, buf->b_mtime_read_ns))
    {
        msg_scroll = TRUE;
        msg_silent = 0;
        msg_attr(_("WARNING: The file has been changed since reading it!!!"),  highlight_attr[(int)(HLF_E)] );
        if (ask_yesno((char_u *)_("Do you really want to write to it"), TRUE) == 'n')
        {
            return FAIL;
        }
        msg_scroll = FALSE;
    }
    return OK;
}

    static char *
new_file_message(void)
{
    return shortmess(SHM_NEW) ? _("[New]") : _("[New File]");
}

    static int
buf_write(buf_T           *buf, char_u          *fname, char_u          *sfname, linenr_T        start, linenr_T        end, exarg_T         *eap, int             append, int             forceit, int             reset_changed, int             filtering)
{
    int             fd;
    char_u          *ffname;
    char_u          *wfname = NULL;
    char_u          *s;
    char_u          *ptr;
    char_u          c;
    int             len;
    linenr_T        lnum;
    long            nchars;
    char_u          *errmsg = NULL;
    int             errmsg_allocated = FALSE;
    char_u          *errnum = NULL;
    char_u          *buffer;
    char_u          smallbuf[SMALLBUFSIZE];
    int             bufsize;
    long            perm;
    int             retval = OK;
    int             newfile = FALSE;
    int             msg_save = msg_scroll;
    int             overwriting;
    int             no_eol = FALSE;
    int             device = FALSE;
    stat_T          st_old;
    int             prev_got_int = got_int;
    int             checking_conversion;
    int             file_readonly = FALSE;
    int             made_writable = FALSE;
    int             whole = (start == 1 && end == buf->b_ml.ml_line_count);
    linenr_T        old_line_count = buf->b_ml.ml_line_count;
    int             attr;
    struct bw_info  write_info;
    int             wb_flags = 0;
    pos_T           orig_start = buf->b_op_start;
    pos_T           orig_end = buf->b_op_end;

    if (fname == NULL || *fname == NUL)
    {
        return FAIL;
    }
    if (buf->b_ml.ml_mfp == NULL)
    {
        emsg(_(e_empty_buffer));
        return FAIL;
    }

    if (check_secure())
    {
        return FAIL;
    }

    if ( strlen((char *)(fname))  >=  PATH_MAX )
    {
        emsg(_(e_name_too_long));
        return FAIL;
    }

    write_info.bw_conv_error = FALSE;
    write_info.bw_conv_error_lnum = 0;
    write_info.bw_restlen = 0;
    write_info.bw_iconv_fd = (iconv_t)-1;

    ex_no_reprint = TRUE;

    if (buf->b_ffname == NULL && reset_changed && whole && buf == curbuf && !filtering && (!append || vim_strchr(p_cpo, CPO_FNAMEAPP) != NULL) && vim_strchr(p_cpo, CPO_FNAMEW) != NULL)
    {
        if (set_rw_fname(fname, sfname) == FAIL)
        {
            return FAIL;
        }
        buf = curbuf;
    }

    if (sfname == NULL)
    {
        sfname = fname;
    }
    ffname = fname;
    fname = sfname;

    if (buf->b_ffname != NULL &&  vim_fnamecmp((char_u *)(ffname), (char_u *)(buf->b_ffname))  == 0)
    {
        overwriting = TRUE;
    }
    else
    {
        overwriting = FALSE;
    }

    if (exiting)
    {
        settmode(TMODE_COOK);
    }

    ++no_wait_return;

    buf->b_op_start.lnum = start;
    buf->b_op_start.col = 0;
    buf->b_op_end.lnum = end;
    buf->b_op_end.col = 0;

    {
        int             buf_ffname = FALSE;
        int             buf_sfname = FALSE;
        int             buf_fname_f = FALSE;
        int             buf_fname_s = FALSE;
        int             empty_memline = (buf->b_ml.ml_mfp == NULL);

        if (ffname == buf->b_ffname)
        {
            buf_ffname = TRUE;
        }
        if (sfname == buf->b_sfname)
        {
            buf_sfname = TRUE;
        }
        if (fname == buf->b_ffname)
        {
            buf_fname_f = TRUE;
        }
        if (fname == buf->b_sfname)
        {
            buf_fname_s = TRUE;
        }

        if (buf == NULL || (buf->b_ml.ml_mfp == NULL && !empty_memline))
        {
            if (buf != NULL && (cmdmod.cmod_flags & CMOD_LOCKMARKS))
            {
                buf->b_op_start = orig_start;
                buf->b_op_end = orig_end;
            }

            --no_wait_return;
            msg_scroll = msg_save;

                emsg(_(e_autocommands_deleted_or_unloaded_buffer_to_be_written));
            return FAIL;
        }

        if (buf->b_ml.ml_line_count != old_line_count)
        {
            if (whole)
            {
                end = buf->b_ml.ml_line_count;
            }
            else if (buf->b_ml.ml_line_count > old_line_count)
            {
                end += buf->b_ml.ml_line_count - old_line_count;
            }
            else
            {
                end -= old_line_count - buf->b_ml.ml_line_count;
                if (end < start)
                {
                    --no_wait_return;
                    msg_scroll = msg_save;
                    emsg(_(e_autocommands_changed_number_of_lines_in_unexpected_way));
                    return FAIL;
                }
            }
        }

        if (buf_ffname)
        {
            ffname = buf->b_ffname;
        }
        if (buf_sfname)
        {
            sfname = buf->b_sfname;
        }
        if (buf_fname_f)
        {
            fname = buf->b_ffname;
        }
        if (buf_fname_s)
        {
            fname = buf->b_sfname;
        }
    }

    if (cmdmod.cmod_flags & CMOD_LOCKMARKS)
    {
        buf->b_op_start = orig_start;
        buf->b_op_end = orig_end;
    }

    if (shortmess(SHM_OVER) && !exiting)
    {
        msg_scroll = FALSE;
    }
    else
    {
        msg_scroll = TRUE;
    }
    if (!filtering)
    {
        filemess(buf, fname, (char_u *)"", 0);
    }
    msg_scroll = FALSE;

    buffer = alloc(WRITEBUFSIZE);
    if (buffer == NULL)
    {
        buffer = smallbuf;
        bufsize = SMALLBUFSIZE;
    }
    else
    {
        bufsize = WRITEBUFSIZE;
    }

    st_old.st_dev = 0;
    st_old.st_ino = 0;
    perm = -1;
    if ( stat(((char *)fname), (&st_old))  < 0)
    {
        newfile = TRUE;
    }
    else
    {
        perm = st_old.st_mode;
        if (!S_ISREG(st_old.st_mode))
        {
            if (S_ISDIR(st_old.st_mode))
            {
                errnum = (char_u *)"E502: ";
                errmsg = (char_u *)_(e_is_a_directory);
                goto fail;
            }
            if (mch_nodetype(fname) != NODE_WRITABLE)
            {
                errnum = (char_u *)"E503: ";
                errmsg = (char_u *)_(e_is_not_file_or_writable_device);
                goto fail;
            }
            device = TRUE;
            newfile = TRUE;
            perm = -1;
        }
    }

    if (!device && !newfile)
    {
        file_readonly = check_file_readonly(fname, (int)perm);

        if (!forceit && file_readonly)
        {
            if (vim_strchr(p_cpo, CPO_FWRITE) != NULL)
            {
                errnum = (char_u *)"E504: ";
                errmsg = (char_u *)_(e_is_read_only_cannot_override_W_in_cpoptions);
            }
            else
            {
                errnum = (char_u *)"E505: ";
                errmsg = (char_u *)_(e_is_read_only_add_bang_to_override);
            }
            goto fail;
        }

        if (overwriting)
        {
            retval = check_mtime(buf, &st_old);
            if (retval == FAIL)
            {
                goto fail;
            }
        }
    }

    if (!newfile)
    {

    prev_got_int = got_int;
    }
    got_int = FALSE;

    buf->b_saving = true;

    if (forceit && perm >= 0 && !(perm & 0200) && vim_strchr(p_cpo, CPO_FWRITE) == NULL)
    {
        perm |= 0200;
        (void)mch_setperm(fname, perm);
        made_writable = TRUE;
    }

    if (forceit && overwriting && vim_strchr(p_cpo, CPO_KEEPRO) == NULL)
    {
        buf->b_p_ro = FALSE;
        status_redraw_all();
    }

    if (end > buf->b_ml.ml_line_count)
    {
        end = buf->b_ml.ml_line_count;
    }
    if (buf->b_ml.ml_flags & ML_EMPTY)
    {
        start = end + 1;
    }

    if (reset_changed && !newfile && overwriting)
    {
        if (got_int)
        {
            errmsg = (char_u *)_(e_interrupted);
            goto restore_backup;
        }
    }

    wfname = fname;

    for (checking_conversion = TRUE; ; checking_conversion = FALSE)
    {
        checking_conversion = FALSE;

        while ((fd =  open(((char *)wfname), (O_WRONLY | O_EXTRA | (append ? (forceit ? (O_APPEND | O_CREAT) : O_APPEND) : (O_CREAT | TRUNC_ON_OPEN))), (perm < 0 ? 0666 : (perm & 0777))) ) < 0)
        {
            if (errmsg == NULL)
            {
                stat_T      st;

                if ((!newfile && st_old.st_nlink > 1) || ( lstat(((char *)fname), (&st))  == 0 && (st.st_dev != st_old.st_dev || st.st_ino != st_old.st_ino)))
                {
                    errmsg =
                          (char_u *)_(e_cant_open_linked_file_for_writing);
                }
                else
                {
                    errmsg = (char_u *)_(e_cant_open_file_for_writing);
                    if (forceit && vim_strchr(p_cpo, CPO_FWRITE) == NULL && perm >= 0)
                    {
                        if (!(perm & 0200))
                        {
                            made_writable = TRUE;
                        }
                        perm |= 0200;
                        perm &= 0777;
                        if (!append)
                        {
                             unlink((char *)(wfname)) ;
                        }
                        continue;
                    }
                }
            }

restore_backup:
            {
                stat_T      st;

                if (!newfile &&  stat(((char *)fname), (&st))  < 0)
                {
                    end = 0;
                }
            }

            if (wfname != fname)
            {
                vim_free(wfname);
            }
            goto fail;
        }
        write_info.bw_fd = fd;

        {
            stat_T  st;

            if (overwriting && fname == wfname && perm >= 0 &&  fstat((fd), (&st))  == 0 && st.st_ino != st_old.st_ino)
            {
                close(fd);
                errmsg = (char_u *)_(e_file_changed_while_writing);
                goto fail;
            }
        }
        if (!append)
        {
            vim_ignored = ftruncate(fd, (off_t)0);
        }

        errmsg = NULL;

        write_info.bw_buf = buffer;
        nchars = 0;

        write_info.bw_start_lnum = start;

        write_info.bw_len = bufsize;
        write_info.bw_flags = wb_flags;
        s = buffer;
        len = 0;
        for (lnum = start; lnum <= end; ++lnum)
        {
            ptr = ml_get_buf(buf, lnum, FALSE) - 1;
            while ((c = *++ptr) != NUL)
            {
                if (c == NL)
                {
                    *s = NUL;
                }
                else
                {
                    *s = c;
                }
                ++s;
                if (++len != bufsize)
                {
                    continue;
                }
                if (buf_write_bytes(&write_info) == FAIL)
                {
                    end = 0;
                    break;
                }
                nchars += bufsize;
                s = buffer;
                len = 0;
                write_info.bw_start_lnum = lnum;
            }
            if (end == 0)
            {
                ++lnum;
                no_eol = TRUE;
                break;
            }
            *s++ = NL;
            if (++len == bufsize && end)
            {
                if (buf_write_bytes(&write_info) == FAIL)
                {
                    end = 0;
                    break;
                }
                nchars += bufsize;
                s = buffer;
                len = 0;

                ui_breakcheck();
                if (got_int)
                {
                    end = 0;
                    break;
                }
            }
        }
        if (len > 0 && end > 0)
        {
            write_info.bw_len = len;
            if (buf_write_bytes(&write_info) == FAIL)
            {
                end = 0;
            }
            nchars += len;
        }

        if (!checking_conversion || end == 0)
        {
            break;
        }

    }

    if ((buf->b_p_fs >= 0 ? buf->b_p_fs : p_fs) && vim_fsync(fd) != 0 && !device)
    {
        errmsg = (char_u *)_(e_fsync_failed);
        end = 0;
    }

    {
        buf_setino(buf);
    }

    if (made_writable)
    {
        perm &= ~0200;
    }
    if (perm >= 0)
    {
        (void)mch_fsetperm(fd, perm);
    }
    if (close(fd) != 0)
    {
        errmsg = (char_u *)_(e_close_failed);
        end = 0;
    }

    if (end == 0)
    {
        if (errmsg == NULL)
        {
            if (got_int)
            {
                errmsg = (char_u *)_(e_interrupted);
            }
            else
            {
                errmsg = (char_u *)_(e_write_error_file_system_full);
            }
        }

        goto fail;
    }

    lnum -= start;
    --no_wait_return;

    if (!filtering)
    {
        msg_add_fname(buf, fname);
        c = FALSE;
        if (device)
        {
             strcat((char *)(IObuff), (char *)(_("[Device]"))) ;
            c = TRUE;
        }
        else if (newfile)
        {
             strcat((char *)(IObuff), (char *)(new_file_message())) ;
            c = TRUE;
        }
        if (no_eol)
        {
            msg_add_eol();
            c = TRUE;
        }
        msg_add_lines(c, (long)lnum, nchars);
        if (!shortmess(SHM_WRITE))
        {
            if (append)
            {
                 strcat((char *)(IObuff), (char *)(shortmess(SHM_WRI) ? _(" [a]") : _(" appended"))) ;
            }
            else
            {
                 strcat((char *)(IObuff), (char *)(shortmess(SHM_WRI) ? _(" [w]") : _(" written"))) ;
            }
        }

        set_keep_msg((char_u *)msg_trunc_attr((char *)IObuff, FALSE, 0), 0);
    }

    if (reset_changed && whole && !append && (overwriting || vim_strchr(p_cpo, CPO_PLUS) != NULL))
    {
        unchanged(buf, TRUE, FALSE);
        if (buf->b_last_changedtick + 1 ==  ((buf)->b_ct_di.di_tv.vval.v_number) )
        {
            buf->b_last_changedtick =  ((buf)->b_ct_di.di_tv.vval.v_number) ;
        }
        u_unchanged(buf);
        u_update_save_nr(buf);
    }

    if (overwriting)
    {
        ml_timestamp(buf);
        if (append)
        {
            buf->b_flags &= ~BF_NEW;
        }
        else
        {
            buf->b_flags &= ~ (BF_NOTEDITED + BF_NEW + BF_READERR) ;
        }
    }

    goto nofail;

fail:
    --no_wait_return;
nofail:

    buf->b_saving = false;

    if (buffer != smallbuf)
    {
        vim_free(buffer);
    }

    if (errmsg != NULL)
    {
        int numlen = errnum != NULL ? (int) strlen((char *)(errnum))  : 0;

        attr =  highlight_attr[(int)(HLF_E)] ;
        msg_add_fname(buf, fname);
        if ( strlen((char *)(IObuff))  +  strlen((char *)(errmsg))  + numlen >=  (1024+1) )
        {
            IObuff[ (1024+1)  -  strlen((char *)(errmsg))  - numlen - 1] = NUL;
        }
        if (errnum != NULL)
        {
              memmove((char *)((IObuff + numlen)), (char *)((IObuff)),  strlen((char *)(IObuff))  + 1)  ;
             memmove((char *)(IObuff), (char *)(errnum), (size_t)numlen) ;
        }
         strcat((char *)(IObuff), (char *)(errmsg)) ;
        emsg((char *)IObuff);
        if (errmsg_allocated)
        {
            vim_free(errmsg);
        }

        retval = FAIL;
        if (end == 0)
        {
            msg_puts_attr(_("\nWARNING: Original file may be lost or damaged\n"), attr | MSG_HIST);
            msg_puts_attr(_("don't quit the editor until the file is successfully written!"), attr | MSG_HIST);

            if ( stat(((char *)fname), (&st_old))  >= 0)
            {
                buf_store_time(buf, &st_old, fname);
                buf->b_mtime_read = buf->b_mtime;
                buf->b_mtime_read_ns = buf->b_mtime_ns;
            }
        }
    }
    msg_scroll = msg_save;

    got_int |= prev_got_int;

    return retval;
}

    static void
change_warning(int col)
{
    static char *w_readonly =  "W10: Warning: Changing a readonly file" ;

    if (curbuf->b_did_warn || curbufIsChanged() || autocmd_busy || !curbuf->b_p_ro)
    {
        return;
    }

    ++curbuf_lock;
    --curbuf_lock;
    if (!curbuf->b_p_ro)
    {
        return;
    }

    msg_start();
    if (msg_row == Rows - 1)
    {
        msg_col = col;
    }
    msg_source( highlight_attr[(int)(HLF_W)] );
    msg_puts_attr(_(w_readonly),  highlight_attr[(int)(HLF_W)]  | MSG_HIST);
    msg_clr_eos();
    (void)msg_end();
    if (msg_silent == 0 && !silent_mode)
    {
        out_flush();
        ui_delay(1002L, TRUE);
    }
    curbuf->b_did_warn = true;
    redraw_cmdline = FALSE;
    if (msg_row < Rows - 1)
    {
        showmode();
    }
}

    static void
changed(void)
{
    if (!curbuf->b_changed)
    {

        change_warning(0);

        changed_internal();
    }
    ++ ((curbuf)->b_ct_di.di_tv.vval.v_number) ;

    highlight_match = FALSE;
}

    static void
changed_internal(void)
{
    curbuf->b_changed = TRUE;
    ml_setflags(curbuf);
    check_status(curbuf);
    redraw_tabline = TRUE;
}

    static void
changed_common(linenr_T    lnum, colnr_T     col, linenr_T    lnume, long        xtra)
{
    win_T       *wp;
    int         i;
    int         cols;
    pos_T       *p;
    int         add;

    changed();

    if ((cmdmod.cmod_flags & CMOD_KEEPJUMPS) == 0)
    {
        curbuf->b_last_change.lnum = lnum;
        curbuf->b_last_change.col = col;

        if (curbuf->b_new_change || curbuf->b_changelistlen == 0)
        {
            if (curbuf->b_changelistlen == 0)
            {
                add = TRUE;
            }
            else
            {
                p = &curbuf->b_changelist[curbuf->b_changelistlen - 1];
                if (p->lnum != lnum)
                {
                    add = TRUE;
                }
                else
                {
                    cols = comp_textwidth();
                    if (cols == 0)
                    {
                        cols = 79;
                    }
                    add = (p->col + cols < col || col + cols < p->col);
                }
            }
            if (add)
            {
                curbuf->b_new_change = false;

                if (curbuf->b_changelistlen == JUMPLISTSIZE)
                {
                    curbuf->b_changelistlen = JUMPLISTSIZE - 1;
                     memmove((char *)(curbuf->b_changelist), (char *)(curbuf->b_changelist + 1), sizeof(pos_T) * (JUMPLISTSIZE - 1)) ;
                     wp = curwin;
                if (wp->w_buffer == curbuf && wp->w_changelistidx > 0)
                {
                    --wp->w_changelistidx;
                }
                }
                 wp = curwin;
            if (wp->w_buffer == curbuf && wp->w_changelistidx == curbuf->b_changelistlen)
            {
                ++wp->w_changelistidx;
            }
                ++curbuf->b_changelistlen;
            }
        }
        curbuf->b_changelist[curbuf->b_changelistlen - 1] =
                                                        curbuf->b_last_change;
        curwin->w_changelistidx = curbuf->b_changelistlen;
    }

    if (VIsual_active)
    {
        check_visual_pos();
    }

     wp = curwin;
if (wp->w_buffer == curbuf)
{
    linenr_T last = lnume + xtra - 1;

    if (!redraw_not_allowed && wp->w_redr_type < UPD_VALID)
    {
        wp->w_redr_type = UPD_VALID;
    }

    if (xtra != 0 && wp->w_redraw_top != 0)
    {
        redraw_win_later(wp, UPD_NOT_VALID);
    }

    if (wp->w_skipcol > 0 && (last < wp->w_topline || (wp->w_topline >= lnum && wp->w_topline < lnume && linetabsize_eol(wp, wp->w_topline) <= wp->w_skipcol + sms_marker_overlap(wp, -1))))
    {
        wp->w_skipcol = 0;
    }

    if (wp->w_cursor.lnum > lnum)
    {
        changed_line_abv_curs_win(wp);
    }
    else if (wp->w_cursor.lnum == lnum && wp->w_cursor.col >= col)
    {
        changed_cline_bef_curs_win(wp);
    }
    if (wp->w_botline >= lnum)
    {
        if (xtra < 0)
        {
            invalidate_botline_win(wp);
        }
        else
        {
            approximate_botline_win(wp);
        }
    }

    for (i = 0; i < wp->w_lines_valid; ++i)
    {
        if (wp->w_lines[i].wl_valid)
        {
            if (wp->w_lines[i].wl_lnum >= lnum)
            {
                if (wp->w_lines[i].wl_lnum < lnume || i == 0)
                {
                    wp->w_lines[i].wl_valid = FALSE;
                }
                else if (xtra != 0)
                {
                    wp->w_lines[i].wl_lnum += xtra;
                }
            }
        }
    }

    if (wp-> w_onebuf_opt.wo_rnu  && xtra != 0)
    {
        wp->w_last_cursor_lnum_rnu = 0;
    }

}
if (wp == curwin && xtra != 0 && search_hl_has_cursor_lnum >= lnum)
{
    search_hl_has_cursor_lnum += xtra;
}

    set_must_redraw(UPD_VALID);

    if (lnum <= curwin->w_cursor.lnum && lnume + (xtra < 0 ? -xtra : xtra) > curwin->w_cursor.lnum)
    {
        last_cursormoved.lnum = 0;
    }
}

    static void
changedOneline(buf_T *buf, linenr_T lnum)
{
    if (buf->b_mod_set)
    {
        if (lnum < buf->b_mod_top)
        {
            buf->b_mod_top = lnum;
        }
        else if (lnum >= buf->b_mod_bot)
        {
            buf->b_mod_bot = lnum + 1;
        }
    }
    else
    {
        buf->b_mod_set = true;
        buf->b_mod_top = lnum;
        buf->b_mod_bot = lnum + 1;
        buf->b_mod_xlines = 0;
    }
}

    static void
changed_bytes(linenr_T lnum, colnr_T col)
{
    changedOneline(curbuf, lnum);
    changed_common(lnum, col, lnum + 1, 0L);

}

    static void
inserted_bytes(linenr_T lnum, colnr_T col, int added  __attribute__((unused)) )
{
    changed_bytes(lnum, col);
}

    static void
appended_lines(linenr_T lnum, long count)
{
    changed_lines(lnum + 1, 0, lnum + 1, count);
}

    static void
appended_lines_mark(linenr_T lnum, long count)
{
    mark_adjust(lnum + 1, (linenr_T) LONG_MAX , count, 0L);
    changed_lines(lnum + 1, 0, lnum + 1, count);
}

    static void
deleted_lines(linenr_T lnum, long count)
{
    changed_lines(lnum, 0, lnum + count, -count);
}

    static void
deleted_lines_mark(linenr_T lnum, long count)
{
    mark_adjust(lnum, (linenr_T)(lnum + count - 1), (long) LONG_MAX , -count);
    changed_lines(lnum, 0, lnum + count, -count);
}

    static void
changed_lines_buf(buf_T       *buf, linenr_T    lnum, linenr_T    lnume, long        xtra)
{
    if (buf->b_mod_set)
    {
        if (lnum < buf->b_mod_top)
        {
            buf->b_mod_top = lnum;
        }
        if (lnum < buf->b_mod_bot)
        {
            buf->b_mod_bot += xtra;
            if (buf->b_mod_bot < lnum)
            {
                buf->b_mod_bot = lnum;
            }
        }
        if (lnume + xtra > buf->b_mod_bot)
        {
            buf->b_mod_bot = lnume + xtra;
        }
        buf->b_mod_xlines += xtra;
    }
    else
    {
        buf->b_mod_set = true;
        buf->b_mod_top = lnum;
        buf->b_mod_bot = lnume + xtra;
        buf->b_mod_xlines = xtra;
    }
}

    static void
changed_lines(linenr_T    lnum, colnr_T     col, linenr_T    lnume, long        xtra)
{
    changed_lines_buf(curbuf, lnum, lnume, xtra);

    changed_common(lnum, col, lnume, xtra);
}

    static void
unchanged(buf_T *buf, int ff, int always_inc_changedtick)
{
    if (buf->b_changed)
    {
        buf->b_changed = 0;
        ml_setflags(buf);
        check_status(buf);
        redraw_tabline = TRUE;
        ++ ((buf)->b_ct_di.di_tv.vval.v_number) ;
    }
    else if (always_inc_changedtick)
    {
        ++ ((buf)->b_ct_di.di_tv.vval.v_number) ;
    }
}

    static void
ins_bytes(char_u *p)
{
    ins_bytes_len(p, (int) strlen((char *)(p)) );
}

    static void
ins_bytes_len(char_u *p, int len)
{
    int         i;
    int         n;

    for (i = 0; i < len; i += n)
    {
        n = utfc_ptr2len_len(p + i, len - i);
        ins_char_bytes(p + i, n);
    }
}

    static void
ins_char(int c)
{
    char_u      buf[MB_MAXBYTES + 1];
    int         n = utf_char2bytes(c, buf);

    if (buf[0] == 0)
    {
        buf[0] = '\n';
    }

    ins_char_bytes(buf, n);
}

    static void
ins_char_bytes(char_u *buf, int charlen)
{
    int         newlen;
    int         oldlen;
    char_u      *p;
    char_u      *newp;
    char_u      *oldp;
    int         linelen;
    colnr_T     col;
    linenr_T    lnum = curwin->w_cursor.lnum;
    int         i;

    if (virtual_active() && curwin->w_cursor.coladd > 0)
    {
        coladvance_force(getviscol());
    }

    col = curwin->w_cursor.col;
    oldp = ml_get(lnum);
    linelen = (int)ml_get_len(lnum) + 1;

    oldlen = 0;
    newlen = charlen;

    if (State & REPLACE_FLAG)
    {
        if (State & VREPLACE_FLAG)
        {
            colnr_T     new_vcol = 0;
            colnr_T     vcol;
            int         old_list;

            old_list = curwin-> w_onebuf_opt.wo_list ;
            if (old_list && vim_strchr(p_cpo, CPO_LISTWM) == NULL)
            {
                curwin-> w_onebuf_opt.wo_list  = FALSE;
            }

            getvcol(curwin, &curwin->w_cursor, NULL, &vcol, NULL, 0);
            new_vcol = vcol + chartabsize(buf, vcol);
            while (oldp[col + oldlen] != NUL && vcol < new_vcol)
            {
                vcol += chartabsize(oldp + col + oldlen, vcol);
                if (vcol > new_vcol && oldp[col + oldlen] == TAB)
                {
                    break;
                }
                oldlen += utfc_ptr2len(oldp + col + oldlen);
                if (vcol > new_vcol)
                {
                    newlen += vcol - new_vcol;
                }
            }
            curwin-> w_onebuf_opt.wo_list  = old_list;
        }
        else if (oldp[col] != NUL)
        {
            oldlen = utfc_ptr2len(oldp + col);
        }

        replace_push(NUL);
        for (i = 0; i < oldlen; ++i)
        {
            i += replace_push_mb(oldp + col + i) - 1;
        }
    }

    newp = alloc(linelen + newlen - oldlen);
    if (newp == NULL)
    {
        return;
    }

    if (col > 0)
    {
         memmove((char *)(newp), (char *)(oldp), (size_t)col) ;
    }

    p = newp + col;
    if (linelen > col + oldlen)
    {
         memmove((char *)(p + newlen), (char *)(oldp + col + oldlen), (size_t)(linelen - col - oldlen)) ;
    }

     memmove((char *)(p), (char *)(buf), charlen) ;
    i = charlen;

    while (i < newlen)
    {
        p[i++] = ' ';
    }

    ml_replace(lnum, newp, FALSE);

    changed_bytes(lnum, col);

    if (p_sm && (State & MODE_INSERT) && msg_silent == 0)
    {
        showmatch(utf_ptr2char(buf));
    }

    {
        curwin->w_cursor.col += charlen;
    }

}

    static void
ins_str(char_u *s, size_t slen)
{
    char_u *oldp;
    char_u *newp;
    int         oldlen;
    colnr_T     col;
    linenr_T    lnum = curwin->w_cursor.lnum;

    if (virtual_active() && curwin->w_cursor.coladd > 0)
    {
        coladvance_force(getviscol());
    }

    col = curwin->w_cursor.col;
    oldp = ml_get(lnum);
    oldlen = (int)ml_get_len(lnum);

    newp = alloc(oldlen + slen + 1);
    if (newp == NULL)
    {
        return;
    }
    if (col > 0)
    {
         memmove((char *)(newp), (char *)(oldp), (size_t)col) ;
    }
     memmove((char *)(newp + col), (char *)(s), slen) ;
     memmove((char *)(newp + col + slen), (char *)(oldp + col), (size_t)(oldlen - col + 1)) ;
    ml_replace(lnum, newp, FALSE);
    inserted_bytes(lnum, col, (int)slen);
    curwin->w_cursor.col += (colnr_T)slen;
}

    static int
del_char(int fixpos)
{
    mb_adjust_cursor();
    if (*ml_get_cursor() == NUL)
    {
        return FAIL;
    }
    return del_chars(1L, fixpos);
    return del_bytes(1L, fixpos, TRUE);
}

    static int
del_chars(long count, int fixpos)
{
    long        bytes = 0;
    long        i;
    char_u      *p;
    int         l;

    p = ml_get_cursor();
    for (i = 0; i < count && *p != NUL; ++i)
    {
        l = utfc_ptr2len(p);
        bytes += l;
        p += l;
    }
    return del_bytes(bytes, fixpos, TRUE);
}

    static int
del_bytes(long        count, int         fixpos_arg, int         use_delcombine  __attribute__((unused)) )
{
    char_u *oldp;
    char_u *newp;
    colnr_T     oldlen;
    colnr_T     newlen;
    linenr_T    lnum = curwin->w_cursor.lnum;
    colnr_T     col = curwin->w_cursor.col;
    int         alloc_newp;
    long        movelen;
    int         fixpos = fixpos_arg;

    oldp = ml_get(lnum);
    oldlen = (int)ml_get_len(lnum);

    if (col >= oldlen)
    {
        return FAIL;
    }

    if (count == 0)
    {
        return OK;
    }

    if (count < 1)
    {
        siemsg(e_invalid_count_for_del_bytes_nr, count);
        return FAIL;
    }

    if (p_deco && use_delcombine && utfc_ptr2len(oldp + col) >= count)
    {
        int     cc[MAX_MCO];
        int     n;

        (void)utfc_ptr2char(oldp + col, cc);
        if (cc[0] != NUL)
        {
            n = col;
            do
            {
                col = n;
                count = utf_ptr2len(oldp + n);
                n += count;
            } while ( utf_iscomposing(utf_ptr2char(oldp + n)) );
            fixpos = 0;
        }
    }

    movelen = (long)oldlen - (long)col - count + 1;
    if (movelen <= 1)
    {
        if (col > 0 && fixpos && restart_edit == 0 && (get_ve_flags() & VE_ONEMORE) == 0)
        {
            --curwin->w_cursor.col;
            curwin->w_cursor.coladd = 0;
            curwin->w_cursor.col -=
                        utf_head_off(oldp, oldp + curwin->w_cursor.col);
        }
        count = oldlen - col;
        movelen = 1;
    }
    newlen = oldlen - count;

        alloc_newp = !ml_line_alloced();
    if (!alloc_newp)
    {
        newp = oldp;
    }
    else
    {
        newp = alloc(newlen + 1);
        if (newp == NULL)
        {
            return FAIL;
        }
         memmove((char *)(newp), (char *)(oldp), (size_t)col) ;
    }
     memmove((char *)(newp + col), (char *)(oldp + col + count), (size_t)movelen) ;
    if (alloc_newp)
    {
        ml_replace(lnum, newp, FALSE);
    }
    else
    {
        curbuf->b_ml.ml_line_len -= count;
        curbuf->b_ml.ml_line_textlen = 0;
    }

    inserted_bytes(lnum, col, -count);

    return OK;
}

    static int
open_line(int         dir, int         flags, int         second_line_indent, int         *did_do_comment  __attribute__((unused)) )
{
    char_u      *saved_line;
    char_u      *next_line = NULL;
    char_u      *p_extra = NULL;
    int         less_cols = 0;
    int         less_cols_off = 0;
    pos_T       old_cursor;
    int         newcol = 0;
    int         newindent = 0;
    int         n;
    int         trunc_line = FALSE;
    int         retval = FAIL;
    char_u      *p;
    int         saved_char = NUL;
    pos_T       *pos;
    int         do_si = may_do_si();
    int         no_si = FALSE;
    int         first_char = NUL;
    int         vreplace_mode;
    int         did_append;
    int         saved_pi = curbuf->b_p_pi;

    saved_line = vim_strnsave(ml_get_curline(), ml_get_curline_len());
    if (saved_line == NULL)
    {
        return FALSE;
    }

    if (State & VREPLACE_FLAG)
    {
        if (curwin->w_cursor.lnum < orig_line_count)
        {
            next_line = vim_strnsave(ml_get(curwin->w_cursor.lnum + 1), ml_get_len(curwin->w_cursor.lnum + 1));
        }
        else
        {
            next_line = vim_strsave((char_u *)"");
        }
        if (next_line == NULL)
        {
            goto theend;
        }

        replace_push(NUL);
        replace_push(NUL);
        p = saved_line + curwin->w_cursor.col;
        while (*p != NUL)
        {
            p += replace_push_mb(p);
        }
        saved_line[curwin->w_cursor.col] = NUL;
    }

    if ((State & MODE_INSERT) && (State & VREPLACE_FLAG) == 0)
    {
        p_extra = saved_line + curwin->w_cursor.col;
        if (do_si)
        {
            p = skipwhite(p_extra);
            first_char = *p;
        }
        saved_char = *p_extra;
        *p_extra = NUL;
    }

    u_clearline();
    did_si = FALSE;
    ai_col = 0;

    if (dir == FORWARD && did_ai)
    {
        trunc_line = TRUE;
    }

    if ((flags & OPENLINE_FORCE_INDENT) && second_line_indent >= 0)
    {
        newindent = second_line_indent;
    }
    else if (curbuf->b_p_ai || do_si)
    {
        newindent = get_indent_str(saved_line, (int)curbuf->b_p_ts, FALSE);
        if (newindent == 0)
        {
            newindent = second_line_indent;
        }

        if (!trunc_line && do_si && *saved_line != NUL && (p_extra == NULL || first_char != '{'))
        {
            char_u  *ptr;
            char_u  last_char;

            old_cursor = curwin->w_cursor;
            ptr = saved_line;
            if (dir == FORWARD)
            {
                if (ptr[0] == '#')
                {
                    while (ptr[0] == '#' && curwin->w_cursor.lnum > 1)
                    {
                        ptr = ml_get(--curwin->w_cursor.lnum);
                    }
                    newindent = get_indent();
                }
                p = ptr +  strlen((char *)(ptr))  - 1;
                while (p > ptr &&  ((*p) == ' ' || (*p) == '\t') )
                {
                    --p;
                }
                last_char = *p;

                if (last_char == '{' || last_char == ';')
                {
                    if (p > ptr)
                    {
                        --p;
                    }
                    while (p > ptr &&  ((*p) == ' ' || (*p) == '\t') )
                    {
                        --p;
                    }
                }
                if (*p == ')')
                {
                    curwin->w_cursor.col = (colnr_T)(p - ptr);
                    if ((pos = findmatch(NULL, '(')) != NULL)
                    {
                        curwin->w_cursor.lnum = pos->lnum;
                        newindent = get_indent();
                        ptr = ml_get_curline();
                    }
                }
                if (last_char == '{')
                {
                    did_si = TRUE;
                    no_si = TRUE;
                }
            }
            else
            {
                if (ptr[0] == '#')
                {
                    int was_backslashed = FALSE;

                    while ((ptr[0] == '#' || was_backslashed) && curwin->w_cursor.lnum < curbuf->b_ml.ml_line_count)
                    {
                        if (*ptr && ptr[ strlen((char *)(ptr))  - 1] == '\\')
                        {
                            was_backslashed = TRUE;
                        }
                        else
                        {
                            was_backslashed = FALSE;
                        }
                        ptr = ml_get(++curwin->w_cursor.lnum);
                    }
                    if (was_backslashed)
                    {
                        newindent = 0;
                    }
                    else
                    {
                        newindent = get_indent();
                    }
                }
                p = skipwhite(ptr);
                if (*p == '}')
                {
                    did_si = TRUE;
                }
                else
                {
                    can_si_back = TRUE;
                }
            }
            curwin->w_cursor = old_cursor;
        }
        if (do_si)
        {
            can_si = TRUE;
        }

        did_ai = TRUE;
    }

    if (p_extra != NULL)
    {
        *p_extra = saved_char;

        if ( (((State) & REPLACE_FLAG) && !((State) & VREPLACE_FLAG)) )
        {
            replace_push(NUL);
        }
        if (curbuf->b_p_ai || (flags & OPENLINE_DELSPACES))
        {
            while ((*p_extra == ' ' || *p_extra == '\t') && (!utf_iscomposing(utf_ptr2char(p_extra + 1))))
            {
                if ( (((State) & REPLACE_FLAG) && !((State) & VREPLACE_FLAG)) )
                {
                    replace_push(*p_extra);
                }
                ++p_extra;
                ++less_cols_off;
            }
        }

        less_cols = (int)(p_extra - saved_line);
    }

    if (p_extra == NULL)
    {
        p_extra = (char_u *)"";
    }

    old_cursor = curwin->w_cursor;
    if (dir ==  (-1) )
    {
        --curwin->w_cursor.lnum;
    }
    if (!(State & VREPLACE_FLAG) || old_cursor.lnum >= orig_line_count)
    {
        if (ml_append(curwin->w_cursor.lnum, p_extra, (colnr_T)0, FALSE) == FAIL)
        {
            goto theend;
        }
        mark_adjust(curwin->w_cursor.lnum + 1, (linenr_T) LONG_MAX , 1L, 0L);
        did_append = TRUE;
    }
    else
    {
        curwin->w_cursor.lnum++;
        if (curwin->w_cursor.lnum >= Insstart.lnum + vr_lines_changed)
        {
            (void)u_save_cursor();
            vr_lines_changed++;
        }
        ml_replace(curwin->w_cursor.lnum, p_extra, TRUE);
        changed_bytes(curwin->w_cursor.lnum, 0);
        curwin->w_cursor.lnum--;
        did_append = FALSE;
    }

    if (newindent || did_si)
    {
        ++curwin->w_cursor.lnum;
        if (did_si)
        {
            int sw = (int)get_sw_value(curbuf);

            if (p_sr)
            {
                newindent -= newindent % sw;
            }
            newindent += sw;
        }
        if (curbuf->b_p_ci)
        {
            (void)copy_indent(newindent, saved_line);

            curbuf->b_p_pi = TRUE;
        }
        else
        {
            (void)set_indent(newindent, SIN_INSERT);
        }
        less_cols -= curwin->w_cursor.col;

        ai_col = curwin->w_cursor.col;

        if ( (((State) & REPLACE_FLAG) && !((State) & VREPLACE_FLAG)) )
        {
            for (n = 0; n < (int)curwin->w_cursor.col; ++n)
            {
                replace_push(NUL);
            }
        }
        newcol += curwin->w_cursor.col;
        if (no_si)
        {
            did_si = FALSE;
        }
    }

    curwin->w_cursor = old_cursor;

    if (dir == FORWARD)
    {
        if (trunc_line || (State & MODE_INSERT))
        {
            saved_line[curwin->w_cursor.col] = NUL;
            if (trunc_line)
            {
                truncate_spaces(saved_line, curwin->w_cursor.col);
            }
            ml_replace(curwin->w_cursor.lnum, saved_line, FALSE);
            saved_line = NULL;
            if (did_append)
            {
                changed_lines(curwin->w_cursor.lnum, curwin->w_cursor.col, curwin->w_cursor.lnum + 1, 1L);
                did_append = FALSE;

                if (flags & OPENLINE_MARKFIX)
                {
                    mark_col_adjust(curwin->w_cursor.lnum, curwin->w_cursor.col + less_cols_off, 1L, (long)-less_cols, 0);
                }
            }
            else
            {
                changed_bytes(curwin->w_cursor.lnum, curwin->w_cursor.col);
            }
        }

        curwin->w_cursor.lnum = old_cursor.lnum + 1;
    }
    if (did_append)
    {
        changed_lines(curwin->w_cursor.lnum, 0, curwin->w_cursor.lnum, 1L);
    }

    curwin->w_cursor.col = newcol;
    curwin->w_cursor.coladd = 0;

    if (State & VREPLACE_FLAG)
    {
        vreplace_mode = State;
        State = MODE_INSERT;
    }
    else
    {
        vreplace_mode = 0;
    }

    if (vreplace_mode != 0)
    {
        State = vreplace_mode;
    }

    if (State & VREPLACE_FLAG)
    {
        p_extra = vim_strnsave(ml_get_curline(), ml_get_curline_len());
        if (p_extra == NULL)
        {
            goto theend;
        }

        ml_replace(curwin->w_cursor.lnum, next_line, FALSE);

        curwin->w_cursor.col = 0;
        curwin->w_cursor.coladd = 0;
        ins_bytes(p_extra);
        vim_free(p_extra);
        next_line = NULL;
    }

    retval = OK;
theend:
    curbuf->b_p_pi = saved_pi;
    vim_free(saved_line);
    vim_free(next_line);
    return retval;
}

    static int
truncate_line(int fixpos)
{
    char_u      *newp;
    linenr_T    lnum = curwin->w_cursor.lnum;
    colnr_T     col = curwin->w_cursor.col;
    char_u      *old_line;
    int         deleted;

    old_line = ml_get(lnum);
    if (col == 0)
    {
        newp = vim_strsave((char_u *)"");
    }
    else
    {
        newp = vim_strnsave(old_line, col);
    }
    deleted = (int)ml_get_len(lnum) - col;

    if (newp == NULL)
    {
        return FAIL;
    }

    ml_replace(lnum, newp, FALSE);

    inserted_bytes(lnum, curwin->w_cursor.col, -deleted);

    if (fixpos && curwin->w_cursor.col > 0)
    {
        --curwin->w_cursor.col;
    }

    return OK;
}

    static void
del_lines(long nlines, int undo)
{
    long        n;
    linenr_T    first = curwin->w_cursor.lnum;

    if (nlines <= 0)
    {
        return;
    }

    if (undo && u_savedel(first, nlines) == FAIL)
    {
        return;
    }

    for (n = 0; n < nlines; )
    {
        if (curbuf->b_ml.ml_flags & ML_EMPTY)
        {
            break;
        }

        ml_delete_flags(first, ML_DEL_MESSAGE);
        ++n;

        if (first > curbuf->b_ml.ml_line_count)
        {
            break;
        }
    }

    curwin->w_cursor.col = 0;
    check_cursor_lnum();

    deleted_lines_mark(first, n);
}

static int parse_isopt(char_u *var, buf_T *buf, int only_check);
static int win_nolbr_chartabsize(chartabsize_T *cts, int *headp);
static unsigned nr2hex(unsigned c);

static int    chartab_initialized = FALSE;

static char_u   g_chartab[256];

enum { CT_CELL_MASK = 0x07 };
enum { CT_PRINT_CHAR = 0x10 };
enum { CT_ID_CHAR = 0x20 };
enum { CT_FNAME_CHAR = 0x40 };

static int in_win_border(win_T *wp, colnr_T vcol);

    static int
init_chartab(void)
{
    return buf_init_chartab(curbuf, TRUE);
}

    static int
buf_init_chartab(buf_T       *buf, int         global)
{
    int         c;
    char_u      *p;
    int         i;

    if (global)
    {
        c = 0;
        while (c < ' ')
        {
            g_chartab[c++] = (dy_flags & DY_UHEX) ? 4 : 2;
        }
        while (c <= '~')
        {
            g_chartab[c++] = 1 + CT_PRINT_CHAR;
        }
        while (c < 256)
        {
            if (c >= 0xa0)
            {
                g_chartab[c++] = CT_PRINT_CHAR + 1;
            }
            else
            {
                g_chartab[c++] = (dy_flags & DY_UHEX) ? 4 : 2;
            }
        }

        for (c = 1; c < 256; ++c)
        {
            if ((c >= 0xa0))
            {
                g_chartab[c] |= CT_FNAME_CHAR;
            }
        }
    }

      memset((&(buf->b_chartab)), (0), (sizeof(buf->b_chartab)))  ;

    for (i = global ? 0 : 3; i <= 3; ++i)
    {
        if (i == 0)
        {
            p = p_isi;
        }
        else if (i == 1)
        {
            p = p_isp;
        }
        else if (i == 2)
        {
            p = p_isf;
        }
        else
        {
            p = buf->b_p_isk;
        }

        if (parse_isopt(p, buf, FALSE) == FAIL)
        {
            return FAIL;
        }
    }

    chartab_initialized = TRUE;
    return OK;
}

        static int
check_isopt(char_u *var)
{
    return parse_isopt(var, NULL, TRUE);
}

    static int
parse_isopt(char_u  *var, buf_T   *buf, int     only_check)
{
    char_u      *p = var;
    int         c;
    int         c2;
    int         tilde;
    int         do_isalpha;
    int         trail_comma;

    while (*p)
    {
        tilde = FALSE;
        do_isalpha = FALSE;
        if (*p == '^' && p[1] != NUL)
        {
            tilde = TRUE;
            ++p;
        }
        if ( ((unsigned)(*p) - '0' < 10) )
        {
            c = getdigits(&p);
        }
        else
        {
            c = mb_ptr2char_adv(&p);
        }
        c2 = -1;
        if (*p == '-' && p[1] != NUL)
        {
            ++p;
            if ( ((unsigned)(*p) - '0' < 10) )
            {
                c2 = getdigits(&p);
            }
            else
            {
                c2 = mb_ptr2char_adv(&p);
            }
        }
        if (c <= 0 || c >= 256 || (c2 < c && c2 != -1) || c2 >= 256 || !(*p == NUL || *p == ','))
        {
            return FAIL;
        }

        trail_comma = *p == ',';
        p = skip_to_option_part(p);
        if (trail_comma && *p == NUL)
        {
            return FAIL;
        }

        if (only_check)
        {
            continue;
        }

        if (c2 == -1)
        {
            if (c == '@')
            {
                do_isalpha = TRUE;
                c = 1;
                c2 = 255;
            }
            else
            {
                c2 = c;
            }
        }

        while (c <= c2)
        {
            if (!do_isalpha ||  vim_islower(c)  ||  vim_isupper(c) )
            {
                if (var == p_isi)
                {
                    if (tilde)
                    {
                        g_chartab[c] &= ~CT_ID_CHAR;
                    }
                    else
                    {
                        g_chartab[c] |= CT_ID_CHAR;
                    }
                }
                else if (var == p_isp)
                {
                    if ((c < ' ' || c > '~'))
                    {
                        if (tilde)
                        {
                            g_chartab[c] = (g_chartab[c] & ~CT_CELL_MASK)
                                         + ((dy_flags & DY_UHEX) ? 4 : 2);
                            g_chartab[c] &= ~CT_PRINT_CHAR;
                        }
                        else
                        {
                            g_chartab[c] = (g_chartab[c] & ~CT_CELL_MASK) + 1;
                            g_chartab[c] |= CT_PRINT_CHAR;
                        }
                    }
                }
                else if (var == p_isf)
                {
                    if (tilde)
                    {
                        g_chartab[c] &= ~CT_FNAME_CHAR;
                    }
                    else
                    {
                        g_chartab[c] |= CT_FNAME_CHAR;
                    }
                }
                else
                {
                    if (tilde)
                    {
                         (buf)->b_chartab[(unsigned)(c) >> 3] &= ~(1 << ((c) & 0x7)) ;
                    }
                    else
                    {
                         (buf)->b_chartab[(unsigned)(c) >> 3] |= (1 << ((c) & 0x7)) ;
                    }
                }
            }
            ++c;
        }
    }

    return OK;
}

    static void
trans_characters(char_u      *buf, int         bufsize)
{
    int         len;
    int         room;
    char_u      *trs;
    int         trs_len;

    len = (int) strlen((char *)(buf)) ;
    room = bufsize - len;
    while (*buf != 0)
    {
        if ((trs_len = utfc_ptr2len(buf)) > 1)
        {
            len -= trs_len;
        }
        else
        {
            trs = transchar_byte(*buf);
            trs_len = (int) strlen((char *)(trs)) ;
            if (trs_len > 1)
            {
                room -= trs_len - 1;
                if (room <= 0)
                {
                    return;
                }
                 memmove((char *)(buf + trs_len), (char *)(buf + 1), (size_t)len) ;
            }
             memmove((char *)(buf), (char *)(trs), (size_t)trs_len) ;
            --len;
        }
        buf += trs_len;
    }
}

static char_u   transchar_charbuf[7];

    static char_u *
transchar(int c)
{
    return transchar_buf(curbuf, c);
}

    static char_u *
transchar_buf(buf_T *buf, int c)
{
    int                 i;

    i = 0;
    if ( ((c) < 0) )
    {
        transchar_charbuf[0] = '~';
        transchar_charbuf[1] = '@';
        i = 2;
        c =  ((c) ==  (0x80)  ? KS_SPECIAL : (c) == NUL ? KS_ZERO :  ((-(c)) & 0xff) ) ;
    }

    if ((!chartab_initialized && ((c >= ' ' && c <= '~'))) || (c < 256 && vim_isprintc_strict(c)))
    {
        transchar_charbuf[i] = c;
        transchar_charbuf[i + 1] = NUL;
    }
    else
    {
        transchar_nonprint(buf, transchar_charbuf + i, c);
    }
    return transchar_charbuf;
}

    static char_u *
transchar_byte(int c)
{
    return transchar_byte_buf(curbuf, c);
}

    static char_u *
transchar_byte_buf(buf_T *buf, int c)
{
    if (c >= 0x80)
    {
        transchar_nonprint(buf, transchar_charbuf, c);
        return transchar_charbuf;
    }
    return transchar_buf(buf, c);
}
    static void
transchar_nonprint(buf_T *buf, char_u *charbuf, int c)
{
    if (c == NL)
    {
        c = NUL;
    }

    if (dy_flags & DY_UHEX)
    {
        transchar_hex(charbuf, c);
    }

    else if (c <= 0x7f)
    {
        charbuf[0] = '^';
        charbuf[1] = c ^ 0x40;
        charbuf[2] = NUL;
    }
    else
    {
        transchar_hex(charbuf, c);
    }
}

    static void
transchar_hex(char_u *buf, int c)
{
    int         i = 0;

    buf[0] = '<';
    if (c > 255)
    {
        buf[++i] = nr2hex((unsigned)c >> 12);
        buf[++i] = nr2hex((unsigned)c >> 8);
    }
    buf[++i] = nr2hex((unsigned)c >> 4);
    buf[++i] = nr2hex((unsigned)c);
    buf[++i] = '>';
    buf[++i] = NUL;
}

    static unsigned
nr2hex(unsigned c)
{
    if ((c & 0xf) <= 9)
    {
        return (c & 0xf) + '0';
    }
    return (c & 0xf) - 10 + 'a';
}

    static int
byte2cells(int b)
{
    if (b >= 0x80)
    {
        return 0;
    }
    return (g_chartab[b] & CT_CELL_MASK);
}

    static int
char2cells(int c)
{
    if ( ((c) < 0) )
    {
        return char2cells( ((c) ==  (0x80)  ? KS_SPECIAL : (c) == NUL ? KS_ZERO :  ((-(c)) & 0xff) ) ) + 2;
    }
    if (c >= 0x80)
    {
        return utf_char2cells(c);
    }
    return (g_chartab[c & 0xff] & CT_CELL_MASK);
}

    static int
ptr2cells(char_u *p)
{

    if (*p >= 0x80)
    {
        return utf_ptr2cells(p);
    }
    return (g_chartab[*p] & CT_CELL_MASK);
}

    static int
vim_strsize(char_u *s)
{
    return vim_strnsize(s, (int)MAXCOL);
}

    static int
vim_strnsize(char_u *s, int len)
{
    int         size = 0;

    while (*s != NUL && --len >= 0)
    {
        int         l = utfc_ptr2len(s);

        size += ptr2cells(s);
        s += l;
        len -= l - 1;
    }

    return size;
}

    static int
chartabsize(char_u *p, colnr_T col)
{
     if (*(p) == TAB && (!(curwin)-> w_onebuf_opt.wo_list  || curwin->w_lcs_chars.tab1))
         {       int ts;         ts = (curbuf)->b_p_ts;     return (int)(ts - (col % ts));     }     else   return ptr2cells(p);
}

    static int
linetabsize_str(char_u *s)
{
    return linetabsize_col(0, s);
}

    static int
linetabsize_col(int startcol, char_u *s)
{
    chartabsize_T cts;
    vimlong_T vcol;

    init_chartabsize_arg(&cts, curwin, 0, startcol, s, s);
    vcol = cts.cts_vcol;

    while (*cts.cts_ptr != NUL)
    {
        vcol += lbr_chartabsize_adv(&cts);
        if (vcol > MAXCOL)
        {
            cts.cts_vcol = MAXCOL;
            break;
        }
        else
        {
            cts.cts_vcol = (int)vcol;
        }
    }
    return (int)cts.cts_vcol;
}

    static int
win_linetabsize(win_T *wp, linenr_T lnum, char_u *line, colnr_T len)
{
    chartabsize_T cts;

    init_chartabsize_arg(&cts, wp, lnum, 0, line, line);
    win_linetabsize_cts(&cts, len);
    return (int)cts.cts_vcol;
}

    static int
linetabsize(win_T *wp, linenr_T lnum)
{
    return win_linetabsize(wp, lnum, ml_get_buf(wp->w_buffer, lnum, FALSE), (colnr_T)MAXCOL);
}

    static int
linetabsize_eol(win_T *wp, linenr_T lnum)
{
    return linetabsize(wp, lnum)
        + ((wp-> w_onebuf_opt.wo_list  && wp->w_lcs_chars.eol != NUL) ? 1 : 0);
}

    static int
linetabsize_no_outer(win_T *wp, linenr_T lnum)
{
    return linetabsize(wp, lnum);
}

    static void
win_linetabsize_cts(chartabsize_T *cts, colnr_T len)
{
    vimlong_T vcol = cts->cts_vcol;
    for ( ; *cts->cts_ptr != NUL && (len == MAXCOL || cts->cts_ptr < cts->cts_line + len);  cts->cts_ptr += utfc_ptr2len(cts->cts_ptr) )
    {
        vcol += win_lbr_chartabsize(cts, NULL, NULL);
        if (vcol > MAXCOL)
        {
            cts->cts_vcol = MAXCOL;
            break;
        }
        else
        {
            cts->cts_vcol = (int)vcol;
        }
    }
}

    static int
vim_isIDc(int c)
{
    return (c > 0 && c < 0x100 && (g_chartab[c] & CT_ID_CHAR));
}

    static int
vim_isNormalIDc(int c)
{
    return  ( ( ((unsigned)(c) - 'A' < 26)  ||  ((unsigned)(c) - 'a' < 26) )  ||  ((unsigned)(c) - '0' < 10) )  || c == '_';
}

    static int
vim_iswordc(int c)
{
    return vim_iswordc_buf(c, curbuf);
}

    static int
vim_iswordc_buf(int c, buf_T *buf)
{
    if (c >= 0x100)
    {
        return utf_class_buf(c, buf) >= 2;
        return FALSE;
    }
    return (c > 0 &&  ((buf)->b_chartab[(unsigned)(c) >> 3] & (1 << ((c) & 0x7)))  != 0);
}

    static int
vim_iswordp(char_u *p)
{
    return vim_iswordp_buf(p, curbuf);
}

    static int
vim_iswordp_buf(char_u *p, buf_T *buf)
{
    int c = *p;

    if (mb_bytelen_tab[c]  > 1)
    {
        c = utf_ptr2char(p);
    }
    return vim_iswordc_buf(c, buf);
}

    static int
vim_isfilec(int c)
{
    return (c >= 0x100 || (c > 0 && (g_chartab[c] & CT_FNAME_CHAR)));
}

    static int
vim_isprintc(int c)
{
    if (c >= 0x100)
    {
        return utf_printable(c);
    }
    return (c >= 0x100 || (c > 0 && (g_chartab[c] & CT_PRINT_CHAR)));
}

    static int
vim_isprintc_strict(int c)
{
    if (c >= 0x100)
    {
        return utf_printable(c);
    }
    return (c >= 0x100 || (c > 0 && (g_chartab[c] & CT_PRINT_CHAR)));
}

    static void
init_chartabsize_arg(chartabsize_T   *cts, win_T           *wp, linenr_T        lnum  __attribute__((unused)) , colnr_T         col, char_u          *line, char_u          *ptr)
{
      memset(((cts)), (0), (sizeof(*(cts))))  ;
    cts->cts_win = wp;
    cts->cts_vcol = col;
    cts->cts_line = line;
    cts->cts_ptr = ptr;
}

    static int
lbr_chartabsize(chartabsize_T *cts)
{
        if (curwin-> w_onebuf_opt.wo_wrap )
        {
            return win_nolbr_chartabsize(cts, NULL);
        }
         if (*(cts->cts_ptr) == TAB && (!(curwin)-> w_onebuf_opt.wo_list  || curwin->w_lcs_chars.tab1))
             {       int ts;         ts = (curbuf)->b_p_ts;     return (int)(ts - (cts->cts_vcol % ts));     }     else   return ptr2cells(cts->cts_ptr);
}

    static int
lbr_chartabsize_adv(chartabsize_T *cts)
{
    int         retval;

    retval = lbr_chartabsize(cts);
     cts->cts_ptr += utfc_ptr2len(cts->cts_ptr) ;
    return retval;
}

    static int
win_lbr_chartabsize(chartabsize_T   *cts, int             *headp  __attribute__((unused)) , int             *tailp  __attribute__((unused)) )
{
    win_T       *wp = cts->cts_win;
    char_u      *s = cts->cts_ptr;
    colnr_T     vcol = cts->cts_vcol;

    {
        if (wp-> w_onebuf_opt.wo_wrap )
        {
            return win_nolbr_chartabsize(cts, headp);
        }
         if (*(s) == TAB && (!(wp)-> w_onebuf_opt.wo_list  || wp->w_lcs_chars.tab1))
             {       int ts;         ts = (wp->w_buffer)->b_p_ts;     return (int)(ts - (vcol % ts));     }     else   return ptr2cells(s);
    }

}

    static int
win_nolbr_chartabsize(chartabsize_T   *cts, int             *headp)
{
    win_T       *wp = cts->cts_win;
    char_u      *s = cts->cts_ptr;
    colnr_T     col = cts->cts_vcol;
    int         n;

    if (*s == TAB && (!wp-> w_onebuf_opt.wo_list  || wp->w_lcs_chars.tab1))
    {
        n = wp->w_buffer->b_p_ts;
        return (int)(n - (col % n));
    }
    n = ptr2cells(s);
    if (n == 2 &&  mb_bytelen_tab[*s]  > 1 && in_win_border(wp, col))
    {
        if (headp != NULL)
        {
            *headp = 1;
        }
        return 3;
    }
    return n;
}

    static int
in_win_border(win_T *wp, colnr_T vcol)
{
    int         width1;
    int         width2;

    if (wp->w_width == 0)
    {
        return FALSE;
    }
    width1 = wp->w_width - win_col_off(wp);
    if ((int)vcol < width1 - 1)
    {
        return FALSE;
    }
    if ((int)vcol == width1 - 1)
    {
        return TRUE;
    }
    width2 = width1 + win_col_off2(wp);
    if (width2 <= 0)
    {
        return FALSE;
    }
    return ((vcol - width1) % width2 == width2 - 1);
}

    static void
getvcol(win_T       *wp, pos_T       *pos, colnr_T     *start, colnr_T     *cursor, colnr_T     *end, int         flags)
{
    colnr_T     vcol;
    char_u      *ptr;
    char_u      *line;
    int         incr;
    int         head;
    int         tail;
    int         ts = wp->w_buffer->b_p_ts;
    int         c;
    chartabsize_T cts;

    vcol = 0;
    line = ptr = ml_get_buf(wp->w_buffer, pos->lnum, FALSE);

    init_chartabsize_arg(&cts, wp, pos->lnum, 0, line, line);
    cts.cts_max_head_vcol = -1;

    if ((!wp-> w_onebuf_opt.wo_list  || wp->w_lcs_chars.tab1 != NUL))
    {
        for (;;)
        {
            head = 0;
            c = *ptr;
            if (c == NUL)
            {
                incr = 1;
                break;
            }
            if (c == TAB)
            {
                incr = ts - (vcol % ts);
            }
            else
            {
                if (c >= 0x80)
                {
                    incr = utf_ptr2cells(ptr);
                }
                else
                {
                    incr = g_chartab[c] & CT_CELL_MASK;
                }

                if (incr == 2 && wp-> w_onebuf_opt.wo_wrap  &&  mb_bytelen_tab[*ptr]  > 1 && in_win_border(wp, vcol))
                {
                    ++incr;
                    head = 1;
                }
            }

            char_u *next_ptr = ptr + utfc_ptr2len(ptr);
            if (next_ptr - line > pos->col)
            {
                break;
            }

            vcol += incr;
            ptr = next_ptr;
        }

        tail = 0;
    }
    else
    {
        for (;;)
        {
            head = 0;
            tail = 0;
            incr = win_lbr_chartabsize(&cts, &head, &tail);
            if (*cts.cts_ptr == NUL)
            {
                incr = 1;
                break;
            }

            char_u *next_ptr = cts.cts_ptr + utfc_ptr2len(cts.cts_ptr);
            if (next_ptr - line > pos->col)
            {
                break;
            }

            cts.cts_vcol += incr;
            cts.cts_ptr = next_ptr;
        }
        vcol = cts.cts_vcol;
        ptr = cts.cts_ptr;
    }

    if (*ptr == NUL && pos->col < MAXCOL && pos->col > ptr - line)
    {
        pos->col = ptr - line;
    }

    if (start != NULL)
    {
        *start = vcol + head;
    }
    if (end != NULL)
    {
        *end = vcol + incr - (flags & GETVCOL_END_EXCL_LBR ? tail : 0) - 1;
    }
    if (cursor != NULL)
    {
        if (*ptr == TAB && (State & MODE_NORMAL) && !wp-> w_onebuf_opt.wo_list  && !virtual_active() && !(VIsual_active && (*p_sel == 'e' ||  ( (((*pos).lnum != (VIsual).lnum)               ? (*pos).lnum < (VIsual).lnum                   : (*pos).col != (VIsual).col                        ? (*pos).col < (VIsual).col                     : (*pos).coladd < (VIsual).coladd)  ||  (((*pos).lnum == (VIsual).lnum) && ((*pos).col == (VIsual).col) && ((*pos).coladd == (VIsual).coladd)) ) )))
        {
            *cursor = vcol + incr - 1;
        }
        else
        {
            *cursor = vcol + head;
        }
    }
}

    static colnr_T
getvcol_nolist(pos_T *posp)
{
    int         list_save = curwin-> w_onebuf_opt.wo_list ;
    colnr_T     vcol;

    curwin-> w_onebuf_opt.wo_list  = FALSE;
    if (posp->coladd)
    {
        getvvcol(curwin, posp, NULL, &vcol, NULL, 0);
    }
    else
    {
        getvcol(curwin, posp, NULL, &vcol, NULL, 0);
    }
    curwin-> w_onebuf_opt.wo_list  = list_save;
    return vcol;
}

    static void
getvvcol(win_T       *wp, pos_T       *pos, colnr_T     *start, colnr_T     *cursor, colnr_T     *end, int         flags)
{
    colnr_T     col;
    colnr_T     coladd;
    colnr_T     endadd;
    char_u      *ptr;

    if (virtual_active())
    {
        getvcol(wp, pos, &col, NULL, NULL, flags);

        coladd = pos->coladd;
        endadd = 0;
        ptr = ml_get_buf(wp->w_buffer, pos->lnum, FALSE);
        if (pos->col < ml_get_buf_len(wp->w_buffer, pos->lnum))
        {
            int c = utf_ptr2char(ptr + pos->col);

            if (c != TAB && vim_isprintc(c))
            {
                endadd = (colnr_T)(char2cells(c) - 1);
                if (coladd > endadd)
                {
                    endadd = 0;
                }
                else
                {
                    coladd = 0;
                }
            }
        }
        col += coladd;
        if (start != NULL)
        {
            *start = col;
        }
        if (cursor != NULL)
        {
            *cursor = col;
        }
        if (end != NULL)
        {
            *end = col + endadd;
        }
    }
    else
    {
        getvcol(wp, pos, start, cursor, end, flags);
    }
}

    static void
getvcols(win_T       *wp, pos_T       *pos1, pos_T       *pos2, colnr_T     *left, colnr_T     *right, int         flags)
{
    colnr_T from1;
    colnr_T from2;
    colnr_T to1;
    colnr_T to2;

    if ( (((pos1)->lnum != (pos2)->lnum)                    ? (pos1)->lnum < (pos2)->lnum                 : (pos1)->col != (pos2)->col                      ? (pos1)->col < (pos2)->col                   : (pos1)->coladd < (pos2)->coladd) )
    {
        getvvcol(wp, pos1, &from1, NULL, &to1, flags);
        getvvcol(wp, pos2, &from2, NULL, &to2, flags);
    }
    else
    {
        getvvcol(wp, pos2, &from1, NULL, &to1, flags);
        getvvcol(wp, pos1, &from2, NULL, &to2, flags);
    }
    if (from2 < from1)
    {
        *left = from2;
    }
    else
    {
        *left = from1;
    }
    if (to2 > to1)
    {
        if (*p_sel == 'e' && from2 - 1 >= to1)
        {
            *right = from2 - 1;
        }
        else
        {
            *right = to2;
        }
    }
    else
    {
        *right = to1;
    }
}

    static char_u *
skipwhite(char_u *q)
{
    char_u      *p = q;

    while ( ((*p) == ' ' || (*p) == '\t') )
    {
        ++p;
    }
    return p;
}

    static int
getwhitecols_curline(void)
{
    return getwhitecols(ml_get_curline());
}

    static int
getwhitecols(char_u *p)
{
    return skipwhite(p) - p;
}

    static char_u *
skipdigits(char_u *q)
{
    char_u      *p = q;

    while ( ((unsigned)(*p) - '0' < 10) )
    {
        ++p;
    }
    return p;
}

    static int
vim_isdigit(int c)
{
    return (c >= '0' && c <= '9');
}

    static int
vim_isxdigit(int c)
{
    return (c >= '0' && c <= '9')
        || (c >= 'a' && c <= 'f')
        || (c >= 'A' && c <= 'F');
}

    static int
vim_isbdigit(int c)
{
    return (c == '0' || c == '1');
}

    static int
vim_isodigit(int c)
{
    return (c >= '0' && c <= '7');
}

enum { LATIN1LOWER = 'l' };
