    static int
vim_islower(int c)
{
    if (c <= '@')
    {
        return FALSE;
    }
    if (c >= 0x80)
    {
        return utf_islower(c);
        if (c >= 0x100)
        {
            return FALSE;
        }
        return (latin1flags[c] & LATIN1LOWER) == LATIN1LOWER;
    }
    return  (islower ((unsigned char)(c))) ;
}

    static int
vim_isupper(int c)
{
    if (c <= '@')
    {
        return FALSE;
    }
    if (c >= 0x80)
    {
        return utf_isupper(c);
        if (c >= 0x100)
        {
            return iswupper(c);
            return FALSE;
        }
        return (latin1flags[c] & LATIN1UPPER) == LATIN1UPPER;
    }
    return  (isupper ((unsigned char)(c))) ;
}

    static int
vim_toupper(int c)
{
    if (c <= '@')
    {
        return c;
    }
    if (c >= 0x80 || !(cmp_flags & CMP_KEEPASCII))
    {
        return utf_toupper(c);
        if (c >= 0x100)
        {
            return towupper(c);
            return c;
        }
        return latin1upper[c];
    }
    if (c < 0x80 && (cmp_flags & CMP_KEEPASCII))
    {
        return  (((c) < 'a' || (c) > 'z') ? (c) : (c) - ('a' - 'A')) ;
    }
    return   (toupper ((unsigned char)(c))) ;
}

    static int
vim_tolower(int c)
{
    if (c <= '@')
    {
        return c;
    }
    if (c >= 0x80 || !(cmp_flags & CMP_KEEPASCII))
    {
        return utf_tolower(c);
        if (c >= 0x100)
        {
            return towlower(c);
            return c;
        }
        return latin1lower[c];
    }
    if (c < 0x80 && (cmp_flags & CMP_KEEPASCII))
    {
        return  (((c) < 'A' || (c) > 'Z') ? (c) : (c) + ('a' - 'A')) ;
    }
    return   (tolower ((unsigned char)(c))) ;
}

    static char_u *
skiptowhite(char_u *p)
{
    while (*p != ' ' && *p != '\t' && *p != NUL)
    {
        ++p;
    }
    return p;
}

    static long
getdigits(char_u **pp)
{
    char_u      *p;
    long        retval;

    p = *pp;
    retval = atol((char *)p);
    if (*p == '-')
    {
        ++p;
    }
    p = skipdigits(p);
    *pp = p;
    return retval;
}

    static long
getdigits_quoted(char_u **pp)
{
    char_u      *p = *pp;
    long        retval = 0;

    if (*p == '-')
    {
        ++p;
    }
    while ( ((unsigned)(*p) - '0' < 10) )
    {
        if (retval >= LONG_MAX / 10 - 10)
        {
            retval = LONG_MAX;
        }
        else
        {
            retval = retval * 10 - '0' + *p;
        }
        ++p;
    }
    if (**pp == '-')
    {
        if (retval == LONG_MAX)
        {
            retval = LONG_MIN;
        }
        else
        {
            retval = -retval;
        }
    }
    *pp = p;
    return retval;
}

    static void
vim_str2nr(char_u              *start, int                 *prep, int                 *len, int                 what, varnumber_T         *nptr, uvarnumber_T        *unptr, int                 maxlen, int                 strict, int                 *overflow)
{
    char_u          *ptr = start;
    int             pre = 0;
    int             negative = FALSE;
    uvarnumber_T    un = 0;
    int             n;

    if (len != NULL)
    {
        *len = 0;
    }

    if (ptr[0] == '-')
    {
        negative = TRUE;
        ++ptr;
    }

    if (ptr[0] == '0' && ptr[1] != '8' && ptr[1] != '9' && (maxlen == 0 || maxlen > 1))
    {
        pre = ptr[1];
        if ((what & STR2NR_HEX) && (pre == 'X' || pre == 'x') && vim_isxdigit(ptr[2]) && (maxlen == 0 || maxlen > 2))
        {
            ptr += 2;
        }
        else if ((what & STR2NR_BIN) && (pre == 'B' || pre == 'b') && vim_isbdigit(ptr[2]) && (maxlen == 0 || maxlen > 2))
        {
            ptr += 2;
        }
        else if ((what & STR2NR_OOCT) && (pre == 'O' || pre == 'o') && vim_isodigit(ptr[2]) && (maxlen == 0 || maxlen > 2))
        {
            ptr += 2;
        }
        else
        {
            pre = 0;
            if (what & STR2NR_OCT)
            {
                for (n = 1; n != maxlen &&  ((unsigned)(ptr[n]) - '0' < 10) ; ++n)
                {
                    if (ptr[n] > '7')
                    {
                        pre = 0;
                        break;
                    }
                    pre = '0';
                }
            }
        }
    }

    n = 1;
    if (pre == 'B' || pre == 'b' || ((what & STR2NR_BIN) && (what & STR2NR_FORCE)))
    {
        if (pre != 0)
        {
            n += 2;
        }
        while ('0' <= *ptr && *ptr <= '1')
        {
            if (un <=  ULLONG_MAX  / 2)
            {
                un = 2 * un + (uvarnumber_T)(*ptr - '0');
            }
            else
            {
                un =  ULLONG_MAX ;
                if (overflow != NULL)
                {
                    *overflow = TRUE;
                }
            }
            ++ptr;
            if (n++ == maxlen)
            {
                break;
            }
            if ((what & STR2NR_QUOTE) && *ptr == '\'' && '0' <= ptr[1] && ptr[1] <= '1')
            {
                ++ptr;
                if (n++ == maxlen)
                {
                    break;
                }
            }
        }
    }
    else if (pre == 'O' || pre == 'o' || pre == '0' || ((what & STR2NR_OCT) && (what & STR2NR_FORCE)))
    {
        if (pre != 0 && pre != '0')
        {
            n += 2;
        }
        while ('0' <= *ptr && *ptr <= '7')
        {
            if (un <=  ULLONG_MAX  / 8)
            {
                un = 8 * un + (uvarnumber_T)(*ptr - '0');
            }
            else
            {
                un =  ULLONG_MAX ;
                if (overflow != NULL)
                {
                    *overflow = TRUE;
                }
            }
            ++ptr;
            if (n++ == maxlen)
            {
                break;
            }
            if ((what & STR2NR_QUOTE) && *ptr == '\'' && '0' <= ptr[1] && ptr[1] <= '7')
            {
                ++ptr;
                if (n++ == maxlen)
                {
                    break;
                }
            }
        }
    }
    else if (pre != 0 || ((what & STR2NR_HEX) && (what & STR2NR_FORCE)))
    {
        if (pre != 0)
        {
            n += 2;
        }
        while (vim_isxdigit(*ptr))
        {
            if (un <=  ULLONG_MAX  / 16)
            {
                un = 16 * un + (uvarnumber_T)hex2nr(*ptr);
            }
            else
            {
                un =  ULLONG_MAX ;
                if (overflow != NULL)
                {
                    *overflow = TRUE;
                }
            }
            ++ptr;
            if (n++ == maxlen)
            {
                break;
            }
            if ((what & STR2NR_QUOTE) && *ptr == '\'' && vim_isxdigit(ptr[1]))
            {
                ++ptr;
                if (n++ == maxlen)
                {
                    break;
                }
            }
        }
    }
    else
    {
        while ( ((unsigned)(*ptr) - '0' < 10) )
        {
            uvarnumber_T    digit = (uvarnumber_T)(*ptr - '0');

            if (un <  ULLONG_MAX  / 10 || (un ==  ULLONG_MAX  / 10 && digit <=  ULLONG_MAX  % 10))
            {
                un = 10 * un + digit;
            }
            else
            {
                un =  ULLONG_MAX ;
                if (overflow != NULL)
                {
                    *overflow = TRUE;
                }
            }
            ++ptr;
            if (n++ == maxlen)
            {
                break;
            }
            if ((what & STR2NR_QUOTE) && *ptr == '\'' &&  ((unsigned)(ptr[1]) - '0' < 10) )
            {
                ++ptr;
                if (n++ == maxlen)
                {
                    break;
                }
            }
        }
    }

    if (strict && n - 1 != maxlen &&  ( ( ((unsigned)(*ptr) - 'A' < 26)  ||  ((unsigned)(*ptr) - 'a' < 26) )  ||  ((unsigned)(*ptr) - '0' < 10) ) )
    {
        return;
    }

    if (prep != NULL)
    {
        *prep = pre;
    }
    if (len != NULL)
    {
        *len = (int)(ptr - start);
    }
    if (nptr != NULL)
    {
        if (negative)
        {
            if (un >  LLONG_MAX )
            {
                *nptr =  LLONG_MIN ;
                if (overflow != NULL)
                {
                    *overflow = TRUE;
                }
            }
            else
            {
                *nptr = -(varnumber_T)un;
            }
        }
        else
        {
            if (un >  LLONG_MAX )
            {
                un =  LLONG_MAX ;
                if (overflow != NULL)
                {
                    *overflow = TRUE;
                }
            }
            *nptr = (varnumber_T)un;
        }
    }
    if (unptr != NULL)
    {
        *unptr = un;
    }
}

    static int
hex2nr(int c)
{
    if (c >= 'a' && c <= 'f')
    {
        return c - 'a' + 10;
    }
    if (c >= 'A' && c <= 'F')
    {
        return c - 'A' + 10;
    }
    return c - '0';
}

    static int
hexhex2nr(char_u *p)
{
    if (!vim_isxdigit(p[0]) || !vim_isxdigit(p[1]))
    {
        return -1;
    }
    return (hex2nr(p[0]) << 4) + hex2nr(p[1]);
}

    static int
rem_backslash(char_u *str)
{
    return (str[0] == '\\' && str[1] != NUL);
}

    static void
backslash_halve(char_u *p)
{
    for ( ; *p; ++p)
    {
        if (rem_backslash(p))
        {
              memmove((char *)((p)), (char *)((p + 1)),  strlen((char *)(p + 1))  + 1)  ;
        }
    }
}

    static char_u *
skip_string(char_u *p)
{
    int     i;

    for ( ; ; ++p)
    {
        if (p[0] == '\'')
        {
            if (p[1] == NUL)
            {
                break;
            }
            i = 2;
            if (p[1] == '\\' && p[2] != NUL)
            {
                ++i;
                while (vim_isdigit(p[i - 1]))
                {
                    ++i;
                }
            }
            if (p[i - 1] != NUL && p[i] == '\'')
            {
                p += i;
                continue;
            }
        }
        else if (p[0] == '"')
        {
            for (++p; p[0]; ++p)
            {
                if (p[0] == '\\' && p[1] != NUL)
                {
                    ++p;
                }
                else if (p[0] == '"')
                {
                    break;
                }
            }
            if (p[0] == '"')
            {
                continue;
            }
        }
        else if (p[0] == 'R' && p[1] == '"')
        {
            char_u *delim = p + 2;
            char_u *paren = vim_strchr(delim, '(');

            if (paren != NULL)
            {
                size_t delim_len = paren - delim;

                for (p += 3; *p; ++p)
                {
                    if (p[0] == ')' &&  strncmp((char *)(p + 1), (char *)(delim), (delim_len))  == 0 && p[delim_len + 1] == '"')
                    {
                        p += delim_len + 1;
                        break;
                    }
                }
                if (p[0] == '"')
                {
                    continue;
                }
            }
        }
        break;
    }
    if (!*p)
    {
        --p;
    }
    return p;
}

    static int
check_linecomment(char_u *line)
{
    char_u  *p;

    p = line;
    for ( ; *p != NUL; ++p)
    {
        p = skip_string(p);
        if (*p == NUL)
        {
            break;
        }
        if (p[0] == '/' && p[1] == '/' && (p == line || p[-1] != '*' || p[2] != '*'))
        {
            break;
        }
    }
    if (*p == NUL)
    {
        p = NULL;
    }

    if (p == NULL)
    {
        return MAXCOL;
    }
    return (int)(p - line);
}

static int      ExpandFromContext(expand_T *xp, char_u *, char_u ***, int *, int);

static string_T cmdline_orig = {NULL, 0};

    static void
wildescape(expand_T    *xp, char_u      *str, int         numfiles, char_u      **files)
{
    char_u      *p;
    int         vse_what = xp->xp_context == EXPAND_BUFFERS
                                                       ? VSE_BUFFER : VSE_NONE;

    if (xp->xp_context == EXPAND_FILES || xp->xp_context == EXPAND_FILES_IN_PATH || xp->xp_context == EXPAND_SHELLCMD || xp->xp_context == EXPAND_BUFFERS || xp->xp_context == EXPAND_DIRECTORIES || xp->xp_context == EXPAND_DIRS_IN_CDPATH)
    {
        for (int i = 0; i < numfiles; ++i)
        {
            if (xp->xp_backslash & XP_BS_THREE)
            {
                char *pat = (xp->xp_backslash & XP_BS_COMMA) ?  " ," : " ";
                p = vim_strsave_escaped(files[i], (char_u *)pat);
                if (p != NULL)
                {
                    vim_free(files[i]);
                    files[i] = p;
                }
            }
            else if (xp->xp_backslash & XP_BS_COMMA)
            {
                if (vim_strchr(files[i], ',') != NULL)
                {
                    p = vim_strsave_escaped(files[i], (char_u *)",");
                    if (p != NULL)
                    {
                        vim_free(files[i]);
                        files[i] = p;
                    }
                }
            }
            p = vim_strsave_fnameescape(files[i], xp->xp_shell ? VSE_SHELL : vse_what);
            if (p != NULL)
            {
                vim_free(files[i]);
                files[i] = p;
            }

            if (str[0] == '\\' && str[1] == '~' && files[i][0] == '~')
            {
                escape_fname(&files[i]);
            }
        }
        xp->xp_backslash = XP_BS_NONE;

        if (*files[0] == '+')
        {
            escape_fname(&files[0]);
        }
    }
    else if (xp->xp_context == EXPAND_TAGS)
    {
        for (int i = 0; i < numfiles; ++i)
        {
            p = vim_strsave_escaped(files[i], (char_u *)"\\|\"");
            if (p != NULL)
            {
                vim_free(files[i]);
                files[i] = p;
            }
        }
    }
}

    static void
ExpandEscape(expand_T    *xp, char_u      *str, int         numfiles, char_u      **files, int         options)
{
    if (options & WILD_HOME_REPLACE)
    {
        tilde_replace(str, numfiles, files);
    }

    if (options & WILD_ESCAPE)
    {
        wildescape(xp, str, numfiles, files);
    }
}

    static char_u *
ExpandOne_start(int mode, expand_T *xp, char_u *str, int options)
{
    int         non_suf_match;
    char_u      *ss = NULL;

    if (ExpandFromContext(xp, str, &xp->xp_files, &xp->xp_numfiles, options) == FAIL)
    {
    }
    else if (xp->xp_numfiles == 0)
    {
        if (!(options & WILD_SILENT))
        {
            semsg(_(e_no_match_str_2), str);
        }
    }
    else
    {
        ExpandEscape(xp, str, xp->xp_numfiles, xp->xp_files, options);

        if (mode != WILD_ALL && mode != WILD_ALL_KEEP && mode != WILD_LONGEST)
        {
            if (xp->xp_numfiles)
            {
                non_suf_match = xp->xp_numfiles;
            }
            else
            {
                non_suf_match = 1;
            }
            if ((xp->xp_context == EXPAND_FILES || xp->xp_context == EXPAND_DIRECTORIES) && xp->xp_numfiles > 1)
            {
                non_suf_match = 0;
            }
            if (non_suf_match != 1)
            {
                if (!(options & WILD_SILENT))
                {
                    emsg(_(e_too_many_file_names));
                }
                else if (!(options & WILD_NO_BEEP))
                {
                    beep_flush();
                }
            }
            if (!(non_suf_match != 1 && mode == WILD_EXPAND_FREE))
            {
                ss = vim_strsave(xp->xp_files[0]);
            }
        }
    }

    return ss;
}

    static void
free_xp_files_extra(expand_T *xp, int numfiles)
{
    if (xp->xp_files_abbr != NULL)
    {
        FreeWild(numfiles, xp->xp_files_abbr);
        xp->xp_files_abbr = NULL;
    }
    if (xp->xp_files_kind != NULL)
    {
        FreeWild(numfiles, xp->xp_files_kind);
        xp->xp_files_kind = NULL;
    }
    if (xp->xp_files_menu != NULL)
    {
        FreeWild(numfiles, xp->xp_files_menu);
        xp->xp_files_menu = NULL;
    }
    if (xp->xp_files_info != NULL)
    {
        FreeWild(numfiles, xp->xp_files_info);
        xp->xp_files_info = NULL;
    }
}

    static char_u *
ExpandOne(expand_T    *xp, char_u      *str, char_u      *orig, int         options, int         mode)
{
    char_u      *ss = NULL;
    int         orig_saved = FALSE;

    if (mode == WILD_APPLY)
    {
        if (xp->xp_selected == -1)
        {
            ss = vim_strsave(xp->xp_orig ? xp->xp_orig : (char_u *)"");
        }
        else
        {
            ss = vim_strsave(xp->xp_files[xp->xp_selected]);
        }
    }

    if (xp->xp_numfiles != -1 && mode != WILD_ALL && mode != WILD_LONGEST)
    {
        FreeWild(xp->xp_numfiles, xp->xp_files);
        free_xp_files_extra(xp, xp->xp_numfiles);
        xp->xp_numfiles = -1;
         vim_free(xp->xp_orig);
         (xp->xp_orig) = NULL;

    }
    xp->xp_selected = (options & WILD_NOSELECT) ? -1 : 0;

    if (xp->xp_numfiles == -1 && mode != WILD_APPLY && mode != WILD_CANCEL)
    {
        vim_free(xp->xp_orig);
        xp->xp_orig = orig;
        orig_saved = TRUE;

        ss = ExpandOne_start(mode, xp, str, options);
    }

    ExpandCleanup(xp);

    if (!orig_saved)
    {
        vim_free(orig);
    }

    return ss;
}

    static void
ExpandInit(expand_T *xp)
{
      memset(((xp)), (0), (sizeof(*(xp))))  ;
    xp->xp_backslash = XP_BS_NONE;
    xp->xp_prefix = XP_PREFIX_NONE;
    xp->xp_numfiles = -1;
}

    static void
ExpandCleanup(expand_T *xp)
{
    if (xp->xp_numfiles >= 0)
    {
        free_xp_files_extra(xp, xp->xp_numfiles);
        FreeWild(xp->xp_numfiles, xp->xp_files);
        xp->xp_numfiles = -1;
    }
     vim_free(xp->xp_orig);
     (xp->xp_orig) = NULL;
}

    static void
clear_cmdline_orig(void)
{
     vim_free(cmdline_orig.string);
     (cmdline_orig.string) = NULL;
     cmdline_orig.length = 0;
}

    static int
expand_files_and_dirs(expand_T        *xp, char_u          *pat, char_u          ***matches, int             *numMatches, int             flags, int             options)
{
    int         free_pat = FALSE;
    int         ret = FAIL;

    if (xp->xp_backslash != XP_BS_NONE)
    {
        size_t  pat_len;
        char_u  *pat_end;
        char_u  *p;

        free_pat = TRUE;

        pat_len =  strlen((char *)(pat)) ;
        pat = vim_strnsave(pat, pat_len);
        if (pat == NULL)
        {
            return ret;
        }

        pat_end = pat + pat_len;
        for (p = pat; *p != NUL; ++p)
        {
            char_u  *from;

            if (*p != '\\')
            {
                continue;
            }

            if (xp->xp_backslash & XP_BS_THREE && *(p + 1) == '\\' && *(p + 2) == '\\' && *(p + 3) == ' ')
            {
                from = p + 3;
                 memmove((char *)(p), (char *)(from), (size_t)(pat_end - from) + 1) ;
                pat_end -= 3;
            }
            else if (xp->xp_backslash & XP_BS_ONE && *(p + 1) == ' ')
            {
                from = p + 1;
                 memmove((char *)(p), (char *)(from), (size_t)(pat_end - from) + 1) ;
                --pat_end;
            }
            else if (xp->xp_backslash & XP_BS_COMMA)
            {
                if (*(p + 1) == '\\' && *(p + 2) == ',')
                {
                    from = p + 2;
                     memmove((char *)(p), (char *)(from), (size_t)(pat_end - from) + 1) ;
                    pat_end -= 2;
                }
            }
        }
    }

    if (xp->xp_context == EXPAND_FINDFUNC)
    {
    }
    else
    {
        if (xp->xp_context == EXPAND_FILES)
        {
            flags |= EW_FILE;
        }
        else if (xp->xp_context == EXPAND_FILES_IN_PATH)
        {
            flags |= (EW_FILE | EW_PATH);
        }
        else if (xp->xp_context == EXPAND_DIRS_IN_CDPATH)
        {
            flags = (flags | EW_DIR | EW_CDPATH) & ~EW_FILE;
        }
        else
        {
            flags = (flags | EW_DIR) & ~EW_FILE;
        }
        if (options & WILD_ICASE)
        {
            flags |= EW_ICASE;
        }

        ret = expand_wildcards_eval(&pat, numMatches, matches, flags);
    }
    if (free_pat)
    {
        vim_free(pat);
    }
    return ret;
}

    static int
map_wildopts_to_ewflags(int options)
{
    int         flags;

    flags = EW_DIR;
    if (options & WILD_LIST_NOTFOUND)
    {
        flags |= EW_NOTFOUND;
    }
    if (options & WILD_ADD_SLASH)
    {
        flags |= EW_ADDSLASH;
    }
    if (options & WILD_KEEP_ALL)
    {
        flags |= EW_KEEPALL;
    }
    if (options & WILD_SILENT)
    {
        flags |= EW_SILENT;
    }
    if (options & WILD_NOERROR)
    {
        flags |= EW_NOERROR;
    }
    if (options & WILD_ALLLINKS)
    {
        flags |= EW_ALLLINKS;
    }

    return flags;
}

    static int
ExpandFromContext(expand_T    *xp, char_u      *pat, char_u      ***matches, int         *numMatches, int         options)
{
    int         flags;

    flags = map_wildopts_to_ewflags(options);

    return expand_files_and_dirs(xp, pat, matches, numMatches, flags, options);

}

static histentry_T *(history[HIST_COUNT]) = {NULL, NULL, NULL, NULL, NULL};
static int      hisidx[HIST_COUNT] = {-1, -1, -1, -1, -1};
static int      hisnum[HIST_COUNT] = {0, 0, 0, 0, 0};
static int      hislen = 0;

    static int
get_hislen(void)
{
    return hislen;
}

    static histentry_T *
get_histentry(int hist_type)
{
    return history[hist_type];
}

    static int *
get_hisidx(int hist_type)
{
    return &hisidx[hist_type];
}

    static int
hist_char2type(int c)
{
    if (c == ':')
    {
        return HIST_CMD;
    }
    if (c == '=')
    {
        return HIST_EXPR;
    }
    if (c == '@')
    {
        return HIST_INPUT;
    }
    if (c == '>')
    {
        return HIST_DEBUG;
    }
    return HIST_SEARCH;
}

static char *(history_names[]) =
{
    "cmd",
    "search",
    "expr",
    "input",
    NULL
};

    static void
init_history(void)
{
    int         newlen;
    histentry_T *temp;
    int         type;

    newlen = (int)p_hi;
    if (newlen == hislen)
    {
        return;
    }

    for (type = 0; type < HIST_COUNT; ++type)
    {
        if (newlen > 0)
        {
            temp =  (histentry_T *)alloc(sizeof(histentry_T) * (newlen)) ;
            if (temp == NULL)
            {
                if (type == 0)
                {
                    newlen = hislen;
                    break;
                }
                newlen = 0;
                type = -1;
                continue;
            }
        }
        else
        {
            temp = NULL;
        }

        if (hisidx[type] < 0)
        {
            int i;

            for (i = 0; i < newlen; ++i)
            {
                clear_hist_entry(&temp[i]);
            }
        }
        else if (newlen > hislen)
        {
            int i;
            int j;

            for (i = 0; i <= hisidx[type]; ++i)
            {
                temp[i] = history[type][i];
            }
            j = i;
            for ( ; i <= newlen - (hislen - hisidx[type]); ++i)
            {
                clear_hist_entry(&temp[i]);
            }
            for ( ; j < hislen; ++i, ++j)
            {
                temp[i] = history[type][j];
            }
        }
        else
        {
            int i;
            int j;

            j = hisidx[type];
            for (i = newlen - 1; ; --i)
            {
                if (i >= 0)
                {
                    temp[i] = history[type][j];
                }
                else
                {
                    vim_free(history[type][j].hisstr);
                    history[type][j].hisstrlen = 0;
                }
                if (--j < 0)
                {
                    j = hislen - 1;
                }
                if (j == hisidx[type])
                {
                    break;
                }
            }
            hisidx[type] = newlen - 1;
        }
        vim_free(history[type]);
        history[type] = temp;
    }
    hislen = newlen;
}

    static void
clear_hist_entry(histentry_T *hisptr)
{
    hisptr->hisnum = 0;
    hisptr->viminfo = FALSE;
    hisptr->hisstr = NULL;
    hisptr->hisstrlen = 0;
    hisptr->time_set = 0;
}

    static int
in_history(int     type, char_u  *str, int     move_to_front, int     sep, int     writing)
{
    int     i;
    int     last_i = -1;
    char_u  *p;
    size_t  len;

    if (hisidx[type] < 0)
    {
        return FALSE;
    }
    i = hisidx[type];
    do
    {
        if (history[type][i].hisstr == NULL)
        {
            return FALSE;
        }

        p = history[type][i].hisstr;
        if ( strcmp((char *)(str), (char *)(p))  == 0 && !(writing && history[type][i].viminfo) && (type != HIST_SEARCH || sep == p[history[type][i].hisstrlen + 1]))
        {
            if (!move_to_front)
            {
                return TRUE;
            }
            last_i = i;
            break;
        }
        if (--i < 0)
        {
            i = hislen - 1;
        }
    } while (i != hisidx[type]);

    if (last_i < 0)
    {
        return FALSE;
    }

    str = history[type][i].hisstr;
    len = history[type][i].hisstrlen;
    while (i != hisidx[type])
    {
        if (++i >= hislen)
        {
            i = 0;
        }
        history[type][last_i] = history[type][i];
        last_i = i;
    }
    history[type][i].hisnum = ++hisnum[type];
    history[type][i].viminfo = FALSE;
    history[type][i].hisstr = str;
    history[type][i].hisstrlen = len;
    history[type][i].time_set = vim_time();
    return TRUE;
}

    static int
get_histtype(char_u *name)
{
    int         i;
    int         len = (int) strlen((char *)(name)) ;

    if (len == 0)
    {
        return hist_char2type(get_cmdline_firstc());
    }

    for (i = 0; history_names[i] != NULL; ++i)
    {
        if ( strncasecmp((char *)(name), (char *)(history_names[i]), (len))  == 0)
        {
            return i;
        }
    }

    if (vim_strchr((char_u *)":=@>?/", name[0]) != NULL && name[1] == NUL)
    {
        return hist_char2type(name[0]);
    }

    return -1;
}

static int      last_maptick = -1;

    static void
add_to_history(int         histype, char_u      *new_entry, size_t      new_entrylen, int         in_map, int         sep)
{
    histentry_T *hisptr;

    if (hislen == 0)
    {
        return;
    }

    if ((cmdmod.cmod_flags & CMOD_KEEPPATTERNS) && histype == HIST_SEARCH)
    {
        return;
    }

    if (histype == HIST_SEARCH && in_map)
    {
        if (maptick == last_maptick && hisidx[HIST_SEARCH] >= 0)
        {
            hisptr = &history[HIST_SEARCH][hisidx[HIST_SEARCH]];
            vim_free(hisptr->hisstr);
            clear_hist_entry(hisptr);
            --hisnum[histype];
            if (--hisidx[HIST_SEARCH] < 0)
            {
                hisidx[HIST_SEARCH] = hislen - 1;
            }
        }
        last_maptick = -1;
    }

    if (in_history(histype, new_entry, TRUE, sep, FALSE))
    {
        return;
    }

    if (++hisidx[histype] == hislen)
    {
        hisidx[histype] = 0;
    }
    hisptr = &history[histype][hisidx[histype]];
    vim_free(hisptr->hisstr);

    hisptr->hisstr = vim_strnsave(new_entry, new_entrylen + 2);
    if (hisptr->hisstr == NULL)
    {
        hisptr->hisstrlen = 0;
    }
    else
    {
        hisptr->hisstr[new_entrylen + 1] = sep;
        hisptr->hisstrlen = new_entrylen;
    }

    hisptr->hisnum = ++hisnum[histype];
    hisptr->viminfo = FALSE;
    hisptr->time_set = vim_time();
    if (histype == HIST_SEARCH && in_map)
    {
        last_maptick = maptick;
    }
}

    static void
ex_history(exarg_T *eap)
{
    histentry_T *hist;
    int         histype1 = HIST_CMD;
    int         histype2 = HIST_CMD;
    int         hisidx1 = 1;
    int         hisidx2 = -1;
    int         idx;
    int i;
    int j;
    int k;
    char_u      *end;
    char_u      *arg = eap->arg;

    if (hislen == 0)
    {
        msg(_("'history' option is zero"));
        return;
    }

    if (!( ((unsigned)(*arg) - '0' < 10)  || *arg == '-' || *arg == ','))
    {
        end = arg;
        while ( ( ((unsigned)(*end) - 'A' < 26)  ||  ((unsigned)(*end) - 'a' < 26) )  || vim_strchr((char_u *)":=@>/?", *end) != NULL)
        {
            end++;
        }
        i = *end;
        *end = NUL;
        histype1 = get_histtype(arg);
        if (histype1 == -1)
        {
            if ( strncasecmp((char *)(arg), (char *)("all"), ( strlen((char *)(arg)) ))  == 0)
            {
                histype1 = 0;
                histype2 = HIST_COUNT-1;
            }
            else
            {
                *end = i;
                semsg(_(e_trailing_characters_str), arg);
                return;
            }
        }
        else
        {
            histype2 = histype1;
        }
        *end = i;
    }
    else
    {
        end = arg;
    }
    if (!get_list_range(&end, &hisidx1, &hisidx2) || *end != NUL)
    {
        if (*end != NUL)
        {
            semsg(_(e_trailing_characters_str), end);
        }
        else
        {
            semsg(_(e_val_too_large), arg);
        }
        return;
    }

    for (; !got_int && histype1 <= histype2; ++histype1)
    {
        vim_snprintf((char *)IObuff,  (1024+1) , "\n      #  %s history", history_names[histype1]);
        msg_puts_title((char *)IObuff);
        idx = hisidx[histype1];
        hist = history[histype1];
        j = hisidx1;
        k = hisidx2;
        if (j < 0)
        {
            j = (-j > hislen) ? 0 : hist[(hislen + j + idx + 1) % hislen].hisnum;
        }
        if (k < 0)
        {
            k = (-k > hislen) ? 0 : hist[(hislen + k + idx + 1) % hislen].hisnum;
        }
        if (idx >= 0 && j <= k)
        {
            for (i = idx + 1; !got_int; ++i)
            {
                if (i == hislen)
                {
                    i = 0;
                }
                if (hist[i].hisstr != NULL && hist[i].hisnum >= j && hist[i].hisnum <= k && !message_filtered(hist[i].hisstr))
                {
                    int  len;

                    msg_putchar('\n');
                    len = vim_snprintf((char *)IObuff,  (1024+1) , "%c%6d  ", i == idx ? '>' : ' ', hist[i].hisnum);
                    if (vim_strsize(hist[i].hisstr) > (int)Columns - 10)
                    {
                        trunc_string(hist[i].hisstr, IObuff + len, (int)Columns - 10,  (1024+1)  - (int)len);
                    }
                    else
                    {
                         strcpy((char *)(IObuff + len), (char *)(hist[i].hisstr)) ;
                    }
                    msg_outtrans(IObuff);
                    out_flush();
                }
                if (i == idx)
                {
                    break;
                }
            }
        }
    }
}

    static int
get_lcs_ext(win_T *wp)
{
    if (wp-> w_onebuf_opt.wo_wrap )
    {
        return NUL;
    }
    if (wp-> w_onebuf_opt.wo_wrap_flags  & P_INSECURE)
    {
        return '>';
    }
    return wp-> w_onebuf_opt.wo_list  ? wp->w_lcs_chars.ext : NUL;
}

