static void win_update(win_T *wp);
static int  did_update_one_window;

    static int
update_screen(int type_arg)
{
    int         type = type_arg;
    win_T       *wp;
    static int  did_intro = FALSE;
    int         no_update = FALSE;
    int         save_pum_will_redraw = pum_will_redraw;
    bool        override_success;

    if (!screen_valid(TRUE))
    {
        return FAIL;
    }

    if (type == UPD_VALID_NO_UPDATE)
    {
        no_update = TRUE;
        type = 0;
    }

    if (must_redraw)
    {
        if (type < must_redraw)
        {
            type = must_redraw;
        }

        must_redraw = 0;
    }

    if (curwin->w_lines_valid == 0 && type < UPD_NOT_VALID)
    {
        type = UPD_NOT_VALID;
    }

    if (!redrawing() || updating_screen)
    {
        redraw_later(type);
        must_redraw = type;
        if (type > UPD_INVERTED_ALL)
        {
            curwin->w_lines_valid = 0;
        }
        return FAIL;
    }
    updating_screen = TRUE;

    int hid_cursor = !sync_output_active();
    if (hid_cursor)
    {
        cursor_off();
    }
    term_set_sync_output(TERM_SYNC_OUTPUT_ENABLE);

    if (no_update)
    {
        ++no_win_do_lines_ins;
    }

    if (msg_scrolled)
    {
        clear_cmdline = TRUE;
        if (type != UPD_CLEAR)
        {
            if (msg_scrolled > Rows - 5)
            {
                type = UPD_NOT_VALID;
                redraw_as_cleared();
            }
            else
            {
                check_for_delay(FALSE);
                if (screen_ins_lines(0, 0, msg_scrolled, (int)Rows, 0, NULL) == FAIL)
                {
                    type = UPD_NOT_VALID;
                    redraw_as_cleared();
                }
                 wp = curwin;
                if (wp->w_winrow < msg_scrolled)
                {
                    if ( (wp->w_winrow)  + wp->w_height > msg_scrolled && wp->w_redr_type < UPD_REDRAW_TOP && wp->w_lines_valid > 0 && wp->w_topline == wp->w_lines[0].wl_lnum)
                    {
                        wp->w_upd_rows = msg_scrolled -  (wp->w_winrow) ;
                        wp->w_redr_type = UPD_REDRAW_TOP;
                    }
                    else
                    {
                        wp->w_redr_type = UPD_NOT_VALID;
                        if ( (wp->w_winrow)  + wp->w_height + wp->w_status_height <= msg_scrolled)
                        {
                            wp->w_redr_status = true;
                        }
                    }
                }
                if (!no_update)
                {
                    redraw_cmdline = TRUE;
                }
                redraw_tabline = TRUE;
            }
        }
        msg_scrolled = 0;
        need_wait_return = FALSE;
    }

    compute_cmdrow();

    if (need_highlight_changed)
    {
        highlight_changed();
    }

    if (type == UPD_CLEAR)
    {
        screenclear();
        type = UPD_NOT_VALID;
        must_redraw = 0;
    }

    if (clear_cmdline)
    {
        check_for_delay(FALSE);
    }

    if (type == UPD_INVERTED)
    {
        update_curswant();
    }
    if (curwin->w_redr_type < type && !((type == UPD_VALID && curwin->w_lines[0].wl_valid && curwin->w_topline == curwin->w_lines[0].wl_lnum) || (type == UPD_INVERTED && VIsual_active && curwin->w_old_cursor_lnum == curwin->w_cursor.lnum && curwin->w_old_visual_mode == VIsual_mode && (curwin->w_valid & VALID_VIRTCOL) && curwin->w_old_curswant == curwin->w_curswant)))
    {
        curwin->w_redr_type = type;
    }

    if (redraw_tabline || type >= UPD_NOT_VALID)
    {
        draw_tabline();
    }

    did_update_one_window = FALSE;
    screen_search_hl.rm.regprog = NULL;
     wp = curwin;
    override_success = push_highlight_overrides(wp->w_hl, wp->w_hl_len);

    if (wp->w_redr_type != 0)
    {
        cursor_off();
        win_update(wp);
    }

    if (wp->w_redr_status)
    {
        cursor_off();
        win_redr_status(wp, TRUE);
    }

    if (override_success)
    {
        pop_highlight_overrides();
    }

    end_search_hl();

    pum_will_redraw = save_pum_will_redraw;

    if (redraw_vseps)
    {
        redraw_vseps = FALSE;
         wp = curwin;
        if (wp->w_vsep_width > 0)
        {
            draw_vsep_win(wp, 0);
        }
    }

     wp = curwin;
    wp->w_buffer->b_mod_set = false;

    after_updating_screen(TRUE);

    if (clear_cmdline || redraw_cmdline || redraw_mode)
    {
        showmode();
    }

    if (no_update)
    {
        --no_win_do_lines_ins;
    }

    if (!did_intro)
    {
    }
    did_intro = TRUE;

    term_set_sync_output(TERM_SYNC_OUTPUT_DISABLE);
    if (hid_cursor)
    {
        cursor_on();
    }

    return OK;
}

    static int
statusline_row(win_T *wp)
{
    return  (wp->w_winrow)  + wp->w_height;
}

    static void
win_redr_status(win_T *wp, int ignore_pum  __attribute__((unused)) )
{
    int         row;
    int         fillchar;
    int         attr;
    int         i;
    static int  busy = FALSE;

    if (busy)
    {
        return;
    }
    busy = TRUE;

    row = statusline_row(wp);

    wp->w_redr_status = false;
    if (wp->w_status_height == 0)
    {
        redraw_cmdline = TRUE;
    }
    else if (!redrawing())
    {
        wp->w_redr_status = true;
    }
    else
    {
        char_u  *p;
        int     plen;
        int     this_ru_col;
        int     n;

        fillchar = fillchar_status(&attr, wp);

        get_trans_bufname(wp->w_buffer);
        p = NameBuff;
        plen = (int) strlen((char *)(p)) ;

        if ((bt_help(wp->w_buffer) || bufIsChanged(wp->w_buffer) || wp->w_buffer->b_p_ro) && plen <  PATH_MAX  - 1)
        {
            *(p + plen++) = ' ';
            *(p + plen) = NUL;
        }
        if (bt_help(wp->w_buffer))
        {
            plen += vim_snprintf((char *)p + plen,  PATH_MAX  - plen, "%s", _("[Help]"));
        }
        if (bufIsChanged(wp->w_buffer))
        {
            plen += vim_snprintf((char *)p + plen,  PATH_MAX  - plen, "%s", "[+]");
        }
        if (wp->w_buffer->b_p_ro)
        {
            plen += vim_snprintf((char *)p + plen,  PATH_MAX  - plen, "%s", _("[RO]"));
        }

        this_ru_col = ru_col - (cmdline_width - wp->w_width);
        n = (wp->w_width + 1) / 2;
        if (this_ru_col < n)
        {
            this_ru_col = n;
        }
        if (this_ru_col <= 1)
        {
            p = (char_u *)"<";
            plen = 1;
        }
        else
        {
            plen = mb_string2cells(p, -1);

            for (i = 0; p[i] != NUL && plen >= this_ru_col - 1; i += utfc_ptr2len(p + i))
            {
                plen -= utf_ptr2cells(p + i);
            }
            if (i > 0)
            {
                p = p + i - 1;
                *p = '<';
                ++plen;
            }
        }

        screen_puts(p, row, wp->w_wincol, attr);
        screen_fill(row, row + 1, plen + wp->w_wincol, this_ru_col + wp->w_wincol, fillchar, fillchar, attr);
        for (i = 1; i < wp->w_status_height; i++)
        {
            screen_fill(row + i, row + i + 1, wp->w_wincol,  ((wp)->w_wincol + (wp)->w_width) , fillchar, fillchar, attr);
        }
        win_redr_ruler(wp, TRUE, ignore_pum);

        if (p_sc && *p_sloc == 's')
        {
            n = this_ru_col - plen - 2;
            int width = MIN(10, n);

            if (width > 0)
            {
                screen_puts_len(showcmd_buf, width, row, wp->w_wincol + this_ru_col - width - 1, attr);
            }
            showcmd_update_clear_state();
        }
    }

    if (wp->w_vsep_width != 0 && wp->w_status_height != 0 && redrawing())
    {
        for (i = 0; i < wp->w_status_height; i++)
        {
            int r = row + i;
            fillchar = fillchar_vsep(&attr, wp, r);
            screen_putchar(fillchar, r,  ((wp)->w_wincol + (wp)->w_width) , attr);
        }
    }
    busy = FALSE;
}

    static void
showruler(int always)
{
    if (!always && !redrawing())
    {
        return;
    }
        win_redr_ruler(curwin, always, FALSE);

    if (redraw_tabline)
    {
        draw_tabline();
    }

}

    static void
win_redr_ruler(win_T *wp, int always, int ignore_pum)
{
    int empty_line = FALSE;

    if (!p_ru)
    {
        return;
    }

    if (wp->w_cursor.lnum > wp->w_buffer->b_ml.ml_line_count)
    {
        return;
    }

    if (wp == curwin && curwin->w_status_height == 0)
    {
        if (edit_submode != NULL)
        {
            return;
        }
    }

    if ((State & MODE_INSERT) == 0 && *ml_get_buf(wp->w_buffer, wp->w_cursor.lnum, FALSE) == NUL)
    {
        empty_line = TRUE;
    }

    validate_virtcol_win(wp);
    if (       redraw_cmdline || always || wp->w_cursor.lnum != wp->w_ru_cursor.lnum || wp->w_cursor.col != wp->w_ru_cursor.col || wp->w_virtcol != wp->w_ru_virtcol || wp->w_cursor.coladd != wp->w_ru_cursor.coladd || wp->w_topline != wp->w_ru_topline || wp->w_buffer->b_ml.ml_line_count != wp->w_ru_line_count || empty_line != wp->w_ru_empty)
    {
        int     row;
        int     fillchar;
        int     attr;
        int     off;
        int     width;
        colnr_T virtcol;
        char_u  buffer[RULER_BUF_LEN];
        int     bufferlen;
        char_u  rel_pos[RULER_BUF_LEN];
        int     rel_poslen;
        int     this_ru_col;
        int     n1;
        int     n2;
        bool    override_success =
            push_highlight_overrides(wp->w_hl, wp->w_hl_len);

        cursor_off();
        if (wp->w_status_height)
        {
            row = statusline_row(wp);
            fillchar = fillchar_status(&attr, wp);
            off = wp->w_wincol;
            width = wp->w_width;
        }
        else
        {
            row = Rows - 1;
            fillchar = ' ';
            attr = 0;
            off = cmdline_col_off;
            width = cmdline_width;
        }

        virtcol = wp->w_virtcol;
        if (wp-> w_onebuf_opt.wo_list  && wp->w_lcs_chars.tab1 == NUL)
        {
            wp-> w_onebuf_opt.wo_list  = FALSE;
            getvvcol(wp, &wp->w_cursor, NULL, &virtcol, NULL, 0);
            wp-> w_onebuf_opt.wo_list  = TRUE;
        }

        bufferlen = vim_snprintf((char *)buffer, RULER_BUF_LEN, _("%ld,"), (wp->w_buffer->b_ml.ml_flags & ML_EMPTY) ? 0L : (long)(wp->w_cursor.lnum));
        bufferlen += col_print(buffer + bufferlen, RULER_BUF_LEN - bufferlen, empty_line ? 0 : (int)wp->w_cursor.col + 1, (int)virtcol + 1);

        rel_poslen = get_rel_pos(wp, rel_pos, RULER_BUF_LEN);
        n1 = bufferlen + vim_strsize(rel_pos);
        if (wp->w_status_height == 0)
        {
            ++n1;
        }

        this_ru_col = ru_col - (cmdline_width - width);
        n2 = (width + 1) / 2;
        if (this_ru_col < n2)
        {
            this_ru_col = n2;
        }
        if (this_ru_col + n1 < width)
        {
            while (this_ru_col + n1 < width && RULER_BUF_LEN > bufferlen + rel_poslen + 1)
            {
                bufferlen += utf_char2bytes(fillchar, buffer + bufferlen);
                ++n1;
            }
            bufferlen += vim_snprintf((char *)buffer + bufferlen, RULER_BUF_LEN - bufferlen, "%s", rel_pos);
        }
        n1 = 0;
        for (n2 = 0; buffer[n1] != NUL; n1 += utfc_ptr2len(buffer + n1))
        {
            n2 += utf_ptr2cells(buffer + n1);
            if (this_ru_col + n2 > width)
            {
                bufferlen = n1;
                buffer[bufferlen] = NUL;
                break;
            }
        }

        screen_puts(buffer, row, this_ru_col + off, attr);
        n1 = redraw_cmdline;
        screen_fill(row, row + 1, this_ru_col + off + bufferlen, (off + width), fillchar, fillchar, attr);
        redraw_cmdline = n1;
        wp->w_ru_cursor = wp->w_cursor;
        wp->w_ru_virtcol = wp->w_virtcol;
        wp->w_ru_empty = empty_line;
        wp->w_ru_topline = wp->w_topline;
        wp->w_ru_line_count = wp->w_buffer->b_ml.ml_line_count;

        if (override_success)
        {
            pop_highlight_overrides();
        }
    }
}

    static void
after_updating_screen(int may_resize_shell  __attribute__((unused)) )
{
    updating_screen = FALSE;

}

    static void
update_curbuf(int type)
{
    redraw_curbuf_later(type);
    update_screen(type);
}

    static void
win_update(win_T *wp)
{
    buf_T       *buf = wp->w_buffer;
    int         type;
    int         top_end = 0;
    int         mid_start = 999;
    int         mid_end = 0;
    int         bot_start = 999;
    int         scrolled_down = FALSE;
    int         scrolled_for_mod = FALSE;
    int         top_to_mod = FALSE;

    int         row;
    linenr_T    lnum;
    int         idx;
    int         srow;

    int         eof = FALSE;
    int         didline = FALSE;
    int         i;
    long        j;
    static int  recursive = FALSE;
    linenr_T    old_botline = wp->w_botline;
    linenr_T    mod_top = 0;
    linenr_T    mod_bot = 0;
    int         save_got_int;
    bool        override_success;

    if (!did_update_one_window)
    {
        did_update_one_window = TRUE;
        start_search_hl();
    }

    type = wp->w_redr_type;

    if (type == UPD_NOT_VALID)
    {
        wp->w_redr_status = true;
        wp->w_lines_valid = 0;
    }

    if (wp->w_height +  0  == 0 || (wp->w_frame->fr_height == wp->w_status_height))
    {
        wp->w_redr_type = 0;
        return;
    }

    if (wp->w_width == 0)
    {
        draw_vsep_win(wp, 0);
        wp->w_redr_type = 0;
        return;
    }

    override_success = push_highlight_overrides(wp->w_hl, wp->w_hl_len);

    init_search_hl(wp, &screen_search_hl);

    if (wp->w_skipcol > 0 && wp->w_width > win_col_off(wp))
    {
        int w = 0;
        int width1 = wp->w_width - win_col_off(wp);
        int width2 = width1 + win_col_off2(wp);
        int add = width1;

        while (w < wp->w_skipcol)
        {
            if (w > 0)
            {
                add = width2;
            }
            w += add;
        }
        if (w != wp->w_skipcol)
        {
            wp->w_skipcol = w - add;
        }
    }

    {
        mod_top = wp->w_redraw_top;
        if (wp->w_redraw_bot != 0)
        {
            mod_bot = wp->w_redraw_bot + 1;
        }
        else
        {
            mod_bot = 0;
        }
        if (buf->b_mod_set)
        {
            if (mod_top == 0 || mod_top > buf->b_mod_top)
            {
                mod_top = buf->b_mod_top;
            }
            if (mod_bot == 0 || mod_bot < buf->b_mod_bot)
            {
                mod_bot = buf->b_mod_bot;
            }

            if (screen_search_hl.rm.regprog != NULL && re_multiline(screen_search_hl.rm.regprog))
            {
                top_to_mod = TRUE;
            }
            else
            {
                matchitem_T *cur = wp->w_match_head;

                while (cur != NULL)
                {
                    if (cur->mit_match.regprog != NULL && re_multiline(cur->mit_match.regprog))
                    {
                        top_to_mod = TRUE;
                        break;
                    }
                    cur = cur->mit_next;
                }
            }
        }

        if (search_hl_has_cursor_lnum > 0)
        {
            if (mod_top == 0 || mod_top > search_hl_has_cursor_lnum)
            {
                mod_top = search_hl_has_cursor_lnum;
            }
            if (mod_bot == 0 || mod_bot < search_hl_has_cursor_lnum + 1)
            {
                mod_bot = search_hl_has_cursor_lnum + 1;
            }
        }

        if (mod_top != 0 && mod_top < wp->w_topline)
        {
            if (mod_bot > wp->w_topline)
            {
                mod_top = wp->w_topline;
            }
        }
    }
    wp->w_redraw_top = 0;
    wp->w_redraw_bot = 0;
    search_hl_has_cursor_lnum = 0;

    if (type == UPD_REDRAW_TOP)
    {
        j = 0;
        for (i = 0; i < wp->w_lines_valid; ++i)
        {
            j += wp->w_lines[i].wl_size;
            if (j >= wp->w_upd_rows)
            {
                top_end = j;
                break;
            }
        }
        if (top_end == 0)
        {
            type = UPD_NOT_VALID;
        }
        else
        {
            type = UPD_VALID;
        }
    }

    if (screen_cleared)
    {
        screen_cleared = MAYBE;
    }

    if ((type == UPD_VALID || type == UPD_SOME_VALID || type == UPD_INVERTED || type == UPD_INVERTED_ALL))
    {
        if (mod_top != 0 && wp->w_topline == mod_top && (!wp->w_lines[0].wl_valid || wp->w_topline == wp->w_lines[0].wl_lnum))
        {
        }
        else if (wp->w_lines[0].wl_valid && (wp->w_topline < wp->w_lines[0].wl_lnum))
        {
                j = wp->w_lines[0].wl_lnum - wp->w_topline;
            if (j < wp->w_height - 2)
            {
                i = plines_m_win(wp, wp->w_topline, wp->w_lines[0].wl_lnum - 1, wp->w_height);
                if (i < wp->w_height - 2)
                {
                    if (i > 0)
                    {
                        check_for_delay(FALSE);
                    }
                    if (win_ins_lines(wp, 0, i, FALSE, TRUE) == OK)
                    {
                        if (wp->w_lines_valid != 0)
                        {
                            top_end = i;
                            scrolled_down = TRUE;

                            if ((wp->w_lines_valid += j) > wp->w_height)
                            {
                                wp->w_lines_valid = wp->w_height;
                            }
                            for (idx = wp->w_lines_valid; idx - j >= 0; idx--)
                            {
                                wp->w_lines[idx] = wp->w_lines[idx - j];
                            }
                            while (idx >= 0)
                            {
                                wp->w_lines[idx--].wl_valid = FALSE;
                            }
                        }
                    }
                    else
                    {
                        mid_start = 0;
                    }
                }
                else
                {
                    mid_start = 0;
                }
            }
            else
            {
                mid_start = 0;
            }
        }
        else
        {
            j = -1;
            row = 0;
            for (i = 0; i < wp->w_lines_valid && i < Rows; i++)
            {
                if (wp->w_lines[i].wl_valid && wp->w_lines[i].wl_lnum == wp->w_topline)
                {
                    j = i;
                    break;
                }
                row += wp->w_lines[i].wl_size;
            }
            if (j == -1)
            {
                mid_start = 0;
            }
            else
            {
                if (row > Rows)
                {
                    row = Rows;
                }
                if (row > 0)
                {
                    check_for_delay(FALSE);
                    if (win_del_lines(wp, 0, row, FALSE, TRUE, 0) == OK)
                    {
                        bot_start = wp->w_height - row;
                    }
                    else
                    {
                        mid_start = 0;
                    }
                }
                if ((row == 0 || bot_start < 999) && wp->w_lines_valid != 0)
                {
                    bot_start = 0;
                    idx = 0;
                    for (;;)
                    {
                        wp->w_lines[idx] = wp->w_lines[j];
                        if (row > 0 && bot_start + row + (int)wp->w_lines[j].wl_size > wp->w_height)
                        {
                            wp->w_lines_valid = idx + 1;
                            break;
                        }
                        bot_start += wp->w_lines[idx++].wl_size;

                        if (++j >= wp->w_lines_valid)
                        {
                            wp->w_lines_valid = idx;
                            break;
                        }
                    }
                }
            }
        }

        if (mid_start == 0)
        {
            mid_end = wp->w_height;
        }

        if (screen_cleared == TRUE)
        {
            must_redraw = 0;
        }
    }
    else
    {
        mid_start = 0;
        mid_end = wp->w_height;
    }

    if (type == UPD_SOME_VALID)
    {
        mid_start = 0;
        mid_end = wp->w_height;
        type = UPD_NOT_VALID;
    }

    if ((VIsual_active && buf == curwin->w_buffer) || (wp->w_old_cursor_lnum != 0 && type != UPD_NOT_VALID))
    {
        linenr_T from;
        linenr_T to;

        if (VIsual_active)
        {
            if (VIsual_mode != wp->w_old_visual_mode || type == UPD_INVERTED_ALL)
            {
                if (curwin->w_cursor.lnum < VIsual.lnum)
                {
                    from = curwin->w_cursor.lnum;
                    to = VIsual.lnum;
                }
                else
                {
                    from = VIsual.lnum;
                    to = curwin->w_cursor.lnum;
                }
                if (wp->w_old_cursor_lnum < from)
                {
                    from = wp->w_old_cursor_lnum;
                }
                if (wp->w_old_cursor_lnum > to)
                {
                    to = wp->w_old_cursor_lnum;
                }
                if (wp->w_old_visual_lnum < from)
                {
                    from = wp->w_old_visual_lnum;
                }
                if (wp->w_old_visual_lnum > to)
                {
                    to = wp->w_old_visual_lnum;
                }
            }
            else
            {
                if (curwin->w_cursor.lnum < wp->w_old_cursor_lnum)
                {
                    from = curwin->w_cursor.lnum;
                    to = wp->w_old_cursor_lnum;
                }
                else
                {
                    from = wp->w_old_cursor_lnum;
                    to = curwin->w_cursor.lnum;
                    if (from == 0)
                    {
                        from = to;
                    }
                }

                if (VIsual.lnum != wp->w_old_visual_lnum || VIsual.col != wp->w_old_visual_col)
                {
                    if (wp->w_old_visual_lnum < from && wp->w_old_visual_lnum != 0)
                    {
                        from = wp->w_old_visual_lnum;
                    }
                    if (wp->w_old_visual_lnum > to)
                    {
                        to = wp->w_old_visual_lnum;
                    }
                    if (VIsual.lnum < from)
                    {
                        from = VIsual.lnum;
                    }
                    if (VIsual.lnum > to)
                    {
                        to = VIsual.lnum;
                    }
                }
            }

            if (VIsual_mode == Ctrl_V)
            {
                colnr_T fromc;
                colnr_T toc;

                getvcols(wp, &VIsual, &curwin->w_cursor, &fromc, &toc, GETVCOL_END_EXCL_LBR);
                ++toc;
                if (curwin->w_curswant == MAXCOL)
                {
                    if (get_ve_flags() & VE_BLOCK)
                    {
                        pos_T       pos;
                        int         cursor_above =
                                           curwin->w_cursor.lnum < VIsual.lnum;

                        toc = 0;
                        pos.coladd = 0;
                        for (pos.lnum = curwin->w_cursor.lnum; cursor_above ? pos.lnum <= VIsual.lnum : pos.lnum >= VIsual.lnum; pos.lnum += cursor_above ? 1 : -1)
                        {
                            colnr_T t;

                            pos.col = (int)ml_get_buf_len(wp->w_buffer, pos.lnum);
                            getvvcol(wp, &pos, NULL, NULL, &t, 0);
                            if (toc < t)
                            {
                                toc = t;
                            }
                        }
                        ++toc;
                    }
                    else
                    {
                        toc = MAXCOL;
                    }
                }

                if (fromc != wp->w_old_cursor_fcol || toc != wp->w_old_cursor_lcol)
                {
                    if (from > VIsual.lnum)
                    {
                        from = VIsual.lnum;
                    }
                    if (to < VIsual.lnum)
                    {
                        to = VIsual.lnum;
                    }
                }
                wp->w_old_cursor_fcol = fromc;
                wp->w_old_cursor_lcol = toc;
            }
        }
        else
        {
            if (wp->w_old_cursor_lnum < wp->w_old_visual_lnum)
            {
                from = wp->w_old_cursor_lnum;
                to = wp->w_old_visual_lnum;
            }
            else
            {
                from = wp->w_old_visual_lnum;
                to = wp->w_old_cursor_lnum;
            }
        }

        if (from < wp->w_topline)
        {
            from = wp->w_topline;
        }

        if (wp->w_valid & VALID_BOTLINE)
        {
            if (from >= wp->w_botline)
            {
                from = wp->w_botline - 1;
            }
            if (to >= wp->w_botline)
            {
                to = wp->w_botline - 1;
            }
        }

        if (mid_start > 0)
        {
            lnum = wp->w_topline;
            idx = 0;
            srow = 0;
            if (scrolled_down)
            {
                mid_start = top_end;
            }
            else
            {
                mid_start = 0;
            }
            while (lnum < from && idx < wp->w_lines_valid)
            {
                if (wp->w_lines[idx].wl_valid)
                {
                    mid_start += wp->w_lines[idx].wl_size;
                }
                else if (!scrolled_down)
                {
                    srow += wp->w_lines[idx].wl_size;
                }
                ++idx;
                    ++lnum;
            }
            srow += mid_start;
            mid_end = wp->w_height;
            for ( ; idx < wp->w_lines_valid; ++idx)
            {
                if (wp->w_lines[idx].wl_valid && wp->w_lines[idx].wl_lnum >= to + 1)
                {
                    mid_end = srow;
                    break;
                }
                srow += wp->w_lines[idx].wl_size;
            }
        }
    }

    if (VIsual_active && buf == curwin->w_buffer)
    {
        wp->w_old_visual_mode = VIsual_mode;
        wp->w_old_cursor_lnum = curwin->w_cursor.lnum;
        wp->w_old_visual_lnum = VIsual.lnum;
        wp->w_old_visual_col = VIsual.col;
        wp->w_old_curswant = curwin->w_curswant;
    }
    else
    {
        wp->w_old_visual_mode = 0;
        wp->w_old_cursor_lnum = 0;
        wp->w_old_visual_lnum = 0;
        wp->w_old_visual_col = 0;
    }

    save_got_int = got_int;
    got_int = 0;

    lnum = wp->w_topline;

    idx = 0;
    row = 0;
    srow = 0;
    for (;;)
    {
        if (row == wp->w_height)
        {
            didline = TRUE;
            break;
        }

        if (lnum > buf->b_ml.ml_line_count)
        {
            eof = TRUE;
            break;
        }

        srow = row;

        if (row < top_end || (row >= mid_start && row < mid_end) || top_to_mod || idx >= wp->w_lines_valid || (row + wp->w_lines[idx].wl_size > bot_start) || (mod_top != 0 && (lnum == mod_top || (lnum >= mod_top && (lnum < mod_bot || (wp->w_match_head != NULL && buf->b_mod_set && buf->b_mod_xlines != 0))))))
        {
            if (lnum == mod_top)
            {
                top_to_mod = FALSE;
            }

            if (!scrolled_for_mod && mod_bot !=  LONG_MAX  && lnum >= mod_top && lnum < MAX(mod_bot, mod_top + 1) && (!scrolled_down || row >= top_end))
            {
                scrolled_for_mod = TRUE;

                int             old_cline_height = 0;
                int             old_rows = 0;
                int             new_rows = 0;
                int             xtra_rows;
                linenr_T        l;

                for (i = idx; i < wp->w_lines_valid; ++i)
                {
                    if (wp->w_lines[i].wl_valid && wp->w_lines[i].wl_lnum == mod_bot)
                    {
                        break;
                    }
                    if (wp->w_lines[i].wl_lnum == wp->w_cursor.lnum)
                    {
                        old_cline_height = wp->w_lines[i].wl_size;
                    }
                    old_rows += wp->w_lines[i].wl_size;
                }

                if (i >= wp->w_lines_valid)
                {
                    bot_start = 0;
                }
                else
                {
                    j = idx;
                    for (l = lnum; l < mod_bot; ++l)
                    {
                        if (dollar_vcol >= 0 && wp == curwin && old_cline_height > 0 && l == wp->w_cursor.lnum)
                        {
                            new_rows += old_cline_height;
                        }
                        else
                        {
                            new_rows += plines_correct_topline(wp, l, TRUE);
                        }
                        ++j;
                        if (new_rows > wp->w_height - row - 2)
                        {
                            new_rows = 9999;
                            break;
                        }
                    }
                    xtra_rows = new_rows - old_rows;
                    if (xtra_rows < 0)
                    {
                        if (row - xtra_rows >= wp->w_height - 2)
                        {
                            mod_bot =  LONG_MAX ;
                        }
                        else
                        {
                            check_for_delay(FALSE);
                            if (win_del_lines(wp, row, -xtra_rows, FALSE, FALSE, 0) == FAIL)
                            {
                                mod_bot =  LONG_MAX ;
                            }
                            else
                            {
                                bot_start = wp->w_height + xtra_rows;
                            }
                        }
                    }
                    else if (xtra_rows > 0)
                    {
                        if (row + xtra_rows >= wp->w_height - 2)
                        {
                            mod_bot =  LONG_MAX ;
                        }
                        else
                        {
                            check_for_delay(FALSE);
                            if (win_ins_lines(wp, row + old_rows, xtra_rows, FALSE, FALSE) == FAIL)
                            {
                                mod_bot =  LONG_MAX ;
                            }
                            else if (top_end > row + old_rows)
                            {
                                top_end += xtra_rows;
                            }
                        }
                    }

                    if (mod_bot !=  LONG_MAX  && i != j)
                    {
                        if (j < i)
                        {
                            int x = row + new_rows;

                            for (;;)
                            {
                                if (i >= wp->w_lines_valid)
                                {
                                    wp->w_lines_valid = j;
                                    break;
                                }
                                wp->w_lines[j] = wp->w_lines[i];
                                if (x + (int)wp->w_lines[j].wl_size > wp->w_height)
                                {
                                    wp->w_lines_valid = j + 1;
                                    break;
                                }
                                x += wp->w_lines[j++].wl_size;
                                ++i;
                            }
                            if (bot_start > x)
                            {
                                bot_start = x;
                            }
                        }
                        else
                        {
                            j -= i;
                            wp->w_lines_valid += j;
                            if (wp->w_lines_valid > wp->w_height)
                            {
                                wp->w_lines_valid = wp->w_height;
                            }
                            for (i = wp->w_lines_valid; i - j >= idx; --i)
                            {
                                wp->w_lines[i] = wp->w_lines[i - j];
                            }

                            while (i >= idx)
                            {
                                wp->w_lines[i].wl_size = 0;
                                wp->w_lines[i--].wl_valid = FALSE;
                            }
                        }
                    }
                }
            }

            if (idx < wp->w_lines_valid && wp->w_lines[idx].wl_valid && wp->w_lines[idx].wl_lnum == lnum && lnum > wp->w_topline && !(dy_flags & (DY_LASTLINE | DY_TRUNCATE)) && ! 0  && srow + wp->w_lines[idx].wl_size > wp->w_height)
            {
                row = wp->w_height + 1;
            }
            else
            {
                prepare_search_hl(wp, &screen_search_hl, lnum);

                row = win_line(wp, lnum, srow, wp->w_height, 0);

            }

            wp->w_lines[idx].wl_lnum = lnum;
            wp->w_lines[idx].wl_valid = TRUE;

            int is_curline = wp == curwin && lnum == wp->w_cursor.lnum;

            if (row > wp->w_height || row + wp->w_winrow >= Rows)
            {
                if (dollar_vcol == -1 || !is_curline)
                {
                    wp->w_lines[idx].wl_size = plines_win(wp, lnum, TRUE);
                }
                ++idx;
                break;
            }
            if (dollar_vcol == -1 || !is_curline)
            {
                wp->w_lines[idx].wl_size = row - srow;
            }
            ++idx;
            ++lnum;
        }
        else
        {
            if ((wp-> w_onebuf_opt.wo_nu  && mod_top != 0 && lnum >= mod_bot && buf->b_mod_set && buf->b_mod_xlines != 0) || (wp-> w_onebuf_opt.wo_rnu  && wp->w_last_cursor_lnum_rnu != wp->w_cursor.lnum))
            {
                    (void)win_line(wp, lnum, srow, wp->w_height, wp->w_lines[idx].wl_size);
            }

            row += wp->w_lines[idx++].wl_size;
            if (row > wp->w_height)
            {
                break;
            }
            ++lnum;
        }

        if (lnum > buf->b_ml.ml_line_count)
        {
            eof = TRUE;
            break;
        }

        if (idx >= Rows)
        {
            break;
        }
    }

    wp->w_last_cursor_lnum_rnu = wp-> w_onebuf_opt.wo_rnu  ? wp->w_cursor.lnum : 0;

    if (idx > wp->w_lines_valid)
    {
        wp->w_lines_valid = idx;
    }

    wp->w_empty_rows = 0;
    if (!eof && !didline)
    {
        if (lnum == wp->w_topline)
        {
            wp->w_botline = lnum + 1;
        }
        else if (dy_flags & DY_TRUNCATE)
        {
            int         scr_row =  (wp->w_winrow)  + wp->w_height - 1;
            int         symbol  = wp->w_fill_chars.lastline;
            int         charlen;
            char_u      fillbuf[12];

            charlen = utf_char2bytes(symbol, &fillbuf[0]);
            utf_char2bytes(symbol, &fillbuf[charlen]);

            screen_puts_len(fillbuf, (wp->w_width > 2 ? 2 : wp->w_width) * charlen, scr_row, wp->w_wincol,  highlight_attr[(int)(HLF_AT)] );
            screen_fill(scr_row, scr_row + 1, (int)wp->w_wincol + 2, (int) ((wp)->w_wincol + (wp)->w_width) , symbol, ' ',  highlight_attr[(int)(HLF_AT)] );
            set_empty_rows(wp, srow);
            wp->w_botline = lnum;
        }
        else if (dy_flags & DY_LASTLINE)
        {
            int start_col = (int) ((wp)->w_wincol + (wp)->w_width)  - 3;
            int symbol    = wp->w_fill_chars.lastline;

            screen_fill( (wp->w_winrow)  + wp->w_height - 1,  (wp->w_winrow)  + wp->w_height, (start_col < wp->w_wincol ? wp->w_wincol : start_col), (int) ((wp)->w_wincol + (wp)->w_width) , symbol, symbol,  highlight_attr[(int)(HLF_AT)] );
            set_empty_rows(wp, srow);
            wp->w_botline = lnum;
        }
        else
        {
            win_draw_end(wp, wp->w_fill_chars.lastline, ' ', TRUE, srow, wp->w_height, HLF_AT);
            wp->w_botline = lnum;
        }
    }
    else
    {
        draw_vsep_win(wp, row);
        if (eof)
        {
            wp->w_botline = buf->b_ml.ml_line_count + 1;
        }
        else if (dollar_vcol == -1 || wp != curwin)
        {
            wp->w_botline = lnum;
        }

        if ( 0 )
        {
            win_draw_end(wp, ' ', ' ', FALSE, row, wp->w_height, HLF_AT);
        }
        else
        {
            win_draw_end(wp, wp->w_fill_chars.eob, ' ', FALSE, row, wp->w_height, HLF_EOB);
        }
    }

    wp->w_redr_type = 0;

    if (dollar_vcol == -1 || wp != curwin)
    {
        wp->w_valid |= VALID_BOTLINE;
        if (wp == curwin && wp->w_botline != old_botline && !recursive)
        {
            win_T       *wwp;
            recursive = TRUE;
            curwin->w_valid &= ~VALID_TOPLINE;
            update_topline();

            if (wp->w_redr_type != 0)
            {
                bool b = curbuf->b_mod_set;
                curbuf->b_mod_set = false;
                j = curbuf->b_mod_xlines;
                curbuf->b_mod_xlines = 0;
                curs_columns(TRUE);
                win_update(curwin);
                curbuf->b_mod_set = b;
                curbuf->b_mod_xlines = j;
            }
            must_redraw = 0;
             wwp = curwin;
            if (wwp->w_redr_type > must_redraw)
            {
                must_redraw = wwp->w_redr_type;
            }
            recursive = FALSE;
        }
    }

    if (!got_int)
    {
        got_int = save_got_int;
    }

    if (override_success)
    {
        pop_highlight_overrides();
    }
}

    static int
redraw_asap(int type)
{
    int         rows;
    int         cols = screen_Columns;
    int         r;
    int         ret = 0;
    schar_T     *screenline;
    sattr_T     *screenattr;
    int         i;
    u8char_T    *screenlineUC = NULL;
    u8char_T    *screenlineC[MAX_MCO];

    redraw_later(type);
    if (msg_scrolled || (State != MODE_NORMAL && State !=  (0x1000 | MODE_NORMAL) ) || exiting)
    {
        return ret;
    }

    rows = screen_Rows - cmdline_row;
    screenline =  (schar_T *)lalloc(sizeof(schar_T) * (rows * cols), FALSE) ;
    screenattr =  (sattr_T *)lalloc(sizeof(sattr_T) * (rows * cols), FALSE) ;
    if (screenline == NULL || screenattr == NULL)
    {
        ret = 2;
    }
    screenlineUC =  (u8char_T *)lalloc(sizeof(u8char_T) * (rows * cols), FALSE) ;
    if (screenlineUC == NULL)
    {
        ret = 2;
    }
    for (i = 0; i < p_mco; ++i)
    {
        screenlineC[i] =  (u8char_T *)lalloc(sizeof(u8char_T) * (rows * cols), FALSE) ;
        if (screenlineC[i] == NULL)
        {
            ret = 2;
        }
    }

    if (ret != 2)
    {
        for (r = 0; r < rows; ++r)
        {
             memmove((char *)(screenline + r * cols), (char *)(ScreenLines + LineOffset[cmdline_row + r]), (size_t)cols * sizeof(schar_T)) ;
             memmove((char *)(screenattr + r * cols), (char *)(ScreenAttrs + LineOffset[cmdline_row + r]), (size_t)cols * sizeof(sattr_T)) ;
             memmove((char *)(screenlineUC + r * cols), (char *)(ScreenLinesUC + LineOffset[cmdline_row + r]), (size_t)cols * sizeof(u8char_T)) ;
            for (i = 0; i < p_mco; ++i)
            {
                 memmove((char *)(screenlineC[i] + r * cols), (char *)(ScreenLinesC[i] + LineOffset[cmdline_row + r]), (size_t)cols * sizeof(u8char_T)) ;
            }
        }

        update_screen(0);
        ret = 3;

        if (must_redraw == 0)
        {
            int off = (int)(current_ScreenLine - ScreenLines);

            for (r = 0; r < rows; ++r)
            {
                 memmove((char *)(current_ScreenLine), (char *)(screenline + r * cols), (size_t)cols * sizeof(schar_T)) ;
                 memmove((char *)(ScreenAttrs + off), (char *)(screenattr + r * cols), (size_t)cols * sizeof(sattr_T)) ;
                 memmove((char *)(ScreenLinesUC + off), (char *)(screenlineUC + r * cols), (size_t)cols * sizeof(u8char_T)) ;
                for (i = 0; i < p_mco; ++i)
                {
                     memmove((char *)(ScreenLinesC[i] + off), (char *)(screenlineC[i] + r * cols), (size_t)cols * sizeof(u8char_T)) ;
                }
                screen_line(curwin, cmdline_row + r, 0, cols, cols, -1, 0);
            }
            ret = 4;
        }
    }

    vim_free(screenline);
    vim_free(screenattr);
    vim_free(screenlineUC);
    for (i = 0; i < p_mco; ++i)
    {
        vim_free(screenlineC[i]);
    }

    setcursor();

    return ret;
}

    static void
redraw_later(int type)
{
    redraw_win_later(curwin, type);
}

    static void
redraw_win_later(win_T       *wp, int         type)
{
    if (!exiting && !redraw_not_allowed && wp->w_redr_type < type)
    {
        wp->w_redr_type = type;
        if (type >= UPD_NOT_VALID)
        {
            wp->w_lines_valid = 0;
        }
        if (must_redraw < type)
        {
            must_redraw = type;
        }
    }
}

    static void
redraw_later_clear(void)
{
    redraw_all_later(UPD_CLEAR);
    reset_screen_attr();
}

    static void
redraw_all_later(int type)
{
    win_T       *wp;

     wp = curwin;
    redraw_win_later(wp, type);
    set_must_redraw(type);
}

    static void
set_must_redraw(int type)
{
    if (!redraw_not_allowed && must_redraw < type)
    {
        must_redraw = type;
    }
}

    static void
redraw_curbuf_later(int type)
{
    redraw_buf_later(curbuf, type);
}

    static void
redraw_buf_later(buf_T *buf, int type)
{
    win_T       *wp;

     wp = curwin;
    if (wp->w_buffer == buf)
    {
        redraw_win_later(wp, type);
    }
}

    static void
ruler_redraw_lastwin(void)
{
    if (p_ru && curwin->w_status_height == 0)
    {
        redraw_cmdline = TRUE;
    }
}

    static void
status_redraw_all(void)
{
    win_T       *wp;

     wp = curwin;
    if (wp->w_status_height)
    {
        wp->w_redr_status = true;
        redraw_later(UPD_VALID);
    }
    ruler_redraw_lastwin();
}

    static void
status_redraw_curbuf(void)
{
    win_T       *wp;

     wp = curwin;
    if (wp->w_status_height != 0 && wp->w_buffer == curbuf)
    {
        wp->w_redr_status = true;
        redraw_later(UPD_VALID);
    }
    if (curwin->w_buffer == curbuf)
    {
        ruler_redraw_lastwin();
    }
}

    static void
redraw_statuslines(void)
{
    win_T       *wp;

     wp = curwin;
    if (wp->w_redr_status)
    {
        bool ret = push_highlight_overrides(wp->w_hl, wp->w_hl_len);
        win_redr_status(wp, FALSE);
        if (ret)
        {
            pop_highlight_overrides();
        }
    }
    if (redraw_tabline)
    {
        draw_tabline();
    }

}

    static void
redrawWinline(win_T       *wp, linenr_T    lnum)
{
    redraw_win_range_later(wp, lnum, lnum);
}

    static void
redraw_win_range_later(win_T       *wp, linenr_T    first, linenr_T    last)
{
    if (last >= wp->w_topline && first < wp->w_botline)
    {
        if (wp->w_redraw_top == 0 || wp->w_redraw_top > first)
        {
            wp->w_redraw_top = first;
        }
        if (wp->w_redraw_bot == 0 || wp->w_redraw_bot < last)
        {
            wp->w_redraw_bot = last;
        }
        redraw_win_later(wp, UPD_VALID);
    }
}

