    static void
free_buff(buffheader_T *buf)
{
    buffblock_T *p;
    buffblock_T *np;

    for (p = buf->bh_first.b_next; p != NULL; p = np)
    {
        np = p->b_next;
        vim_free(p);
    }
    buf->bh_first.b_next = NULL;
    buf->bh_curr = NULL;
}

    static char_u *
get_buffcont(buffheader_T        *buffer, int                 dozero, size_t              *len)
{
    long_u          count = 0;
    char_u          *p = NULL;
    char_u          *p2;
    char_u          *str;
    buffblock_T *bp;
    size_t          i = 0;

    for (bp = buffer->bh_first.b_next; bp != NULL; bp = bp->b_next)
    {
        count += (long_u)bp->b_strlen;
    }

    if ((count > 0 || dozero) && (p = alloc(count + 1)) != NULL)
    {
        p2 = p;
        for (bp = buffer->bh_first.b_next; bp != NULL; bp = bp->b_next)
        {
            for (str = bp->b_str; *str; )
            {
                *p2++ = *str++;
            }
        }
        *p2 = NUL;
        i = (size_t)(p2 - p);
    }

    if (len != NULL)
    {
        *len = i;
    }

    return p;
}

    static char_u *
get_recorded(void)
{
    char_u      *p;
    size_t      len;

    p = get_buffcont(&recordbuff, TRUE, &len);
    if (p == NULL)
    {
        return NULL;
    }

    free_buff(&recordbuff);

    if (len >= last_recorded_len)
    {
        len -= last_recorded_len;
        p[len] = NUL;
    }

    if (len > 0 && restart_edit != 0 && p[len - 1] == Ctrl_O)
    {
        p[len - 1] = NUL;
    }

    return (p);
}

    static string_T
get_inserted(void)
{
    size_t len = 0;
    char_u *str = get_buffcont(&redobuff, FALSE, &len);
    string_T ret = { str, len };
    return ret;
}

    static void
add_buff(buffheader_T        *buf, char_u              *s, long                slen)
{
    if (slen < 0)
    {
        slen = (long) strlen((char *)(s)) ;
    }
    if (slen == 0)
    {
        return;
    }

    if (buf->bh_first.b_next == NULL)
    {
        buf->bh_curr = &(buf->bh_first);
        buf->bh_create_newblock = TRUE;
    }
    else if (buf->bh_curr == NULL)
    {
        iemsg(e_add_to_internal_buffer_that_was_already_read_from);
        return;
    }
    else if (buf->bh_index != 0)
    {
         memmove((char *)(buf->bh_first.b_next->b_str), (char *)(buf->bh_first.b_next->b_str + buf->bh_index), (buf->bh_first.b_next->b_strlen - buf->bh_index) + 1) ;
        buf->bh_first.b_next->b_strlen -= buf->bh_index;
        buf->bh_space += buf->bh_index;
    }
    buf->bh_index = 0;

    if (!buf->bh_create_newblock && buf->bh_space >= (int)slen)
    {
        vim_strncpy(buf->bh_curr->b_str + buf->bh_curr->b_strlen, s, (size_t)slen);
        buf->bh_curr->b_strlen += slen;
        buf->bh_space -= slen;
    }
    else
    {
        long_u      len;
        buffblock_T *p;

        if (slen < MINIMAL_SIZE)
        {
            len = MINIMAL_SIZE;
        }
        else
        {
            len = slen;
        }
        p = alloc(offsetof(buffblock_T, b_str) + len + 1);
        if (p == NULL)
        {
            return;
        }
        vim_strncpy(p->b_str, s, (size_t)slen);
        p->b_strlen = slen;
        buf->bh_space = (int)(len - slen);
        buf->bh_create_newblock = FALSE;

        p->b_next = buf->bh_curr->b_next;
        buf->bh_curr->b_next = p;
        buf->bh_curr = p;
    }
}

    static void
delete_buff_tail(buffheader_T *buf, int slen)
{
    if (buf->bh_curr == NULL)
    {
        return;
    }
    if (buf->bh_curr->b_strlen < (size_t)slen)
    {
        return;
    }

    buf->bh_curr->b_str[buf->bh_curr->b_strlen - (size_t)slen] = NUL;
    buf->bh_curr->b_strlen -= slen;
    buf->bh_space += slen;
}

    static void
add_num_buff(buffheader_T *buf, long n)
{
    char_u      number[32];
    int         numberlen;

    numberlen = vim_snprintf((char *)number, sizeof(number), "%ld", n);
    add_buff(buf, number, (long)numberlen);
}

    static void
add_char_buff(buffheader_T *buf, int c)
{
    char_u      bytes[MB_MAXBYTES + 1];
    int         len;
    int         i;
    char_u      temp[4];
    long        templen;

    if ( ((c) < 0) )
    {
        len = 1;
    }
    else
    {
        len = utf_char2bytes(c, bytes);
    }
    for (i = 0; i < len; ++i)
    {
        if (! ((c) < 0) )
        {
            c = bytes[i];
        }

        if ( ((c) < 0)  || c ==  (0x80)  || c == NUL)
        {
            temp[0] =  (0x80) ;
            temp[1] =  ((c) ==  (0x80)  ? KS_SPECIAL : (c) == NUL ? KS_ZERO :  ((-(c)) & 0xff) ) ;
            temp[2] =  (((c) ==  (0x80)  || (c) == NUL) ?  ('X')  :  (((unsigned)(-(c)) >> 8) & 0xff) ) ;
            temp[3] = NUL;
            templen = 3;
        }
        else
        {
            temp[0] = c;
            temp[1] = NUL;
            templen = 1;
        }
        add_buff(buf, temp, templen);
    }
}

static buffheader_T readbuf1 = {{NULL, 0, {NUL}}, NULL, 0, 0, FALSE};

static buffheader_T readbuf2 = {{NULL, 0, {NUL}}, NULL, 0, 0, FALSE};

    static int
read_readbuffers(int advance)
{
    int c;

    c = read_readbuf(&readbuf1, advance);
    if (c == NUL)
    {
        c = read_readbuf(&readbuf2, advance);
    }
    return c;
}

    static int
read_readbuf(buffheader_T *buf, int advance)
{
    char_u      c;
    buffblock_T *curr;

    if (buf->bh_first.b_next == NULL)
    {
        return NUL;
    }

    curr = buf->bh_first.b_next;
    c = curr->b_str[buf->bh_index];

    if (advance)
    {
        if (curr->b_str[++buf->bh_index] == NUL)
        {
            buf->bh_first.b_next = curr->b_next;
            vim_free(curr);
            buf->bh_index = 0;
        }
    }
    return c;
}

    static void
start_stuff(void)
{
    if (readbuf1.bh_first.b_next != NULL)
    {
        readbuf1.bh_curr = &(readbuf1.bh_first);
        readbuf1.bh_create_newblock = TRUE;
    }
    if (readbuf2.bh_first.b_next != NULL)
    {
        readbuf2.bh_curr = &(readbuf2.bh_first);
        readbuf2.bh_create_newblock = TRUE;
    }
}

    static int
stuff_empty(void)
{
    return (readbuf1.bh_first.b_next == NULL && readbuf2.bh_first.b_next == NULL);
}

    static void
typeahead_noflush(int c)
{
    typeahead_char = c;
}

    static void
flush_buffers(flush_buffers_T flush_typeahead)
{
    init_typebuf();

    start_stuff();
    while (read_readbuffers(TRUE) != NUL)
    {
        ;
    }

    if (flush_typeahead == FLUSH_MINIMAL)
    {
        if (typebuf.tb_off + typebuf.tb_maplen >= typebuf.tb_buflen)
        {
            typebuf.tb_off = MAXMAPLEN;
            typebuf.tb_len = 0;
        }
        else
        {
            typebuf.tb_off += typebuf.tb_maplen;
            typebuf.tb_len -= typebuf.tb_maplen;
        }
    }
    else
    {
        if (flush_typeahead == FLUSH_INPUT)
        {
            while (inchar(typebuf.tb_buf, typebuf.tb_buflen - 1, 10L) != 0)
            {
                ;
            }
        }
        typebuf.tb_off = MAXMAPLEN;
        typebuf.tb_len = 0;
    }
    typebuf.tb_maplen = 0;
    typebuf.tb_silent = 0;
    cmd_silent = FALSE;
    typebuf.tb_no_abbr_cnt = 0;
    if (++typebuf.tb_change_cnt == 0)
    {
        typebuf.tb_change_cnt = 1;
    }
}

    static void
ResetRedobuff(void)
{
    if (block_redo)
    {
        return;
    }

    free_buff(&old_redobuff);
    old_redobuff = redobuff;
    redobuff.bh_first.b_next = NULL;
}

    static void
CancelRedo(void)
{
    if (block_redo)
    {
        return;
    }

    free_buff(&redobuff);
    redobuff = old_redobuff;
    old_redobuff.bh_first.b_next = NULL;
    start_stuff();
    while (read_readbuffers(TRUE) != NUL)
    {
        ;
    }
}

    static void
AppendToRedobuff(char_u *s)
{
    if (!block_redo)
    {
        add_buff(&redobuff, s, -1L);
    }
}

    static void
AppendToRedobuffLit(char_u      *str, int         len)
{
    char_u      *s = str;
    int         c;
    char_u      *start;

    if (block_redo)
    {
        return;
    }

    while (len < 0 ? *s != NUL : s - str < len)
    {
        start = s;
        while (*s >= ' ' && *s < DEL && (len < 0 || s - str < len))
        {
            ++s;
        }

        if (*s == NUL && (s[-1] == '0' || s[-1] == '^'))
        {
            --s;
        }
        if (s > start)
        {
            add_buff(&redobuff, start, (long)(s - start));
        }

        if (*s == NUL || (len >= 0 && s - str >= len))
        {
            break;
        }

        c = mb_cptr2char_adv(&s);
        if (c < ' ' || c == DEL || (*s == NUL && (c == '0' || c == '^')))
        {
            add_char_buff(&redobuff, Ctrl_V);
        }

        if (*s == NUL && c == '0')
        {
            add_buff(&redobuff, (char_u *)"048", 3L);
        }
        else
        {
            add_char_buff(&redobuff, c);
        }
    }
}

    static void
AppendToRedobuffSpec(char_u *s)
{
    if (block_redo)
    {
        return;
    }

    while (*s != NUL)
    {
        if (*s ==  (0x80)  && s[1] != NUL && s[2] != NUL)
        {
            add_buff(&redobuff, s, 3L);
            s += 3;
        }
        else
        {
            add_char_buff(&redobuff, mb_cptr2char_adv(&s));
        }
    }
}

    static void
AppendCharToRedobuff(int c)
{
    if (!block_redo)
    {
        add_char_buff(&redobuff, c);
    }
}

    static void
AppendNumberToRedobuff(long n)
{
    if (!block_redo)
    {
        add_num_buff(&redobuff, n);
    }
}

    static void
stuffReadbuff(char_u *s)
{
    add_buff(&readbuf1, s, -1L);
}

    static void
stuffRedoReadbuff(char_u *s)
{
    add_buff(&readbuf2, s, -1L);
}

    static void
stuffReadbuffLen(char_u *s, long len)
{
    add_buff(&readbuf1, s, len);
}

    static void
stuffcharReadbuff(int c)
{
    add_char_buff(&readbuf1, c);
}

    static void
stuffnumReadbuff(long n)
{
    add_num_buff(&readbuf1, n);
}

    static void
stuffescaped(char_u *arg, int literally)
{
    int         c;
    char_u      *start;

    while (*arg != NUL)
    {
        start = arg;
        while ((*arg >= ' ' && *arg < DEL) || (*arg ==  (0x80)  && !literally))
        {
            ++arg;
        }
        if (arg > start)
        {
            stuffReadbuffLen(start, (long)(arg - start));
        }

        if (*arg != NUL)
        {
            c = mb_cptr2char_adv(&arg);
            if (literally && ((c < ' ' && c != TAB) || c == DEL))
            {
                stuffcharReadbuff(Ctrl_V);
            }
            stuffcharReadbuff(c);
        }
    }
}

    static int
read_redo(int init, int old_redo)
{
    static buffblock_T  *bp;
    static char_u       *p;
    int                 c;
    int                 n;
    char_u              buf[MB_MAXBYTES + 1];
    int                 i;

    if (init)
    {
        if (old_redo)
        {
            bp = old_redobuff.bh_first.b_next;
        }
        else
        {
            bp = redobuff.bh_first.b_next;
        }
        if (bp == NULL)
        {
            return FAIL;
        }
        p = bp->b_str;
        return OK;
    }
    if ((c = *p) != NUL)
    {
        if ((c !=  (0x80)  || p[1] == KS_SPECIAL))
        {
            n =  (((c) < 0 || (c) > 255) ? 1 : mb_bytelen_tab[c]) ;
        }
        else
        {
            n = 1;
        }
        for (i = 0; ; ++i)
        {
            if (c ==  (0x80) )
            {
                c =  ((p[1]) == KS_SPECIAL ?  (0x80)  : (p[1]) == KS_ZERO ?   (-((KS_ZERO) + ((int)( ('X') ) << 8)))   :  (-((p[1]) + ((int)(p[2]) << 8))) ) ;
                p += 2;
            }
            if (*++p == NUL && bp->b_next != NULL)
            {
                bp = bp->b_next;
                p = bp->b_str;
            }
            buf[i] = c;
            if (i == n - 1)
            {
                if (n != 1)
                {
                    c = utf_ptr2char(buf);
                }
                break;
            }
            c = *p;
            if (c == NUL)
            {
                break;
            }
        }
    }

    return c;
}

    static void
copy_redo(int old_redo)
{
    int     c;

    while ((c = read_redo(FALSE, old_redo)) != NUL)
    {
        add_char_buff(&readbuf2, c);
    }
}

    static int
start_redo(long count, int old_redo)
{
    int     c;

    if (read_redo(TRUE, old_redo) == FAIL)
    {
        return FAIL;
    }

    c = read_redo(FALSE, old_redo);

    if (c == '"')
    {
        add_buff(&readbuf2, (char_u *)"\"", 1L);
        c = read_redo(FALSE, old_redo);

        if (c >= '1' && c < '9')
        {
            ++c;
        }
        add_char_buff(&readbuf2, c);

        if (c == '=')
        {
            add_char_buff(&readbuf2, CAR);
            cmd_silent = TRUE;
        }

        c = read_redo(FALSE, old_redo);
    }

    if (c == 'v')
    {
        VIsual = curwin->w_cursor;
        VIsual_active = TRUE;
        VIsual_select = FALSE;
        VIsual_reselect = TRUE;
        redo_VIsual_busy = TRUE;
        c = read_redo(FALSE, old_redo);
    }

    if (count)
    {
        while ( ((unsigned)(c) - '0' < 10) )
        {
            c = read_redo(FALSE, old_redo);
        }
        add_num_buff(&readbuf2, count);
    }

    add_char_buff(&readbuf2, c);
    copy_redo(old_redo);
    return OK;
}

    static int
start_redo_ins(void)
{
    int     c;

    if (read_redo(TRUE, FALSE) == FAIL)
    {
        return FAIL;
    }
    start_stuff();

    while ((c = read_redo(FALSE, FALSE)) != NUL)
    {
        if (vim_strchr((char_u *)"AaIiRrOo", c) != NULL)
        {
            if (c == 'O' || c == 'o')
            {
                add_buff(&readbuf2,  (char_u *)"\012" , -1L);
            }
            break;
        }
    }

    copy_redo(FALSE);
    block_redo = TRUE;
    return OK;
}

    static void
stop_redo_ins(void)
{
    block_redo = FALSE;
}

    static void
init_typebuf(void)
{
    if (typebuf.tb_buf != NULL)
    {
        return;
    }

    typebuf.tb_buf = typebuf_init;
    typebuf.tb_noremap = noremapbuf_init;
    typebuf.tb_buflen =  (5 * (MAXMAPLEN + 3)) ;
    typebuf.tb_len = 0;
    typebuf.tb_off = MAXMAPLEN + 4;
    typebuf.tb_change_cnt = 1;
}

    static int
ins_typebuf(char_u      *str, int         noremap, int         offset, int         nottyped, int         silent)
{
    char_u *s1;
    char_u *s2;
    int         newlen;
    int         addlen;
    int         i;
    int         newoff;
    int         val;
    int         nrm;

    init_typebuf();
    if (++typebuf.tb_change_cnt == 0)
    {
        typebuf.tb_change_cnt = 1;
    }

    addlen = (int) strlen((char *)(str)) ;

    if (offset == 0 && addlen <= typebuf.tb_off)
    {
        typebuf.tb_off -= addlen;
         memmove((char *)(typebuf.tb_buf + typebuf.tb_off), (char *)(str), (size_t)addlen) ;
    }
    else if (typebuf.tb_len == 0 && typebuf.tb_buflen >= addlen + 3 * (MAXMAPLEN + 4))
    {
        typebuf.tb_off = (typebuf.tb_buflen - addlen - 3 * (MAXMAPLEN + 4)) / 2;
         memmove((char *)(typebuf.tb_buf + typebuf.tb_off), (char *)(str), (size_t)addlen) ;
    }
    else
    {
        int extra;

        newoff = MAXMAPLEN + 4;
        extra = addlen + newoff + 4 * (MAXMAPLEN + 4);
        if (typebuf.tb_len > 2147483647 - extra)
        {
            emsg(_(e_command_too_complex));
            setcursor();
            return FAIL;
        }
        newlen = typebuf.tb_len + extra;
        s1 = alloc(newlen);
        if (s1 == NULL)
        {
            return FAIL;
        }
        s2 = alloc(newlen);
        if (s2 == NULL)
        {
            vim_free(s1);
            return FAIL;
        }
        typebuf.tb_buflen = newlen;

         memmove((char *)(s1 + newoff), (char *)(typebuf.tb_buf + typebuf.tb_off), (size_t)offset) ;
         memmove((char *)(s1 + newoff + offset), (char *)(str), (size_t)addlen) ;
         memmove((char *)(s1 + newoff + offset + addlen), (char *)(typebuf.tb_buf + typebuf.tb_off + offset), (size_t)(typebuf.tb_len - offset + 1)) ;
        if (typebuf.tb_buf != typebuf_init)
        {
            vim_free(typebuf.tb_buf);
        }
        typebuf.tb_buf = s1;

         memmove((char *)(s2 + newoff), (char *)(typebuf.tb_noremap + typebuf.tb_off), (size_t)offset) ;
         memmove((char *)(s2 + newoff + offset + addlen), (char *)(typebuf.tb_noremap + typebuf.tb_off + offset), (size_t)(typebuf.tb_len - offset)) ;
        if (typebuf.tb_noremap != noremapbuf_init)
        {
            vim_free(typebuf.tb_noremap);
        }
        typebuf.tb_noremap = s2;

        typebuf.tb_off = newoff;
    }
    typebuf.tb_len += addlen;

    if (noremap ==  (-2) )
    {
        val = RM_SCRIPT;
    }
    else if (noremap ==  (-3) )
    {
        val = RM_ABBR;
    }
    else
    {
        val = RM_NONE;
    }

    if (noremap ==  (-3) )
    {
        nrm = 1;
    }
    else if (noremap < 0)
    {
        nrm = addlen;
    }
    else
    {
        nrm = noremap;
    }
    for (i = 0; i < addlen; ++i)
    {
        typebuf.tb_noremap[typebuf.tb_off + i + offset] =
                                                  (--nrm >= 0) ? val : RM_YES;
    }

    if (nottyped || typebuf.tb_maplen > offset)
    {
        typebuf.tb_maplen += addlen;
    }
    if (silent || typebuf.tb_silent > offset)
    {
        typebuf.tb_silent += addlen;
        cmd_silent = TRUE;
    }
    if (typebuf.tb_no_abbr_cnt && offset == 0)
    {
        typebuf.tb_no_abbr_cnt += addlen;
    }

    return OK;
}

    static int
ins_char_typebuf(int c, int modifiers)
{
    char_u      buf[MB_MAXBYTES * 3 + 4];
    int         len = special_to_buf(c, modifiers, TRUE, buf);

    buf[len] = NUL;
    (void)ins_typebuf(buf, KeyNoremap, 0, !KeyTyped, cmd_silent);
    return len;
}

    static int
typebuf_changed(int         tb_change_cnt)
{
    return (tb_change_cnt != 0 && (typebuf.tb_change_cnt != tb_change_cnt));
}

    static int
typebuf_typed(void)
{
    return typebuf.tb_maplen == 0;
}

    static int
typebuf_maplen(void)
{
    return typebuf.tb_maplen;
}

    static void
del_typebuf(int len, int offset)
{
    int     i;

    if (len == 0)
    {
        return;
    }

    typebuf.tb_len -= len;

    if (offset == 0 && typebuf.tb_buflen - (typebuf.tb_off + len) >= 3 * MAXMAPLEN + 3)
    {
        typebuf.tb_off += len;
    }
    else
    {
        i = typebuf.tb_off + offset;
        if (typebuf.tb_off > MAXMAPLEN)
        {
             memmove((char *)(typebuf.tb_buf + MAXMAPLEN), (char *)(typebuf.tb_buf + typebuf.tb_off), (size_t)offset) ;
             memmove((char *)(typebuf.tb_noremap + MAXMAPLEN), (char *)(typebuf.tb_noremap + typebuf.tb_off), (size_t)offset) ;
            typebuf.tb_off = MAXMAPLEN;
        }
         memmove((char *)(typebuf.tb_buf + typebuf.tb_off + offset), (char *)(typebuf.tb_buf + i + len), (size_t)(typebuf.tb_len - offset + 1)) ;
         memmove((char *)(typebuf.tb_noremap + typebuf.tb_off + offset), (char *)(typebuf.tb_noremap + i + len), (size_t)(typebuf.tb_len - offset)) ;
    }

    if (typebuf.tb_maplen > offset)
    {
        if (typebuf.tb_maplen < offset + len)
        {
            typebuf.tb_maplen = offset;
        }
        else
        {
            typebuf.tb_maplen -= len;
        }
    }
    if (typebuf.tb_silent > offset)
    {
        if (typebuf.tb_silent < offset + len)
        {
            typebuf.tb_silent = offset;
        }
        else
        {
            typebuf.tb_silent -= len;
        }
    }
    if (typebuf.tb_no_abbr_cnt > offset)
    {
        if (typebuf.tb_no_abbr_cnt < offset + len)
        {
            typebuf.tb_no_abbr_cnt = offset;
        }
        else
        {
            typebuf.tb_no_abbr_cnt -= len;
        }
    }

    if (++typebuf.tb_change_cnt == 0)
    {
        typebuf.tb_change_cnt = 1;
    }
}

typedef struct
{
    char_u      buf[MB_MAXBYTES * 3 + 4];
    int         prev_c;
    size_t      buflen;
    unsigned    pending_special;
    unsigned    pending_mbyte;
} gotchars_state_T;

    static int
gotchars_add_byte(gotchars_state_T *state, char_u byte)
{
    int         c = state->buf[state->buflen++] = byte;
    int         retval = FALSE;
    int         in_special = state->pending_special > 0;
    int         in_mbyte = state->pending_mbyte > 0;

    if (in_special)
    {
        state->pending_special--;
    }
    else if (c ==  (0x80) )
    {
        state->pending_special = 2;
    }

    if (state->pending_special > 0)
    {
        goto ret_false;
    }

    if (in_mbyte)
    {
        state->pending_mbyte--;
    }
    else
    {
        if (in_special)
        {
            if (state->prev_c == KS_MODIFIER)
            {
                goto ret_false;
            }
            c =  ((state->prev_c) == KS_SPECIAL ?  (0x80)  : (state->prev_c) == KS_ZERO ?   (-((KS_ZERO) + ((int)( ('X') ) << 8)))   :  (-((state->prev_c) + ((int)(c) << 8))) ) ;
            if (c ==   (-((KS_EXTRA) + ((int)(KE_FOCUSGAINED) << 8)))   || c ==   (-((KS_EXTRA) + ((int)(KE_FOCUSLOST) << 8)))   || c ==   (-((KS_EXTRA) + ((int)(KE_COMPLETE_DELAY) << 8)))  )
            {
                state->buflen = 0;
            }
        }
        state->pending_mbyte =  (((c) < 0 || (c) > 255) ? 1 : mb_bytelen_tab[c])  - 1;
    }

    if (state->pending_mbyte > 0)
    {
        goto ret_false;
    }

    retval = TRUE;
ret_false:
    state->prev_c = c;
    return retval;
}

    static void
gotchars(char_u *chars, int len)
{
    char_u              *s = chars;
    int                 todo = len;
    static gotchars_state_T state;

    while (todo-- > 0)
    {
        if (!gotchars_add_byte(&state, *s++))
        {
            continue;
        }

        if (reg_recording != 0)
        {
            state.buf[state.buflen] = NUL;
            add_buff(&recordbuff, state.buf, (long)state.buflen);
            last_recorded_len += state.buflen;
        }
        state.buflen = 0;
    }

    may_sync_undo();

    ++maptick;
}

    static void
gotchars_ignore(void)
{
    char_u nop_buf[3] = {  (0x80) , KS_EXTRA, KE_IGNORE };
    gotchars(nop_buf, 3);
}

    static void
ungetchars(int len)
{
    if (reg_recording == 0)
    {
        return;
    }

    delete_buff_tail(&recordbuff, len);
    last_recorded_len -= len;
}

    static void
may_sync_undo(void)
{
    if ((!(State & (MODE_INSERT | MODE_CMDLINE)) || arrow_used) && scriptin[curscript] == NULL)
    {
        u_sync(FALSE);
    }
}

    static int
alloc_typebuf(void)
{
    typebuf.tb_buf = alloc( (5 * (MAXMAPLEN + 3)) );
    typebuf.tb_noremap = alloc( (5 * (MAXMAPLEN + 3)) );
    if (typebuf.tb_buf == NULL || typebuf.tb_noremap == NULL)
    {
        free_typebuf();
        return FAIL;
    }
    typebuf.tb_buflen =  (5 * (MAXMAPLEN + 3)) ;
    typebuf.tb_off = MAXMAPLEN + 4;
    typebuf.tb_len = 0;
    typebuf.tb_maplen = 0;
    typebuf.tb_silent = 0;
    typebuf.tb_no_abbr_cnt = 0;
    if (++typebuf.tb_change_cnt == 0)
    {
        typebuf.tb_change_cnt = 1;
    }
    return OK;
}

    static void
free_typebuf(void)
{
    if (typebuf.tb_buf == typebuf_init)
    {
        internal_error("Free typebuf 1");
    }
    else
    {
         vim_free(typebuf.tb_buf);
         (typebuf.tb_buf) = NULL;
    }
    if (typebuf.tb_noremap == noremapbuf_init)
    {
        internal_error("Free typebuf 2");
    }
    else
    {
         vim_free(typebuf.tb_noremap);
         (typebuf.tb_noremap) = NULL;
    }
}

static typebuf_T saved_typebuf[NSCRIPT];

static int old_char = -1;
static int old_mod_mask;
static int old_KeyStuffed;

static int can_get_old_char(void)
{
    return old_char != -1 && (old_KeyStuffed || stuff_empty());
}

    static void
save_typeahead(tasave_T *tp)
{
    tp->save_typebuf = typebuf;
    tp->typebuf_valid = (alloc_typebuf() == OK);
    if (!tp->typebuf_valid)
    {
        typebuf = tp->save_typebuf;
    }

    tp->old_char = old_char;
    tp->old_mod_mask = old_mod_mask;
    old_char = -1;

    tp->save_readbuf1 = readbuf1;
    readbuf1.bh_first.b_next = NULL;
    tp->save_readbuf2 = readbuf2;
    readbuf2.bh_first.b_next = NULL;
    tp->save_inputbuf = get_input_buf();
}

    static void
restore_typeahead(tasave_T *tp, int overwrite  __attribute__((unused)) )
{
    if (tp->typebuf_valid)
    {
        free_typebuf();
        typebuf = tp->save_typebuf;
    }

    old_char = tp->old_char;
    old_mod_mask = tp->old_mod_mask;

    free_buff(&readbuf1);
    readbuf1 = tp->save_readbuf1;
    free_buff(&readbuf2);
    readbuf2 = tp->save_readbuf2;
    set_input_buf(tp->save_inputbuf, overwrite);
}

    static void
closescript(void)
{
    free_typebuf();
    typebuf = saved_typebuf[curscript];

    fclose(scriptin[curscript]);
    scriptin[curscript] = NULL;
    if (curscript > 0)
    {
        --curscript;
    }
}

    static int
using_script(void)
{
    return scriptin[curscript] != NULL;
}

    static int
merge_modifyOtherKeys(int c_arg, int *modifiers)
{
    int c = c_arg;

    if (*modifiers & MOD_MASK_CTRL)
    {
        if ((c >= '`' && c <= 0x7f) || (c >= '@' && c <= '_'))
        {
            c &= 0x1f;
            if (c == NUL)
            {
                c =   (-((KS_ZERO) + ((int)( ('X') ) << 8)))  ;
            }
        }
        else if (c == '6')
        {
            c = 0x1e;
        }
        if (c != c_arg)
        {
            *modifiers &= ~MOD_MASK_CTRL;
        }
    }

    if ((*modifiers & (MOD_MASK_META | MOD_MASK_ALT)) && c >= 0 && c <= 127)
    {
        if ((*modifiers & MOD_MASK_SHIFT) && c >= 'a' && c <= 'z')
        {
            c += 'a' - 'A';
            *modifiers &= ~MOD_MASK_SHIFT;
        }
        c += 0x80;
        *modifiers &= ~(MOD_MASK_META | MOD_MASK_ALT);
    }

    return c;
}

    static void
add_byte_to_showcmd(char_u byte)
{
    static gotchars_state_T state;
    char_u      *ptr;
    int         modifiers = 0;
    int         c = NUL;

    if (!p_sc || msg_silent != 0)
    {
        return;
    }

    if (!gotchars_add_byte(&state, byte))
    {
        return;
    }

    state.buf[state.buflen] = NUL;
    state.buflen = 0;

    ptr = state.buf;
    if (ptr[0] ==  (0x80)  && ptr[1] == KS_MODIFIER && ptr[2] != NUL)
    {
        modifiers = ptr[2];
        ptr += 3;
    }

    if (*ptr != NUL)
    {
        char_u          *mb_ptr = mb_unescape(&ptr);

        c = mb_ptr != NULL ? utf_ptr2char(mb_ptr) : *ptr++;
        if (c <= 0x7f)
        {
            int         modifiers_after = modifiers;
            int         mod_c = merge_modifyOtherKeys(c, &modifiers_after);

            if (modifiers_after == 0)
            {
                modifiers = 0;
                c = mod_c;
            }
        }
    }

    if (modifiers != 0)
    {
        add_to_showcmd( (0x80) );
        add_to_showcmd(KS_MODIFIER);
        add_to_showcmd(modifiers);
    }
    if (c != NUL)
    {
        add_to_showcmd(c);
    }
    while (*ptr != NUL)
    {
        add_to_showcmd(*ptr++);
    }
}

    static int
vgetc(void)
{
    int c;
    int c2;
    int         n;
    char_u      buf[MB_MAXBYTES + 1];
    int         i;

    if (can_get_old_char())
    {
        c = old_char;
        old_char = -1;
        mod_mask = old_mod_mask;
    }
    else
    {
        static size_t   last_vgetc_recorded_len = 0;

        mod_mask = 0;
        vgetc_mod_mask = 0;
        vgetc_char = 0;

        last_recorded_len -= last_vgetc_recorded_len;

        for (;;)
        {
            int did_inc = FALSE;

            if (mod_mask)
            {
                ++no_mapping;
                ++allow_keys;
                did_inc = TRUE;
            }
            c = vgetorpeek(TRUE);
            if (did_inc)
            {
                --no_mapping;
                --allow_keys;
            }

            if (c ==  (0x80) )
            {
                int         save_allow_keys = allow_keys;

                ++no_mapping;
                allow_keys = 0;
                c2 = vgetorpeek(TRUE);
                c = vgetorpeek(TRUE);
                --no_mapping;
                allow_keys = save_allow_keys;
                if (c2 == KS_MODIFIER)
                {
                    mod_mask = c;
                    continue;
                }
                c =  ((c2) == KS_SPECIAL ?  (0x80)  : (c2) == KS_ZERO ?   (-((KS_ZERO) + ((int)( ('X') ) << 8)))   :  (-((c2) + ((int)(c) << 8))) ) ;

                if (allow_osc_key == 0 && c ==   (-((KS_EXTRA) + ((int)(KE_OSC) << 8)))  )
                {
                    continue;
                }

                if (c ==   (-((KS_EXTRA) + ((int)(KE_ESC) << 8)))  )
                {
                    c = ESC;
                }

            }

            if ((n =  (((c) < 0 || (c) > 255) ? 1 : mb_bytelen_tab[c]) ) > 1)
            {
                ++no_mapping;
                buf[0] = c;
                for (i = 1; i < n; ++i)
                {
                    buf[i] = vgetorpeek(TRUE);
                    if (buf[i] ==  (0x80) )
                    {
                        c = vgetorpeek(TRUE);
                        if (vgetorpeek(TRUE) == KE_CSI && c == KS_EXTRA)
                        {
                            buf[i] = CSI;
                        }
                    }
                }
                --no_mapping;
                c = utf_ptr2char(buf);
            }

            if (vgetc_char == 0)
            {
                vgetc_mod_mask = mod_mask;
                vgetc_char = c;
            }

            switch (c)
            {
                case   (-(('K') + ((int)('6') << 8)))  :
                    c = '+';
                    break;
                case   (-(('K') + ((int)('7') << 8)))  :
                    c = '-';
                    break;
                case   (-(('K') + ((int)('8') << 8)))  :
                    c = '/';
                    break;
                case   (-(('K') + ((int)('9') << 8)))  :
                    c = '*';
                    break;
                case   (-(('K') + ((int)('A') << 8)))  :
                    c = CAR;
                    break;
                case   (-(('K') + ((int)('B') << 8)))  :
                                c = '.';
                                break;
                case   (-(('K') + ((int)('C') << 8)))  :
                    c = '0';
                    break;
                case   (-(('K') + ((int)('D') << 8)))  :
                    c = '1';
                    break;
                case   (-(('K') + ((int)('E') << 8)))  :
                    c = '2';
                    break;
                case   (-(('K') + ((int)('F') << 8)))  :
                    c = '3';
                    break;
                case   (-(('K') + ((int)('G') << 8)))  :
                    c = '4';
                    break;
                case   (-(('K') + ((int)('H') << 8)))  :
                    c = '5';
                    break;
                case   (-(('K') + ((int)('I') << 8)))  :
                    c = '6';
                    break;
                case   (-(('K') + ((int)('J') << 8)))  :
                    c = '7';
                    break;
                case   (-(('K') + ((int)('K') << 8)))  :
                    c = '8';
                    break;
                case   (-(('K') + ((int)('L') << 8)))  :
                    c = '9';
                    break;

                case   (-((KS_EXTRA) + ((int)(KE_XHOME) << 8)))  :
                case   (-((KS_EXTRA) + ((int)(KE_ZHOME) << 8)))  :
                    if (mod_mask == MOD_MASK_SHIFT)
                                {
                                    c =   (-(('#') + ((int)('2') << 8)))  ;
                                    mod_mask = 0;
                                }
                                else if (mod_mask == MOD_MASK_CTRL)
                                {
                                    c =   (-((KS_EXTRA) + ((int)(KE_C_HOME) << 8)))  ;
                                    mod_mask = 0;
                                }
                                else
                                {
                                    c =   (-(('k') + ((int)('h') << 8)))  ;
                                }
                                break;
                case   (-((KS_EXTRA) + ((int)(KE_XEND) << 8)))  :
                case   (-((KS_EXTRA) + ((int)(KE_ZEND) << 8)))  :
                    if (mod_mask == MOD_MASK_SHIFT)
                                {
                                    c =   (-(('*') + ((int)('7') << 8)))  ;
                                    mod_mask = 0;
                                }
                                else if (mod_mask == MOD_MASK_CTRL)
                                {
                                    c =   (-((KS_EXTRA) + ((int)(KE_C_END) << 8)))  ;
                                    mod_mask = 0;
                                }
                                else
                                {
                                    c =   (-(('@') + ((int)('7') << 8)))  ;
                                }
                                break;

                case   (-((KS_EXTRA) + ((int)(KE_XUP) << 8)))  :
                    c =   (-(('k') + ((int)('u') << 8)))  ;
                    break;
                case   (-((KS_EXTRA) + ((int)(KE_XDOWN) << 8)))  :
                    c =   (-(('k') + ((int)('d') << 8)))  ;
                    break;
                case   (-((KS_EXTRA) + ((int)(KE_XLEFT) << 8)))  :
                    c =   (-(('k') + ((int)('l') << 8)))  ;
                    break;
                case   (-((KS_EXTRA) + ((int)(KE_XRIGHT) << 8)))  :
                    c =   (-(('k') + ((int)('r') << 8)))  ;
                    break;
            }

            break;
        }

        last_vgetc_recorded_len = last_recorded_len;
    }

    if (c !=   (-((KS_EXTRA) + ((int)(KE_IGNORE) << 8)))  )
    {
    }

    return c;
}

    static int
safe_vgetc(void)
{
    int c;

    c = vgetc();
    if (c == NUL)
    {
        c = get_keystroke();
    }
    return c;
}

    static int
plain_vgetc_nopaste(void)
{
    int c;

    do
    {
        c = safe_vgetc();
    }
    while (c ==   (-((KS_EXTRA) + ((int)(KE_IGNORE) << 8)))   || c ==   (-((KS_VER_SCROLLBAR) + ((int)( ('X') ) << 8)))   || c ==   (-((KS_HOR_SCROLLBAR) + ((int)( ('X') ) << 8)))   || c ==   (-((KS_EXTRA) + ((int)(KE_MOUSEMOVE) << 8)))  )
        ;
    return c;
}

    static int
plain_vgetc(void)
{
    int c = plain_vgetc_nopaste();

    if (c ==   (-(('P') + ((int)('S') << 8)))  )
    {
        c = bracketed_paste(PASTE_ONE_CHAR, FALSE, NULL);
    }

    return c;
}

    static int
vpeekc(void)
{
    if (can_get_old_char())
    {
        return old_char;
    }
    return vgetorpeek(FALSE);
}

    static int
char_avail(void)
{
    int     retval;

    ++no_mapping;
    retval = vpeekc();
    --no_mapping;
    return (retval != NUL);
}

typedef enum {
    map_result_fail,
    map_result_get,
    map_result_retry,
    map_result_nomatch
} map_result_T;

    static int
check_simplify_modifier(int max_offset)
{
    int         offset;
    char_u      *tp;

    for (offset = 0; offset < max_offset; ++offset)
    {
        if (offset + 3 >= typebuf.tb_len)
        {
            break;
        }
        tp = typebuf.tb_buf + typebuf.tb_off + offset;
        if ((tp[0] ==  (0x80)  || tp[0] == CSI) && tp[1] == KS_MODIFIER)
        {
            int modifier = tp[2];
            int c = tp[3];
            int new_c = merge_modifyOtherKeys(c, &modifier);

            if (new_c != c)
            {
                char_u  new_string[MB_MAXBYTES];
                int     len;
                int     key_offset = offset;

                if (offset == 0)
                {
                    vgetc_char = c;
                    vgetc_mod_mask = tp[2];
                }
                if ( ((new_c) < 0) )
                {
                    new_string[0] =  (0x80) ;
                    new_string[1] =  ((new_c) ==  (0x80)  ? KS_SPECIAL : (new_c) == NUL ? KS_ZERO :  ((-(new_c)) & 0xff) ) ;
                    new_string[2] =  (((new_c) ==  (0x80)  || (new_c) == NUL) ?  ('X')  :  (((unsigned)(-(new_c)) >> 8) & 0xff) ) ;
                    len = 3;
                }
                else
                {
                    len = utf_char2bytes(new_c, new_string);
                }
                if (modifier == 0)
                {
                    if (put_string_in_typebuf(offset, 4, new_string, len, NULL, 0, NULL) == FAIL)
                    {
                        return -1;
                    }
                }
                else
                {
                    tp[2] = modifier;
                    key_offset = offset + 3;
                    if (put_string_in_typebuf(key_offset, 1, new_string, len, NULL, 0, NULL) == FAIL)
                    {
                        return -1;
                    }
                }

                for (int i = 0; i < len; ++i)
                {
                    typebuf.tb_noremap[typebuf.tb_off + key_offset + i]
                                                            |= RM_SIMPLIFIED;
                }
                return len;
            }
        }
    }
    return 0;
}

    static int
key_protocol_enabled(void)
{
    int using_mok = modify_otherkeys_state != MOKS_INITIAL
                        ? modify_otherkeys_state == MOKS_ENABLED
                        : seenModifyOtherKeys;
    return using_mok || kitty_protocol_state == KKPS_ENABLED;
}

    static int
handle_mapping(int *keylenp, int *timedout, int *mapdepth)
{
    mapblock_T  *mp = NULL;
    mapblock_T  *mp2;
    mapblock_T  *mp_match;
    int         mp_match_len = 0;
    int         max_mlen = 0;
    int         want_termcode = 0;
    int         tb_c1;
    int         mlen;
    int         keylen = *keylenp;
    int         i;
    int         local_State = get_real_state();
    int         is_plug_map = FALSE;
    bool        in_osc = in_osc_sequence();

    if (!in_osc && typebuf.tb_len >= 3 && typebuf.tb_buf[typebuf.tb_off] ==  (0x80)  && typebuf.tb_buf[typebuf.tb_off + 1] == KS_EXTRA && typebuf.tb_buf[typebuf.tb_off + 2] == KE_PLUG)
    {
        is_plug_map = TRUE;
    }

    tb_c1 = typebuf.tb_buf[typebuf.tb_off];
    if (!in_osc && no_mapping == 0 && is_maphash_valid() && (no_zero_mapping == 0 || tb_c1 != '0') && (typebuf.tb_maplen == 0 || is_plug_map || (p_remap && (typebuf.tb_noremap[typebuf.tb_off] & (RM_NONE|RM_ABBR)) == 0)) && !(p_paste && (State & (MODE_INSERT | MODE_CMDLINE))) && !(State ==  (0x2000 | MODE_NORMAL)  && (tb_c1 == CAR || tb_c1 == ' ')) && State != MODE_ASKMORE && State != MODE_CONFIRM)
    {
        mp = get_buf_maphash_list(local_State, tb_c1);
        mp2 = get_maphash_list(local_State, tb_c1);
        if (mp == NULL)
        {
            mp = mp2;
            mp2 = NULL;
        }

        mp_match = NULL;
        mp_match_len = 0;
        for ( ; mp != NULL; mp->m_next == NULL ? (mp = mp2, mp2 = NULL) : (mp = mp->m_next))
        {
            if (mp->m_keys[0] == tb_c1 && (mp->m_mode & local_State) && !(mp->m_simplified && key_protocol_enabled() && typebuf.tb_maplen == 0 && (typebuf.tb_noremap[typebuf.tb_off] & RM_SIMPLIFIED) == 0))
            {
                for (mlen = 1; mlen < typebuf.tb_len; ++mlen)
                {
                    int c2 = typebuf.tb_buf[typebuf.tb_off + mlen];
                    if (mp->m_keys[mlen] != c2)
                    {
                        break;
                    }
                }

                {
                    char_u *p1 = mp->m_keys;
                    char_u *p2 = mb_unescape(&p1);

                    if (p2 != NULL && mb_bytelen_tab[tb_c1]  > utfc_ptr2len(p2))
                    {
                        mlen = 0;
                    }
                }

                keylen = mp->m_keylen;
                if (mlen == keylen || (mlen == typebuf.tb_len && typebuf.tb_len < keylen))
                {
                    char_u  *s;
                    int     n;

                    s = typebuf.tb_noremap + typebuf.tb_off;
                    if ((*s & ~RM_SIMPLIFIED) == RM_SCRIPT && (mp->m_keys[0] !=  (0x80)  || mp->m_keys[1] != KS_EXTRA || mp->m_keys[2] != KE_SNR))
                    {
                        continue;
                    }

                    for (n = mlen; --n >= 0; )
                    {
                        if (*s++ & (RM_NONE|RM_ABBR))
                        {
                            break;
                        }
                    }
                    if (!is_plug_map && n >= 0)
                    {
                        continue;
                    }

                    if (keylen > typebuf.tb_len)
                    {
                        if (!*timedout && !(mp_match != NULL && mp_match->m_nowait))
                        {
                            keylen =  (-2) ;
                            break;
                        }
                    }
                    else if (keylen > mp_match_len)
                    {
                        mp_match = mp;
                        mp_match_len = keylen;
                    }
                }
                else
                {
                    if (max_mlen < mlen)
                    {
                        max_mlen = mlen;
                        want_termcode = mp->m_keys[mlen] ==  (0x80) ;
                    }
                    else if (max_mlen == mlen && mp->m_keys[mlen] ==  (0x80) )
                    {
                        want_termcode = 1;
                    }

                    if ( ((unsigned)(mp->m_keys[mlen]) - 'A' < 26) )
                    {
                        want_termcode = 1;
                    }
                }
            }
        }

        if (keylen !=  (-2)  && mp_match != NULL)
        {
            mp = mp_match;
            keylen = mp_match_len;
        }
    }

    if (!in_osc && *p_pt != NUL && mp == NULL && (State & (MODE_INSERT | MODE_NORMAL)))
    {
        for (mlen = 0; mlen < typebuf.tb_len && p_pt[mlen]; ++mlen)
        {
            if (p_pt[mlen] != typebuf.tb_buf[typebuf.tb_off + mlen])
            {
                    break;
            }
        }
        if (p_pt[mlen] == NUL)
        {
            if (mlen > typebuf.tb_maplen)
            {
                gotchars(typebuf.tb_buf + typebuf.tb_off + typebuf.tb_maplen, mlen - typebuf.tb_maplen);
            }

            del_typebuf(mlen, 0);
            set_option_value_give_err((char_u *)"paste", (long)!p_paste, NULL, 0);
            if (!(State & MODE_INSERT))
            {
                msg_col = 0;
                msg_row = Rows - 1;
                msg_clr_eos();
            }
            status_redraw_all();
            redraw_statuslines();
            showmode();
            setcursor();
            *keylenp = keylen;
            return map_result_retry;
        }
        if (mlen == typebuf.tb_len)
        {
            keylen =  (-1) ;
        }
        else if (max_mlen < mlen)
        {
            max_mlen = mlen + 1;
        }
    }

    if (in_osc || ((mp == NULL || max_mlen + want_termcode > mp_match_len || (mp_match_len == 1 && *mp->m_keys == ESC && !*timedout)) && keylen !=  (-2) ))
    {
        int     save_keylen = keylen;

        if (in_osc || no_mapping == 0 || allow_keys != 0)
        {
            if (in_osc || ((typebuf.tb_maplen == 0 || (p_remap && (typebuf.tb_noremap[typebuf.tb_off] & ~RM_SIMPLIFIED) == RM_YES)) && !*timedout))
            {
                keylen = check_termcode(max_mlen + 1, NULL, 0, NULL);
            }
            else
            {
                keylen = 0;
            }

            if (keylen == 0 && save_keylen ==  (-1)  && !*timedout)
            {
                keylen =  (-1) ;
            }

            if (keylen == 0 && !no_reduce_keys)
            {
                keylen = check_simplify_modifier(max_mlen + 1);
                if (keylen < 0)
                {
                    return map_result_fail;
                }
            }

            if (keylen < 0 && typebuf.tb_len == typebuf.tb_maplen)
            {
                keylen = 0;
            }
        }
        else
        {
            keylen = 0;
        }
        if (keylen == 0)
        {
                if (mp == NULL)
                {
                    *keylenp = keylen;
                    return map_result_get;
                }
        }

        if (keylen > 0)
        {
            *keylenp = keylen;
            return map_result_retry;
        }

        if (mp == NULL || keylen < 0)
        {
            keylen =  (-1) ;
        }
        else
        {
            keylen = mp_match_len;
        }
    }

    if (keylen >= 0 && keylen <= typebuf.tb_len)
    {
        char_u *map_str;

        if (keylen > typebuf.tb_maplen)
        {
            gotchars(typebuf.tb_buf + typebuf.tb_off + typebuf.tb_maplen, keylen - typebuf.tb_maplen);
        }

        cmd_silent = (typebuf.tb_silent > 0);
        del_typebuf(keylen, 0);

        if (++*mapdepth >= p_mmd)
        {
            emsg(_(e_recursive_mapping));
            if (State & MODE_CMDLINE)
            {
                redrawcmdline();
            }
            else
            {
                setcursor();
            }
            flush_buffers(FLUSH_MINIMAL);
            *mapdepth = 0;
            *keylenp = keylen;
            return map_result_fail;
        }

        if (VIsual_active && VIsual_select && (mp->m_mode & MODE_VISUAL))
        {
            VIsual_select = FALSE;
            (void)ins_typebuf( (char_u *)"\200\365X" ,  (-1) , 0, TRUE, FALSE);
        }

            map_str = mp->m_str;

        if (map_str == NULL)
        {
            i = FAIL;
        }
        else
        {
            int noremap;

            if ( mp->m_noremap  != REMAP_YES)
            {
                noremap =  mp->m_noremap ;
            }
            else if ( strncmp((char *)(map_str), (char *)(mp->m_keys), ((size_t)keylen))  == 0 || (mp->m_alt != NULL &&  strncmp((char *)(map_str), (char *)(mp->m_alt->m_keys), ((size_t)mp->m_alt->m_keylen))  == 0))
            {
                noremap =  (-3) ;
            }
            else
            {
                noremap = REMAP_YES;
            }
            i = ins_typebuf(map_str, noremap, 0, TRUE, cmd_silent ||  mp->m_silent );
        }
        *keylenp = keylen;
        if (i == FAIL)
        {
            return map_result_fail;
        }
        return map_result_retry;
    }

    *keylenp = keylen;
    return map_result_nomatch;
}

    static void
vungetc(int c)
{
    old_char = c;
    old_mod_mask = mod_mask;
    old_KeyStuffed = KeyStuffed;
}

    static void
check_end_reg_executing(int advance)
{
    if (reg_executing != 0 && (typebuf.tb_maplen == 0 || pending_end_reg_executing))
    {
        if (advance)
        {
            reg_executing = 0;
            pending_end_reg_executing = FALSE;
        }
        else
        {
            pending_end_reg_executing = TRUE;
        }
    }

}

    static int
vgetorpeek(int advance)
{
    int         c;
    int         timedout = FALSE;
    int         mapdepth = 0;
    int         mode_deleted = FALSE;
    int new_wcol;
    int new_wrow;
    int         n;
    int old_wcol;
    int old_wrow;
    int         wait_tb_len;

    if (vgetc_busy > 0 && ex_normal_busy == 0)
    {
        return NUL;
    }

    ++vgetc_busy;

    if (advance)
    {
        KeyStuffed = FALSE;
    }

    init_typebuf();
    start_stuff();
    check_end_reg_executing(advance);
    do
    {
        if (typeahead_char != 0)
        {
            c = typeahead_char;
            if (advance)
            {
                typeahead_char = 0;
            }
        }
        else
        {
            c = read_readbuffers(advance);
        }
        if (c != NUL && !got_int)
        {
            if (advance)
            {
                KeyStuffed = TRUE;
            }
            if (typebuf.tb_no_abbr_cnt == 0)
            {
                typebuf.tb_no_abbr_cnt = 1;
            }
        }
        else
        {
            for (;;)
            {
                long    wait_time;
                int     keylen = 0;
                int     showcmd_idx;
                check_end_reg_executing(advance);
                if (typebuf.tb_maplen)
                {
                    line_breakcheck();
                }
                else
                {
                    ui_breakcheck();
                }
                if (got_int)
                {
                    c = inchar(typebuf.tb_buf, typebuf.tb_buflen - 1, 0L);

                    if ((c || typebuf.tb_maplen) && (State & (MODE_INSERT | MODE_CMDLINE)))
                    {
                        c = ESC;
                    }
                    else
                    {
                        c = Ctrl_C;
                    }
                    flush_buffers(FLUSH_INPUT);

                    if (advance)
                    {
                        *typebuf.tb_buf = c;
                        gotchars(typebuf.tb_buf, 1);
                    }
                    cmd_silent = FALSE;

                    break;
                }
                else if (typebuf.tb_len > 0)
                {
                    map_result_T result = handle_mapping(&keylen, &timedout, &mapdepth);

                    if (result == map_result_retry)
                    {
                        continue;
                    }
                    if (result == map_result_fail)
                    {
                        c = -1;
                        break;
                    }
                    if (result == map_result_get)
                    {
                        c = typebuf.tb_buf[typebuf.tb_off];
                        if (advance)
                        {
                            cmd_silent = (typebuf.tb_silent > 0);
                            if (typebuf.tb_maplen > 0)
                            {
                                KeyTyped = FALSE;
                            }
                            else
                            {
                                KeyTyped = TRUE;
                                gotchars(typebuf.tb_buf + typebuf.tb_off, 1);
                            }
                            KeyNoremap = typebuf.tb_noremap[typebuf.tb_off]
                                                            & ~RM_SIMPLIFIED;
                            del_typebuf(1, 0);
                        }
                        break;
                    }

                }

                c = 0;
                new_wcol = curwin->w_wcol;
                new_wrow = curwin->w_wrow;
                if (       advance && typebuf.tb_len == 1 && typebuf.tb_buf[typebuf.tb_off] == ESC && !no_mapping && kitty_protocol_state != KKPS_ENABLED && ex_normal_busy == 0 && typebuf.tb_maplen == 0 && (State & MODE_INSERT) && (p_timeout || (keylen ==  (-1)  && p_ttimeout)) && (c = inchar(typebuf.tb_buf + typebuf.tb_off + typebuf.tb_len, 3, 25L)) == 0)
                {
                    colnr_T     col = 0;
                    char_u      *ptr;

                    if (mode_displayed)
                    {
                        unshowmode(TRUE);
                        mode_deleted = TRUE;
                    }
                    validate_cursor();
                    old_wcol = curwin->w_wcol;
                    old_wrow = curwin->w_wrow;

                    if (curwin->w_cursor.col != 0)
                    {
                        if (curwin->w_wcol > 0)
                        {
                            if (did_ai && *skipwhite(ml_get_curline() + curwin->w_cursor.col) == NUL)
                            {
                                chartabsize_T cts;

                                curwin->w_wcol = 0;
                                ptr = ml_get_curline();
                                init_chartabsize_arg(&cts, curwin, curwin->w_cursor.lnum, 0, ptr, ptr);
                                while (cts.cts_ptr < ptr + curwin->w_cursor.col)
                                {
                                    if (! ((*cts.cts_ptr) == ' ' || (*cts.cts_ptr) == '\t') )
                                    {
                                        curwin->w_wcol = cts.cts_vcol;
                                    }
                                    cts.cts_vcol += lbr_chartabsize(&cts);
                                    cts.cts_ptr +=
                                               utfc_ptr2len(cts.cts_ptr);
                                }

                                curwin->w_wrow = curwin->w_cline_row
                                           + curwin->w_wcol / curwin->w_width;
                                curwin->w_wcol %= curwin->w_width;
                                curwin->w_wcol += curwin_col_off();
                                col = 0;
                            }
                            else
                            {
                                --curwin->w_wcol;
                                col = curwin->w_cursor.col - 1;
                            }
                        }
                        else if (curwin-> w_onebuf_opt.wo_wrap  && curwin->w_wrow)
                        {
                            --curwin->w_wrow;
                            curwin->w_wcol = curwin->w_width - 1;
                            col = curwin->w_cursor.col - 1;
                        }
                        if (col > 0 && curwin->w_wcol > 0)
                        {
                            ptr = ml_get_curline();
                            col -= utf_head_off(ptr, ptr + col);
                            if (utf_ptr2cells(ptr + col) > 1)
                            {
                                --curwin->w_wcol;
                            }
                        }
                    }
                    setcursor();
                    out_flush();
                    new_wcol = curwin->w_wcol;
                    new_wrow = curwin->w_wrow;
                    curwin->w_wcol = old_wcol;
                    curwin->w_wrow = old_wrow;
                }
                if (c < 0)
                {
                    continue;
                }

                for (n = 1; n <= c; ++n)
                {
                    typebuf.tb_noremap[typebuf.tb_off + n] = RM_YES;
                }
                typebuf.tb_len += c;

                if (typebuf.tb_len >= typebuf.tb_maplen + MAXMAPLEN)
                {
                    timedout = TRUE;
                    continue;
                }

                if (ex_normal_busy > 0)
                {

                    if (typebuf.tb_len > 0)
                    {
                        timedout = TRUE;
                        continue;
                    }

                    if (p_im && (State & MODE_INSERT))
                    {
                        c = Ctrl_L;
                    }
                    else if ((State & MODE_CMDLINE))
                    {
                        c = Ctrl_C;
                    }
                    else
                    {
                        c = ESC;
                    }
                    if (advance)
                    {
                    }

                    if (pending_exmode_active)
                    {
                        exmode_active = EXMODE_NORMAL;
                    }

                    typebuf.tb_no_abbr_cnt = 0;

                    break;
                }

                if (((State & MODE_INSERT) != 0 || p_lz) && (State & MODE_CMDLINE) == 0 && advance && must_redraw != 0 && !need_wait_return)
                {
                    update_screen(0);
                    setcursor();
                }

                showcmd_idx = 0;
                int showing_partial = FALSE;
                if (typebuf.tb_len > 0 && advance && !exmode_active)
                {
                    if ((State & (MODE_NORMAL | MODE_INSERT)) && State !=  (0x2000 | MODE_NORMAL) )
                    {
                        if (State & MODE_INSERT && ptr2cells(typebuf.tb_buf + typebuf.tb_off + typebuf.tb_len - 1) == 1)
                        {
                            edit_putchar(typebuf.tb_buf[typebuf.tb_off + typebuf.tb_len - 1], FALSE);
                            setcursor();
                            showing_partial = TRUE;
                        }
                        old_wcol = curwin->w_wcol;
                        old_wrow = curwin->w_wrow;
                        curwin->w_wcol = new_wcol;
                        curwin->w_wrow = new_wrow;
                        push_showcmd();
                        if (typebuf.tb_len > SHOWCMD_COLS)
                        {
                            showcmd_idx = typebuf.tb_len - SHOWCMD_COLS;
                        }
                        while (showcmd_idx < typebuf.tb_len)
                        {
                            add_byte_to_showcmd(typebuf.tb_buf[typebuf.tb_off + showcmd_idx++]);
                        }
                        curwin->w_wcol = old_wcol;
                        curwin->w_wrow = old_wrow;
                    }

                    if ((State & MODE_CMDLINE) && get_cmdline_info()->cmdbuff != NULL && ptr2cells(typebuf.tb_buf + typebuf.tb_off + typebuf.tb_len - 1) == 1)
                    {
                        putcmdline(typebuf.tb_buf[typebuf.tb_off + typebuf.tb_len - 1], FALSE);
                        showing_partial = TRUE;
                    }
                }

                if (typebuf.tb_len == 0)
                {
                    timedout = FALSE;
                }

                if (advance)
                {
                    if (typebuf.tb_len == 0 || !(p_timeout || (p_ttimeout && keylen ==  (-1) )))
                    {
                        wait_time = -1L;
                    }
                    else if (keylen ==  (-1)  && p_ttm >= 0)
                    {
                        wait_time = p_ttm;
                    }
                    else
                    {
                        wait_time = p_tm;
                    }
                }
                else
                {
                    wait_time = 0;
                }

                wait_tb_len = typebuf.tb_len;
                c = inchar(typebuf.tb_buf + typebuf.tb_off + typebuf.tb_len, typebuf.tb_buflen - typebuf.tb_off - typebuf.tb_len - 1, wait_time);

                if (showcmd_idx != 0)
                {
                    pop_showcmd();
                }
                if (showing_partial)
                {
                    if (State & MODE_INSERT)
                    {
                        edit_unputchar();
                    }
                    if ((State & MODE_CMDLINE) && get_cmdline_info()->cmdbuff != NULL)
                    {
                        unputcmdline();
                    }
                    else
                    {
                        setcursor();
                    }
                }

                if (c < 0)
                {
                    continue;
                }
                if (c == NUL)
                {
                    if (!advance)
                    {
                        break;
                    }
                    if (wait_tb_len > 0)
                    {
                        timedout = TRUE;
                        continue;
                    }
                }
                else
                {
                    while (typebuf.tb_buf[typebuf.tb_off + typebuf.tb_len] != NUL)
                    {
                        typebuf.tb_noremap[typebuf.tb_off + typebuf.tb_len++] = RM_YES;
                    }
                }
            }
        }

    } while ((c < 0 && c !=   (-((KS_EXTRA) + ((int)(KE_CANCEL) << 8)))  ) || (advance && c == NUL));

    if (advance && p_smd && msg_silent == 0 && (State & MODE_INSERT))
    {
        if (c == ESC && !mode_deleted && !no_mapping && mode_displayed)
        {
            if (typebuf.tb_len && !KeyTyped)
            {
                redraw_cmdline = TRUE;
            }
            else
            {
                unshowmode(FALSE);
            }
        }
        else if (c != ESC && mode_deleted)
        {
            if (typebuf.tb_len && !KeyTyped)
            {
                redraw_cmdline = TRUE;
            }
            else
            {
                showmode();
            }
        }
    }
    if (timedout && c == ESC)
    {
        gotchars_ignore();
    }

    --vgetc_busy;

    return c;
}

    static int
inchar(char_u      *buf, int         maxlen, long        wait_time)
{
    int         len = 0;
    int         retesc = FALSE;
    int         script_char;
    int         tb_change_cnt = typebuf.tb_change_cnt;

    if (wait_time == -1L || wait_time > 100L)
    {
        cursor_on();
        out_flush_cursor(FALSE, FALSE);
    }

    if (State !=  (0x2000 | MODE_NORMAL) )
    {
        did_outofmem_msg = FALSE;
    }
    undo_off = FALSE;

    script_char = -1;
    while (scriptin[curscript] != NULL && script_char < 0)
    {
        if (got_int || (script_char = getc(scriptin[curscript])) < 0)
        {
            closescript();
            if (got_int)
            {
                retesc = TRUE;
            }
            else
            {
                return -1;
            }
        }
        else
        {
            buf[0] = script_char;
            len = 1;
        }
    }

    if (script_char < 0)
    {
        if (got_int)
        {
            char_u      dum[ (MAXMAPLEN * 3 + 3)  + 1];

            for (;;)
            {
                len = ui_inchar(dum,  (MAXMAPLEN * 3 + 3) , 0L, 0);
                if (len == 0 || (len == 1 && dum[0] == Ctrl_C))
                {
                    break;
                }
            }
            return retesc;
        }

        if (wait_time == -1L || wait_time > 10L)
        {
            out_flush();
        }

        len = ui_inchar(buf, maxlen / 3, wait_time, tb_change_cnt);
    }

    if (typebuf_changed(tb_change_cnt))
    {
        return 0;
    }

    if (len > 0 && ++typebuf.tb_change_cnt == 0)
    {
        typebuf.tb_change_cnt = 1;
    }

    return fix_input_buffer(buf, len);
}

    static int
fix_input_buffer(char_u *buf, int len)
{
    int         i;
    char_u      *p = buf;

    for (i = len; --i >= 0; ++p)
    {
        if (p[0] == NUL || (p[0] ==  (0x80)  && (i < 2 || p[1] != KS_EXTRA || (p[2] != (int)KE_CURSORHOLD && p[2] != (int)KE_COMPLETE_DELAY))))
        {
             memmove((char *)(p + 3), (char *)(p + 1), (size_t)i) ;
            p[2] =  (((p[0]) ==  (0x80)  || (p[0]) == NUL) ?  ('X')  :  (((unsigned)(-(p[0])) >> 8) & 0xff) ) ;
            p[1] =  ((p[0]) ==  (0x80)  ? KS_SPECIAL : (p[0]) == NUL ? KS_ZERO :  ((-(p[0])) & 0xff) ) ;
            p[0] =  (0x80) ;
            p += 2;
            len += 2;
        }
    }
    *p = NUL;
    return len;
}

    static int
input_available(void)
{
    return (!vim_is_input_buf_empty());
}

    static char_u *
getcmdkeycmd(int             promptc  __attribute__((unused)) , void            *cookie  __attribute__((unused)) , int             indent  __attribute__((unused)) , getline_opt_T   do_concat  __attribute__((unused)) )
{
    garray_T    line_ga;
    int         c1 = -1;
    int         c2;
    int         cmod = 0;
    int         aborted = FALSE;

    ga_init2(&line_ga, 1, 32);

    no_mapping++;

    got_int = FALSE;
    while (c1 != NUL && !aborted)
    {
        if (ga_grow(&line_ga, 32) == FAIL)
        {
            aborted = TRUE;
            break;
        }

        if (vgetorpeek(FALSE) == NUL)
        {
            emsg(_(e_cmd_mapping_must_end_with_cr));
            aborted = TRUE;
            break;
        }

        c1 = vgetorpeek(TRUE);

        if (c1 ==  (0x80) )
        {
            c1 = vgetorpeek(TRUE);
            c2 = vgetorpeek(TRUE);
            if (c1 == KS_MODIFIER)
            {
                cmod = c2;
                continue;
            }
            c1 =  ((c1) == KS_SPECIAL ?  (0x80)  : (c1) == KS_ZERO ?   (-((KS_ZERO) + ((int)( ('X') ) << 8)))   :  (-((c1) + ((int)(c2) << 8))) ) ;

            if (c1 ==   (-((KS_EXTRA) + ((int)(KE_ESC) << 8)))  )
            {
                c1 = ESC;
            }

        }

        if (got_int)
        {
            aborted = TRUE;
        }
        else if (c1 == '\r' || c1 == '\n')
        {
            c1 = NUL;
        }
        else if (c1 == ESC)
        {
            aborted = TRUE;
        }
        else if (c1 ==   (-((KS_EXTRA) + ((int)(KE_COMMAND) << 8)))   || c1 ==   (-((KS_EXTRA) + ((int)(KE_SCRIPT_COMMAND) << 8)))  )
        {
            emsg(_(e_cmd_mapping_must_end_with_cr_before_second_cmd));
            aborted = TRUE;
        }
        else if (c1 ==   (-((KS_EXTRA) + ((int)(KE_SNR) << 8)))  )
        {
             ga_concat_len((&line_ga), (char_u *)("<SNR>"),  (sizeof("<SNR>" "") - 1) ) ;
        }
        else
        {
            if (cmod != 0)
            {
                ga_append(&line_ga,  (0x80) );
                ga_append(&line_ga, KS_MODIFIER);
                ga_append(&line_ga, cmod);
            }
            if ( ((c1) < 0) )
            {
                ga_append(&line_ga,  (0x80) );
                ga_append(&line_ga,  ((c1) ==  (0x80)  ? KS_SPECIAL : (c1) == NUL ? KS_ZERO :  ((-(c1)) & 0xff) ) );
                ga_append(&line_ga,  (((c1) ==  (0x80)  || (c1) == NUL) ?  ('X')  :  (((unsigned)(-(c1)) >> 8) & 0xff) ) );
            }
            else
            {
                ga_append(&line_ga, c1);
            }
        }

        cmod = 0;
    }

    no_mapping--;

    if (aborted)
    {
        ga_clear(&line_ga);
    }

    return (char_u *)line_ga.ga_data;
}

    static int
do_cmdkey_command(int key  __attribute__((unused)) , int flags)
{
    int     res;

    res = do_cmdline(NULL, getcmdkeycmd, NULL, flags);

    return res;
}

enum { PERTURB_SHIFT = 5 };

static int hash_may_resize(hashtab_T *ht, int minitems);

    static void
hash_init(hashtab_T *ht)
{
      memset(((ht)), (0), (sizeof(*(ht))))  ;
    ht->ht_array = ht->ht_smallarray;
    ht->ht_mask = HT_INIT_SIZE - 1;
}

    static int
check_hashtab_frozen(hashtab_T *ht, char *command)
{
    if ((ht->ht_flags & HTFLAGS_FROZEN) == 0)
    {
        return FALSE;
    }

    semsg(_(e_not_allowed_to_add_or_remove_entries_str), command);
    return TRUE;
}

    static hashitem_T *
hash_find(hashtab_T *ht, char_u *key)
{
    return hash_lookup(ht, key, hash_hash(key));
}

    static hashitem_T *
hash_lookup(hashtab_T *ht, char_u *key, hash_T hash)
{
    hash_T      perturb;
    hashitem_T  *freeitem;
    hashitem_T  *hi;
    unsigned    idx;

    idx = (unsigned)(hash & ht->ht_mask);
    hi = &ht->ht_array[idx];

    if (hi->hi_key == NULL)
    {
        return hi;
    }
    if (hi->hi_key ==  &hash_removed )
    {
        freeitem = hi;
    }
    else if (hi->hi_hash == hash &&  strcmp((char *)(hi->hi_key), (char *)(key))  == 0)
    {
        return hi;
    }
    else
    {
        freeitem = NULL;
    }

    for (perturb = hash; ; perturb >>= PERTURB_SHIFT)
    {
        idx = (unsigned)((idx << 2U) + idx + perturb + 1U);
        hi = &ht->ht_array[idx & ht->ht_mask];
        if (hi->hi_key == NULL)
        {
            return freeitem == NULL ? hi : freeitem;
        }
        if (hi->hi_hash == hash && hi->hi_key !=  &hash_removed  &&  strcmp((char *)(hi->hi_key), (char *)(key))  == 0)
        {
            return hi;
        }
        if (hi->hi_key ==  &hash_removed  && freeitem == NULL)
        {
            freeitem = hi;
        }
    }
}

    static int
hash_add(hashtab_T *ht, char_u *key, char *command)
{
    hash_T      hash = hash_hash(key);
    hashitem_T  *hi;

    if (check_hashtab_frozen(ht, command))
    {
        return FAIL;
    }
    hi = hash_lookup(ht, key, hash);
    if (! ((hi)->hi_key == NULL || (hi)->hi_key == &hash_removed) )
    {
        internal_error("hash_add()");
        return FAIL;
    }
    return hash_add_item(ht, hi, key, hash);
}

    static int
hash_add_item(hashtab_T   *ht, hashitem_T  *hi, char_u      *key, hash_T      hash)
{
    if (ht->ht_flags & HTFLAGS_ERROR)
    {
        return FAIL;
    }

    ++ht->ht_used;
    ++ht->ht_changed;
    if (hi->hi_key == NULL)
    {
        ++ht->ht_filled;
    }
    hi->hi_key = key;
    hi->hi_hash = hash;

    return hash_may_resize(ht, 0);
}

    static int
hash_remove(hashtab_T *ht, hashitem_T *hi, char *command)
{
    if (check_hashtab_frozen(ht, command))
    {
        return FAIL;
    }
    --ht->ht_used;
    ++ht->ht_changed;
    hi->hi_key =  &hash_removed ;
    hash_may_resize(ht, 0);
    return OK;
}

    static int
hash_may_resize(hashtab_T   *ht, int         minitems)
{
    hashitem_T  temparray[HT_INIT_SIZE];
    hashitem_T *oldarray;
    hashitem_T *newarray;
    hashitem_T *olditem;
    hashitem_T *newitem;
    unsigned    newi;
    int         todo;
    long_u      newsize;
    long_u      minsize;
    long_u      newmask;
    hash_T      perturb;

    if (ht->ht_locked > 0)
    {
        return OK;
    }

    long_u oldsize = ht->ht_mask + 1;
    if (minitems == 0)
    {
        if (ht->ht_filled < HT_INIT_SIZE - 1 && ht->ht_array == ht->ht_smallarray)
        {
            return OK;
        }

        if (ht->ht_filled * 3 < oldsize * 2 && ht->ht_used > oldsize / 5)
        {
            return OK;
        }

        if (ht->ht_used > 1000)
        {
            minsize = ht->ht_used * 2;
        }
        else
        {
            minsize = ht->ht_used * 4;
        }
    }
    else
    {
        if ((long_u)minitems < ht->ht_used)
        {
            minitems = (int)ht->ht_used;
        }
        minsize = (minitems * 3 + 1) / 2;
    }

    newsize = HT_INIT_SIZE;
    while (newsize < minsize)
    {
        newsize <<= 1;
        if (newsize == 0)
        {
            return FAIL;
        }
    }

    if (newsize == HT_INIT_SIZE)
    {
        newarray = ht->ht_smallarray;
        if (ht->ht_array == newarray)
        {
             memmove((char *)(temparray), (char *)(newarray), sizeof(temparray)) ;
            oldarray = temparray;
        }
        else
        {
            oldarray = ht->ht_array;
        }
          memset((&(ht->ht_smallarray)), (0), (sizeof(ht->ht_smallarray)))  ;
    }

    else if (newsize == oldsize && ht->ht_filled * 3 < oldsize * 2)
    {
        return OK;
    }

    else
    {
        newarray =  (hashitem_T *)alloc_clear(sizeof(hashitem_T) * (newsize)) ;
        if (newarray == NULL)
        {
            if (ht->ht_filled < ht->ht_mask)
            {
                return OK;
            }
            ht->ht_flags |= HTFLAGS_ERROR;
            return FAIL;
        }
        oldarray = ht->ht_array;
    }

    newmask = newsize - 1;
    todo = (int)ht->ht_used;
    for (olditem = oldarray; todo > 0; ++olditem)
    {
        if (! ((olditem)->hi_key == NULL || (olditem)->hi_key == &hash_removed) )
        {
            newi = (unsigned)(olditem->hi_hash & newmask);
            newitem = &newarray[newi];

            if (newitem->hi_key != NULL)
            {
                for (perturb = olditem->hi_hash; ; perturb >>= PERTURB_SHIFT)
                {
                    newi = (unsigned)((newi << 2U) + newi + perturb + 1U);
                    newitem = &newarray[newi & newmask];
                    if (newitem->hi_key == NULL)
                    {
                        break;
                    }
                }
            }
            *newitem = *olditem;
            --todo;
        }
    }

    if (ht->ht_array != ht->ht_smallarray)
    {
        vim_free(ht->ht_array);
    }
    ht->ht_array = newarray;
    ht->ht_mask = newmask;
    ht->ht_filled = ht->ht_used;
    ++ht->ht_changed;
    ht->ht_flags &= ~HTFLAGS_ERROR;

    return OK;
}

    static hash_T
hash_hash(char_u *key)
{
    hash_T      hash;
    char_u      *p;

    if ((hash = *key) == 0)
    {
        return (hash_T)0;
    }
    p = key + 1;

    while (*p != NUL)
    {
        hash = hash * 101 + *p++;
    }

    return hash;
}

    static void
prepare_help_buffer(void)
{
    char_u      *p;

    curbuf->b_help = true;

    p = (char_u *)"!-~,^*,^|,^\",192-255";
    if ( strcmp((char *)(curbuf->b_p_isk), (char *)(p))  != 0)
    {
        set_string_option_direct((char_u *)"isk", -1, p, OPT_FREE|OPT_LOCAL, 0);
        check_buf_options(curbuf);
        (void)buf_init_chartab(curbuf, FALSE);
    }

    curbuf->b_p_ts = 8;
    curwin-> w_onebuf_opt.wo_list  = FALSE;

    curbuf->b_p_ma = FALSE;
    curwin-> w_onebuf_opt.wo_nu  = 0;
    curwin-> w_onebuf_opt.wo_rnu  = 0;

}

    static void
fix_help_buffer(void)
{
    linenr_T    lnum;
    char_u      *line;
    int         in_example = FALSE;
    int         len;

    {
        for (lnum = 1; lnum <= curbuf->b_ml.ml_line_count; ++lnum)
        {
            line = ml_get_buf(curbuf, lnum, FALSE);
            len = ml_get_buf_len(curbuf, lnum);
            if (in_example && len > 0 && ! ((line[0]) == ' ' || (line[0]) == '\t') )
            {
                if (line[0] == '<')
                {
                    line = ml_get_buf(curbuf, lnum, TRUE);
                    line[0] = ' ';
                }
                in_example = FALSE;
            }
            if (!in_example && len > 0)
            {
                if (line[len - 1] == '>' && (len == 1 || line[len - 2] == ' '))
                {
                    line = ml_get_buf(curbuf, lnum, TRUE);
                    line[len - 1] = ' ';
                    in_example = TRUE;
                }
                else if (line[len - 1] == '~')
                {
                    line = ml_get_buf(curbuf, lnum, TRUE);
                    line[len - 1] = ' ';
                }
            }
        }
    }

}

