    static int
highlight_set_cterm_font(int     idx, char_u  *arg, int     init)
{
    int         font;

    if (init && ( ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_set & SG_CTERM))
    {
        return FALSE;
    }

    if (!init)
    {
         ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_set |= SG_CTERM;
    }

    if ( ((unsigned)(*arg) - '0' < 10) )
    {
        font = atoi((char *)arg);
    }
    else if ( strcasecmp((char *)(arg), (char *)("NONE"))  == 0)
    {
        font = -1;
    }
    else
    {
        return FALSE;
    }

     ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_cterm_font = font + 1;
    return TRUE;
}

    static int
highlight_set_cterm_color(int     idx, char_u  *key, char_u  *key_start, char_u  *arg, int     is_normal_group, int     init)
{
    int         color;

    if (init && ( ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_set & SG_CTERM))
    {
        return FALSE;
    }

    if (!init)
    {
         ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_set |= SG_CTERM;
    }

    if (key[5] == 'F' &&  ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_cterm_bold)
    {
         ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_cterm &= ~HL_BOLD;
         ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_cterm_bold = FALSE;
    }

    if ( ((unsigned)(*arg) - '0' < 10) )
    {
        color = atoi((char *)arg);
    }
    else if ( strcasecmp((char *)(arg), (char *)("fg"))  == 0)
    {
        if (cterm_normal_fg_color)
        {
            color = cterm_normal_fg_color - 1;
        }
        else
        {
            emsg(_(e_fg_color_unknown));
            return FALSE;
        }
    }
    else if ( strcasecmp((char *)(arg), (char *)("bg"))  == 0)
    {
        if (cterm_normal_bg_color > 0)
        {
            color = cterm_normal_bg_color - 1;
        }
        else
        {
            emsg(_(e_bg_color_unknown));
            return FALSE;
        }
    }
    else if ( strcasecmp((char *)(arg), (char *)("ul"))  == 0)
    {
        if (cterm_normal_ul_color > 0)
        {
            color = cterm_normal_ul_color - 1;
        }
        else
        {
            emsg(_(e_ul_color_unknown));
            return FALSE;
        }
    }
    else
    {
        int bold = MAYBE;
        keyvalue_T target;
        keyvalue_T *entry;

        target.key = 0;
        target.value.string = arg;
        target.value.length = 0;
        entry = (keyvalue_T *)bsearch(&target, &color_name_tab,  (sizeof(color_name_tab) / sizeof((color_name_tab)[0])) , sizeof(color_name_tab[0]), cmp_keyvalue_value_i);
        if (entry == NULL)
        {
            semsg(_(e_color_name_or_number_not_recognized_str), key_start);
            return FALSE;
        }

        color = lookup_color(entry->key, key[5] == 'F', &bold);

        if (bold == TRUE)
        {
             ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_cterm |= HL_BOLD;
             ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_cterm_bold = TRUE;
        }
        else if (bold == FALSE)
        {
             ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_cterm &= ~HL_BOLD;
        }
    }

    if (key[5] == 'F')
    {
        highlight_set_ctermfg(idx, color, is_normal_group);
    }
    else if (key[5] == 'B')
    {
        highlight_set_ctermbg(idx, color, is_normal_group);
    }
    else
    {
        highlight_set_ctermul(idx, color, is_normal_group);
    }

    return TRUE;
}

    static int
highlight_set_startstop_termcode(int idx, char_u *key, char_u *arg, int init)
{
    int         off;
    char_u      buf[100];
    int         len;
    char_u      *tname;
    char_u      *p;

    if (!init)
    {
         ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_set |= SG_TERM;
    }

    if ( strncmp((char *)(arg), (char *)("t_"), (2))  == 0)
    {
        off = 0;
        buf[0] = 0;
        while (arg[off] != NUL)
        {
            for (len = 0; arg[off + len] && arg[off + len] != ','; ++len)
            {
                ;
            }
            tname = vim_strnsave(arg + off, len);
            if (tname == NULL)
            {
                return FALSE;
            }
            p = get_term_code(tname);
            vim_free(tname);
            if (p == NULL)
            {
                p = (char_u *)"";
            }

            if ((int)( strlen((char *)(buf))  +  strlen((char *)(p)) ) >= 99)
            {
                semsg(_(e_terminal_code_too_long_str), arg);
                return FALSE;
            }
             strcat((char *)(buf), (char *)(p)) ;

            off += len;
            if (arg[off] == ',')
            {
                ++off;
            }
        }
    }
    else
    {
        p = arg;
        for (off = 0; off < 100 - 6 && *p; )
        {
            len = trans_special(&p, buf + off, FSK_SIMPLIFY, FALSE, NULL);
            if (len > 0)
            {
                off += len;
            }
            else
            {
                buf[off++] = *p++;
            }
        }
        buf[off] = NUL;
    }

    if ( strcmp((char *)(buf), (char *)("NONE"))  == 0)
    {
        p = NULL;
    }
    else
    {
        p = vim_strsave(buf);
    }
    if (key[2] == 'A')
    {
        vim_free( ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_start);
         ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_start = p;
    }
    else
    {
        vim_free( ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_stop);
         ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_stop = p;
    }
    return TRUE;
}

    static void
do_highlight(char_u      *line, int         forceit, int         init)
{
    char_u      *name_end;
    char_u      *linep;
    char_u      *key_start;
    char_u      *arg_start;
    char_u *key = NULL;
    char_u *arg = NULL;
    long        i;
    int         id;
    int         idx;
    hl_group_T  item_before;
    int         did_change = FALSE;
    int         dodefault = FALSE;
    int         doclear = FALSE;
    int         dolink = FALSE;
    int         error = FALSE;
    int         is_normal_group = FALSE;

    if (!init && ends_excmd2(line - 1, line))
    {
        for (i = 1; i <= highlight_ga.ga_len && !got_int; ++i)
        {
            highlight_list_one((int)i);
        }
        return;
    }

    name_end = skiptowhite(line);
    linep = skipwhite(name_end);

    if ( strncmp((char *)(line), (char *)("default"), (name_end - line))  == 0)
    {
        dodefault = TRUE;
        line = linep;
        name_end = skiptowhite(line);
        linep = skipwhite(name_end);
    }

    if ( strncmp((char *)(line), (char *)("clear"), (name_end - line))  == 0)
    {
        doclear = TRUE;
    }
    if ( strncmp((char *)(line), (char *)("link"), (name_end - line))  == 0)
    {
        dolink = TRUE;
    }

    if (!doclear && !dolink && ends_excmd2(line, linep))
    {
        id = syn_namen2id(line, (int)(name_end - line));
        if (id == 0)
        {
            semsg(_(e_highlight_group_name_not_found_str), line);
        }
        else
        {
            highlight_list_one(id);
        }
        return;
    }

    if (dolink)
    {
        char_u      *from_start = linep;
        char_u      *from_end;
        int         from_len;
        char_u      *to_start;
        char_u      *to_end;
        int         to_len;

        from_end = skiptowhite(from_start);
        to_start = skipwhite(from_end);
        to_end   = skiptowhite(to_start);

        if (ends_excmd2(line, from_start) || ends_excmd2(line, to_start))
        {
            semsg(_(e_not_enough_arguments_highlight_link_str), from_start);
            return;
        }

        if (!ends_excmd2(line, skipwhite(to_end)))
        {
            semsg(_(e_too_many_arguments_highlight_link_str), from_start);
            return;
        }

        from_len = (int)(from_end - from_start);
        to_len = (int)(to_end - to_start);
        highlight_group_link(from_start, from_len, to_start, to_len, dodefault, forceit, init);
        return;
    }

    if (doclear)
    {
        if (ends_excmd2(line, linep))
        {
            highlight_reset_all();
            return;
        }
        line = linep;
        name_end = skiptowhite(line);
        linep = skipwhite(name_end);
    }

    id = syn_check_group(line, (int)(name_end - line));
    if (id == 0)
    {
        return;
    }
    idx = id - 1;

    if (dodefault && hl_has_settings(idx, TRUE))
    {
        return;
    }

    item_before =  ((hl_group_T *)((highlight_ga.ga_data))) [idx];

    if ( strcmp((char *)( ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_name_u), (char *)("NORMAL"))  == 0)
    {
        is_normal_group = TRUE;
    }

    if (doclear || (forceit && init))
    {
        highlight_clear(idx);
        if (!doclear)
        {
             ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_set = 0;
        }
    }

    if (!doclear)
    {
        while (!ends_excmd2(line, linep))
        {
            key_start = linep;
            if (*linep == '=')
            {
                semsg(_(e_unexpected_equal_sign_str), key_start);
                error = TRUE;
                break;
            }

            while (*linep && ! ((*linep) == ' ' || (*linep) == '\t')  && *linep != '=')
            {
                ++linep;
            }
            vim_free(key);
            key = vim_strnsave_up(key_start, linep - key_start);
            if (key == NULL)
            {
                error = TRUE;
                break;
            }
            linep = skipwhite(linep);

            if ( strcmp((char *)(key), (char *)("NONE"))  == 0)
            {
                if (!init ||  ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_set == 0)
                {
                    if (!init)
                    {
                         ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_set |= SG_TERM+SG_CTERM+SG_GUI;
                    }
                    highlight_clear(idx);
                }
                continue;
            }

            if (*linep != '=')
            {
                semsg(_(e_missing_equal_sign_str_2), key_start);
                error = TRUE;
                break;
            }
            ++linep;

            linep = skipwhite(linep);
            if (*linep == '\'')
            {
                arg_start = ++linep;
                linep = vim_strchr(linep, '\'');
                if (linep == NULL)
                {
                    semsg(_(e_invalid_argument_str), key_start);
                    error = TRUE;
                    break;
                }
            }
            else
            {
                arg_start = linep;
                linep = skiptowhite(linep);
            }
            if (linep == arg_start)
            {
                semsg(_(e_missing_argument_str), key_start);
                error = TRUE;
                break;
            }
            vim_free(arg);
            arg = vim_strnsave(arg_start, linep - arg_start);
            if (arg == NULL)
            {
                error = TRUE;
                break;
            }
            if (*linep == '\'')
            {
                ++linep;
            }

            if ( strcmp((char *)(key), (char *)("TERM"))  == 0 ||  strcmp((char *)(key), (char *)("CTERM"))  == 0 ||  strcmp((char *)(key), (char *)("GUI"))  == 0)
            {
                if (!highlight_set_termgui_attr(idx, key, arg, init))
                {
                    error = TRUE;
                    break;
                }
            }
            else if ( strcmp((char *)(key), (char *)("FONT"))  == 0)
            {
            }
            else if ( strcmp((char *)(key), (char *)("CTERMFG"))  == 0 ||  strcmp((char *)(key), (char *)("CTERMBG"))  == 0 ||  strcmp((char *)(key), (char *)("CTERMUL"))  == 0)
            {
                if (!highlight_set_cterm_color(idx, key, key_start, arg, is_normal_group, init))
                {
                    error = TRUE;
                    break;
                }
            }
            else if ( strcmp((char *)(key), (char *)("CTERMFONT"))  == 0)
            {
                if (!highlight_set_cterm_font(idx, arg, init))
                {
                    error = TRUE;
                    break;
                }
            }
            else if ( strcmp((char *)(key), (char *)("GUIFG"))  == 0)
            {
            }
            else if ( strcmp((char *)(key), (char *)("GUIBG"))  == 0)
            {
            }
            else if ( strcmp((char *)(key), (char *)("GUISP"))  == 0)
            {
            }
            else if ( strcmp((char *)(key), (char *)("START"))  == 0 ||  strcmp((char *)(key), (char *)("STOP"))  == 0)
            {
                if (!highlight_set_startstop_termcode(idx, key, arg, init))
                {
                    error = TRUE;
                    break;
                }
            }
            else
            {
                semsg(_(e_illegal_argument_str_3), key_start);
                error = TRUE;
                break;
            }
             ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_cleared = FALSE;

            if (!init || !( ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_set & SG_LINK))
            {
                 ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_link = 0;
            }

            linep = skipwhite(linep);
        }
    }

    if (error && idx == highlight_ga.ga_len)
    {
        syn_unadd_group();
    }
    else
    {
        if (is_normal_group)
        {
             ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_term_attr = 0;
             ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_cterm_attr = 0;
            resolve_fallback_fg_to_rgb();
            resolve_fallback_bg_to_rgb();
        }
        else
        {
            set_hl_attr(idx);
        }
    }

    vim_free(key);
    vim_free(arg);

    if ((did_change || memcmp(& ((hl_group_T *)((highlight_ga.ga_data))) [idx], &item_before, sizeof(item_before)) != 0))
    {
        if (!updating_screen)
        {
            redraw_all_later(UPD_NOT_VALID);
        }
        need_highlight_changed = TRUE;
    }
}

