static garray_T term_attr_table = {0, 0, 0, 0, NULL};

static garray_T cterm_attr_table = {0, 0, 0, 0, NULL};

    static int
get_attr_entry(garray_T *table, attrentry_T *aep)
{
    int         i;
    attrentry_T *taep;
    static int  recursive = FALSE;

    table->ga_itemsize = sizeof(attrentry_T);
    table->ga_growsize = 7;

    for (i = 0; i < table->ga_len; ++i)
    {
        taep = &(((attrentry_T *)table->ga_data)[i]);
        if (       aep->ae_attr == taep->ae_attr && ((table == &term_attr_table && (aep->ae_u.term.start == NULL) == (taep->ae_u.term.start == NULL) && (aep->ae_u.term.start == NULL ||  strcmp((char *)(aep->ae_u.term.start), (char *)(taep->ae_u.term.start))  == 0) && (aep->ae_u.term.stop == NULL) == (taep->ae_u.term.stop == NULL) && (aep->ae_u.term.stop == NULL ||  strcmp((char *)(aep->ae_u.term.stop), (char *)(taep->ae_u.term.stop))  == 0)) || (table == &cterm_attr_table && aep->ae_u.cterm.fg_color == taep->ae_u.cterm.fg_color && aep->ae_u.cterm.bg_color == taep->ae_u.cterm.bg_color && aep->ae_u.cterm.ul_color == taep->ae_u.cterm.ul_color && aep->ae_u.cterm.font == taep->ae_u.cterm.font)))
        {
        return i +  (HL_ALL + 1) ;
        }
    }

    if (table->ga_len +  (HL_ALL + 1)  > MAX_TYPENR)
    {
        if (recursive)
        {
            emsg(_(e_too_many_different_highlighting_attributes_in_use));
            return 0;
        }
        recursive = TRUE;

        clear_hl_tables();

        set_must_redraw(UPD_CLEAR);

        for (i = 0; i < highlight_ga.ga_len; ++i)
        {
            set_hl_attr(i);
        }

        recursive = FALSE;
    }

    if (ga_grow(table, 1) == FAIL)
    {
        return 0;
    }

    taep = &(((attrentry_T *)table->ga_data)[table->ga_len]);
      memset(((taep)), (0), (sizeof(*(taep))))  ;
    taep->ae_attr = aep->ae_attr;
    if (table == &term_attr_table)
    {
        if (aep->ae_u.term.start == NULL)
        {
            taep->ae_u.term.start = NULL;
        }
        else
        {
            taep->ae_u.term.start = vim_strsave(aep->ae_u.term.start);
        }
        if (aep->ae_u.term.stop == NULL)
        {
            taep->ae_u.term.stop = NULL;
        }
        else
        {
            taep->ae_u.term.stop = vim_strsave(aep->ae_u.term.stop);
        }
    }
    else if (table == &cterm_attr_table)
    {
        taep->ae_u.cterm.fg_color = aep->ae_u.cterm.fg_color;
        taep->ae_u.cterm.bg_color = aep->ae_u.cterm.bg_color;
        taep->ae_u.cterm.ul_color = aep->ae_u.cterm.ul_color;
        taep->ae_u.cterm.font = aep->ae_u.cterm.font;
    }
    ++table->ga_len;
    return (table->ga_len - 1 +  (HL_ALL + 1) );
}

    static void
clear_hl_tables(void)
{
    int         i;
    attrentry_T *taep;

    for (i = 0; i < term_attr_table.ga_len; ++i)
    {
        taep = &(((attrentry_T *)term_attr_table.ga_data)[i]);
        vim_free(taep->ae_u.term.start);
        vim_free(taep->ae_u.term.stop);
    }
    ga_clear(&term_attr_table);
    ga_clear(&cterm_attr_table);
}

