static const long_u cterm_color_16[16] = {
    0x000000, 0xc00000, 0x008000, 0x808000,
    0x0000c0, 0xc000c0, 0x004080, 0xc0c0c0,
    0x808080, 0xff8080, 0x00ff00, 0xffff00,
    0x6060ff, 0xff40ff, 0x00ffff, 0xffffff
};

    static void
cterm_idx_to_rgb(int idx, int *r, int *g, int *b)
{
    static const int cube[] = { 0x00, 0x5F, 0x87, 0xAF, 0xD7, 0xFF };

    if (idx < 0 || idx > 255)
    {
        *r = *g = *b = 0;
        return;
    }
    if (idx < 16)
    {
        long_u rgb = cterm_color_16[idx];
        *r = (rgb >> 16) & 0xFF;
        *g = (rgb >> 8) & 0xFF;
        *b = rgb & 0xFF;
    }
    else if (idx < 232)
    {
        int n = idx - 16;
        *r = cube[n / 36 % 6];
        *g = cube[n / 6  % 6];
        *b = cube[n      % 6];
    }
    else
    {
        int v = 8 + (idx - 232) * 10;
        *r = *g = *b = v;
    }
}

    static int
rgb_to_cterm_idx(int r, int g, int b)
{
    static const int cube[] = { 0x00, 0x5F, 0x87, 0xAF, 0xD7, 0xFF };
    int best = 0;
    long best_d = -1;
    int i;

    for (i = 16; i < 232; ++i)
    {
        int n = i - 16;
        int cr = cube[n / 36 % 6];
        int cg = cube[n / 6  % 6];
        int cb = cube[n      % 6];
        long d = (cr - r) * (cr - r) + (cg - g) * (cg - g) + (cb - b) * (cb - b);
        if (best_d < 0 || d < best_d)
        {
            best_d = d;
            best = i;
        }
    }
    for (i = 232; i < 256; ++i)
    {
        int v = 8 + (i - 232) * 10;
        long d = (v - r) * (v - r) + (v - g) * (v - g) + (v - b) * (v - b);
        if (d < best_d)
        {
            best_d = d;
            best = i;
        }
    }
    return best;
}

    static bool
resolve_color_to_rgb(int cterm_c,  long  rgb  __attribute__((unused)) , int *r, int *g, int *b)
{
    if (cterm_c > 0)
    {
        cterm_idx_to_rgb(cterm_c - 1, r, g, b);
        return true;
    }
    return false;
}

    static  long 
resolve_fallback_color(int cterm_c,  long  rgb,  long  default_rgb)
{
    int red;
    int green;
    int blue;
    if (!resolve_color_to_rgb(cterm_c, rgb, &red, &green, &blue))
    {
        return default_rgb;
    }
    else
    {
        return (red << 16) | (green << 8) | blue;
    }
}

    static void
resolve_fallback_fg_to_rgb(void)
{
     long  fgcolor_or_gui_fgcolor =  (( long )0x1ffffff) ;
    fallback_fg_rgb = resolve_fallback_color(cterm_normal_fg_color, fgcolor_or_gui_fgcolor, (*p_bg == 'l') ? 0x000000 : 0xFFFFFF);
}

    static void
resolve_fallback_bg_to_rgb(void)
{
     long  bgcolor_or_gui_bgcolor =  (( long )0x1ffffff) ;
    fallback_bg_rgb = resolve_fallback_color(cterm_normal_bg_color, bgcolor_or_gui_bgcolor, (*p_bg == 'l') ? 0xFFFFFF : 0x000000);
}

    static int
blend_cterm_colors(int popup_c,  long  popup_rgb, int under_c,  long  under_rgb, int default_rgb, int blend_val)
{
    int pr;
    int pg;
    int pb;
    int ur;
    int ug;
    int ub;
    int r;
    int g;
    int b;

    if (t_colors < 256)
    {
        return popup_c;
    }
    if (!resolve_color_to_rgb(popup_c, popup_rgb, &pr, &pg, &pb))
    {
        return under_c;
    }
    if (blend_val <= 0)
    {
        return rgb_to_cterm_idx(pr, pg, pb) + 1;
    }
    if (!resolve_color_to_rgb(under_c, under_rgb, &ur, &ug, &ub))
    {
        ur = (default_rgb >> 16) & 0xFF;
        ug = (default_rgb >> 8) & 0xFF;
        ub = default_rgb & 0xFF;
    }
    if (blend_val >= 100)
    {
        return rgb_to_cterm_idx(ur, ug, ub) + 1;
    }
    r = pr + (ur - pr) * blend_val / 100;
    g = pg + (ug - pg) * blend_val / 100;
    b = pb + (ub - pb) * blend_val / 100;
    return rgb_to_cterm_idx(r, g, b) + 1;
}

    static int
hl_blend_attr(int char_attr, int popup_attr, int blend, int blend_fg  __attribute__((unused)) )
{
    attrentry_T *char_aep = NULL;
    attrentry_T *popup_aep;
    attrentry_T new_en;
    attrentry_T tmp_en;

    if (blend >= 100 && blend_fg)
    {
        return char_attr;
    }

    if ( (t_colors > 1) )
    {
        if (char_attr > HL_ALL)
        {
            char_aep = syn_cterm_attr2entry(char_attr);
        }
        if (char_aep != NULL)
        {
            new_en = *char_aep;
        }
        else
        {
              memset((&(new_en)), (0), (sizeof(new_en)))  ;
            if (char_attr <= HL_ALL)
            {
                new_en.ae_attr = char_attr;
            }
        }

        if (popup_attr <= HL_ALL)
        {
              memset((&(tmp_en)), (0), (sizeof(tmp_en)))  ;
            tmp_en.ae_attr = popup_attr;
            popup_aep = &tmp_en;

            popup_aep->ae_u.cterm.bg_color = cterm_normal_bg_color;
        }
        else
        {
            popup_aep = syn_cterm_attr2entry(popup_attr);
        }

        if (popup_aep != NULL)
        {
             long  popup_bg_rgb =  (( long )0x1ffffff) ;
            if ( ((popup_bg_rgb) ==  (( long )0x1ffffff)  || (popup_bg_rgb) ==  (( long )0x1fffffe) )  && popup_aep->ae_u.cterm.bg_color == 0)
            {
                popup_bg_rgb = fallback_bg_rgb;
            }

            if (!blend_fg)
            {
                new_en.ae_attr = popup_aep->ae_attr;
                if (popup_aep->ae_u.cterm.fg_color > 0)
                {
                    new_en.ae_u.cterm.fg_color =
                        popup_aep->ae_u.cterm.fg_color;
                }
                else if (cterm_normal_fg_color > 0)
                {
                    new_en.ae_u.cterm.fg_color = cterm_normal_fg_color;
                }
                else
                {
                    new_en.ae_u.cterm.fg_color = (*p_bg == 'l') ? 1 : 16;
                }
                new_en.ae_u.cterm.ul_color = popup_aep->ae_u.cterm.ul_color;
                new_en.ae_u.cterm.font = popup_aep->ae_u.cterm.font;
            }
            else
            {
                int under_fg = (char_aep != NULL)
                    ? char_aep->ae_u.cterm.fg_color : 0;
                 long  under_fg_rgb =  (( long )0x1ffffff) ;
                new_en.ae_u.cterm.fg_color = blend_cterm_colors(popup_aep->ae_u.cterm.bg_color, popup_bg_rgb, under_fg, under_fg_rgb, fallback_fg_rgb, blend);
            }
            {
                int under_bg = (char_aep != NULL)
                    ? char_aep->ae_u.cterm.bg_color : 0;
                 long  under_bg_rgb =  (( long )0x1ffffff) ;
                new_en.ae_u.cterm.bg_color = blend_cterm_colors(popup_aep->ae_u.cterm.bg_color, popup_bg_rgb, under_bg, under_bg_rgb, fallback_bg_rgb, blend);
            }
        }
        return get_attr_entry(&cterm_attr_table, &new_en);
    }

    if (char_attr > HL_ALL)
    {
        char_aep = syn_term_attr2entry(char_attr);
    }
    if (char_aep != NULL)
    {
        new_en = *char_aep;
    }
    else
    {
          memset((&(new_en)), (0), (sizeof(new_en)))  ;
        if (char_attr <= HL_ALL)
        {
            new_en.ae_attr = char_attr;
        }
    }

    return get_attr_entry(&term_attr_table, &new_en);
}

