    static int
get_indent_str(char_u      *ptr, int         ts, int         no_ts)
{
    int         count = 0;

    for ( ; *ptr; ++ptr)
    {
        if (*ptr == TAB)
        {
            if (!no_ts)
            {
                count += ts - (count % ts);
            }
            else
            {
                count += ptr2cells(ptr);
            }
        }
        else if (*ptr == ' ')
        {
            ++count;
        }
        else
        {
            break;
        }
    }
    return count;
}

    static int
set_indent(int         size, int         flags)
{
    char_u      *p;
    char_u      *newline;
    char_u      *oldline;
    char_u      *s;
    int         todo;
    int         ind_len;
    int         line_len;
    int         doit = FALSE;
    int         ind_done = 0;
    int         tab_pad;
    int         retval = FALSE;
    int         orig_char_len = -1;

    todo = size;
    ind_len = 0;
    p = oldline = ml_get_curline();
    line_len = ml_get_curline_len() + 1;

    if (!curbuf->b_p_et || (!(flags & SIN_INSERT) && curbuf->b_p_pi))
    {
        if (!(flags & SIN_INSERT) && curbuf->b_p_pi)
        {
            ind_done = 0;

            while (todo > 0 &&  ((*p) == ' ' || (*p) == '\t') )
            {
                if (*p == TAB)
                {
                    tab_pad = (int)curbuf->b_p_ts
                                           - (ind_done % (int)curbuf->b_p_ts);
                    if (todo < tab_pad)
                    {
                        break;
                    }
                    todo -= tab_pad;
                    ++ind_len;
                    ind_done += tab_pad;
                }
                else
                {
                    --todo;
                    ++ind_len;
                    ++ind_done;
                }
                ++p;
            }

            if (curbuf->b_p_et)
            {
                orig_char_len = ind_len;
            }

            tab_pad = (int)curbuf->b_p_ts - (ind_done % (int)curbuf->b_p_ts);
            if (todo >= tab_pad && orig_char_len == -1)
            {
                doit = TRUE;
                todo -= tab_pad;
                ++ind_len;
            }
        }

        while (todo >= (int)curbuf->b_p_ts)
        {
            if (*p != TAB)
            {
                doit = TRUE;
            }
            else
            {
                ++p;
            }
            todo -= (int)curbuf->b_p_ts;
            ++ind_len;
        }
    }
    while (todo > 0)
    {
        if (*p != ' ')
        {
            doit = TRUE;
        }
        else
        {
            ++p;
        }
        --todo;
        ++ind_len;
    }

    if (!doit && ! ((*p) == ' ' || (*p) == '\t')  && !(flags & SIN_INSERT))
    {
        return FALSE;
    }

    if (flags & SIN_INSERT)
    {
        p = oldline;
    }
    else
    {
        p = skipwhite(p);
        line_len -= (int)(p - oldline);
    }

    if (orig_char_len != -1)
    {
        newline = alloc(orig_char_len + size - ind_done + line_len);
        if (newline == NULL)
        {
            return FALSE;
        }
        todo = size - ind_done;
        ind_len = orig_char_len + todo;
        p = oldline;
        s = newline;
        while (orig_char_len > 0)
        {
            *s++ = *p++;
            orig_char_len--;
        }

        while ( ((*p) == ' ' || (*p) == '\t') )
        {
            ++p;
        }

    }
    else
    {
        todo = size;
        newline = alloc(ind_len + line_len);
        if (newline == NULL)
        {
            return FALSE;
        }
        s = newline;
    }

    if (!curbuf->b_p_et)
    {
        if (!(flags & SIN_INSERT) && curbuf->b_p_pi)
        {
            p = oldline;
            ind_done = 0;

            while (todo > 0 &&  ((*p) == ' ' || (*p) == '\t') )
            {
                if (*p == TAB)
                {
                    tab_pad = (int)curbuf->b_p_ts
                                           - (ind_done % (int)curbuf->b_p_ts);
                    if (todo < tab_pad)
                    {
                        break;
                    }
                    todo -= tab_pad;
                    ind_done += tab_pad;
                }
                else
                {
                    --todo;
                    ++ind_done;
                }
                *s++ = *p++;
            }

            tab_pad = (int)curbuf->b_p_ts - (ind_done % (int)curbuf->b_p_ts);
            if (todo >= tab_pad)
            {
                *s++ = TAB;
                todo -= tab_pad;
            }

            p = skipwhite(p);
        }

        while (todo >= (int)curbuf->b_p_ts)
        {
            *s++ = TAB;
            todo -= (int)curbuf->b_p_ts;
        }
    }
    while (todo > 0)
    {
        *s++ = ' ';
        --todo;
    }
     memmove((char *)(s), (char *)(p), (size_t)line_len) ;

    if (!(flags & SIN_UNDO) || u_savesub(curwin->w_cursor.lnum) == OK)
    {
        colnr_T old_offset = (colnr_T)(p - oldline);
        colnr_T new_offset = (colnr_T)(s - newline);

        ml_replace(curwin->w_cursor.lnum, newline, FALSE);
        if (flags & SIN_CHANGED)
        {
            changed_bytes(curwin->w_cursor.lnum, 0);
        }

        if (saved_cursor.lnum == curwin->w_cursor.lnum)
        {
            if (saved_cursor.col >= old_offset)
            {
                saved_cursor.col += ind_len - old_offset;
            }
            else if (saved_cursor.col >= new_offset)
            {
                saved_cursor.col = new_offset;
            }
        }
        retval = TRUE;
    }
    else
    {
        vim_free(newline);
    }

    curwin->w_cursor.col = ind_len;
    return retval;
}

    static int
inindent(int extra)
{
    char_u      *ptr;
    colnr_T     col;

    for (col = 0, ptr = ml_get_curline();  ((*ptr) == ' ' || (*ptr) == '\t') ; ++col)
    {
        ++ptr;
    }
    if (col >= curwin->w_cursor.col + extra)
    {
        return TRUE;
    }
    else
    {
        return FALSE;
    }
}

