    static void
ins_try_si(int c)
{
    pos_T *pos;
    pos_T old_pos;
    char_u      *ptr;
    int         i;
    int         temp;

    if (((did_si || can_si_back) && c == '{') || (can_si && c == '}' && inindent(0)))
    {
        if (c == '}' && (pos = findmatch(NULL, '{')) != NULL)
        {
            old_pos = curwin->w_cursor;
            ptr = ml_get(pos->lnum);
            i = pos->col;
            if (i > 0)
            {
                while (--i > 0 &&  ((ptr[i]) == ' ' || (ptr[i]) == '\t') )
                {
                    ;
                }
            }
            curwin->w_cursor.lnum = pos->lnum;
            curwin->w_cursor.col = i;
            if (ptr[i] == ')' && (pos = findmatch(NULL, '(')) != NULL)
            {
                curwin->w_cursor = *pos;
            }
            i = get_indent();
            curwin->w_cursor = old_pos;
            if (State & VREPLACE_FLAG)
            {
                change_indent(INDENT_SET, i, FALSE, NUL, TRUE);
            }
            else
            {
                (void)set_indent(i, SIN_CHANGED);
            }
        }
        else if (curwin->w_cursor.col > 0)
        {
            temp = TRUE;
            if (c == '{' && can_si_back && curwin->w_cursor.lnum > 1)
            {
                old_pos = curwin->w_cursor;
                i = get_indent();
                while (curwin->w_cursor.lnum > 1)
                {
                    ptr = skipwhite(ml_get(--(curwin->w_cursor.lnum)));

                    if (*ptr != '#' && *ptr != NUL)
                    {
                        break;
                    }
                }
                if (get_indent() >= i)
                {
                    temp = FALSE;
                }
                curwin->w_cursor = old_pos;
            }
            if (temp)
            {
                shift_line(TRUE, FALSE, 1, TRUE);
            }
        }
    }

    if (curwin->w_cursor.col > 0 && can_si && c == '#' && inindent(0))
    {
        old_indent = get_indent();
        (void)set_indent(0, SIN_CHANGED);
    }

    if (ai_col > curwin->w_cursor.col)
    {
        ai_col = curwin->w_cursor.col;
    }
}

    static void
change_indent(int         type, int         amount, int         round, int         replaced, int         call_changed_bytes)
{
    int         vcol;
    int         last_vcol;
    int         insstart_less;
    int         new_cursor_col;
    int         i;
    char_u      *ptr;
    int         save_p_list;
    int         start_col;
    colnr_T     vc;
    colnr_T     orig_col = 0;
    char_u *new_line;
    char_u *orig_line = NULL;

    if (State & VREPLACE_FLAG)
    {
        orig_line = vim_strnsave(ml_get_curline(), ml_get_curline_len());
        orig_col = curwin->w_cursor.col;
    }

    save_p_list = curwin-> w_onebuf_opt.wo_list ;
    curwin-> w_onebuf_opt.wo_list  = FALSE;
    vc = getvcol_nolist(&curwin->w_cursor);
    vcol = vc;

    start_col = curwin->w_cursor.col;

    new_cursor_col = curwin->w_cursor.col;
    beginline(BL_WHITE);
    new_cursor_col -= curwin->w_cursor.col;

    insstart_less = curwin->w_cursor.col;

    if (new_cursor_col < 0)
    {
        vcol = get_indent() - vcol;
    }

    if (new_cursor_col > 0)
    {
        start_col = -1;
    }

    if (type == INDENT_SET)
    {
        (void)set_indent(amount, call_changed_bytes ? SIN_CHANGED : 0);
    }
    else
    {
        int     save_State = State;

        if (State & VREPLACE_FLAG)
        {
            State = MODE_INSERT;
        }
        shift_line(type == INDENT_DEC, round, 1, call_changed_bytes);
        State = save_State;
    }
    insstart_less -= curwin->w_cursor.col;

    if (new_cursor_col >= 0)
    {
        if (new_cursor_col == 0)
        {
            insstart_less = MAXCOL;
        }
        new_cursor_col += curwin->w_cursor.col;
    }
    else if (!(State & MODE_INSERT))
    {
        new_cursor_col = curwin->w_cursor.col;
    }
    else
    {
        chartabsize_T cts;

        vcol = get_indent() - vcol;
        curwin->w_virtcol = (colnr_T)((vcol < 0) ? 0 : vcol);

        last_vcol = 0;
        ptr = ml_get_curline();
        init_chartabsize_arg(&cts, curwin, 0, 0, ptr, ptr);
        while (cts.cts_vcol <= (int)curwin->w_virtcol)
        {
            last_vcol = cts.cts_vcol;
            if (cts.cts_vcol > 0)
            {
                 cts.cts_ptr += utfc_ptr2len(cts.cts_ptr) ;
            }
            if (*cts.cts_ptr == NUL)
            {
                break;
            }
            cts.cts_vcol += lbr_chartabsize(&cts);
        }
        vcol = last_vcol;
        new_cursor_col = cts.cts_ptr - cts.cts_line;

        if (vcol != (int)curwin->w_virtcol)
        {
            curwin->w_cursor.col = (colnr_T)new_cursor_col;
            i = (int)curwin->w_virtcol - vcol;
            ptr = alloc(i + 1);
            if (ptr != NULL)
            {
                size_t ptrlen;
                new_cursor_col += i;
                ptr[i] = NUL;
                ptrlen = i;
                while (--i >= 0)
                {
                    ptr[i] = ' ';
                }
                ins_str(ptr, ptrlen);
                vim_free(ptr);
            }
        }

        insstart_less = MAXCOL;
    }

    curwin-> w_onebuf_opt.wo_list  = save_p_list;

    if (new_cursor_col <= 0)
    {
        curwin->w_cursor.col = 0;
    }
    else
    {
        curwin->w_cursor.col = (colnr_T)new_cursor_col;
    }
    curwin->w_set_curswant = true;
    changed_cline_bef_curs();

    if (State & MODE_INSERT)
    {
        if (curwin->w_cursor.lnum == Insstart.lnum && Insstart.col != 0)
        {
            if ((int)Insstart.col <= insstart_less)
            {
                Insstart.col = 0;
            }
            else
            {
                Insstart.col -= insstart_less;
            }
        }
        if ((int)ai_col <= insstart_less)
        {
            ai_col = 0;
        }
        else
        {
            ai_col -= insstart_less;
        }
    }

    if ( (((State) & REPLACE_FLAG) && !((State) & VREPLACE_FLAG))  && start_col >= 0)
    {
        while (start_col > (int)curwin->w_cursor.col)
        {
            replace_join(0);
            --start_col;
        }
        while (start_col < (int)curwin->w_cursor.col || replaced)
        {
            replace_push(NUL);
            if (replaced)
            {
                replace_push(replaced);
                replaced = NUL;
            }
            ++start_col;
        }
    }

    if (State & VREPLACE_FLAG)
    {
        if (orig_line == NULL)
        {
            return;
        }

        new_line = vim_strnsave(ml_get_curline(), ml_get_curline_len());
        if (new_line == NULL)
        {
            vim_free(orig_line);
            return;
        }

        new_line[curwin->w_cursor.col] = NUL;

        ml_replace(curwin->w_cursor.lnum, orig_line, FALSE);
        curwin->w_cursor.col = orig_col;

        backspace_until_column(0);

        ins_bytes(new_line);

        vim_free(new_line);
    }
}

    static int
copy_indent(int size, char_u *src)
{
    char_u      *p = NULL;
    char_u      *line = NULL;
    char_u      *s;
    int         todo;
    int         ind_len;
    int         line_len = 0;
    int         tab_pad;
    int         ind_done;
    int         round;

    for (round = 1; round <= 2; ++round)
    {
        todo = size;
        ind_len = 0;
        ind_done = 0;
        s = src;

        while (todo > 0 &&  ((*s) == ' ' || (*s) == '\t') )
        {
            if (*s == TAB)
            {
                tab_pad = (int)curbuf->b_p_ts
                                           - (ind_done % (int)curbuf->b_p_ts);
                if (todo < tab_pad)
                {
                    break;
                }
                todo -= tab_pad;
                ind_done += tab_pad;
            }
            else
            {
                --todo;
                ++ind_done;
            }
            ++ind_len;
            if (p != NULL)
            {
                *p++ = *s;
            }
            ++s;
        }

        tab_pad = (int)curbuf->b_p_ts - (ind_done % (int)curbuf->b_p_ts);
        if (todo >= tab_pad && !curbuf->b_p_et)
        {
            todo -= tab_pad;
            ++ind_len;
            if (p != NULL)
            {
                *p++ = TAB;
            }
        }

        if (!curbuf->b_p_et)
        {
            while (todo >= (int)curbuf->b_p_ts)
            {
                todo -= (int)curbuf->b_p_ts;
                ++ind_len;
                if (p != NULL)
                {
                    *p++ = TAB;
                }
            }
        }

        while (todo > 0)
        {
            --todo;
            ++ind_len;
            if (p != NULL)
            {
                *p++ = ' ';
            }
        }

        if (p == NULL)
        {
            line_len = ml_get_curline_len() + 1;
            line = alloc(ind_len + line_len);
            if (line == NULL)
            {
                return FALSE;
            }
            p = line;
        }
    }

     memmove((char *)(p), (char *)(ml_get_curline()), (size_t)line_len) ;

    ml_replace(curwin->w_cursor.lnum, line, FALSE);

    curwin->w_cursor.col = ind_len;
    return TRUE;
}

