    static char_u *
map_mode_to_chars(int mode)
{
    garray_T    mapmode;

    ga_init2(&mapmode, 1, 7);

    if ((mode & (MODE_INSERT | MODE_CMDLINE)) == (MODE_INSERT | MODE_CMDLINE))
    {
        ga_append(&mapmode, '!');
    }
    else if (mode & MODE_INSERT)
    {
        ga_append(&mapmode, 'i');
    }
    else if (mode & MODE_CMDLINE)
    {
        ga_append(&mapmode, 'c');
    }
    else if ((mode & (MODE_NORMAL | MODE_VISUAL | MODE_SELECT | MODE_OP_PENDING)) == (MODE_NORMAL | MODE_VISUAL | MODE_SELECT | MODE_OP_PENDING))
    {
        ga_append(&mapmode, ' ');
    }
    else
    {
        if (mode & MODE_NORMAL)
        {
            ga_append(&mapmode, 'n');
        }
        if (mode & MODE_OP_PENDING)
        {
            ga_append(&mapmode, 'o');
        }
        if ((mode & (MODE_VISUAL | MODE_SELECT)) == (MODE_VISUAL | MODE_SELECT))
        {
            ga_append(&mapmode, 'v');
        }
        else
        {
            if (mode & MODE_VISUAL)
            {
                ga_append(&mapmode, 'x');
            }
            if (mode & MODE_SELECT)
            {
                ga_append(&mapmode, 's');
            }
        }
    }

    ga_append(&mapmode, NUL);
    return (char_u *)mapmode.ga_data;
}

    static void
showmap(mapblock_T  *mp, int         local)
{
    int         len = 1;
    char_u      *mapchars;

    if (message_filtered(mp->m_keys) && message_filtered(mp->m_str))
    {
        return;
    }

    ++map_locked;

    if (msg_didout || msg_silent != 0)
    {
        msg_putchar('\n');
        if (got_int)
        {
            goto theend;
        }
    }

    mapchars = map_mode_to_chars(mp->m_mode);
    if (mapchars != NULL)
    {
        msg_puts((char *)mapchars);
        len = (int) strlen((char *)(mapchars)) ;
        vim_free(mapchars);
    }

    while (++len <= 3)
    {
        msg_putchar(' ');
    }

    len = msg_outtrans_special(mp->m_keys, TRUE, 0);
    do
    {
        msg_putchar(' ');
        ++len;
    } while (len < 12);

    if (mp->m_noremap ==  (-1) )
    {
        msg_puts_attr("*",  highlight_attr[(int)(HLF_8)] );
    }
    else if (mp->m_noremap ==  (-2) )
    {
        msg_puts_attr("&",  highlight_attr[(int)(HLF_8)] );
    }
    else
    {
        msg_putchar(' ');
    }

    if (local)
    {
        msg_putchar('@');
    }
    else
    {
        msg_putchar(' ');
    }

    if (*mp->m_str == NUL)
    {
        msg_puts_attr("<Nop>",  highlight_attr[(int)(HLF_8)] );
    }
    else
    {
        msg_outtrans_special(mp->m_str, FALSE, 0);
    }
    msg_clr_eos();
    out_flush();

theend:
    --map_locked;
}

    static mapblock_T *
map_add(mapblock_T  **map_table, mapblock_T  **abbr_table, char_u      *keys, char_u      *rhs, char_u      *orig_rhs, int         noremap, int         nowait, int         silent, int         mode, int         is_abbr, int         simplified)
{
    mapblock_T  *mp =  (mapblock_T *)alloc_clear(sizeof(mapblock_T)) ;

    if (mp == NULL)
    {
        return NULL;
    }

    if (*keys == Ctrl_C)
    {
        if (map_table == curbuf->b_maphash)
        {
            curbuf->b_mapped_ctrl_c |= mode;
        }
        else
        {
            mapped_ctrl_c |= mode;
        }
    }

    mp->m_keys = vim_strsave(keys);
    mp->m_str = vim_strsave(rhs);
    mp->m_orig_str = vim_strsave(orig_rhs);
    if (mp->m_keys == NULL || mp->m_str == NULL)
    {
        vim_free(mp->m_keys);
        vim_free(mp->m_str);
        vim_free(mp->m_orig_str);
        vim_free(mp);
        return NULL;
    }
    mp->m_keylen = (int) strlen((char *)(mp->m_keys)) ;
    mp->m_noremap = noremap;
    mp->m_nowait = nowait;
    mp->m_silent = silent;
    mp->m_mode = mode;
    mp->m_simplified = simplified;

    if (is_abbr)
    {
        mp->m_next = *abbr_table;
        *abbr_table = mp;
    }
    else
    {
        int n =  (((mp->m_mode) & (MODE_NORMAL | MODE_VISUAL | MODE_SELECT | MODE_OP_PENDING | MODE_TERMINAL)) ? (mp->m_keys[0]) : ((mp->m_keys[0]) ^ 0x80)) ;

        mp->m_next = map_table[n];
        map_table[n] = mp;
    }
    return mp;
}

    static void
list_mappings(int     keyround, int     abbrev, int     haskey, char_u  *keys, int     keys_len, int     mode, int     *did_local)
{
    ++map_locked;

    if (p_verbose > 0 && keyround == 1)
    {
        if (seenModifyOtherKeys)
        {
            msg_puts(_("Seen modifyOtherKeys: true\n"));
        }

        if (modify_otherkeys_state != MOKS_INITIAL)
        {
            char *name = _("Unknown");
            switch (modify_otherkeys_state)
            {
                case MOKS_INITIAL:
                    break;
                case MOKS_OFF:
                    name = _("Off");
                    break;
                case MOKS_ENABLED:
                    name = _("On");
                    break;
                case MOKS_DISABLED:
                    name = _("Disabled");
                    break;
                case MOKS_AFTER_T_TE:
                    name = _("Cleared");
                    break;
            }

            char buf[200];
            vim_snprintf(buf, sizeof(buf), _("modifyOtherKeys detected: %s\n"), name);
            msg_puts(buf);
        }

        if (kitty_protocol_state != KKPS_INITIAL)
        {
            char *name = _("Unknown");
            switch (kitty_protocol_state)
            {
                case KKPS_INITIAL:
                    break;
                case KKPS_OFF:
                    name = _("Off");
                    break;
                case KKPS_ENABLED:
                    name = _("On");
                    break;
                case KKPS_DISABLED:
                    name = _("Disabled");
                    break;
                case KKPS_AFTER_T_TE:
                    name = _("Cleared");
                    break;
            }

            char buf[200];
            vim_snprintf(buf, sizeof(buf), _("Kitty keyboard protocol: %s\n"), name);
            msg_puts(buf);
        }
    }

    for (int hash = 0; hash < 256 && !got_int; ++hash)
    {
        mapblock_T      *mp;

        if (abbrev)
        {
            if (hash != 0)
            {
                break;
            }
            mp = curbuf->b_first_abbr;
        }
        else
        {
            mp = curbuf->b_maphash[hash];
        }
        for ( ; mp != NULL && !got_int; mp = mp->m_next)
        {
            if (!mp->m_simplified && (mp->m_mode & mode) != 0)
            {
                if (!haskey)
                {
                    showmap(mp, TRUE);
                    *did_local = TRUE;
                }
                else
                {
                    int n = mp->m_keylen;
                    if ( strncmp((char *)(mp->m_keys), (char *)(keys), ((size_t)(n < keys_len ? n : keys_len)))  == 0)
                    {
                        showmap(mp, TRUE);
                        *did_local = TRUE;
                    }
                }
            }
        }
    }

    --map_locked;
}

    static int
do_map(int         maptype, char_u      *arg, int         mode, int         abbrev)
{
    char_u      *keys;
    mapblock_T *mp;
    mapblock_T **mpp;
    mapblock_T  *mp_result[2] = {NULL, NULL};
    char_u      *rhs;
    char_u      *p;
    int         n;
    int         len = 0;
    int         hasarg;
    int         haskey;
    int         do_print;
    int         keyround;
    char_u      *keys_buf = NULL;
    char_u      *alt_keys_buf = NULL;
    char_u      *arg_buf = NULL;
    int         retval = 0;
    int         do_backslash;
    mapblock_T  **abbr_table;
    mapblock_T  **map_table;
    int         unique = FALSE;
    int         nowait = FALSE;
    int         silent = FALSE;
    int         special = FALSE;
    int         did_simplify = FALSE;
    int         unmap_lhs_only = FALSE;
    int         noremap;
    char_u      *orig_rhs;

    keys = arg;
    map_table = maphash;
    abbr_table = &first_abbr;

    if (maptype == MAPTYPE_UNMAP_LHS)
    {
        unmap_lhs_only = TRUE;
        maptype = MAPTYPE_UNMAP;
    }

    if (maptype == MAPTYPE_NOREMAP)
    {
        noremap =  (-1) ;
    }
    else
    {
        noremap = REMAP_YES;
    }

    for (;;)
    {
        if ( strncmp((char *)(keys), (char *)("<buffer>"), (8))  == 0)
        {
            keys = skipwhite(keys + 8);
            map_table = curbuf->b_maphash;
            abbr_table = &curbuf->b_first_abbr;
            continue;
        }

        if ( strncmp((char *)(keys), (char *)("<nowait>"), (8))  == 0)
        {
            keys = skipwhite(keys + 8);
            nowait = TRUE;
            continue;
        }

        if ( strncmp((char *)(keys), (char *)("<silent>"), (8))  == 0)
        {
            keys = skipwhite(keys + 8);
            silent = TRUE;
            continue;
        }

        if ( strncmp((char *)(keys), (char *)("<special>"), (9))  == 0)
        {
            keys = skipwhite(keys + 9);
            special = TRUE;
            continue;
        }

        if ( strncmp((char *)(keys), (char *)("<unique>"), (8))  == 0)
        {
            keys = skipwhite(keys + 8);
            unique = TRUE;
            continue;
        }
        break;
    }

    validate_maphash();

    p = keys;
    do_backslash = (vim_strchr(p_cpo, CPO_BSLASH) == NULL);
    while (*p && (maptype == MAPTYPE_UNMAP || ! ((*p) == ' ' || (*p) == '\t') ))
    {
        if ((p[0] == Ctrl_V || (do_backslash && p[0] == '\\')) && p[1] != NUL)
        {
            ++p;
        }
        ++p;
    }
    if (*p != NUL)
    {
        *p++ = NUL;
    }

    p = skipwhite(p);
    rhs = p;
    hasarg = (*rhs != NUL);
    haskey = (*keys != NUL);
    do_print = !haskey || (maptype != MAPTYPE_UNMAP && !hasarg);

    if (maptype == MAPTYPE_UNMAP && !haskey)
    {
        retval = 1;
        goto theend;
    }

    if (haskey)
    {
        char_u  *new_keys;
        int     flags = REPTERM_FROM_PART | REPTERM_DO_LT;

        if (special)
        {
            flags |= REPTERM_SPECIAL;
        }
        new_keys = replace_termcodes(keys, &keys_buf, 0, flags, &did_simplify);
        if (did_simplify)
        {
            (void)replace_termcodes(keys, &alt_keys_buf, 0, flags | REPTERM_NO_SIMPLIFY, NULL);
        }
        keys = new_keys;
    }
    orig_rhs = rhs;
    if (hasarg)
    {
        if ( strcasecmp((char *)(rhs), (char *)("<nop>"))  == 0)
        {
            rhs = (char_u *)"";
        }
        else
        {
            rhs = replace_termcodes(rhs, &arg_buf, 0, REPTERM_DO_LT | (special ? REPTERM_SPECIAL : 0), NULL);
        }
    }

    for (keyround = 1; keyround <= 2; ++keyround)
    {
        int     did_it = FALSE;
        int     did_local = FALSE;
        int     keyround1_simplified = keyround == 1 && did_simplify;
        int     round;
        int     num_rounds;

        if (keyround == 2)
        {
            if (alt_keys_buf == NULL)
            {
                break;
            }
            keys = alt_keys_buf;
        }
        else if (alt_keys_buf != NULL && do_print)
        {
            keys = alt_keys_buf;
        }

        if (haskey)
        {
            len = (int) strlen((char *)(keys)) ;
            if (len > MAXMAPLEN)
            {
                retval = 1;
                goto theend;
            }

            if (abbrev && maptype != MAPTYPE_UNMAP)
            {
                int first;
                int last;
                int         same = -1;
                char_u      keys_unescaped[MAXMAPLEN + 1];
                size_t      keys_unescaped_len;

                 memmove((char *)(keys_unescaped), (char *)(keys), (size_t)(len + 1)) ;
                keys_unescaped_len = vim_unescape_csi(keys_unescaped);
                p = keys_unescaped;

                first = vim_iswordp(p);
                last = first;
                 p += utfc_ptr2len(p) ;
                n = 1;
                while (p < keys_unescaped + keys_unescaped_len)
                {
                    ++n;
                    last = vim_iswordp(p);
                    if (same == -1 && last != first)
                    {
                        same = n - 1;
                    }
                     p += utfc_ptr2len(p) ;
                }
                if (last && n > 2 && same >= 0 && same < n - 1)
                {
                    retval = 1;
                    goto theend;
                }
                for (n = 0; n < len; ++n)
                {
                    if ( ((keys[n]) == ' ' || (keys[n]) == '\t') )
                    {
                        retval = 1;
                        goto theend;
                    }
                }
            }
        }

        if (haskey && hasarg && abbrev)
        {
            no_abbr = FALSE;
        }

        if (do_print)
        {
            msg_start();
        }

        if (unique && map_table == curbuf->b_maphash && haskey && hasarg && maptype != MAPTYPE_UNMAP)
        {
            for (int hash = 0; hash < 256 && !got_int; ++hash)
            {
                if (abbrev)
                {
                    if (hash != 0)
                    {
                        break;
                    }
                    mp = first_abbr;
                }
                else
                {
                    mp = maphash[hash];
                }
                for ( ; mp != NULL && !got_int; mp = mp->m_next)
                {
                    if ((mp->m_mode & mode) != 0 && mp->m_keylen == len &&  strncmp((char *)(mp->m_keys), (char *)(keys), ((size_t)len))  == 0)
                    {
                        if (abbrev)
                        {
                            semsg(_(e_global_abbreviation_already_exists_for_str), mp->m_keys);
                        }
                        else
                        {
                            semsg(_(e_global_mapping_already_exists_for_str), mp->m_keys);
                        }
                        retval = 5;
                        goto theend;
                    }
                }
            }
        }

        if (map_table != curbuf->b_maphash && !hasarg && maptype != MAPTYPE_UNMAP)
        {
            list_mappings(keyround, abbrev, haskey, keys, len, mode, &did_local);
        }

        num_rounds = maptype == MAPTYPE_UNMAP && !unmap_lhs_only ? 2 : 1;
        for (round = 0; round < num_rounds && !did_it && !got_int; ++round)
        {
            for (int hash = 0; hash < 256 && !got_int; ++hash)
            {
                if (abbrev)
                {
                    if (hash > 0)
                    {
                        break;
                    }
                    mpp = abbr_table;
                }
                else
                {
                    mpp = &(map_table[hash]);
                }
                for (mp = *mpp; mp != NULL && !got_int; mp = *mpp)
                {
                    if ((mp->m_mode & mode) == 0)
                    {
                        mpp = &(mp->m_next);
                        continue;
                    }
                    if (!haskey)
                    {
                        if (!mp->m_simplified)
                        {
                            showmap(mp, map_table != maphash);
                            did_it = TRUE;
                        }
                    }
                    else
                    {
                        if (round)
                        {
                            n = (int) strlen((char *)(mp->m_str)) ;
                            p = mp->m_str;
                        }
                        else
                        {
                            n = mp->m_keylen;
                            p = mp->m_keys;
                        }
                        if ( strncmp((char *)(p), (char *)(keys), ((size_t)(n < len ? n : len)))  == 0)
                        {
                            if (maptype == MAPTYPE_UNMAP)
                            {
                                if (n != len && (!abbrev || round || n > len || *skipwhite(keys + n) != NUL))
                                {
                                    mpp = &(mp->m_next);
                                    continue;
                                }
                                if (keyround1_simplified && !mp->m_simplified)
                                {
                                    break;
                                }
                                mp->m_mode &= ~mode;
                                did_it = TRUE;
                            }
                            else if (!hasarg)
                            {
                                if (!mp->m_simplified)
                                {
                                    showmap(mp, map_table != maphash);
                                    did_it = TRUE;
                                }
                            }
                            else if (n != len)
                            {
                                mpp = &(mp->m_next);
                                continue;
                            }
                            else if (unique)
                            {
                                if (abbrev)
                                {
                                    semsg(_(e_abbreviation_already_exists_for_str), p);
                                }
                                else
                                {
                                    semsg(_(e_mapping_already_exists_for_str), p);
                                }
                                retval = 5;
                                goto theend;
                            }
                            else
                            {
                                mp->m_mode &= ~mode;
                                if (mp->m_mode == 0 && !did_it)
                                {
                                    char_u *newstr = vim_strsave(rhs);

                                    if (newstr == NULL)
                                    {
                                        retval = 4;
                                        goto theend;
                                    }
                                    if (mp->m_alt != NULL)
                                    {
                                        mp->m_alt = mp->m_alt->m_alt = NULL;
                                    }
                                    vim_free(mp->m_str);
                                    mp->m_str = newstr;
                                    vim_free(mp->m_orig_str);
                                    mp->m_orig_str = vim_strsave(orig_rhs);
                                    mp->m_noremap = noremap;
                                    mp->m_nowait = nowait;
                                    mp->m_silent = silent;
                                    mp->m_mode = mode;
                                    mp->m_simplified = keyround1_simplified;
                                    mp_result[keyround - 1] = mp;
                                    did_it = TRUE;
                                }
                            }
                            if (mp->m_mode == 0)
                            {
                                map_free(mpp);
                                continue;
                            }

                            int new_hash =  (((mp->m_mode) & (MODE_NORMAL | MODE_VISUAL | MODE_SELECT | MODE_OP_PENDING | MODE_TERMINAL)) ? (mp->m_keys[0]) : ((mp->m_keys[0]) ^ 0x80)) ;
                            if (!abbrev && new_hash != hash)
                            {
                                *mpp = mp->m_next;
                                mp->m_next = map_table[new_hash];
                                map_table[new_hash] = mp;

                                continue;
                            }
                        }
                    }
                    mpp = &(mp->m_next);
                }
            }
        }

        if (maptype == MAPTYPE_UNMAP)
        {
            if (!did_it)
            {
                if (!keyround1_simplified)
                {
                    retval = 2;
                }
            }
            else if (*keys == Ctrl_C)
            {
                if (map_table == curbuf->b_maphash)
                {
                    curbuf->b_mapped_ctrl_c &= ~mode;
                }
                else
                {
                    mapped_ctrl_c &= ~mode;
                }
            }
            continue;
        }

        if (!haskey || !hasarg)
        {
            if (!did_it && !did_local)
            {
                if (abbrev)
                {
                    msg(_("No abbreviation found"));
                }
                else
                {
                    msg(_("No mapping found"));
                }
            }
            goto theend;
        }

        if (did_it)
        {
            continue;
        }

        mp_result[keyround - 1] = map_add(map_table, abbr_table, keys, rhs, orig_rhs, noremap, nowait, silent, mode, abbrev, keyround1_simplified);
        if (mp_result[keyround - 1] == NULL)
        {
            retval = 4;
            goto theend;
        }
    }

    if (mp_result[0] != NULL && mp_result[1] != NULL)
    {
        mp_result[0]->m_alt = mp_result[1];
        mp_result[1]->m_alt = mp_result[0];
    }

theend:
    vim_free(keys_buf);
    vim_free(alt_keys_buf);
    vim_free(arg_buf);
    return retval;
}

    static int
get_map_mode(char_u **cmdp, int forceit)
{
    char_u      *p;
    int         modec;
    int         mode;

    p = *cmdp;
    modec = *p++;
    if (modec == 'i')
    {
        mode = MODE_INSERT;
    }
    else if (modec == 'c')
    {
        mode = MODE_CMDLINE;
    }
    else if (modec == 'n' && *p != 'o')
    {
        mode = MODE_NORMAL;
    }
    else if (modec == 'v')
    {
        mode = MODE_VISUAL | MODE_SELECT;
    }
    else if (modec == 'x')
    {
        mode = MODE_VISUAL;
    }
    else if (modec == 's')
    {
        mode = MODE_SELECT;
    }
    else if (modec == 'o')
    {
        mode = MODE_OP_PENDING;
    }
    else
    {
        --p;
        if (forceit)
        {
            mode = MODE_INSERT | MODE_CMDLINE;
        }
        else
        {
            mode = MODE_VISUAL | MODE_SELECT | MODE_NORMAL | MODE_OP_PENDING;
        }
    }

    *cmdp = p;
    return mode;
}

    static void
map_clear(char_u      *cmdp, char_u      *arg, int         forceit, int         abbr)
{
    int         mode;
    int         local;

    local = ( strcmp((char *)(arg), (char *)("<buffer>"))  == 0);
    if (!local && *arg != NUL)
    {
        emsg(_(e_invalid_argument));
        return;
    }

    mode = get_map_mode(&cmdp, forceit);
    map_clear_mode(curbuf, mode, local, abbr);
}

    static int
is_map_locked(void)
{
    if (map_locked > 0)
    {
        emsg(_(e_cannot_change_mappings_while_listing));
        return TRUE;
    }
    return FALSE;
}

    static void
map_clear_mode(buf_T       *buf, int         mode, int         local, int         abbr)
{
    mapblock_T *mp;
    mapblock_T **mpp;
    int         hash;
    int         new_hash;

    if (is_map_locked())
    {
        return;
    }

    validate_maphash();

    for (hash = 0; hash < 256; ++hash)
    {
        if (abbr)
        {
            if (hash > 0)
            {
                break;
            }
            if (local)
            {
                mpp = &buf->b_first_abbr;
            }
            else
            {
                mpp = &first_abbr;
            }
        }
        else
        {
            if (local)
            {
                mpp = &buf->b_maphash[hash];
            }
            else
            {
                mpp = &maphash[hash];
            }
        }
        while (*mpp != NULL)
        {
            mp = *mpp;
            if (mp->m_mode & mode)
            {
                mp->m_mode &= ~mode;
                if (mp->m_mode == 0)
                {
                    map_free(mpp);
                    continue;
                }
                new_hash =  (((mp->m_mode) & (MODE_NORMAL | MODE_VISUAL | MODE_SELECT | MODE_OP_PENDING | MODE_TERMINAL)) ? (mp->m_keys[0]) : ((mp->m_keys[0]) ^ 0x80)) ;
                if (!abbr && new_hash != hash)
                {
                    *mpp = mp->m_next;
                    if (local)
                    {
                        mp->m_next = buf->b_maphash[new_hash];
                        buf->b_maphash[new_hash] = mp;
                    }
                    else
                    {
                        mp->m_next = maphash[new_hash];
                        maphash[new_hash] = mp;
                    }
                    continue;
                }
            }
            mpp = &(mp->m_next);
        }
    }
}

    static char_u *
vim_strsave_escape_csi(char_u *p)
{
    char_u      *res;
    char_u *s;
    char_u *d;

    res = alloc( strlen((char *)(p))  * 4 + 1);
    if (res == NULL)
    {
        return NULL;
    }

    d = res;
    for (s = p; *s != NUL; )
    {
        if ((s[0] ==  (0x80) ) && s[1] != NUL && s[2] != NUL)
        {
            *d++ = *s++;
            *d++ = *s++;
            *d++ = *s++;
        }
        else
        {
            d = add_char2buf( (utf_ptr2char(s)) , d);
            s +=  (utf_ptr2len(s)) ;
        }
    }
    *d = NUL;

    return res;
}

    static size_t
vim_unescape_csi(char_u *p)
{
    char_u *s = p;
    char_u *d = p;

    while (*s != NUL)
    {
        if (s[0] ==  (0x80)  && s[1] == KS_SPECIAL && s[2] ==  ('X') )
        {
            *d++ =  (0x80) ;
            s += 3;
        }
        else if ((s[0] ==  (0x80)  || s[0] == CSI) && s[1] == KS_EXTRA && s[2] == (int)KE_CSI)
        {
            *d++ = CSI;
            s += 3;
        }
        else
        {
            *d++ = *s++;
        }
    }
    *d = NUL;
    return (size_t)(d - p);
}

    static void
check_map_keycodes(void)
{
    mapblock_T  *mp;
    char_u      *p;
    int         i;
    char_u      buf[3];
    int         abbr;
    int         hash;
    buf_T       *bp;

    validate_maphash();
    estack_push(ETYPE_INTERNAL, (char_u *)"mappings", 0);

    for (bp = curbuf; ; bp = NULL)
    {
        for (abbr = 0; abbr <= 1; ++abbr)
        {
            for (hash = 0; hash < 256; ++hash)
            {
                if (abbr)
                {
                    if (hash)
                    {
                        break;
                    }
                    if (bp != NULL)
                    {
                        mp = bp->b_first_abbr;
                    }
                    else
                    {
                        mp = first_abbr;
                    }
                }
                else
                {
                    if (bp != NULL)
                    {
                        mp = bp->b_maphash[hash];
                    }
                    else
                    {
                        mp = maphash[hash];
                    }
                }
                for ( ; mp != NULL; mp = mp->m_next)
                {
                    for (i = 0; i <= 1; ++i)
                    {
                        if (i == 0)
                        {
                            p = mp->m_keys;
                        }
                        else
                        {
                            p = mp->m_str;
                        }
                        while (*p)
                        {
                            if (*p ==  (0x80) )
                            {
                                ++p;
                                if (*p < 128)
                                {
                                    buf[0] = p[0];
                                    buf[1] = p[1];
                                    buf[2] = NUL;
                                    (void)add_termcap_entry(buf, FALSE);
                                }
                                ++p;
                            }
                            ++p;
                        }
                    }
                }
            }
        }
        if (bp == NULL)
        {
            break;
        }
    }
    estack_pop();
}

struct initmap
{
    char_u      *arg;
    int         mode;
};

static struct initmap vimrc_mappings[] =
{
        {(char_u *)"<Tab> %", MODE_NORMAL | MODE_VISUAL | MODE_SELECT | MODE_OP_PENDING},
        {(char_u *)"\u00a7 <C-_>", MODE_INSERT | MODE_CMDLINE},
        {(char_u *)"\u00e9 u", MODE_NORMAL},
        {(char_u *)"\u00e1 <C-R>", MODE_NORMAL},
};

    static void
init_mappings(void)
{
    for (int i = 0; i < (int) (sizeof(vimrc_mappings) / sizeof((vimrc_mappings)[0])) ; ++i)
    {
        add_map(vimrc_mappings[i].arg, vimrc_mappings[i].mode, FALSE);
    }
}

    static void
add_map(char_u *map, int mode, int nore)
{
    char_u      *s;
    char_u      *cpo_save = p_cpo;

    p_cpo = empty_option;
    s = vim_strsave(map);
    if (s != NULL)
    {
        (void)do_map(nore ? MAPTYPE_NOREMAP : MAPTYPE_MAP, s, mode, FALSE);
        vim_free(s);
    }
    p_cpo = cpo_save;
}

    static void
do_exmap(exarg_T *eap, int isabbrev)
{
    int     mode;
    char_u  *cmdp;

    cmdp = eap->cmd;
    mode = get_map_mode(&cmdp, eap->forceit || isabbrev);

    switch (do_map(*cmdp == 'n' ? MAPTYPE_NOREMAP : *cmdp == 'u' ? MAPTYPE_UNMAP : MAPTYPE_MAP, eap->arg, mode, isabbrev))
    {
        case 1:
            emsg(_(e_invalid_argument));
                break;
        case 2:
            emsg((isabbrev ? _(e_no_such_abbreviation) : _(e_no_such_mapping)));
                break;
    }
}

    static void
ex_map(exarg_T *eap)
{
    if (secure)
    {
        secure = 2;
        msg_outtrans(eap->cmd);
        msg_putchar('\n');
    }
    do_exmap(eap, FALSE);
}

    static void
ex_unmap(exarg_T *eap)
{
    do_exmap(eap, FALSE);
}

    static void
ex_mapclear(exarg_T *eap)
{
    map_clear(eap->cmd, eap->arg, eap->forceit, FALSE);
}

static char_u *mark_line(pos_T *mp, int lead_len);
static void show_one_mark(int, char_u *, pos_T *, char_u *, int current);
static void mark_adjust_internal(linenr_T line1, linenr_T line2, long amount, long amount_after, int adjust_folds);

    static int
setmark(int c)
{
    return setmark_pos(c, &curwin->w_cursor, curbuf->b_fnum);
}

    static int
setmark_pos(int c, pos_T *pos, int fnum)
{
    int         i;
    buf_T       *buf;

    if (c < 0)
    {
        return FAIL;
    }

    if (c == '\'' || c == '`')
    {
        if (pos == &curwin->w_cursor)
        {
            setpcmark();
            curwin->w_prev_pcmark = curwin->w_pcmark;
        }
        else
        {
            curwin->w_pcmark = *pos;
        }
        return OK;
    }

    buf = buflist_findnr(fnum);
    if (buf == NULL)
    {
        return FAIL;
    }

    if (c == '"')
    {
        buf->b_last_cursor = *pos;
        return OK;
    }

    if (c == '[')
    {
        buf->b_op_start = *pos;
        return OK;
    }
    if (c == ']')
    {
        buf->b_op_end = *pos;
        return OK;
    }

    if (c == '<' || c == '>')
    {
        if (c == '<')
        {
            buf->b_visual.vi_start = *pos;
        }
        else
        {
            buf->b_visual.vi_end = *pos;
        }
        if (buf->b_visual.vi_mode == NUL)
        {
            buf->b_visual.vi_mode = 'v';
        }
        return OK;
    }

    if ( ((unsigned)(c) - 'a' < 26) )
    {
        i = c - 'a';
        buf->b_namedm[i] = *pos;
        return OK;
    }
    return FAIL;
}

    static void
setpcmark(void)
{

    if (global_busy || listcmd_busy || (cmdmod.cmod_flags & CMOD_KEEPJUMPS))
    {
        return;
    }

    curwin->w_prev_pcmark = curwin->w_pcmark;
    curwin->w_pcmark = curwin->w_cursor;

}

    static void
checkpcmark(void)
{
    if (curwin->w_prev_pcmark.lnum != 0 && ( (((curwin->w_pcmark).lnum == (curwin->w_cursor).lnum) && ((curwin->w_pcmark).col == (curwin->w_cursor).col) && ((curwin->w_pcmark).coladd == (curwin->w_cursor).coladd))  || curwin->w_pcmark.lnum == 0))
    {
        curwin->w_pcmark = curwin->w_prev_pcmark;
    }
    curwin->w_prev_pcmark.lnum = 0;
}

    static pos_T *
movechangelist(int count)
{
    int         n;

    if (curbuf->b_changelistlen == 0)
    {
        return (pos_T *)NULL;
    }

    n = curwin->w_changelistidx;
    if (n + count < 0)
    {
        if (n == 0)
        {
            return (pos_T *)NULL;
        }
        n = 0;
    }
    else if (n + count >= curbuf->b_changelistlen)
    {
        if (n == curbuf->b_changelistlen - 1)
        {
            return (pos_T *)NULL;
        }
        n = curbuf->b_changelistlen - 1;
    }
    else
    {
        n += count;
    }
    curwin->w_changelistidx = n;
    return curbuf->b_changelist + n;
}

    static pos_T *
getmark_buf(buf_T *buf, int c, int changefile)
{
    return getmark_buf_fnum(buf, c, changefile, NULL);
}

    static pos_T *
getmark(int c, int changefile)
{
    return getmark_buf_fnum(curbuf, c, changefile, NULL);
}

    static pos_T *
getmark_buf_fnum(buf_T       *buf, int         c, int         changefile, int         *fnum)
{
    pos_T               *posp;
    pos_T *startp;
    pos_T *endp;
    static pos_T        pos_copy;

    posp = NULL;

    if (c < 0)
    {
        return posp;
    }
    if (c > '~')
    {
        ;
    }
    else if (c == '\'' || c == '`')
    {
        pos_copy = curwin->w_pcmark;
        posp = &pos_copy;
    }
    else if (c == '"')
    {
        posp = &(buf->b_last_cursor);
    }
    else if (c == '^')
    {
        posp = &(buf->b_last_insert);
    }
    else if (c == '.')
    {
        posp = &(buf->b_last_change);
    }
    else if (c == '[')
    {
        posp = &(buf->b_op_start);
    }
    else if (c == ']')
    {
        posp = &(buf->b_op_end);
    }
    else if (c == '<' || c == '>')
    {
        startp = &buf->b_visual.vi_start;
        endp = &buf->b_visual.vi_end;
        if (((c == '<') ==  (((*startp).lnum != (*endp).lnum)               ? (*startp).lnum < (*endp).lnum                   : (*startp).col != (*endp).col                        ? (*startp).col < (*endp).col                     : (*startp).coladd < (*endp).coladd)  || endp->lnum == 0) && startp->lnum != 0)
        {
            posp = startp;
        }
        else
        {
            posp = endp;
        }
        if (buf->b_visual.vi_mode == 'V')
        {
            pos_copy = *posp;
            posp = &pos_copy;
            if (c == '<')
            {
                pos_copy.col = 0;
            }
            else
            {
                pos_copy.col = MAXCOL;
            }
            pos_copy.coladd = 0;
        }
    }
    else if ( ((unsigned)(c) - 'a' < 26) )
    {
        posp = &(buf->b_namedm[c - 'a']);
    }

    return posp;
}

    static pos_T *
getnextmark(pos_T       *startpos, int         dir, int         begin_line)
{
    int         i;
    pos_T       *result = NULL;
    pos_T       pos;

    pos = *startpos;

    if (dir ==  (-1)  && begin_line)
    {
        pos.col = 0;
    }
    else if (dir == FORWARD && begin_line)
    {
        pos.col = MAXCOL;
    }

    for (i = 0; i <  ('z' - 'a' + 1) ; i++)
    {
        if (curbuf->b_namedm[i].lnum > 0)
        {
            if (dir == FORWARD)
            {
                if ((result == NULL ||  (((curbuf->b_namedm[i]).lnum != (*result).lnum)               ? (curbuf->b_namedm[i]).lnum < (*result).lnum                   : (curbuf->b_namedm[i]).col != (*result).col                        ? (curbuf->b_namedm[i]).col < (*result).col                     : (curbuf->b_namedm[i]).coladd < (*result).coladd) ) &&  (((pos).lnum != (curbuf->b_namedm[i]).lnum)               ? (pos).lnum < (curbuf->b_namedm[i]).lnum                   : (pos).col != (curbuf->b_namedm[i]).col                        ? (pos).col < (curbuf->b_namedm[i]).col                     : (pos).coladd < (curbuf->b_namedm[i]).coladd) )
                {
                    result = &curbuf->b_namedm[i];
                }
            }
            else
            {
                if ((result == NULL ||  (((*result).lnum != (curbuf->b_namedm[i]).lnum)               ? (*result).lnum < (curbuf->b_namedm[i]).lnum                   : (*result).col != (curbuf->b_namedm[i]).col                        ? (*result).col < (curbuf->b_namedm[i]).col                     : (*result).coladd < (curbuf->b_namedm[i]).coladd) ) &&  (((curbuf->b_namedm[i]).lnum != (pos).lnum)               ? (curbuf->b_namedm[i]).lnum < (pos).lnum                   : (curbuf->b_namedm[i]).col != (pos).col                        ? (curbuf->b_namedm[i]).col < (pos).col                     : (curbuf->b_namedm[i]).coladd < (pos).coladd) )
                {
                    result = &curbuf->b_namedm[i];
                }
            }
        }
    }

    return result;
}

    static int
check_mark(pos_T *pos)
{
    if (pos == NULL)
    {
        emsg(_(e_unknown_mark));
        return FAIL;
    }
    if (pos->lnum <= 0)
    {
        if (pos->lnum == 0)
        {
            emsg(_(e_mark_not_set));
        }
        return FAIL;
    }
    if (pos->lnum > curbuf->b_ml.ml_line_count)
    {
        emsg(_(e_mark_has_invalid_line_number));
        return FAIL;
    }
    return OK;
}

    static void
clrallmarks(buf_T *buf)
{
    int         i;

    for (i = 0; i <  ('z' - 'a' + 1) ; i++)
    {
        buf->b_namedm[i].lnum = 0;
    }
    buf->b_op_start.lnum = 0;
    buf->b_op_end.lnum = 0;
    buf->b_last_cursor.lnum = 1;
    buf->b_last_cursor.col = 0;
    buf->b_last_cursor.coladd = 0;
    buf->b_last_insert.lnum = 0;
    buf->b_last_change.lnum = 0;
    buf->b_changelistlen = 0;
}

    static char_u *
mark_line(pos_T *mp, int lead_len)
{
    char_u *s;
    char_u *p;
    int         len;

    if (mp->lnum == 0 || mp->lnum > curbuf->b_ml.ml_line_count)
    {
        return vim_strsave((char_u *)"-invalid-");
    }
    s = vim_strnsave(skipwhite(ml_get(mp->lnum)), Columns * 5);
    if (s == NULL)
    {
        return NULL;
    }
    len = 0;
    for (p = s; *p != NUL;  p += utfc_ptr2len(p) )
    {
        len += ptr2cells(p);
        if (len >= Columns - lead_len)
        {
            break;
        }
    }
    *p = NUL;
    return s;
}

    static void
ex_marks(exarg_T *eap)
{
    char_u      *arg = eap->arg;
    int         i;
    pos_T *posp;
    pos_T *startp;
    pos_T *endp;

    if (arg != NULL && *arg == NUL)
    {
        arg = NULL;
    }

    show_one_mark('\'', arg, &curwin->w_pcmark, NULL, TRUE);
    for (i = 0; i <  ('z' - 'a' + 1) ; ++i)
    {
        show_one_mark(i + 'a', arg, &curbuf->b_namedm[i], NULL, TRUE);
    }
    show_one_mark('"', arg, &curbuf->b_last_cursor, NULL, TRUE);
    show_one_mark('[', arg, &curbuf->b_op_start, NULL, TRUE);
    show_one_mark(']', arg, &curbuf->b_op_end, NULL, TRUE);
    show_one_mark('^', arg, &curbuf->b_last_insert, NULL, TRUE);
    show_one_mark('.', arg, &curbuf->b_last_change, NULL, TRUE);

    startp = &curbuf->b_visual.vi_start;
    endp = &curbuf->b_visual.vi_end;
    if (( (((*startp).lnum != (*endp).lnum)               ? (*startp).lnum < (*endp).lnum                   : (*startp).col != (*endp).col                        ? (*startp).col < (*endp).col                     : (*startp).coladd < (*endp).coladd)  || endp->lnum == 0) && startp->lnum != 0)
    {
        posp = startp;
    }
    else
    {
        posp = endp;
    }
    show_one_mark('<', arg, posp, NULL, TRUE);
    show_one_mark('>', arg, posp == startp ? endp : startp, NULL, TRUE);

    show_one_mark(-1, arg, NULL, NULL, FALSE);
}

    static void
show_one_mark(int         c, char_u      *arg, pos_T       *p, char_u      *name_arg, int         current)
{
    static int  did_title = FALSE;
    int         mustfree = FALSE;
    char_u      *name = name_arg;

    if (c == -1)
    {
        if (did_title)
        {
            did_title = FALSE;
        }
        else
        {
            if (arg == NULL)
            {
                msg(_("No marks set"));
            }
            else
            {
                semsg(_(e_no_marks_matching_str), arg);
            }
        }
    }
    else if (!got_int && (arg == NULL || vim_strchr(arg, c) != NULL) && p->lnum != 0)
    {
        if (name == NULL && current)
        {
            name = mark_line(p, 15);
            if (name == NULL)
            {
                emsg(_(e_out_of_memory));
                return;
            }
            mustfree = TRUE;
        }
        if (!message_filtered(name))
        {
            if (!did_title)
            {
                msg_puts_title(_("\nmark line  col file/text"));
                did_title = TRUE;
            }
            msg_putchar('\n');
            if (!got_int)
            {
                sprintf((char *)IObuff, " %c %6ld %4d ", c, p->lnum, p->col);
                msg_outtrans(IObuff);
                if (name != NULL)
                {
                    msg_outtrans_attr(name, current ?  highlight_attr[(int)(HLF_D)]  : 0);
                }
            }
            out_flush();
        }
        if (mustfree)
        {
            vim_free(name);
        }
    }
}

    static void
ex_delmarks(exarg_T *eap)
{
    char_u      *p;
    int from;
    int to;
    int         i;

    if (*eap->arg == NUL && eap->forceit)
    {
        clrallmarks(curbuf);
    }
    else if (eap->forceit)
    {
        emsg(_(e_invalid_argument));
    }
    else if (*eap->arg == NUL)
    {
        emsg(_(e_argument_required));
    }
    else
    {
        for (p = eap->arg; *p != NUL; ++p)
        {
            if ( ((unsigned)(*p) - 'a' < 26) )
            {
                if (p[1] == '-')
                {
                    from = *p;
                    to = p[2];
                    if (! ((unsigned)(p[2]) - 'a' < 26)  || to < from)
                    {
                        semsg(_(e_invalid_argument_str), p);
                        return;
                    }
                    p += 2;
                }
                else
                {
                    from = to = *p;
                }

                for (i = from; i <= to; ++i)
                {
                    curbuf->b_namedm[i - 'a'].lnum = 0;
                }
            }
            else
            {
                switch (*p)
                {
                    case '"':
                        curbuf->b_last_cursor.lnum = 0;
                        break;
                    case '^':
                        curbuf->b_last_insert.lnum = 0;
                        break;
                    case '.':
                        curbuf->b_last_change.lnum = 0;
                        break;
                    case '[':
                        curbuf->b_op_start.lnum    = 0;
                        break;
                    case ']':
                        curbuf->b_op_end.lnum      = 0;
                        break;
                    case '<':
                        curbuf->b_visual.vi_start.lnum = 0;
                        break;
                    case '>':
                        curbuf->b_visual.vi_end.lnum   = 0;
                        break;
                    case ' ':
                        break;
                    default:
                        semsg(_(e_invalid_argument_str), p);
                              return;
                }
            }
        }
    }
}

    static void
ex_changes(exarg_T *eap  __attribute__((unused)) )
{
    int         i;
    char_u      *name;

    msg_puts_title(_("\nchange line  col text"));

    for (i = 0; i < curbuf->b_changelistlen && !got_int; ++i)
    {
        if (curbuf->b_changelist[i].lnum != 0)
        {
            msg_putchar('\n');
            if (got_int)
            {
                break;
            }
            sprintf((char *)IObuff, "%c %3d %5ld %4d ", i == curwin->w_changelistidx ? '>' : ' ', i > curwin->w_changelistidx ? i - curwin->w_changelistidx : curwin->w_changelistidx - i, (long)curbuf->b_changelist[i].lnum, curbuf->b_changelist[i].col);
            msg_outtrans(IObuff);
            name = mark_line(&curbuf->b_changelist[i], 17);
            if (name == NULL)
            {
                break;
            }
            msg_outtrans_attr(name,  highlight_attr[(int)(HLF_D)] );
            vim_free(name);
            ui_breakcheck();
        }
        out_flush();
    }
    if (curwin->w_changelistidx == curbuf->b_changelistlen)
    {
        msg_puts("\n>");
    }
}

    static void
mark_adjust(linenr_T    line1, linenr_T    line2, long        amount, long        amount_after)
{
    mark_adjust_internal(line1, line2, amount, amount_after, TRUE);
}

    static void
mark_adjust_nofold(linenr_T    line1, linenr_T    line2, long        amount, long        amount_after)
{
    mark_adjust_internal(line1, line2, amount, amount_after, FALSE);
}

    static void
mark_adjust_internal(linenr_T    line1, linenr_T    line2, long        amount, long        amount_after, int         adjust_folds  __attribute__((unused)) )
{
    int         i;
    int         fnum = curbuf->b_fnum;
    linenr_T    *lp;
    win_T       *win;
    wininfo_T   *wip;
    static pos_T initpos = {1, 0, 0};

    if (line2 < line1 && amount_after == 0L)
    {
        return;
    }

    if ((cmdmod.cmod_flags & CMOD_LOCKMARKS) == 0)
    {
        for (i = 0; i <  ('z' - 'a' + 1) ; i++)
        {
             {   lp = &(curbuf->b_namedm[i].lnum);       if (*lp >= line1 && *lp <= line2)       {           if (amount ==  LONG_MAX )              *lp = 0;            else                *lp += amount;  }       else if (amount_after && *lp > line2)       *lp += amount_after;     } ;
        }

         {   lp = &(curbuf->b_last_insert.lnum);       if (*lp >= line1 && *lp <= line2)       {           if (amount ==  LONG_MAX )              *lp = 0;            else                *lp += amount;  }       else if (amount_after && *lp > line2)       *lp += amount_after;     } ;

         {   lp = &(curbuf->b_last_change.lnum);       if (*lp >= line1 && *lp <= line2)       {           if (amount ==  LONG_MAX )              *lp = 0;            else                *lp += amount;  }       else if (amount_after && *lp > line2)       *lp += amount_after;     } ;

        if (! (((curbuf->b_last_cursor).lnum == (initpos).lnum) && ((curbuf->b_last_cursor).col == (initpos).col) && ((curbuf->b_last_cursor).coladd == (initpos).coladd)) )
        {
             {   lp = &(curbuf->b_last_cursor.lnum);       if (*lp >= line1 && *lp <= line2)       {           if (amount ==  LONG_MAX )              *lp = 0;            else                *lp += amount;  }       else if (amount_after && *lp > line2)       *lp += amount_after;     } ;
        }

        for (i = 0; i < curbuf->b_changelistlen; ++i)
        {
             {     lp = &(curbuf->b_changelist[i].lnum);       if (*lp >= line1 && *lp <= line2)       {           if (amount ==  LONG_MAX )              *lp = line1;        else                *lp += amount;  }       else if (amount_after && *lp > line2)       *lp += amount_after;     } ;
        }

         {     lp = &(curbuf->b_visual.vi_start.lnum);       if (*lp >= line1 && *lp <= line2)       {           if (amount ==  LONG_MAX )              *lp = line1;        else                *lp += amount;  }       else if (amount_after && *lp > line2)       *lp += amount_after;     } ;
         {     lp = &(curbuf->b_visual.vi_end.lnum);       if (*lp >= line1 && *lp <= line2)       {           if (amount ==  LONG_MAX )              *lp = line1;        else                *lp += amount;  }       else if (amount_after && *lp > line2)       *lp += amount_after;     } ;

    }

     {   lp = &(curwin->w_pcmark.lnum);       if (*lp >= line1 && *lp <= line2)       {           if (amount ==  LONG_MAX )              *lp = 0;            else                *lp += amount;  }       else if (amount_after && *lp > line2)       *lp += amount_after;     } ;

     {   lp = &(curwin->w_prev_pcmark.lnum);       if (*lp >= line1 && *lp <= line2)       {           if (amount ==  LONG_MAX )              *lp = 0;            else                *lp += amount;  }       else if (amount_after && *lp > line2)       *lp += amount_after;     } ;

    if (saved_cursor.lnum != 0)
    {
         {     lp = &(saved_cursor.lnum);       if (*lp >= line1 && *lp <= line2)       {           if (amount ==  LONG_MAX )              *lp = line1;        else                *lp += amount;  }       else if (amount_after && *lp > line2)       *lp += amount_after;     } ;
    }

     win = curwin;
if (win->w_buffer == curbuf)
{
    if ((cmdmod.cmod_flags & CMOD_LOCKMARKS) == 0)
    {
        for (i = 0; i < win->w_tagstacklen; i++)
        {
            if (win->w_tagstack[i].fmark.fnum == fnum)
            {
                 {     lp = &(win->w_tagstack[i].fmark.mark.lnum);       if (*lp >= line1 && *lp <= line2)       {           if (amount ==  LONG_MAX )              *lp = line1;        else                *lp += amount;  }       else if (amount_after && *lp > line2)       *lp += amount_after;     } ;
            }
        }
    }

    if (win->w_old_cursor_lnum != 0)
    {
         {     lp = &(win->w_old_cursor_lnum);       if (*lp >= line1 && *lp <= line2)       {           if (amount ==  LONG_MAX )              *lp = line1;        else                *lp += amount;  }       else if (amount_after && *lp > line2)       *lp += amount_after;     } ;
         {     lp = &(win->w_old_visual_lnum);       if (*lp >= line1 && *lp <= line2)       {           if (amount ==  LONG_MAX )              *lp = line1;        else                *lp += amount;  }       else if (amount_after && *lp > line2)       *lp += amount_after;     } ;
    }

    if (win != curwin)
    {
        if (win->w_topline >= line1 && win->w_topline <= line2)
        {
            if (amount ==  LONG_MAX )
            {
                if (line1 <= 1)
                {
                    win->w_topline = 1;
                }
                else
                {
                    win->w_topline = line1 - 1;
                }
            }
            else if (win->w_topline > line1)
            {
                win->w_topline += amount;
            }
        }
        else if (amount_after && win->w_topline > line2)
        {
            win->w_topline += amount_after;
        }
         {     pos_T *posp = &(win->w_cursor);       if (posp->lnum >= line1 && posp->lnum <= line2)         {           if (amount ==  LONG_MAX )          {           posp->lnum = MAX(line1 - 1, 1);                 posp->col = 0;      }       else               posp->lnum += amount;   }       else if (amount_after && posp->lnum > line2)        posp->lnum += amount_after;     } ;
    }

}

     for ((wip) = (curbuf)->b_wininfo; (wip) != NULL; (wip) = (wip)->wi_next) 
         {     pos_T *posp = &(wip->wi_fpos);       if (posp->lnum >= line1 && posp->lnum <= line2)         {           if (amount ==  LONG_MAX )          {           posp->lnum = MAX(line1 - 1, 1);                 posp->col = 0;      }       else               posp->lnum += amount;   }       else if (amount_after && posp->lnum > line2)        posp->lnum += amount_after;     } ;
}

    static void
mark_col_adjust(linenr_T    lnum, colnr_T     mincol, long        lnum_amount, long        col_amount, int         spaces_removed)
{
    int         i;
    int         fnum = curbuf->b_fnum;
    win_T       *win;
    pos_T       *posp;

    if ((col_amount == 0L && lnum_amount == 0L) || (cmdmod.cmod_flags & CMOD_LOCKMARKS))
    {
        return;
    }

    for (i = 0; i <  ('z' - 'a' + 1) ; i++)
    {
         {    posp = &(curbuf->b_namedm[i]);      if (posp->lnum == lnum && posp->col >= mincol)  {           posp->lnum += lnum_amount;      if (col_amount < 0 && posp->col <= (colnr_T)-col_amount)            posp->col = 0;      else if (posp->col < spaces_removed)                posp->col = col_amount + spaces_removed;            else                posp->col += col_amount;        }     } ;
    }

     {    posp = &(curbuf->b_last_insert);      if (posp->lnum == lnum && posp->col >= mincol)  {           posp->lnum += lnum_amount;      if (col_amount < 0 && posp->col <= (colnr_T)-col_amount)            posp->col = 0;      else if (posp->col < spaces_removed)                posp->col = col_amount + spaces_removed;            else                posp->col += col_amount;        }     } ;

     {    posp = &(curbuf->b_last_change);      if (posp->lnum == lnum && posp->col >= mincol)  {           posp->lnum += lnum_amount;      if (col_amount < 0 && posp->col <= (colnr_T)-col_amount)            posp->col = 0;      else if (posp->col < spaces_removed)                posp->col = col_amount + spaces_removed;            else                posp->col += col_amount;        }     } ;

    for (i = 0; i < curbuf->b_changelistlen; ++i)
    {
         {    posp = &(curbuf->b_changelist[i]);      if (posp->lnum == lnum && posp->col >= mincol)  {           posp->lnum += lnum_amount;      if (col_amount < 0 && posp->col <= (colnr_T)-col_amount)            posp->col = 0;      else if (posp->col < spaces_removed)                posp->col = col_amount + spaces_removed;            else                posp->col += col_amount;        }     } ;
    }

     {    posp = &(curbuf->b_visual.vi_start);      if (posp->lnum == lnum && posp->col >= mincol)  {           posp->lnum += lnum_amount;      if (col_amount < 0 && posp->col <= (colnr_T)-col_amount)            posp->col = 0;      else if (posp->col < spaces_removed)                posp->col = col_amount + spaces_removed;            else                posp->col += col_amount;        }     } ;
     {    posp = &(curbuf->b_visual.vi_end);      if (posp->lnum == lnum && posp->col >= mincol)  {           posp->lnum += lnum_amount;      if (col_amount < 0 && posp->col <= (colnr_T)-col_amount)            posp->col = 0;      else if (posp->col < spaces_removed)                posp->col = col_amount + spaces_removed;            else                posp->col += col_amount;        }     } ;

     {    posp = &(curwin->w_pcmark);      if (posp->lnum == lnum && posp->col >= mincol)  {           posp->lnum += lnum_amount;      if (col_amount < 0 && posp->col <= (colnr_T)-col_amount)            posp->col = 0;      else if (posp->col < spaces_removed)                posp->col = col_amount + spaces_removed;            else                posp->col += col_amount;        }     } ;

     {    posp = &(curwin->w_prev_pcmark);      if (posp->lnum == lnum && posp->col >= mincol)  {           posp->lnum += lnum_amount;      if (col_amount < 0 && posp->col <= (colnr_T)-col_amount)            posp->col = 0;      else if (posp->col < spaces_removed)                posp->col = col_amount + spaces_removed;            else                posp->col += col_amount;        }     } ;

     {    posp = &saved_cursor;      if (posp->lnum == lnum && posp->col >= mincol)  {           posp->lnum += lnum_amount;      if (col_amount < 0 && posp->col <= (colnr_T)-col_amount)            posp->col = 0;      else if (posp->col < spaces_removed)                posp->col = col_amount + spaces_removed;            else                posp->col += col_amount;        }     } ;

     win = curwin;
    if (win->w_buffer == curbuf)
    {
        for (i = 0; i < win->w_tagstacklen; i++)
        {
            if (win->w_tagstack[i].fmark.fnum == fnum)
            {
                 {    posp = &(win->w_tagstack[i].fmark.mark);      if (posp->lnum == lnum && posp->col >= mincol)  {           posp->lnum += lnum_amount;      if (col_amount < 0 && posp->col <= (colnr_T)-col_amount)            posp->col = 0;      else if (posp->col < spaces_removed)                posp->col = col_amount + spaces_removed;            else                posp->col += col_amount;        }     } ;
            }
        }

        if (win != curwin)
        {
             {    posp = &win->w_cursor;      if (posp->lnum == lnum && posp->col >= mincol)  {           posp->lnum += lnum_amount;      if (col_amount < 0 && posp->col <= (colnr_T)-col_amount)            posp->col = 0;      else if (posp->col < spaces_removed)                posp->col = col_amount + spaces_removed;            else                posp->col += col_amount;        }     } ;
        }
    }
}

    static void
set_last_cursor(win_T *win)
{
    if (win->w_buffer != NULL)
    {
        win->w_buffer->b_last_cursor = win->w_cursor;
    }
}

enum { SEARCH_HL_PRIORITY = 0 };

    static int
match_add(win_T       *wp, char_u      *grp, char_u      *pat, int         prio, int         id, list_T      *pos_list, char_u      *conceal_char  __attribute__((unused)) )
{
    matchitem_T *cur;
    matchitem_T *prev;
    matchitem_T *m = NULL;
    int         hlg_id;
    regprog_T   *regprog = NULL;
    int         rtype = UPD_SOME_VALID;

    if (*grp == NUL || (pat != NULL && *pat == NUL))
    {
        return -1;
    }
    if (id < -1 || id == 0)
    {
        semsg(_(e_invalid_id_nr_must_be_greater_than_or_equal_to_one_1), id);
        return -1;
    }
    if (id == -1)
    {
        id = wp->w_next_match_id++;
    }
    else
    {
        for (cur = wp->w_match_head; cur != NULL; cur = cur->mit_next)
        {
            if (cur->mit_id == id)
            {
                semsg(_(e_id_already_taken_nr), id);
                return -1;
            }
        }

        if (wp->w_next_match_id < id + 100)
        {
            wp->w_next_match_id = id + 100;
        }
    }

    if ((hlg_id = syn_namen2id(grp, (int) strlen((char *)(grp)) )) == 0)
    {
        semsg(_(e_no_such_highlight_group_name_str), grp);
        return -1;
    }
    if (pat != NULL && (regprog = vim_regcomp(pat, RE_MAGIC)) == NULL)
    {
        semsg(_(e_invalid_argument_str), pat);
        return -1;
    }

    m =  (matchitem_T *)alloc_clear(sizeof(matchitem_T)) ;
    if (m == NULL)
    {
        goto fail;
    }
    m->mit_id = id;
    m->mit_priority = prio;
    m->mit_pattern = pat == NULL ? NULL : vim_strsave(pat);
    m->mit_hlg_id = hlg_id;
    m->mit_match.regprog = regprog;
    m->mit_match.rmm_ic = FALSE;
    m->mit_match.rmm_maxcol = 0;

    cur = wp->w_match_head;
    prev = cur;
    while (cur != NULL && prio >= cur->mit_priority)
    {
        prev = cur;
        cur = cur->mit_next;
    }
    if (cur == prev)
    {
        wp->w_match_head = m;
    }
    else
    {
        prev->mit_next = m;
    }
    m->mit_next = cur;

    redraw_win_later(wp, rtype);
    return id;

fail:
    vim_regfree(regprog);
    if (m != NULL)
    {
        vim_free(m->mit_pattern);
        vim_free(m->mit_pos_array);
        vim_free(m);
    }
    return -1;
}

    static int
match_delete(win_T *wp, int id, int perr)
{
    matchitem_T *cur = wp->w_match_head;
    matchitem_T *prev = cur;
    int         rtype = UPD_SOME_VALID;

    if (id < 1)
    {
        if (perr == TRUE)
        {
            semsg(_(e_invalid_id_nr_must_be_greater_than_or_equal_to_one_2), id);
        }
        return -1;
    }
    while (cur != NULL && cur->mit_id != id)
    {
        prev = cur;
        cur = cur->mit_next;
    }
    if (cur == NULL)
    {
        if (perr == TRUE)
        {
            semsg(_(e_id_not_found_nr), id);
        }
        return -1;
    }
    if (cur == prev)
    {
        wp->w_match_head = cur->mit_next;
    }
    else
    {
        prev->mit_next = cur->mit_next;
    }
    vim_regfree(cur->mit_match.regprog);
    vim_free(cur->mit_pattern);
    if (cur->mit_toplnum != 0)
    {
        redraw_win_range_later(wp, cur->mit_toplnum, cur->mit_botlnum);
        rtype = UPD_VALID;
    }
    vim_free(cur->mit_pos_array);
    vim_free(cur);
    redraw_win_later(wp, rtype);
    return 0;
}

    static void
init_search_hl(win_T *wp, match_T *search_hl)
{
    matchitem_T *cur;

    cur = wp->w_match_head;
    while (cur != NULL)
    {
        cur->mit_hl.rm = cur->mit_match;
        if (cur->mit_hlg_id == 0)
        {
            cur->mit_hl.attr = 0;
        }
        else
        {
            cur->mit_hl.attr = syn_id2attr(cur->mit_hlg_id);
        }
        cur->mit_hl.buf = wp->w_buffer;
        cur->mit_hl.lnum = 0;
        cur->mit_hl.first_lnum = 0;
        cur = cur->mit_next;
    }
    search_hl->attr =  highlight_attr[(int)(HLF_L)] ;

    search_hl->buf = wp->w_buffer;
    search_hl->lnum = 0;
    search_hl->first_lnum = 0;
}

    static int
next_search_hl_pos(match_T         *shl, linenr_T        lnum, matchitem_T     *match, colnr_T         mincol)
{
    int     i;
    int     found = -1;

    for (i = match->mit_pos_cur; i < match->mit_pos_count; i++)
    {
        llpos_T *pos = &match->mit_pos_array[i];

        if (pos->lnum == 0)
        {
            break;
        }
        if (pos->len == 0 && pos->col < mincol)
        {
            continue;
        }
        if (pos->lnum == lnum)
        {
            if (found >= 0)
            {
                if (pos->col < match->mit_pos_array[found].col)
                {
                    llpos_T     tmp = *pos;

                    *pos = match->mit_pos_array[found];
                    match->mit_pos_array[found] = tmp;
                }
            }
            else
            {
                found = i;
            }
        }
    }
    match->mit_pos_cur = 0;
    if (found >= 0)
    {
        colnr_T start = match->mit_pos_array[found].col == 0
                                     ? 0 : match->mit_pos_array[found].col - 1;
        colnr_T end = match->mit_pos_array[found].col == 0
                            ? MAXCOL : start + match->mit_pos_array[found].len;

        shl->lnum = lnum;
        shl->rm.startpos[0].lnum = 0;
        shl->rm.startpos[0].col = start;
        shl->rm.endpos[0].lnum = 0;
        shl->rm.endpos[0].col = end;
        shl->is_addpos = TRUE;
        shl->has_cursor = FALSE;
        match->mit_pos_cur = found + 1;
        return 1;
    }
    return 0;
}

    static void
next_search_hl(win_T           *win, match_T         *search_hl, match_T         *shl, linenr_T        lnum, colnr_T         mincol, matchitem_T     *cur)
{
    linenr_T    l;
    colnr_T     matchcol;
    long        nmatched;
    int         called_emsg_before = called_emsg;
    int         timed_out = FALSE;

    if ((lnum < search_first_line || lnum > search_last_line) && cur == NULL)
    {
        shl->lnum = 0;
        return;
    }

    if (shl->lnum != 0)
    {
        l = shl->lnum + shl->rm.endpos[0].lnum - shl->rm.startpos[0].lnum;
        if (lnum > l)
        {
            shl->lnum = 0;
        }
        else if (lnum < l || shl->rm.endpos[0].col > mincol)
        {
            return;
        }
    }

    for (;;)
    {
        if (shl->lnum == 0)
        {
            matchcol = 0;
        }
        else if (vim_strchr(p_cpo, CPO_SEARCH) == NULL || (shl->rm.endpos[0].lnum == 0 && shl->rm.endpos[0].col <= shl->rm.startpos[0].col))
        {
            char_u      *ml;

            matchcol = shl->rm.startpos[0].col;
            ml = ml_get_buf(shl->buf, lnum, FALSE) + matchcol;
            if (*ml == NUL)
            {
                ++matchcol;
                shl->lnum = 0;
                break;
            }
            matchcol += utfc_ptr2len(ml);
        }
        else
        {
            matchcol = shl->rm.endpos[0].col;
        }

        shl->lnum = lnum;
        if (shl->rm.regprog != NULL)
        {
            int regprog_is_copy = (shl != search_hl && cur != NULL && shl == &cur->mit_hl && cur->mit_match.regprog == cur->mit_hl.rm.regprog);

            nmatched = vim_regexec_multi(&shl->rm, win, shl->buf, lnum, matchcol, &timed_out);
            if (regprog_is_copy)
            {
                cur->mit_match.regprog = cur->mit_hl.rm.regprog;
            }

            if (called_emsg > called_emsg_before || got_int || timed_out)
            {
                if (shl == search_hl)
                {
                    vim_regfree(shl->rm.regprog);
                    set_no_hlsearch(TRUE);
                }
                shl->rm.regprog = NULL;
                shl->lnum = 0;
                got_int = FALSE;
                break;
            }
        }
        else if (cur != NULL)
        {
            nmatched = next_search_hl_pos(shl, lnum, cur, matchcol);
        }
        else
        {
            nmatched = 0;
        }
        if (nmatched == 0)
        {
            shl->lnum = 0;
            break;
        }
        if (shl->rm.startpos[0].lnum > 0 || shl->rm.startpos[0].col >= mincol || nmatched > 1 || shl->rm.endpos[0].col > mincol)
        {
            shl->lnum += shl->rm.startpos[0].lnum;
            break;
        }
    }
}

    static void
prepare_search_hl(win_T *wp, match_T *search_hl, linenr_T lnum)
{
    matchitem_T *cur;
    match_T     *shl;
    int         shl_flag;
    int         pos_inprogress;
    int         n;

    cur = wp->w_match_head;
    shl_flag =  0 ;
    while (cur != NULL || shl_flag == FALSE)
    {
        if (shl_flag == FALSE)
        {
            shl = search_hl;
            shl_flag = TRUE;
        }
        else
        {
            shl = &cur->mit_hl;
        }
        if (shl->rm.regprog != NULL && shl->lnum == 0 && re_multiline(shl->rm.regprog))
        {
            if (shl->first_lnum == 0)
            {
                shl->first_lnum = wp->w_topline;
            }
            if (cur != NULL)
            {
                cur->mit_pos_cur = 0;
            }
            pos_inprogress = TRUE;
            n = 0;
            while (shl->first_lnum < lnum && (shl->rm.regprog != NULL || (cur != NULL && pos_inprogress)))
            {
                next_search_hl(wp, search_hl, shl, shl->first_lnum, (colnr_T)n, shl == search_hl ? NULL : cur);
                pos_inprogress = cur == NULL || cur->mit_pos_cur == 0
                                                              ? FALSE : TRUE;
                if (shl->lnum != 0)
                {
                    shl->first_lnum = shl->lnum
                                    + shl->rm.endpos[0].lnum
                                    - shl->rm.startpos[0].lnum;
                    n = shl->rm.endpos[0].col;
                }
                else
                {
                    ++shl->first_lnum;
                    n = 0;
                }
            }
        }
        if (shl != search_hl && cur != NULL)
        {
            cur = cur->mit_next;
        }
    }
}

    static void
check_cur_search_hl(win_T *wp, match_T *shl)
{
    linenr_T linecount = shl->rm.endpos[0].lnum - shl->rm.startpos[0].lnum;

    if (wp->w_cursor.lnum >= shl->lnum && wp->w_cursor.lnum <= shl->lnum + linecount && (wp->w_cursor.lnum > shl->lnum || wp->w_cursor.col >= shl->rm.startpos[0].col) && (wp->w_cursor.lnum < shl->lnum + linecount || wp->w_cursor.col < shl->rm.endpos[0].col))
    {
        shl->has_cursor = TRUE;
    }
    else
    {
        shl->has_cursor = FALSE;
    }
}

    static int
prepare_search_hl_line(win_T       *wp, linenr_T    lnum, colnr_T     mincol, char_u      **line, match_T     *search_hl, int         *search_attr)
{
    matchitem_T *cur;
    match_T     *shl;
    int         shl_flag;
    int         area_highlighting = FALSE;

    cur = wp->w_match_head;
    shl_flag =  0 ;
    while (cur != NULL || shl_flag == FALSE)
    {
        if (shl_flag == FALSE)
        {
            shl = search_hl;
            shl_flag = TRUE;
        }
        else
        {
            shl = &cur->mit_hl;
        }
        shl->startcol = MAXCOL;
        shl->endcol = MAXCOL;
        shl->attr_cur = 0;
        shl->is_addpos = FALSE;
        shl->has_cursor = FALSE;
        if (cur != NULL)
        {
            cur->mit_pos_cur = 0;
        }
        next_search_hl(wp, search_hl, shl, lnum, mincol, shl == search_hl ? NULL : cur);

        *line = ml_get_buf(wp->w_buffer, lnum, FALSE);

        if (shl->lnum != 0 && shl->lnum <= lnum)
        {
            if (shl->lnum == lnum)
            {
                shl->startcol = shl->rm.startpos[0].col;
            }
            else
            {
                shl->startcol = 0;
            }
            if (lnum == shl->lnum + shl->rm.endpos[0].lnum - shl->rm.startpos[0].lnum)
            {
                shl->endcol = shl->rm.endpos[0].col;
            }
            else
            {
                shl->endcol = MAXCOL;
            }

            if (shl == search_hl)
            {
                check_cur_search_hl(wp, shl);
            }

            if (shl->startcol == shl->endcol)
            {
                if ((*line)[shl->endcol] != NUL)
                {
                    shl->endcol += utfc_ptr2len((*line) + shl->endcol);
                }
                else
                {
                    ++shl->endcol;
                }
            }
            if ((long)shl->startcol < mincol)
            {
                shl->attr_cur = shl->attr;
                *search_attr = shl->attr;
            }
            area_highlighting = TRUE;
        }
        if (shl != search_hl && cur != NULL)
        {
            cur = cur->mit_next;
        }
    }
    return area_highlighting;
}

    static int
update_search_hl(win_T       *wp, linenr_T    lnum, colnr_T     col, char_u      **line, match_T     *search_hl, int         *has_match_conc  __attribute__((unused)) , int         *match_conc  __attribute__((unused)) , int         did_line_attr, int         lcs_eol_one, int         *on_last_col)
{
    matchitem_T *cur;
    match_T     *shl;
    int         shl_flag;
    int         pos_inprogress;
    int         search_attr = 0;

    cur = wp->w_match_head;
    shl_flag =  0 ;
    while (cur != NULL || shl_flag == FALSE)
    {
        if (shl_flag == FALSE && (cur == NULL || cur->mit_priority > SEARCH_HL_PRIORITY))
        {
            shl = search_hl;
            shl_flag = TRUE;
        }
        else
        {
            shl = &cur->mit_hl;
        }
        if (cur != NULL)
        {
            cur->mit_pos_cur = 0;
        }
        pos_inprogress = TRUE;
        while (shl->rm.regprog != NULL || (cur != NULL && pos_inprogress))
        {
            if (shl->startcol != MAXCOL && col >= shl->startcol && col < shl->endcol)
            {
                int next_col = col + utfc_ptr2len(*line + col);

                if (shl->endcol < next_col)
                {
                    shl->endcol = next_col;
                }
                shl->attr_cur = shl->attr;
                if (shl == search_hl && shl->has_cursor)
                {
                    shl->attr_cur =  highlight_attr[(int)(HLF_LC)] ;
                    if (shl->attr_cur != shl->attr)
                    {
                        search_hl_has_cursor_lnum = lnum;
                    }
                }

            }
            else if (col == shl->endcol)
            {
                shl->attr_cur = 0;
                next_search_hl(wp, search_hl, shl, lnum, col, shl == search_hl ? NULL : cur);
                pos_inprogress = !(cur == NULL || cur->mit_pos_cur == 0);

                *line = ml_get_buf(wp->w_buffer, lnum, FALSE);

                if (shl->lnum == lnum)
                {
                    shl->startcol = shl->rm.startpos[0].col;
                    if (shl->rm.endpos[0].lnum == 0)
                    {
                        shl->endcol = shl->rm.endpos[0].col;
                    }
                    else
                    {
                        shl->endcol = MAXCOL;
                    }

                    if (shl == search_hl)
                    {
                        check_cur_search_hl(wp, shl);
                    }

                    if (shl->startcol == shl->endcol)
                    {
                        char_u *p = *line + shl->endcol;

                        if (*p == NUL)
                        {
                            ++shl->endcol;
                        }
                        else
                        {
                            shl->endcol += utfc_ptr2len(p);
                        }
                    }

                    continue;
                }
            }
            break;
        }
        if (shl != search_hl && cur != NULL)
        {
            cur = cur->mit_next;
        }
    }

    cur = wp->w_match_head;
    shl_flag =  0 ;
    while (cur != NULL || shl_flag == FALSE)
    {
        if (shl_flag == FALSE && (cur == NULL || cur->mit_priority > SEARCH_HL_PRIORITY))
        {
            shl = search_hl;
            shl_flag = TRUE;
        }
        else
        {
            shl = &cur->mit_hl;
        }
        if (shl->attr_cur != 0)
        {
            search_attr = shl->attr_cur;
            *on_last_col = col + 1 >= shl->endcol;
        }
        if (shl != search_hl && cur != NULL)
        {
            cur = cur->mit_next;
        }
    }
    if (*(*line + col) == NUL && (did_line_attr >= 1 || (wp-> w_onebuf_opt.wo_list  && lcs_eol_one == -1)))
    {
        search_attr = 0;
    }
    return search_attr;
}

    static int
get_prevcol_hl_flag(win_T *wp, match_T *search_hl, long curcol)
{
    long        prevcol = curcol;
    int         prevcol_hl_flag = FALSE;
    matchitem_T *cur;

    if ((long)(wp-> w_onebuf_opt.wo_wrap  ? wp->w_skipcol : wp->w_leftcol) > prevcol)
    {
        ++prevcol;
    }

    if (!search_hl->is_addpos && (prevcol == (long)search_hl->startcol || (prevcol > (long)search_hl->startcol && search_hl->endcol == MAXCOL)))
    {
        prevcol_hl_flag = TRUE;
    }
    else
    {
        cur = wp->w_match_head;
        while (cur != NULL)
        {
            if (!cur->mit_hl.is_addpos && (prevcol == (long)cur->mit_hl.startcol || (prevcol > (long)cur->mit_hl.startcol && cur->mit_hl.endcol == MAXCOL)))
            {
                prevcol_hl_flag = TRUE;
                break;
            }
            cur = cur->mit_next;
        }
    }
    return prevcol_hl_flag;
}

    static void
get_search_match_hl(win_T *wp, match_T *search_hl, long col, int *char_attr)
{
    matchitem_T *cur;
    match_T     *shl;
    int         shl_flag;

    cur = wp->w_match_head;
    shl_flag =  0 ;
    while (cur != NULL || shl_flag == FALSE)
    {
        if (shl_flag == FALSE && ((cur != NULL && cur->mit_priority > SEARCH_HL_PRIORITY) || cur == NULL))
        {
            shl = search_hl;
            shl_flag = TRUE;
        }
        else
        {
            shl = &cur->mit_hl;
        }
        if (col - 1 == (long)shl->startcol && (shl == search_hl || !shl->is_addpos))
        {
            *char_attr = shl->attr;
        }
        if (shl != search_hl && cur != NULL)
        {
            cur = cur->mit_next;
        }
    }
}

    static void
ex_match(exarg_T *eap)
{
    char_u      *p;
    char_u      *g = NULL;
    char_u      *end;
    int         c;
    int         id;

    if (eap->line2 <= 3)
    {
        id = eap->line2;
    }
    else
    {
        emsg(_(e_invalid_command));
        return;
    }

    match_delete(curwin, id, FALSE);

    if (ends_excmd2(eap->cmd, eap->arg))
    {
        end = eap->arg;
    }
    else if (( strncasecmp((char *)(eap->arg), (char *)("none"), (4))  == 0 && ( ((eap->arg[4]) == ' ' || (eap->arg[4]) == '\t')  || ends_excmd2(eap->arg, eap->arg + 4))))
    {
        end = eap->arg + 4;
    }
    else
    {
        p = skiptowhite(eap->arg);
        g = vim_strnsave(eap->arg, p - eap->arg);
        p = skipwhite(p);
        if (*p == NUL)
        {
            vim_free(g);
            semsg(_(e_invalid_argument_str), eap->arg);
            return;
        }
        end = skip_regexp(p + 1, *p, TRUE);
        if (*end != NUL && !ends_excmd2(end, skipwhite(end + 1)))
        {
            vim_free(g);
            eap->errmsg = ex_errmsg(e_trailing_characters_str, end);
            return;
        }
        if (*end != *p)
        {
            vim_free(g);
            semsg(_(e_invalid_argument_str), p);
            return;
        }

        c = *end;
        *end = NUL;
        match_add(curwin, g, p + 1, 10, id, NULL, NULL);
        vim_free(g);
        *end = c;
    }
    eap->nextcmd = find_nextcmd(end);
}

