    static char *
mb_init(void)
{
    int         i;
    int         n;

    for (i = 0; i < 256; ++i)
    {
        n = utf8len_tab[i];

        mb_bytelen_tab[i] = n;
    }

    (void)init_chartab();

    screenalloc(FALSE);

    return NULL;
}

    static int
mb_get_class(char_u *p)
{
    return mb_get_class_buf(p, curbuf);
}

    static int
mb_get_class_buf(char_u *p, buf_T *buf)
{
    if ( mb_bytelen_tab[p[0]]  == 1)
    {
        if (p[0] == NUL ||  ((p[0]) == ' ' || (p[0]) == '\t') )
        {
            return 0;
        }
        if (vim_iswordc_buf(p[0], buf))
        {
            return 2;
        }
        return 1;
    }
    return utf_class_buf(utf_ptr2char(p), buf);
    return 0;
}

struct interval
{
    long first;
    long last;
};

    static int
intable(struct interval *table, size_t size, int c)
{
    int mid;
    int bot;
    int top;

    if (c < table[0].first)
    {
        return FALSE;
    }

    bot = 0;
    top = (int)(size / sizeof(struct interval) - 1);
    while (top >= bot)
    {
        mid = (bot + top) / 2;
        if (table[mid].last < c)
        {
            bot = mid + 1;
        }
        else if (table[mid].first > c)
        {
            top = mid - 1;
        }
        else
        {
            return TRUE;
        }
    }
    return FALSE;
}

