    static colnr_T
ml_get_buf_len(buf_T *buf, linenr_T lnum)
{
    char_u      *line;

    if (*(line = ml_get_buf(buf, lnum, FALSE)) == NUL)
    {
        return 0;
    }

    if (buf->b_ml.ml_line_textlen <= 0)
    {
        buf->b_ml.ml_line_textlen = (int) strlen((char *)(line))  + 1;
    }
    return buf->b_ml.ml_line_textlen - 1;
}

    static char_u  *
ml_get_buf(buf_T       *buf, linenr_T    lnum, int         will_change)
{
    bhdr_T      *hp;
    DATA_BL     *dp;
    static int  recursive = 0;
    static char_u questions[4];

    if (lnum > buf->b_ml.ml_line_count)
    {
        if (recursive == 0)
        {
            ++recursive;
            siemsg(e_ml_get_invalid_lnum_nr, lnum);
            --recursive;
        }
        ml_flush_line(buf);
errorret:
         strcpy((char *)(questions), (char *)("???")) ;
        buf->b_ml.ml_line_len = 4;
        buf->b_ml.ml_line_textlen = buf->b_ml.ml_line_len;
        buf->b_ml.ml_line_lnum = lnum;
        return questions;
    }
    if (lnum <= 0)
    {
        lnum = 1;
    }

    if (buf->b_ml.ml_mfp == NULL)
    {
        buf->b_ml.ml_line_len = 1;
        buf->b_ml.ml_line_textlen = buf->b_ml.ml_line_len;
        return (char_u *)"";
    }

    if (buf->b_ml.ml_line_lnum != lnum || mf_dont_release)
    {
        unsigned start;
        unsigned end;
        int         idx;

        ml_flush_line(buf);

        if ((hp = ml_find_line(buf, lnum, ML_FIND)) == NULL)
        {
            if (recursive == 0)
            {
                ++recursive;
                get_trans_bufname(buf);
                shorten_dir(NameBuff);
                siemsg(e_ml_get_cannot_find_line_nr_in_buffer_nr_str, lnum, buf->b_fnum, NameBuff);
                --recursive;
            }
            goto errorret;
        }

        dp = (DATA_BL *)(hp->bh_data);

        idx = lnum - buf->b_ml.ml_locked_low;
        start = ((dp->db_index[idx]) &  (~ ((unsigned)1 << ((sizeof(unsigned) * 8) - 1)) ) );
        if (idx == 0)
        {
            end = dp->db_txt_end;
        }
        else
        {
            end = ((dp->db_index[idx - 1]) &  (~ ((unsigned)1 << ((sizeof(unsigned) * 8) - 1)) ) );
        }

        buf->b_ml.ml_line_ptr = (char_u *)dp + start;
        buf->b_ml.ml_line_len = end - start;
            buf->b_ml.ml_line_textlen = buf->b_ml.ml_line_len;
        buf->b_ml.ml_line_lnum = lnum;
        buf->b_ml.ml_flags &= ~(ML_LINE_DIRTY | ML_ALLOCATED);
    }
    if (will_change)
    {
        buf->b_ml.ml_flags |= (ML_LOCKED_DIRTY | ML_LOCKED_POS);
    }

    return buf->b_ml.ml_line_ptr;
}

    static int
ml_line_alloced(void)
{
    return (curbuf->b_ml.ml_flags & ML_LINE_DIRTY);
}

    static int
ml_append_int(buf_T       *buf, linenr_T    lnum, char_u      *line_arg, colnr_T     len_arg, int         flags)
{
    char_u      *line = line_arg;
    colnr_T     len = len_arg;
    int         i;
    int         line_count;
    int         offset;
    int from;
    int to;
    long        space_needed;
    int         page_size;
    int         page_count;
    int         db_idx;
    bhdr_T      *hp;
    memfile_T   *mfp;
    DATA_BL     *dp;
    PTR_BL      *pp;
    infoptr_T   *ip;
    int         ret = FAIL;

    if (lnum > buf->b_ml.ml_line_count || buf->b_ml.ml_mfp == NULL)
    {
        return FAIL;
    }

    if (lowest_marked && lowest_marked > lnum)
    {
        lowest_marked = lnum + 1;
    }

    if (len == 0)
    {
        len = (colnr_T) strlen((char *)(line))  + 1;
    }

    space_needed = len +  (sizeof(unsigned)) ;

    mfp = buf->b_ml.ml_mfp;
    page_size = mfp->mf_page_size;

    if ((hp = ml_find_line(buf, lnum == 0 ? (linenr_T)1 : lnum, ML_INSERT)) == NULL)
    {
        goto theend;
    }

    buf->b_ml.ml_flags &= ~ML_EMPTY;

    if (lnum == 0)
    {
        db_idx = -1;
    }
    else
    {
        db_idx = lnum - buf->b_ml.ml_locked_low;
    }
    line_count = buf->b_ml.ml_locked_high - buf->b_ml.ml_locked_low;

    dp = (DATA_BL *)(hp->bh_data);

    if ((long)dp->db_free < space_needed && db_idx == line_count - 1 && lnum < buf->b_ml.ml_line_count)
    {
        --(buf->b_ml.ml_locked_lineadd);
        --(buf->b_ml.ml_locked_high);
        if ((hp = ml_find_line(buf, lnum + 1, ML_INSERT)) == NULL)
        {
            goto theend;
        }

        db_idx = -1;
        line_count = buf->b_ml.ml_locked_high - buf->b_ml.ml_locked_low;

        dp = (DATA_BL *)(hp->bh_data);
    }

    ++buf->b_ml.ml_line_count;

    if ((long)dp->db_free >= space_needed)
    {
        dp->db_txt_start -= len;
        dp->db_free -= space_needed;
        ++(dp->db_line_count);

        if (line_count > db_idx + 1)
        {
            if (db_idx < 0)
            {
                offset = dp->db_txt_end;
            }
            else
            {
                offset = ((dp->db_index[db_idx]) &  (~ ((unsigned)1 << ((sizeof(unsigned) * 8) - 1)) ) );
            }
             memmove((char *)((char *)dp + dp->db_txt_start), (char *)((char *)dp + dp->db_txt_start + len), (size_t)(offset - (dp->db_txt_start + len))) ;
            for (i = line_count - 1; i > db_idx; --i)
            {
                dp->db_index[i + 1] = dp->db_index[i] - len;
            }
            dp->db_index[db_idx + 1] = offset - len;
        }
        else
        {
            dp->db_index[db_idx + 1] = dp->db_txt_start;
        }

         memmove((char *)((char *)dp + dp->db_index[db_idx + 1]), (char *)(line), (size_t)len) ;
        if (flags & ML_APPEND_MARK)
        {
            dp->db_index[db_idx + 1] |=  ((unsigned)1 << ((sizeof(unsigned) * 8) - 1)) ;
        }

        buf->b_ml.ml_flags |= ML_LOCKED_DIRTY;
        if (!(flags & ML_APPEND_NEW))
        {
            buf->b_ml.ml_flags |= ML_LOCKED_POS;
        }
    }
    else
    {
        long line_count_left;
        long line_count_right;
        int page_count_left;
        int page_count_right;
        bhdr_T      *hp_left;
        bhdr_T      *hp_right;
        bhdr_T      *hp_new;
        int         lines_moved;
        int         data_moved = 0;
        int         total_moved = 0;
        DATA_BL *dp_right;
        DATA_BL *dp_left;
        int         stack_idx;
        int         in_left;
        int         lineadd;
        blocknr_T bnum_left;
        blocknr_T bnum_right;
        linenr_T lnum_left;
        linenr_T lnum_right;
        int         pb_idx;
        PTR_BL      *pp_new;

        if (db_idx < 0)
        {
            lines_moved = 0;
            in_left = TRUE;
        }
        else
        {
            lines_moved = line_count - db_idx - 1;
            if (lines_moved == 0)
            {
                in_left = FALSE;
            }
            else
            {
                data_moved = ((dp->db_index[db_idx]) &  (~ ((unsigned)1 << ((sizeof(unsigned) * 8) - 1)) ) ) -
                                                            dp->db_txt_start;
                total_moved = data_moved + lines_moved *  (sizeof(unsigned)) ;
                if ((long)dp->db_free + total_moved >= space_needed)
                {
                    in_left = TRUE;
                    space_needed = total_moved;
                }
                else
                {
                    in_left = FALSE;
                    space_needed += total_moved;
                }
            }
        }

        page_count = ((space_needed +  (offsetof(DATA_BL, db_index)) ) + page_size - 1) / page_size;
        if ((hp_new = ml_new_data(mfp, flags & ML_APPEND_NEW, page_count)) == NULL)
        {
            --(buf->b_ml.ml_locked_lineadd);
            --(buf->b_ml.ml_locked_high);
            goto theend;
        }
        if (db_idx < 0)
        {
            hp_left = hp_new;
            hp_right = hp;
            line_count_left = 0;
            line_count_right = line_count;
        }
        else
        {
            hp_left = hp;
            hp_right = hp_new;
            line_count_left = line_count;
            line_count_right = 0;
        }
        dp_right = (DATA_BL *)(hp_right->bh_data);
        dp_left = (DATA_BL *)(hp_left->bh_data);
        bnum_left = hp_left-> bh_hashitem.mhi_key ;
        bnum_right = hp_right-> bh_hashitem.mhi_key ;
        page_count_left = hp_left->bh_page_count;
        page_count_right = hp_right->bh_page_count;

        if (!in_left)
        {
            dp_right->db_txt_start -= len;
            dp_right->db_free -= len +  (sizeof(unsigned)) ;
            dp_right->db_index[0] = dp_right->db_txt_start;
            if (flags & ML_APPEND_MARK)
            {
                dp_right->db_index[0] |=  ((unsigned)1 << ((sizeof(unsigned) * 8) - 1)) ;
            }

             memmove((char *)((char *)dp_right + dp_right->db_txt_start), (char *)(line), (size_t)len) ;
            ++line_count_right;
        }
        if (lines_moved)
        {
            dp_right->db_txt_start -= data_moved;
            dp_right->db_free -= total_moved;
             memmove((char *)((char *)dp_right + dp_right->db_txt_start), (char *)((char *)dp_left + dp_left->db_txt_start), (size_t)data_moved) ;
            offset = dp_right->db_txt_start - dp_left->db_txt_start;
            dp_left->db_txt_start += data_moved;
            dp_left->db_free += total_moved;

            to = line_count_right;
            for (from = db_idx + 1; from < line_count_left; ++from, ++to)
            {
                dp_right->db_index[to] = dp->db_index[from] + offset;
            }
            line_count_right += lines_moved;
            line_count_left -= lines_moved;
        }

        if (in_left)
        {
            dp_left->db_txt_start -= len;
            dp_left->db_free -= len +  (sizeof(unsigned)) ;
            dp_left->db_index[line_count_left] = dp_left->db_txt_start;
            if (flags & ML_APPEND_MARK)
            {
                dp_left->db_index[line_count_left] |=  ((unsigned)1 << ((sizeof(unsigned) * 8) - 1)) ;
            }
             memmove((char *)((char *)dp_left + dp_left->db_txt_start), (char *)(line), (size_t)len) ;
            ++line_count_left;
        }

        if (db_idx < 0)
        {
            lnum_left = lnum + 1;
            lnum_right = 0;
        }
        else
        {
            lnum_left = 0;
            if (in_left)
            {
                lnum_right = lnum + 2;
            }
            else
            {
                lnum_right = lnum + 1;
            }
        }
        dp_left->db_line_count = line_count_left;
        dp_right->db_line_count = line_count_right;

        if (lines_moved || in_left)
        {
            buf->b_ml.ml_flags |= ML_LOCKED_DIRTY;
        }
        if (!(flags & ML_APPEND_NEW) && db_idx >= 0 && in_left)
        {
            buf->b_ml.ml_flags |= ML_LOCKED_POS;
        }
        mf_put(mfp, hp_new, TRUE, FALSE);

        lineadd = buf->b_ml.ml_locked_lineadd;
        buf->b_ml.ml_locked_lineadd = 0;
        ml_find_line(buf, (linenr_T)0, ML_FLUSH);

        for (stack_idx = buf->b_ml.ml_stack_top - 1; stack_idx >= 0; --stack_idx)
        {
            ip = &(buf->b_ml.ml_stack[stack_idx]);
            pb_idx = ip->ip_index;
            if ((hp = mf_get(mfp, ip->ip_bnum, 1)) == NULL)
            {
                goto theend;
            }
            pp = (PTR_BL *)(hp->bh_data);
            if (pp->pb_id !=  (('p' << 8) + 't') )
            {
                iemsg(e_pointer_block_id_wrong_three);
                mf_put(mfp, hp, FALSE, FALSE);
                goto theend;
            }
            if (pp->pb_count < pp->pb_count_max)
            {
                if (pb_idx + 1 < (int)pp->pb_count)
                {
                     memmove((char *)(&pp->pb_pointer[pb_idx + 2]), (char *)(&pp->pb_pointer[pb_idx + 1]), (size_t)(pp->pb_count - pb_idx - 1) * sizeof(PTR_EN)) ;
                }
                ++pp->pb_count;
                pp->pb_pointer[pb_idx].pe_line_count = line_count_left;
                pp->pb_pointer[pb_idx].pe_bnum = bnum_left;
                pp->pb_pointer[pb_idx].pe_page_count = page_count_left;
                pp->pb_pointer[pb_idx + 1].pe_line_count = line_count_right;
                pp->pb_pointer[pb_idx + 1].pe_bnum = bnum_right;
                pp->pb_pointer[pb_idx + 1].pe_page_count = page_count_right;

                if (lnum_left != 0)
                {
                    pp->pb_pointer[pb_idx].pe_old_lnum = lnum_left;
                }
                if (lnum_right != 0)
                {
                    pp->pb_pointer[pb_idx + 1].pe_old_lnum = lnum_right;
                }

                mf_put(mfp, hp, TRUE, FALSE);
                buf->b_ml.ml_stack_top = stack_idx + 1;

                if (lineadd)
                {
                    --(buf->b_ml.ml_stack_top);
                    ml_lineadd(buf, lineadd);
                    buf->b_ml.ml_stack[buf->b_ml.ml_stack_top].ip_high +=
                                                                      lineadd;
                    ++(buf->b_ml.ml_stack_top);
                }

                break;
            }
            for (;;)
            {
                hp_new = ml_new_ptr(mfp);
                if (hp_new == NULL)
                {
                    goto theend;
                }
                pp_new = (PTR_BL *)(hp_new->bh_data);

                if (hp-> bh_hashitem.mhi_key  != 1)
                {
                    break;
                }

                 memmove((char *)(pp_new), (char *)(pp), (size_t)page_size) ;
                pp->pb_count = 1;
                pp->pb_pointer[0].pe_bnum = hp_new-> bh_hashitem.mhi_key ;
                pp->pb_pointer[0].pe_line_count = buf->b_ml.ml_line_count;
                pp->pb_pointer[0].pe_old_lnum = 1;
                pp->pb_pointer[0].pe_page_count = 1;
                mf_put(mfp, hp, TRUE, FALSE);
                hp = hp_new;
                pp = pp_new;
                ip->ip_index = 0;
                ++stack_idx;
            }
            total_moved = pp->pb_count - pb_idx - 1;
            if (total_moved)
            {
                 memmove((char *)(&pp_new->pb_pointer[0]), (char *)(&pp->pb_pointer[pb_idx + 1]), (size_t)(total_moved) * sizeof(PTR_EN)) ;
                pp_new->pb_count = total_moved;
                pp->pb_count -= total_moved - 1;
                pp->pb_pointer[pb_idx + 1].pe_bnum = bnum_right;
                pp->pb_pointer[pb_idx + 1].pe_line_count = line_count_right;
                pp->pb_pointer[pb_idx + 1].pe_page_count = page_count_right;
                if (lnum_right)
                {
                    pp->pb_pointer[pb_idx + 1].pe_old_lnum = lnum_right;
                }
            }
            else
            {
                pp_new->pb_count = 1;
                pp_new->pb_pointer[0].pe_bnum = bnum_right;
                pp_new->pb_pointer[0].pe_line_count = line_count_right;
                pp_new->pb_pointer[0].pe_page_count = page_count_right;
                pp_new->pb_pointer[0].pe_old_lnum = lnum_right;
            }
            pp->pb_pointer[pb_idx].pe_bnum = bnum_left;
            pp->pb_pointer[pb_idx].pe_line_count = line_count_left;
            pp->pb_pointer[pb_idx].pe_page_count = page_count_left;
            if (lnum_left)
            {
                pp->pb_pointer[pb_idx].pe_old_lnum = lnum_left;
            }
            lnum_left = 0;
            lnum_right = 0;

            line_count_right = 0;
            for (i = 0; i < (int)pp_new->pb_count; ++i)
            {
                line_count_right += pp_new->pb_pointer[i].pe_line_count;
            }
            line_count_left = 0;
            for (i = 0; i < (int)pp->pb_count; ++i)
            {
                line_count_left += pp->pb_pointer[i].pe_line_count;
            }

            bnum_left = hp-> bh_hashitem.mhi_key ;
            bnum_right = hp_new-> bh_hashitem.mhi_key ;
            page_count_left = 1;
            page_count_right = 1;
            mf_put(mfp, hp, TRUE, FALSE);
            mf_put(mfp, hp_new, TRUE, FALSE);

        }

        if (stack_idx < 0)
        {
            iemsg(e_updated_too_many_blocks);
            buf->b_ml.ml_stack_top = 0;
        }
    }

    ret = OK;

theend:
    return ret;
}

    static int
ml_append_flush(buf_T       *buf, linenr_T    lnum, char_u      *line, colnr_T     len, int         flags)
{
    if (lnum > buf->b_ml.ml_line_count)
    {
        return FAIL;
    }

    if (buf->b_ml.ml_line_lnum != 0)
    {
        ml_flush_line(buf);
    }

    return ml_append_int(buf, lnum, line, len, flags);
}

    static int
ml_append(linenr_T    lnum, char_u      *line, colnr_T     len, int         newfile)
{
    return ml_append_flags(lnum, line, len, newfile ? ML_APPEND_NEW : 0);
}

    static int
ml_append_flags(linenr_T    lnum, char_u      *line, colnr_T     len, int         flags)
{
    if (curbuf->b_ml.ml_mfp == NULL && open_buffer(FALSE, NULL, 0) == FAIL)
    {
        return FAIL;
    }
    return ml_append_flush(curbuf, lnum, line, len, flags);
}

    static int
ml_replace(linenr_T lnum, char_u *line, int copy)
{
    colnr_T len = -1;

    if (line != NULL)
    {
        len = (colnr_T) strlen((char *)(line)) ;
    }
    return ml_replace_len(lnum, line, len, FALSE, copy);
}

    static int
ml_replace_len(linenr_T    lnum, char_u      *line_arg, colnr_T     len_arg, int         has_props, int         copy)
{
    char_u *line = line_arg;
    colnr_T len = len_arg;

    if (line == NULL)
    {
        return FAIL;
    }

    if (curbuf->b_ml.ml_mfp == NULL && open_buffer(FALSE, NULL, 0) == FAIL)
    {
        return FAIL;
    }

    if (!has_props)
    {
        ++len;
    }
    if (copy)
    {
            line = vim_strnsave(line, len - 1);
        if (line == NULL)
        {
            return FAIL;
        }
    }

    if (curbuf->b_ml.ml_line_lnum != lnum)
    {
        ml_flush_line(curbuf);

    }

    if (curbuf->b_ml.ml_flags & (ML_LINE_DIRTY | ML_ALLOCATED))
    {
        vim_free(curbuf->b_ml.ml_line_ptr);
    }

    curbuf->b_ml.ml_line_ptr = line;
    curbuf->b_ml.ml_line_len = len;
    curbuf->b_ml.ml_line_textlen = !has_props ? len_arg + 1 : 0;
    curbuf->b_ml.ml_line_lnum = lnum;
    curbuf->b_ml.ml_flags = (curbuf->b_ml.ml_flags | ML_LINE_DIRTY) & ~ML_EMPTY;

    return OK;
}

    static int
ml_delete_int(buf_T *buf, linenr_T lnum, int flags)
{
    bhdr_T      *hp;
    memfile_T   *mfp;
    DATA_BL     *dp;
    PTR_BL      *pp;
    infoptr_T   *ip;
    int         count;
    int         idx;
    int         stack_idx;
    int         text_start;
    int         line_start;
    long        line_size;
    int         i;
    int         ret = FAIL;

    if (lowest_marked && lowest_marked > lnum)
    {
        lowest_marked--;
    }

    if (buf->b_ml.ml_line_count == 1)
    {
        if ((flags & ML_DEL_MESSAGE))
        {
            set_keep_msg((char_u *)_((char *)no_lines_msg), 0);
        }

        i = ml_replace((linenr_T)1, (char_u *)"", TRUE);
        buf->b_ml.ml_flags |= ML_EMPTY;

        return i;
    }

    mfp = buf->b_ml.ml_mfp;
    if (mfp == NULL)
    {
        return FAIL;
    }

    if ((hp = ml_find_line(buf, lnum, ML_DELETE)) == NULL)
    {
        return FAIL;
    }

    dp = (DATA_BL *)(hp->bh_data);
    count = (long)(buf->b_ml.ml_locked_high)
                                        - (long)(buf->b_ml.ml_locked_low) + 2;
    idx = lnum - buf->b_ml.ml_locked_low;

    --buf->b_ml.ml_line_count;

    line_start = ((dp->db_index[idx]) &  (~ ((unsigned)1 << ((sizeof(unsigned) * 8) - 1)) ) );
    if (idx == 0)
    {
        line_size = dp->db_txt_end - line_start;
    }
    else
    {
        line_size = ((dp->db_index[idx - 1]) &  (~ ((unsigned)1 << ((sizeof(unsigned) * 8) - 1)) ) ) - line_start;
    }

    if (count == 1)
    {
        mf_free(mfp, hp);
        buf->b_ml.ml_locked = NULL;

        for (stack_idx = buf->b_ml.ml_stack_top - 1; stack_idx >= 0; --stack_idx)
        {
            buf->b_ml.ml_stack_top = 0;
            ip = &(buf->b_ml.ml_stack[stack_idx]);
            idx = ip->ip_index;
            if ((hp = mf_get(mfp, ip->ip_bnum, 1)) == NULL)
            {
                goto theend;
            }
            pp = (PTR_BL *)(hp->bh_data);
            if (pp->pb_id !=  (('p' << 8) + 't') )
            {
                iemsg(e_pointer_block_id_wrong_four);
                mf_put(mfp, hp, FALSE, FALSE);
                goto theend;
            }
            count = --(pp->pb_count);
            if (count == 0)
            {
                mf_free(mfp, hp);
            }
            else
            {
                if (count != idx)
                {
                     memmove((char *)(&pp->pb_pointer[idx]), (char *)(&pp->pb_pointer[idx + 1]), (size_t)(count - idx) * sizeof(PTR_EN)) ;
                }
                mf_put(mfp, hp, TRUE, FALSE);

                buf->b_ml.ml_stack_top = stack_idx;
                if (buf->b_ml.ml_locked_lineadd != 0)
                {
                    ml_lineadd(buf, buf->b_ml.ml_locked_lineadd);
                    buf->b_ml.ml_stack[buf->b_ml.ml_stack_top].ip_high +=
                                                  buf->b_ml.ml_locked_lineadd;
                }
                ++(buf->b_ml.ml_stack_top);

                break;
            }
        }
    }
    else
    {
        text_start = dp->db_txt_start;
         memmove((char *)((char *)dp + text_start + line_size), (char *)((char *)dp + text_start), (size_t)(line_start - text_start)) ;

        for (i = idx; i < count - 1; ++i)
        {
            dp->db_index[i] = dp->db_index[i + 1] + line_size;
        }

        dp->db_free += line_size +  (sizeof(unsigned)) ;
        dp->db_txt_start += line_size;
        --(dp->db_line_count);

        buf->b_ml.ml_flags |= (ML_LOCKED_DIRTY | ML_LOCKED_POS);
    }

    ret = OK;

theend:
    return ret;
}

    static int
ml_delete(linenr_T lnum)
{
    return ml_delete_flags(lnum, 0);
}

    static int
ml_delete_flags(linenr_T lnum, int flags)
{
    ml_flush_line(curbuf);
    if (lnum < 1 || lnum > curbuf->b_ml.ml_line_count)
    {
        return FAIL;
    }

    return ml_delete_int(curbuf, lnum, flags);
}

    static void
ml_setmarked(linenr_T lnum)
{
    bhdr_T    *hp;
    DATA_BL *dp;
    if (lnum < 1 || lnum > curbuf->b_ml.ml_line_count || curbuf->b_ml.ml_mfp == NULL)
    {
        return;
    }

    if (lowest_marked == 0 || lowest_marked > lnum)
    {
        lowest_marked = lnum;
    }

    if ((hp = ml_find_line(curbuf, lnum, ML_FIND)) == NULL)
    {
        return;
    }

    dp = (DATA_BL *)(hp->bh_data);
    dp->db_index[lnum - curbuf->b_ml.ml_locked_low] |=  ((unsigned)1 << ((sizeof(unsigned) * 8) - 1)) ;
    curbuf->b_ml.ml_flags |= ML_LOCKED_DIRTY;
}

    static linenr_T
ml_firstmarked(void)
{
    bhdr_T      *hp;
    DATA_BL     *dp;
    linenr_T    lnum;
    int         i;

    if (curbuf->b_ml.ml_mfp == NULL)
    {
        return (linenr_T) 0;
    }

    for (lnum = lowest_marked; lnum <= curbuf->b_ml.ml_line_count; )
    {
        if ((hp = ml_find_line(curbuf, lnum, ML_FIND)) == NULL)
        {
            return (linenr_T)0;
        }

        dp = (DATA_BL *)(hp->bh_data);

        for (i = lnum - curbuf->b_ml.ml_locked_low; lnum <= curbuf->b_ml.ml_locked_high; ++i, ++lnum)
        {
            if ((dp->db_index[i]) &  ((unsigned)1 << ((sizeof(unsigned) * 8) - 1)) )
            {
                (dp->db_index[i]) &=  (~ ((unsigned)1 << ((sizeof(unsigned) * 8) - 1)) ) ;
                curbuf->b_ml.ml_flags |= ML_LOCKED_DIRTY;
                lowest_marked = lnum + 1;
                return lnum;
            }
        }
    }

    return (linenr_T) 0;
}

    static void
ml_clearmarked(void)
{
    bhdr_T      *hp;
    DATA_BL     *dp;
    linenr_T    lnum;
    int         i;

    if (curbuf->b_ml.ml_mfp == NULL)
    {
        return;
    }

    for (lnum = lowest_marked; lnum <= curbuf->b_ml.ml_line_count; )
    {
        if ((hp = ml_find_line(curbuf, lnum, ML_FIND)) == NULL)
        {
            return;
        }

        dp = (DATA_BL *)(hp->bh_data);

        for (i = lnum - curbuf->b_ml.ml_locked_low; lnum <= curbuf->b_ml.ml_locked_high; ++i, ++lnum)
        {
            if ((dp->db_index[i]) &  ((unsigned)1 << ((sizeof(unsigned) * 8) - 1)) )
            {
                (dp->db_index[i]) &=  (~ ((unsigned)1 << ((sizeof(unsigned) * 8) - 1)) ) ;
                curbuf->b_ml.ml_flags |= ML_LOCKED_DIRTY;
            }
        }
    }

    lowest_marked = 0;
}

    static void
ml_flush_line(buf_T *buf)
{
    bhdr_T      *hp;
    DATA_BL     *dp;
    linenr_T    lnum;
    char_u      *new_line;
    char_u      *old_line;
    colnr_T     new_len;
    int         old_len;
    int         extra;
    int         idx;
    int         start;
    int         count;
    int         i;
    static int  entered = FALSE;

    if (buf->b_ml.ml_line_lnum == 0 || buf->b_ml.ml_mfp == NULL)
    {
        return;
    }

    if (buf->b_ml.ml_flags & ML_LINE_DIRTY)
    {
        if (entered)
        {
            return;
        }
        entered = TRUE;

        lnum = buf->b_ml.ml_line_lnum;
        new_line = buf->b_ml.ml_line_ptr;

        hp = ml_find_line(buf, lnum, ML_FIND);
        if (hp == NULL)
        {
            siemsg(e_cannot_find_line_nr, lnum);
        }
        else
        {
            dp = (DATA_BL *)(hp->bh_data);
            idx = lnum - buf->b_ml.ml_locked_low;
            start = ((dp->db_index[idx]) &  (~ ((unsigned)1 << ((sizeof(unsigned) * 8) - 1)) ) );
            old_line = (char_u *)dp + start;
            if (idx == 0)
            {
                old_len = dp->db_txt_end - start;
            }
            else
            {
                old_len = (dp->db_index[idx - 1] &  (~ ((unsigned)1 << ((sizeof(unsigned) * 8) - 1)) ) ) - start;
            }
            new_len = buf->b_ml.ml_line_len;
            extra = new_len - old_len;

            if ((int)dp->db_free >= extra)
            {
                count = buf->b_ml.ml_locked_high - buf->b_ml.ml_locked_low + 1;
                if (extra != 0 && idx < count - 1)
                {
                     memmove((char *)((char *)dp + dp->db_txt_start - extra), (char *)((char *)dp + dp->db_txt_start), (size_t)(start - dp->db_txt_start)) ;

                    for (i = idx + 1; i < count; ++i)
                    {
                        dp->db_index[i] -= extra;
                    }
                }
                dp->db_index[idx] -= extra;

                dp->db_free -= extra;
                dp->db_txt_start -= extra;

                 memmove((char *)(old_line - extra), (char *)(new_line), (size_t)new_len) ;
                buf->b_ml.ml_flags |= (ML_LOCKED_DIRTY | ML_LOCKED_POS);
            }
            else
            {
                (void)ml_append_int(buf, lnum, new_line, new_len, ((dp->db_index[idx] &  ((unsigned)1 << ((sizeof(unsigned) * 8) - 1)) ) ? ML_APPEND_MARK : 0));
                (void)ml_delete_int(buf, lnum, ML_DEL_NOPROP);
            }
        }
        vim_free(new_line);

        entered = FALSE;
    }
    else if (buf->b_ml.ml_flags & ML_ALLOCATED)
    {
        vim_free(buf->b_ml.ml_line_ptr);
    }

    buf->b_ml.ml_flags &= ~(ML_LINE_DIRTY | ML_ALLOCATED);
    buf->b_ml.ml_line_lnum = 0;
}

    static bhdr_T *
ml_new_data(memfile_T *mfp, int negative, int page_count)
{
    bhdr_T      *hp;
    DATA_BL     *dp;

    if ((hp = mf_new(mfp, negative, page_count)) == NULL)
    {
        return NULL;
    }

    dp = (DATA_BL *)(hp->bh_data);
    dp->db_id =  (('d' << 8) + 'a') ;
    dp->db_txt_start = dp->db_txt_end = page_count * mfp->mf_page_size;
    dp->db_free = dp->db_txt_start -  (offsetof(DATA_BL, db_index)) ;
    dp->db_line_count = 0;

    return hp;
}

    static bhdr_T *
ml_new_ptr(memfile_T *mfp)
{
    bhdr_T      *hp;
    PTR_BL      *pp;

    if ((hp = mf_new(mfp, FALSE, 1)) == NULL)
    {
        return NULL;
    }

    pp = (PTR_BL *)(hp->bh_data);
    pp->pb_id =  (('p' << 8) + 't') ;
    pp->pb_count = 0;
    pp->pb_count_max =  (short_u)(((mfp)->mf_page_size - offsetof(PTR_BL, pb_pointer)) / sizeof(PTR_EN)) ;

    return hp;
}

    static bhdr_T *
ml_find_line(buf_T *buf, linenr_T lnum, int action)
{
    DATA_BL     *dp;
    PTR_BL      *pp;
    infoptr_T   *ip;
    bhdr_T      *hp;
    memfile_T   *mfp;
    linenr_T    t;
    blocknr_T bnum;
    blocknr_T bnum2;
    int         dirty;
    linenr_T low;
    linenr_T high;
    int         top;
    int         page_count;
    int         idx;

    mfp = buf->b_ml.ml_mfp;

    if (buf->b_ml.ml_locked)
    {
        if ( ((action) & 0x10)  && buf->b_ml.ml_locked_low <= lnum && buf->b_ml.ml_locked_high >= lnum && !mf_dont_release)
        {
            if (action == ML_INSERT)
            {
                ++(buf->b_ml.ml_locked_lineadd);
                ++(buf->b_ml.ml_locked_high);
            }
            else if (action == ML_DELETE)
            {
                --(buf->b_ml.ml_locked_lineadd);
                --(buf->b_ml.ml_locked_high);
            }
            return (buf->b_ml.ml_locked);
        }

        mf_put(mfp, buf->b_ml.ml_locked, buf->b_ml.ml_flags & ML_LOCKED_DIRTY, buf->b_ml.ml_flags & ML_LOCKED_POS);
        buf->b_ml.ml_locked = NULL;

        if (buf->b_ml.ml_locked_lineadd != 0)
        {
            ml_lineadd(buf, buf->b_ml.ml_locked_lineadd);
        }
    }

    if (action == ML_FLUSH)
    {
        return NULL;
    }

    bnum = 1;
    page_count = 1;
    low = 1;
    high = buf->b_ml.ml_line_count;

    if (action == ML_FIND)
    {
        for (top = buf->b_ml.ml_stack_top - 1; top >= 0; --top)
        {
            ip = &(buf->b_ml.ml_stack[top]);
            if (ip->ip_low <= lnum && ip->ip_high >= lnum)
            {
                bnum = ip->ip_bnum;
                low = ip->ip_low;
                high = ip->ip_high;
                buf->b_ml.ml_stack_top = top;
                break;
            }
        }
        if (top < 0)
        {
            buf->b_ml.ml_stack_top = 0;
        }
    }
    else
    {
        buf->b_ml.ml_stack_top = 0;
    }

    for (;;)
    {
        if ((hp = mf_get(mfp, bnum, page_count)) == NULL)
        {
            goto error_noblock;
        }

        if (action == ML_INSERT)
        {
            ++high;
        }
        else if (action == ML_DELETE)
        {
            --high;
        }

        dp = (DATA_BL *)(hp->bh_data);
        if (dp->db_id ==  (('d' << 8) + 'a') )
        {
            buf->b_ml.ml_locked = hp;
            buf->b_ml.ml_locked_low = low;
            buf->b_ml.ml_locked_high = high;
            buf->b_ml.ml_locked_lineadd = 0;
            buf->b_ml.ml_flags &= ~(ML_LOCKED_DIRTY | ML_LOCKED_POS);
            return hp;
        }

        pp = (PTR_BL *)(dp);
        if (pp->pb_id !=  (('p' << 8) + 't') )
        {
            iemsg(e_pointer_block_id_wrong);
            goto error_block;
        }

        if ((top = ml_add_stack(buf)) < 0)
        {
            goto error_block;
        }
        ip = &(buf->b_ml.ml_stack[top]);
        ip->ip_bnum = bnum;
        ip->ip_low = low;
        ip->ip_high = high;
        ip->ip_index = -1;

        dirty = FALSE;
        for (idx = 0; idx < (int)pp->pb_count; ++idx)
        {
            t = pp->pb_pointer[idx].pe_line_count;
            if ((low += t) > lnum)
            {
                ip->ip_index = idx;
                bnum = pp->pb_pointer[idx].pe_bnum;
                page_count = pp->pb_pointer[idx].pe_page_count;
                high = low - 1;
                low -= t;

                if (bnum < 0)
                {
                    bnum2 = mf_trans_del(mfp, bnum);
                    if (bnum != bnum2)
                    {
                        bnum = bnum2;
                        pp->pb_pointer[idx].pe_bnum = bnum;
                        dirty = TRUE;
                    }
                }

                break;
            }
        }
        if (idx >= (int)pp->pb_count)
        {
            if (lnum > buf->b_ml.ml_line_count)
            {
                siemsg(e_line_number_out_of_range_nr_past_the_end, lnum - buf->b_ml.ml_line_count);
            }

            else
            {
                siemsg(e_line_count_wrong_in_block_nr, bnum);
            }
            goto error_block;
        }
        if (action == ML_DELETE)
        {
            pp->pb_pointer[idx].pe_line_count--;
            dirty = TRUE;
        }
        else if (action == ML_INSERT)
        {
            pp->pb_pointer[idx].pe_line_count++;
            dirty = TRUE;
        }
        mf_put(mfp, hp, dirty, FALSE);
    }

error_block:
    mf_put(mfp, hp, FALSE, FALSE);
error_noblock:
    if (action == ML_DELETE)
    {
        ml_lineadd(buf, 1);
    }
    else if (action == ML_INSERT)
    {
        ml_lineadd(buf, -1);
    }
    buf->b_ml.ml_stack_top = 0;
    return NULL;
}

    static int
ml_add_stack(buf_T *buf)
{
    int         top;
    infoptr_T   *newstack;

    top = buf->b_ml.ml_stack_top;

    if (top == buf->b_ml.ml_stack_size)
    {
        newstack =  (infoptr_T *)alloc(sizeof(infoptr_T) * (buf->b_ml.ml_stack_size + STACK_INCR)) ;
        if (newstack == NULL)
        {
            return -1;
        }
        if (top > 0)
        {
             memmove((char *)(newstack), (char *)(buf->b_ml.ml_stack), (size_t)top * sizeof(infoptr_T)) ;
        }
        vim_free(buf->b_ml.ml_stack);
        buf->b_ml.ml_stack = newstack;
        buf->b_ml.ml_stack_size += STACK_INCR;
    }

    buf->b_ml.ml_stack_top++;
    return top;
}

    static void
ml_lineadd(buf_T *buf, int count)
{
    int         idx;
    infoptr_T   *ip;
    PTR_BL      *pp;
    memfile_T   *mfp = buf->b_ml.ml_mfp;
    bhdr_T      *hp;

    for (idx = buf->b_ml.ml_stack_top - 1; idx >= 0; --idx)
    {
        ip = &(buf->b_ml.ml_stack[idx]);
        if ((hp = mf_get(mfp, ip->ip_bnum, 1)) == NULL)
        {
            break;
        }
        pp = (PTR_BL *)(hp->bh_data);
        if (pp->pb_id !=  (('p' << 8) + 't') )
        {
            mf_put(mfp, hp, FALSE, FALSE);
            iemsg(e_pointer_block_id_wrong_two);
            break;
        }
        pp->pb_pointer[ip->ip_index].pe_line_count += count;
        ip->ip_high += count;
        mf_put(mfp, hp, TRUE, FALSE);
    }
}

    static void
long_to_char(long n, char_u *s)
{
    s[0] = (char_u)(n & 0xff);
    n = (unsigned)n >> 8;
    s[1] = (char_u)(n & 0xff);
    n = (unsigned)n >> 8;
    s[2] = (char_u)(n & 0xff);
    n = (unsigned)n >> 8;
    s[3] = (char_u)(n & 0xff);
}

    static void
ml_setflags(buf_T *buf)
{
    bhdr_T      *hp;
    ZERO_BL     *b0p;

    if (!buf->b_ml.ml_mfp)
    {
        return;
    }
    for (hp = buf->b_ml.ml_mfp->mf_used_last; hp != NULL; hp = hp->bh_prev)
    {
        if (hp-> bh_hashitem.mhi_key  == 0)
        {
            b0p = (ZERO_BL *)(hp->bh_data);
            b0p-> b0_fname[B0_FNAME_SIZE_ORG - 1]  = buf->b_changed ? B0_DIRTY : 0;
            hp->bh_flags |= BH_DIRTY;
            mf_sync(buf->b_ml.ml_mfp, MFS_ZERO);
            break;
        }
    }
}

