struct msg_hist
{
    struct msg_hist     *next;
    char_u              *msg;
    int                 attr;
};

static struct msg_hist *first_msg_hist = NULL;
static struct msg_hist *last_msg_hist = NULL;
static int msg_hist_len = 0;
static int msg_hist_max = 500;

enum { MESSAGES_HIT_ENTER = 0x001 };
enum { MESSAGES_WAIT = 0x002 };
enum { MESSAGES_HISTORY = 0x004 };

static int msg_flags = MESSAGES_HIT_ENTER | MESSAGES_HISTORY;
static int msg_wait = 0;

    static int
msg(char *s)
{
    return msg_attr_keep(s, 0, FALSE);
}

    static int
msg_attr(char *s, int attr)
{
    return msg_attr_keep(s, attr, FALSE);
}

    static int
msg_attr_keep(char        *s, int         attr, int         keep)
{
    static int  entered = 0;
    int         retval;
    char_u      *buf = NULL;

    if (!emsg_on_display && message_filtered((char_u *)s))
    {
        return TRUE;
    }

    if (entered >= 3)
    {
        return TRUE;
    }
    ++entered;

    if ((char_u *)s != keep_msg || (*s != '<' && last_msg_hist != NULL && last_msg_hist->msg != NULL &&  strcmp((char *)(s), (char *)(last_msg_hist->msg))  != 0))
    {
        add_msg_hist((char_u *)s, -1, attr);
    }

    msg_start();
    buf = msg_strtrunc((char_u *)s, FALSE);
    if (buf != NULL)
    {
        s = (char *)buf;
    }

    msg_outtrans_attr((char_u *)s, attr);
    msg_clr_eos();
    retval = msg_end();

    if (keep && retval && vim_strsize((char_u *)s) < (int)(Rows - cmdline_row - 1) * cmdline_width + sc_col)
    {
        set_keep_msg((char_u *)s, 0);
    }

    need_fileinfo = FALSE;

    vim_free(buf);
    --entered;
    return retval;
}

    static char_u *
msg_strtrunc(char_u      *s, int         force)
{
    char_u      *buf = NULL;
    int         len;
    int         room;

    if ((!msg_scroll && !need_wait_return && shortmess(SHM_TRUNCALL) && !exmode_active && msg_silent == 0) || force)
    {
        len = vim_strsize(s);
        if (msg_scrolled != 0)
        {
            room = (int)(Rows - msg_row) * cmdline_width - 1;
        }
        else
        {
            room = (int)(Rows - msg_row - 1) * cmdline_width + sc_col - 1;
        }
        if (len > room && room > 0)
        {
            len = (room + 2) * 18;
            buf = alloc(len);
            if (buf != NULL)
            {
                trunc_string(s, buf, room, len);
            }
        }
    }
    return buf;
}

    static void
trunc_string(char_u      *s, char_u      *buf, int         room_in, int         buflen)
{
    size_t      room = room_in - 3;
    size_t      half;
    size_t      len = 0;
    int         e;
    int         i;
    int         n;

    if (*s == NUL)
    {
        if (buflen > 0)
        {
            *buf = NUL;
        }
        return;
    }

    if (room_in < 3)
    {
        room = 0;
    }
    half = room / 2;

    for (e = 0; len < half && e < buflen; ++e)
    {
        if (s[e] == NUL)
        {
            buf[e] = NUL;
            return;
        }
        n = ptr2cells(s + e);
        if (len + n > half)
        {
            break;
        }
        len += n;
        buf[e] = s[e];
        for (n = utfc_ptr2len(s + e); --n > 0; )
        {
            if (++e == buflen)
            {
                break;
            }
            buf[e] = s[e];
        }
    }

    i = e;
    half = i = (int) strlen((char *)(s)) ;
    for (;;)
    {
        do
        {
            half = half - utf_head_off(s, s + half - 1) - 1;
        }
        while (half > 0 && utf_iscomposing(utf_ptr2char(s + half)))
            ;
        n = ptr2cells(s + half);
        if (len + n > room || half == 0)
        {
            break;
        }
        len += n;
        i = (int)half;
    }

    if (i <= e + 3)
    {
        if (s != buf)
        {
            len =  strlen((char *)(s)) ;
            if (len >= (size_t)buflen)
            {
                len = buflen - 1;
            }
            len = len - e + 1;
            if (len < 1)
            {
                buf[e - 1] = NUL;
            }
            else
            {
                 memmove((char *)(buf + e), (char *)(s + e), len) ;
            }
        }
    }
    else if (e + 3 < buflen)
    {
         memmove((char *)(buf + e), (char *)("..."), (size_t)3) ;
        len =  strlen((char *)(s + i))  + 1;
        if (len >= (size_t)buflen - e - 3)
        {
            len = buflen - e - 3 - 1;
        }
         memmove((char *)(buf + e + 3), (char *)(s + i), len) ;
        buf[e + 3 + len - 1] = NUL;
    }
    else
    {
        buf[buflen - 1] = NUL;
    }
}

static int vim_snprintf(char *str, size_t str_m, const char *fmt, ...);

    static int
smsg(const char *s, ...)
{
    if (IObuff == NULL)
    {
        return msg((char *)s);
    }

    va_list arglist;

    va_start(arglist, s);
    vim_vsnprintf((char *)IObuff,  (1024+1) , s, arglist);
    va_end(arglist);
    return msg((char *)IObuff);
}

    static int
smsg_attr(int attr, const char *s, ...)
{
    if (IObuff == NULL)
    {
        return msg_attr((char *)s, attr);
    }

    va_list arglist;

    va_start(arglist, s);
    vim_vsnprintf((char *)IObuff,  (1024+1) , s, arglist);
    va_end(arglist);
    return msg_attr((char *)IObuff, attr);
}

    static int
smsg_attr_keep(int attr, const char *s, ...)
{
    if (IObuff == NULL)
    {
        return msg_attr_keep((char *)s, attr, TRUE);
    }

    va_list arglist;

    va_start(arglist, s);
    vim_vsnprintf((char *)IObuff,  (1024+1) , s, arglist);
    va_end(arglist);
    return msg_attr_keep((char *)IObuff, attr, TRUE);
}

static int      last_sourcing_lnum = 0;
