    static void
give_warning_with_source(char_u *message, int hl, int with_source)
{
    if (msg_silent != 0)
    {
        return;
    }

    ++no_wait_return;

     vim_free(keep_msg);
     (keep_msg) = NULL;
    if (hl)
    {
        keep_msg_attr =  highlight_attr[(int)(HLF_W)] ;
    }
    else
    {
        keep_msg_attr = 0;
    }

    if (with_source)
    {
        msg_start();
        msg_source( highlight_attr[(int)(HLF_W)] );
        msg_puts(" ");
        msg_puts_attr((char *)message,  highlight_attr[(int)(HLF_W)]  | MSG_HIST);
        msg_clr_eos();
        (void)msg_end();
    }
    else if (msg_attr((char *)message, keep_msg_attr) && msg_scrolled == 0)
    {
        set_keep_msg(message, keep_msg_attr);
    }

    msg_didout = FALSE;
    msg_nowait = TRUE;
    msg_col = 0;

    --no_wait_return;
}

    static void
msg_advance(int col)
{
    if (msg_silent != 0)
    {
        msg_col = col;
        return;
    }
    if (col >= cmdline_width)
    {
        col = cmdline_width - 1;
    }
        while (msg_col < col)
        {
            msg_putchar(' ');
        }
}

