    static int
plines(linenr_T lnum)
{
    return plines_win(curwin, lnum, TRUE);
}

    static int
plines_win(win_T       *wp, linenr_T    lnum, int         limit_winheight)
{
    int         lines;

    if (wp->w_width == 0)
    {
        return 1;
    }

    if (!wp-> w_onebuf_opt.wo_wrap )
    {
        lines = 1
        ;
    }
    else
    {
        lines = plines_win_nofold(wp, lnum);
    }

    if (limit_winheight && lines > wp->w_height)
    {
        return wp->w_height;
    }
    return lines;
}

    static int
plines_win_nofold(win_T *wp, linenr_T lnum)
{
    char_u      *s;
    long        col;
    int         width;
    chartabsize_T cts;

    s = ml_get_buf(wp->w_buffer, lnum, FALSE);
    init_chartabsize_arg(&cts, wp, lnum, 0, s, s);
    if (*s == NUL)
    {
        return 1;
    }
    win_linetabsize_cts(&cts, (colnr_T)MAXCOL);
    col = (int)cts.cts_vcol;

    if (wp-> w_onebuf_opt.wo_list  && wp->w_lcs_chars.eol != NUL)
    {
        col += 1;
    }

    width = wp->w_width - win_col_off(wp);
    if (width <= 0)
    {
        return 32000;
    }
    if (col <= width)
    {
        return 1;
    }
    col -= width;
    width += win_col_off2(wp);
    return (col + (width - 1)) / width + 1;
}

    static int
plines_win_col(win_T *wp, linenr_T lnum, long column)
{
    long        col;
    int         lines = 0;
    int         width;
    char_u      *line;
    chartabsize_T cts;

    if (!wp-> w_onebuf_opt.wo_wrap )
    {
        return lines + 1;
    }

    if (wp->w_width == 0)
    {
        return lines + 1;
    }

    line = ml_get_buf(wp->w_buffer, lnum, FALSE);

    init_chartabsize_arg(&cts, wp, lnum, 0, line, line);
    while (*cts.cts_ptr != NUL && cts.cts_ptr < line + column)
    {
        cts.cts_vcol += win_lbr_chartabsize(&cts, NULL, NULL);
         cts.cts_ptr += utfc_ptr2len(cts.cts_ptr) ;
    }

    col = cts.cts_vcol;
    if (*cts.cts_ptr == TAB && (State & MODE_NORMAL) && (!wp-> w_onebuf_opt.wo_list  || wp->w_lcs_chars.tab1))
    {
        col += win_lbr_chartabsize(&cts, NULL, NULL) - 1;
    }

    width = wp->w_width - win_col_off(wp);
    if (width <= 0)
    {
        return 9999;
    }

    lines += 1;
    if (col > width)
    {
        lines += (col - width) / (width + win_col_off2(wp)) + 1;
    }
    return lines;
}

    static int
plines_m_win(win_T *wp, linenr_T first, linenr_T last, int max)
{
    int         count = 0;

    while (first <= last && count < max)
    {
        {
                count += plines_win(wp, first, FALSE);
            ++first;
        }
    }
    return MIN(max, count);
}

    static int
gchar_pos(pos_T *pos)
{
    char_u      *ptr;
    int         ptrlen;

    if (pos->col == MAXCOL)
    {
        return NUL;
    }
    ptrlen = ml_get_len(pos->lnum);
    ptr = ml_get_pos(pos);
    if (pos->col > ptrlen)
    {
        return NUL;
    }
    return utf_ptr2char(ptr);
    return (int)*ptr;
}

    static int
gchar_cursor(void)
{
    return utf_ptr2char(ml_get_cursor());
    return (int)*ml_get_cursor();
}

    static void
pchar_cursor(int c)
{
    *(ml_get_buf(curbuf, curwin->w_cursor.lnum, TRUE) + curwin->w_cursor.col) = c;
}

    static char_u *
skip_to_option_part(char_u *p)
{
    if (*p == ',')
    {
        ++p;
    }
    while (*p == ' ')
    {
        ++p;
    }
    return p;
}

    static void
check_status(buf_T *buf)
{
    win_T       *wp;

     wp = curwin;
    if (wp->w_buffer == buf && wp->w_status_height)
    {
        wp->w_redr_status = true;
        set_must_redraw(UPD_VALID);
    }
}

    static int
ask_yesno(char_u *str, int direct)
{
    int     r = ' ';
    int     save_State = State;

    if (exiting)
    {
        settmode(TMODE_RAW);
    }
    ++no_wait_return;
    State = MODE_CONFIRM;
    ++no_mapping;
    ++allow_keys;

    while (r != 'y' && r != 'n')
    {
        smsg_attr( highlight_attr[(int)(HLF_R)] , "%s (y/n)?", str);
        if (direct)
        {
            r = get_keystroke();
        }
        else
        {
            r = plain_vgetc();
        }
        if (r == Ctrl_C || r == ESC)
        {
            r = 'n';
        }
        msg_putchar(r);
        out_flush();
    }
    --no_wait_return;
    State = save_State;
    --no_mapping;
    --allow_keys;

    return r;
}

    static int
get_keystroke(void)
{
    char_u      *buf = NULL;
    int         buflen = 150;
    int         maxlen;
    int         len = 0;
    int         n;
    int         save_mapped_ctrl_c = mapped_ctrl_c;
    int         waited = 0;

    mod_mask = 0;
    mapped_ctrl_c = FALSE;
    for (;;)
    {
        cursor_on();
        out_flush();

        maxlen = (buflen - 6 - len) / 3;
        if (buf == NULL)
        {
            buf = alloc(buflen);
        }
        else if (maxlen < 10)
        {
            char_u  *t_buf = buf;

            buflen += 100;
            buf =  realloc((buf), (buflen)) ;
            if (buf == NULL)
            {
                vim_free(t_buf);
            }
            maxlen = (buflen - 6 - len) / 3;
        }
        if (buf == NULL)
        {
            do_outofmem_msg((long_u)buflen);
            return ESC;
        }

        n = ui_inchar(buf + len, maxlen, len == 0 ? -1L : 100L, 0);
        if (n > 0)
        {
            n = fix_input_buffer(buf + len, n);
            len += n;
            waited = 0;
        }
        else if (len > 0)
        {
            ++waited;
        }

        if ((n = check_termcode(1, buf, buflen, &len)) < 0 && (!p_ttimeout || waited * 100L < (p_ttm < 0 ? p_tm : p_ttm)))
        {
            continue;
        }

        if (n == KEYLEN_REMOVED)
        {
            if (must_redraw != 0 && !need_wait_return && (State & (MODE_CMDLINE |  (0x2000 | MODE_NORMAL)  | MODE_ASKMORE)) == 0)
            {
                update_screen(0);
                setcursor();
            }
            continue;
        }
        if (n > 0)
        {
            len = n;
        }
        if (len == 0)
        {
            continue;
        }

        n = buf[0];
        if (n ==  (0x80) )
        {
            n =  ((buf[1]) == KS_SPECIAL ?  (0x80)  : (buf[1]) == KS_ZERO ?   (-((KS_ZERO) + ((int)( ('X') ) << 8)))   :  (-((buf[1]) + ((int)(buf[2]) << 8))) ) ;
            if (buf[1] == KS_MODIFIER || n ==   (-((KS_EXTRA) + ((int)(KE_IGNORE) << 8)))  )
            {
                if (buf[1] == KS_MODIFIER)
                {
                    mod_mask = buf[2];
                }
                len -= 3;
                if (len > 0)
                {
                     memmove((char *)(buf), (char *)(buf + 3), (size_t)len) ;
                }
                continue;
            }
            break;
        }
        if ( mb_bytelen_tab[n]  > len)
        {
            continue;
        }
        buf[len >= buflen ? buflen - 1 : len] = NUL;
        n = utf_ptr2char(buf);
        if (n == intr_char)
        {
            n = ESC;
        }
        break;
    }
    vim_free(buf);

    mapped_ctrl_c = save_mapped_ctrl_c;
    return merge_modifyOtherKeys(n, &mod_mask);
}

    static void
msgmore(long n)
{
    long pn;

    if (global_busy || !messaging())
    {
        return;
    }

    if (keep_msg != NULL && !keep_msg_more)
    {
        return;
    }

    if (n > 0)
    {
        pn = n;
    }
    else
    {
        pn = -n;
    }

    if (pn > p_report)
    {
        if (n > 0)
        {
            vim_snprintf(msg_buf, MSG_BUF_LEN, NGETTEXT("%ld more line", "%ld more lines", pn), pn);
        }
        else
        {
            vim_snprintf(msg_buf, MSG_BUF_LEN, NGETTEXT("%ld line less", "%ld fewer lines", pn), pn);
        }
        if (got_int)
        {
            vim_strcat((char_u *)msg_buf, (char_u *)_(" (Interrupted)"), MSG_BUF_LEN);
        }
        if (msg(msg_buf))
        {
            set_keep_msg((char_u *)msg_buf, 0);
            keep_msg_more = TRUE;
        }
    }
}

    static void
beep_flush(void)
{
    if (emsg_silent == 0)
    {
        flush_buffers(FLUSH_MINIMAL);
        vim_beep(BO_ERROR);
    }
}

    static void
vim_beep(unsigned val)
{
    if (emsg_silent != 0 || in_assert_fails)
    {
        return;
    }

    if (!((bo_flags & val) || (bo_flags & BO_ALL)))
    {
        static int              did_init = FALSE;
        static elapsed_T        start_tv;

        if (!did_init ||  elapsed(&(start_tv))  > 500)
        {
            did_init = TRUE;
             gettimeofday(&(start_tv), NULL) ;
            if (p_vb)
            {
                out_str_cf( ( term_strings[(int)(KS_VB)] ) );
            }
            else
            {
                out_char(BELL);
            }
        }
    }

}

    static char_u *
expand_env_save(char_u *src)
{
    return expand_env_save_opt(src, FALSE, NULL);
}

    static char_u *
expand_env_save_opt(char_u *src, int one, char_u *esc_chars)
{
    char_u      *p;

    p = alloc( PATH_MAX );
    if (p != NULL)
    {
        expand_env_esc(src, p,  PATH_MAX , esc_chars, one, NULL);
    }
    return p;
}

    static size_t
expand_env_esc(char_u      *srcp, char_u      *dst, int         dstlen, char_u      *esc_chars, int         one, char_u      *startstr)
{
    char_u      *src;
    char_u      *dst_start = dst;

    src = skipwhite(srcp);
    --dstlen;
    while (*src && dstlen > 0)
    {
        if (src[0] == '\\' && src[1] != NUL)
        {
            *dst++ = *src++;
            --dstlen;
        }
        if (dstlen > 0)
        {
            *dst++ = *src++;
            --dstlen;
        }
    }
    *dst = NUL;

    return (size_t)(dst - dst_start);
}

    static void
prepare_to_exit(void)
{
    mch_signal(SIGHUP, SIG_IGN);

    {
        windgoto((int)Rows - 1, cmdline_col_off);

        if (!full_screen)
        {
        }

        {
            int was_full_screen = full_screen;

            full_screen = TRUE;
            settmode(TMODE_COOK);
            full_screen = was_full_screen;
        }
        stoptermcap();
        out_flush();
    }
}

    static void
preserve_exit(void)
{

    prepare_to_exit();

    really_exiting = TRUE;

    out_str(IObuff);
    screen_start();
    out_flush();

    ml_close_notmod();

    ml_close_all(FALSE);

     out_str((char_u *)("Vim: Finished.\r\n")) ;

    getout(1);
}

enum { BREAKCHECK_SKIP = 1000 };

static int      breakcheck_count = 0;

    static void
line_breakcheck(void)
{
    if (++breakcheck_count >= BREAKCHECK_SKIP)
    {
        breakcheck_count = 0;
        ui_breakcheck();
    }
}

    static void
fast_breakcheck(void)
{
    if (++breakcheck_count >= BREAKCHECK_SKIP * 10)
    {
        breakcheck_count = 0;
        ui_breakcheck();
    }
}

    static int
goto_im(void)
{
    return (p_im && stuff_empty() && typebuf_typed());
}

    static int
path_is_url(char_u *p)
{
    if ( strncmp((char *)(p), (char *)("://"), ((size_t)3))  == 0)
    {
        return URL_SLASH;
    }
    else if ( strncmp((char *)(p), (char *)(":\\\\"), ((size_t)3))  == 0)
    {
        return URL_BACKSLASH;
    }
    return 0;
}

    static int
path_with_url(char_u *fname)
{
    char_u *p;

    if (! ( ((unsigned)(*fname) - 'A' < 26)  ||  ((unsigned)(*fname) - 'a' < 26) ) )
    {
        return 0;
    }

    for (p = fname + 1; ( ( ((unsigned)(*p) - 'A' < 26)  ||  ((unsigned)(*p) - 'a' < 26) )  || (*p == '-')); ++p)
    {
        ;
    }

    if (p[-1] == '-')
    {
        return 0;
    }

    return path_is_url(p);
}

    static int
vim_append_digit_long(long *value, int digit)
{
    long x = *value;
    if (x > ((LONG_MAX - (long)digit) / 10))
    {
        return FAIL;
    }
    *value = x * 10 + (long)digit;
    return OK;
}

    static int
trim_to_int(vimlong_T x)
{
    return x > INT_MAX ? INT_MAX : x < INT_MIN ? INT_MIN : x;
}

static int coladvance2(pos_T *pos, int addspaces, int finetune, colnr_T wcol);

    static int
virtual_active(void)
{
    unsigned int cur_ve_flags = get_ve_flags();

    if (cur_ve_flags == VE_ALL || ((cur_ve_flags & VE_INSERT) && (State & MODE_INSERT)))
    {
        return TRUE;
    }

    if (virtual_op != MAYBE)
    {
        return virtual_op;
    }
    return (cur_ve_flags & VE_BLOCK) && VIsual_active && VIsual_mode == Ctrl_V;
}

    static int
getviscol(void)
{
    colnr_T     x;

    getvvcol(curwin, &curwin->w_cursor, &x, NULL, NULL, 0);
    return (int)x;
}

    static int
coladvance_force(colnr_T wcol)
{
    int rc = coladvance2(&curwin->w_cursor, TRUE, FALSE, wcol);

    if (wcol == MAXCOL)
    {
        curwin->w_valid &= ~VALID_VIRTCOL;
    }
    else
    {
        set_valid_virtcol(curwin, wcol);
    }
    return rc;
}

    static int
getviscol2(colnr_T col, colnr_T coladd)
{
    colnr_T     x;
    pos_T       pos;

    pos.lnum = curwin->w_cursor.lnum;
    pos.col = col;
    pos.coladd = coladd;
    getvvcol(curwin, &pos, &x, NULL, NULL, 0);
    return (int)x;
}

    static int
coladvance(colnr_T wantcol)
{
    int rc = getvpos(&curwin->w_cursor, wantcol);

    if (wantcol == MAXCOL || rc == FAIL)
    {
        curwin->w_valid &= ~VALID_VIRTCOL;
    }
    else if (*ml_get_cursor() != TAB)
    {
        set_valid_virtcol(curwin, wantcol);
    }
    return rc;
}

    static int
getvpos(pos_T *pos, colnr_T wantcol)
{
    return coladvance2(pos, FALSE, virtual_active(), wantcol);
}

    static int
coladvance2(pos_T       *pos, int         addspaces, int         finetune, colnr_T     wcol_arg)
{
    colnr_T     wcol = wcol_arg;
    int         idx;
    char_u      *line;
    int         linelen;
    colnr_T     col = 0;
    int         csize = 0;
    int         one_more;

    one_more = (State & MODE_INSERT)
                    || restart_edit != NUL
                    || (VIsual_active && *p_sel != 'o')
                    || ((get_ve_flags() & VE_ONEMORE) && wcol < MAXCOL);
    line = ml_get_buf(curbuf, pos->lnum, FALSE);
    linelen = ml_get_buf_len(curbuf, pos->lnum);

    if (wcol >= MAXCOL)
    {
            idx = linelen - 1 + one_more;
            col = wcol;

            if ((addspaces || finetune) && !VIsual_active)
            {
                curwin->w_curswant = linetabsize(curwin, pos->lnum) + one_more;
                if (curwin->w_curswant > 0)
                {
                    --curwin->w_curswant;
                }
            }
    }
    else
    {
        int             width = curwin->w_width - win_col_off(curwin);
        chartabsize_T   cts;

        if (finetune && curwin-> w_onebuf_opt.wo_wrap  && curwin->w_width != 0 && wcol >= (colnr_T)width && width > 0)
        {
            csize = linetabsize_eol(curwin, pos->lnum);
            if (csize > 0)
            {
                csize--;
            }

            if (wcol / width > (colnr_T)csize / width && ((State & MODE_INSERT) == 0 || (int)wcol > csize + 1))
            {
                wcol = (csize / width + 1) * width - 1;
            }
        }

        init_chartabsize_arg(&cts, curwin, pos->lnum, 0, line, line);
        while (cts.cts_vcol <= wcol && *cts.cts_ptr != NUL)
        {
            csize = lbr_chartabsize_adv(&cts);
            cts.cts_vcol += csize;
        }
        col = cts.cts_vcol;
        idx = (int)(cts.cts_ptr - line);

        if (col > wcol || (!virtual_active() && one_more == 0))
        {
            idx -= 1;
            col -= csize;
        }

        if (virtual_active() && addspaces && wcol >= 0 && ((col != wcol && col != wcol + 1) || csize > 1))
        {
            if (line[idx] == NUL)
            {
                int     correct = wcol - col;
                char_u  *newline = alloc(idx + correct + 1);
                int     t;

                if (newline == NULL)
                {
                    return FAIL;
                }

                for (t = 0; t < idx; ++t)
                {
                    newline[t] = line[t];
                }

                for (t = 0; t < correct; ++t)
                {
                    newline[t + idx] = ' ';
                }

                newline[idx + correct] = NUL;

                ml_replace(pos->lnum, newline, FALSE);
                changed_bytes(pos->lnum, (colnr_T)idx);
                idx += correct;
                col = wcol;
            }
            else
            {
                int     correct = wcol - col - csize + 1;
                char_u  *newline;
                int t;
                int s = 0;
                int     v;

                if (-correct > csize)
                {
                    return FAIL;
                }

                newline = alloc(linelen + csize);
                if (newline == NULL)
                {
                    return FAIL;
                }

                for (t = 0; t < linelen; t++)
                {
                    if (t != idx)
                    {
                        newline[s++] = line[t];
                    }
                    else
                    {
                        for (v = 0; v < csize; v++)
                        {
                            newline[s++] = ' ';
                        }
                    }
                }

                newline[linelen + csize - 1] = NUL;

                ml_replace(pos->lnum, newline, FALSE);
                changed_bytes(pos->lnum, idx);
                idx += (csize - 1 + correct);
                col += correct;
            }
        }
    }

    if (idx < 0)
    {
        pos->col = 0;
    }
    else
    {
        pos->col = idx;
    }

    pos->coladd = 0;

    if (finetune)
    {
        if (wcol == MAXCOL)
        {
            if (!one_more)
            {
                colnr_T scol;
                colnr_T ecol;

                getvcol(curwin, pos, &scol, NULL, &ecol, 0);
                pos->coladd = ecol - scol;
            }
        }
        else
        {
            int b = (int)wcol - (int)col;

            if (b > 0 && b < (MAXCOL - 2 * curwin->w_width))
            {
                pos->coladd = b;
            }

            col += b;
        }
    }

    mb_adjustpos(curbuf, pos);

    if (wcol < 0 || col < wcol)
    {
        return FAIL;
    }
    return OK;
}

    static int
inc_cursor(void)
{
    return inc(&curwin->w_cursor);
}

    static int
inc(pos_T *lp)
{
    char_u  *p;

    if (lp->col != MAXCOL)
    {
        p = ml_get_pos(lp);
        if (*p != NUL)
        {
            int l = utfc_ptr2len(p);

            lp->col += l;
            return ((p[l] != NUL) ? 0 : 2);
            lp->col++;
            lp->coladd = 0;
            return ((p[1] != NUL) ? 0 : 2);
        }
    }
    if (lp->lnum != curbuf->b_ml.ml_line_count)
    {
        lp->col = 0;
        lp->lnum++;
        lp->coladd = 0;
        return 1;
    }
    return -1;
}

    static int
incl(pos_T *lp)
{
    int     r;

    if ((r = inc(lp)) >= 1 && lp->col)
    {
        r = inc(lp);
    }
    return r;
}

    static int
dec_cursor(void)
{
    return dec(&curwin->w_cursor);
}

    static int
dec(pos_T *lp)
{
    char_u      *p;

    lp->coladd = 0;
    if (lp->col == MAXCOL)
    {
        p = ml_get(lp->lnum);
        lp->col = ml_get_len(lp->lnum);
        lp->col -= utf_head_off(p, p + lp->col);
        return 0;
    }

    if (lp->col > 0)
    {
        lp->col--;
        p = ml_get(lp->lnum);
        lp->col -= utf_head_off(p, p + lp->col);
        return 0;
    }

    if (lp->lnum > 1)
    {
        lp->lnum--;
        p = ml_get(lp->lnum);
        lp->col = ml_get_len(lp->lnum);
        lp->col -= utf_head_off(p, p + lp->col);
        return 1;
    }

    return -1;
}

    static int
decl(pos_T *lp)
{
    int     r;

    if ((r = dec(lp)) == 1 && lp->col)
    {
        r = dec(lp);
    }
    return r;
}

    static linenr_T
get_cursor_rel_lnum(win_T       *wp, linenr_T    lnum)
{
    linenr_T    cursor = wp->w_cursor.lnum;
    linenr_T    retval = 0;

        retval = lnum - cursor;

    return retval;
}

    static void
check_pos(buf_T *buf, pos_T *pos)
{
    colnr_T len;

    if (pos->lnum > buf->b_ml.ml_line_count)
    {
        pos->lnum = buf->b_ml.ml_line_count;
    }

    if (pos->col > 0)
    {
        len = ml_get_buf_len(buf, pos->lnum);
        if (pos->col > len)
        {
            pos->col = len;
        }
    }
}

    static void
check_cursor_lnum(void)
{
    if (curwin->w_cursor.lnum > curbuf->b_ml.ml_line_count)
    {
            curwin->w_cursor.lnum = curbuf->b_ml.ml_line_count;
    }
    if (curwin->w_cursor.lnum <= 0)
    {
        curwin->w_cursor.lnum = 1;
    }
}

    static void
check_cursor_col(void)
{
    check_cursor_col_win(curwin);
}

    static void
check_cursor_col_win(win_T *win)
{
    colnr_T      len;
    colnr_T      oldcol = win->w_cursor.col;
    colnr_T      oldcoladd = win->w_cursor.col + win->w_cursor.coladd;
    unsigned int cur_ve_flags = get_ve_flags();

    len = ml_get_buf_len(win->w_buffer, win->w_cursor.lnum);
    if (len == 0)
    {
        win->w_cursor.col = 0;
    }
    else if (win->w_cursor.col >= len)
    {
        if ((State & MODE_INSERT) || restart_edit || (VIsual_active && *p_sel != 'o') || (cur_ve_flags & VE_ONEMORE) || virtual_active())
        {
            win->w_cursor.col = len;
        }
        else
        {
            win->w_cursor.col = len - 1;
            mb_adjustpos(win->w_buffer, &win->w_cursor);
        }
    }
    else if (win->w_cursor.col < 0)
    {
        win->w_cursor.col = 0;
    }

    if (oldcol == MAXCOL)
    {
        win->w_cursor.coladd = 0;
    }
    else if (cur_ve_flags == VE_ALL)
    {
        if (oldcoladd > win->w_cursor.col)
        {
            win->w_cursor.coladd = oldcoladd - win->w_cursor.col;

            if (win->w_cursor.col + 1 < len)
            {
                int cs;
                int ce;

                getvcol(win, &win->w_cursor, &cs, NULL, &ce, 0);
                if (win->w_cursor.coladd > ce - cs)
                {
                    win->w_cursor.coladd = ce - cs;
                }
            }
        }
        else
        {
            win->w_cursor.coladd = 0;
        }
    }
}

    static void
check_cursor(void)
{
    check_cursor_lnum();
    check_cursor_col();
}

    static void
check_visual_pos(void)
{
    if (VIsual.lnum > curbuf->b_ml.ml_line_count)
    {
        VIsual.lnum = curbuf->b_ml.ml_line_count;
        VIsual.col = 0;
        VIsual.coladd = 0;
    }
    else
    {
        int len = ml_get_len(VIsual.lnum);

        if (VIsual.col > len)
        {
            VIsual.col = len;
            VIsual.coladd = 0;
        }
    }
}

    static void
adjust_cursor_col(void)
{
    if (curwin->w_cursor.col > 0 && (!VIsual_active || *p_sel == 'o') && gchar_cursor() == NUL)
    {
        --curwin->w_cursor.col;
    }
}

    static int
set_leftcol(colnr_T leftcol)
{
    int         retval = FALSE;

    if (curwin->w_leftcol == leftcol)
    {
        return FALSE;
    }
    curwin->w_leftcol = leftcol;

    changed_cline_bef_curs();
    long lastcol = curwin->w_leftcol + curwin->w_width - curwin_col_off() - 1;
    validate_virtcol();

    long siso = get_sidescrolloff_value();
    if (curwin->w_virtcol > (colnr_T)(lastcol - siso))
    {
        retval = TRUE;
        coladvance((colnr_T)(lastcol - siso));
    }
    else if (curwin->w_virtcol < curwin->w_leftcol + siso)
    {
        retval = TRUE;
        (void)coladvance((colnr_T)(curwin->w_leftcol + siso));
    }

    colnr_T s;
    colnr_T e;
    getvvcol(curwin, &curwin->w_cursor, &s, NULL, &e, 0);
    if (e > (colnr_T)lastcol)
    {
        retval = TRUE;
        coladvance(s - 1);
    }
    else if (s < curwin->w_leftcol)
    {
        retval = TRUE;
        if (coladvance(e + 1) == FAIL)
        {
            curwin->w_leftcol = s;
            changed_cline_bef_curs();
        }
    }

    if (retval)
    {
        curwin->w_set_curswant = true;
    }
    redraw_later(UPD_NOT_VALID);
    return retval;
}

    static int
copy_option_part(char_u      **option, char_u      *buf, int         maxlen, char        *sep_chars)
{
    int     len = 0;
    char_u  *p = *option;

    if (*p == '.')
    {
        buf[len++] = *p++;
    }
    while (*p != NUL && vim_strchr((char_u *)sep_chars, *p) == NULL)
    {
        if (p[0] == '\\' && vim_strchr((char_u *)sep_chars, p[1]) != NULL)
        {
            ++p;
        }
        if (len < maxlen - 1)
        {
            buf[len++] = *p;
        }
        ++p;
    }
    buf[len] = NUL;

    if (*p != NUL && *p != ',')
    {
        ++p;
    }
    p = skip_to_option_part(p);

    *option = p;
    return len;
}

    static int
vim_isspace(int x)
{
    return ((x >= 9 && x <= 13) || x == ' ');
}

