    static int
name_to_mod_mask(int c)
{
    int     i;

    c =  (((c) < 'a' || (c) > 'z') ? (c) : (c) - ('a' - 'A')) ;
    for (i = 0; mod_mask_table[i].mod_mask != 0; i++)
    {
        if (c == mod_mask_table[i].name)
        {
            return mod_mask_table[i].mod_flag;
        }
    }
    return 0;
}

    static int
simplify_key(int key, int *modifiers)
{
    int     i;
    int     key0;
    int     key1;

    if (!(*modifiers & (MOD_MASK_SHIFT | MOD_MASK_CTRL)))
    {
        return key;
    }

    if (key == TAB && (*modifiers & MOD_MASK_SHIFT))
    {
        *modifiers &= ~MOD_MASK_SHIFT;
        return   (-(('k') + ((int)('B') << 8)))  ;
    }
    key0 =  ((-(key)) & 0xff) ;
    key1 =  (((unsigned)(-(key)) >> 8) & 0xff) ;
    for (i = 0; modifier_keys_table[i] != NUL; i += MOD_KEYS_ENTRY_SIZE)
    {
        if (key0 == modifier_keys_table[i + 3] && key1 == modifier_keys_table[i + 4] && (*modifiers & modifier_keys_table[i]))
        {
            *modifiers &= ~modifier_keys_table[i];
            return  (-((modifier_keys_table[i + 1]) + ((int)(modifier_keys_table[i + 2]) << 8))) ;
        }
    }
    return key;
}

    static int
handle_x_keys(int key)
{
    switch (key)
    {
        case   (-((KS_EXTRA) + ((int)(KE_XUP) << 8)))  :
            return   (-(('k') + ((int)('u') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_XDOWN) << 8)))  :
            return   (-(('k') + ((int)('d') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_XLEFT) << 8)))  :
            return   (-(('k') + ((int)('l') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_XRIGHT) << 8)))  :
            return   (-(('k') + ((int)('r') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_XHOME) << 8)))  :
            return   (-(('k') + ((int)('h') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_ZHOME) << 8)))  :
            return   (-(('k') + ((int)('h') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_XEND) << 8)))  :
            return   (-(('@') + ((int)('7') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_ZEND) << 8)))  :
            return   (-(('@') + ((int)('7') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_XF1) << 8)))  :
            return   (-(('k') + ((int)('1') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_XF2) << 8)))  :
            return   (-(('k') + ((int)('2') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_XF3) << 8)))  :
            return   (-(('k') + ((int)('3') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_XF4) << 8)))  :
            return   (-(('k') + ((int)('4') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_S_XF1) << 8)))  :
            return   (-((KS_EXTRA) + ((int)(KE_S_F1) << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_S_XF2) << 8)))  :
            return   (-((KS_EXTRA) + ((int)(KE_S_F2) << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_S_XF3) << 8)))  :
            return   (-((KS_EXTRA) + ((int)(KE_S_F3) << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_S_XF4) << 8)))  :
            return   (-((KS_EXTRA) + ((int)(KE_S_F4) << 8)))  ;
    }
    return key;
}

    static char_u *
get_special_key_name(int c, int modifiers)
{
    static char_u string[MAX_KEY_NAME_LEN + 1];
    int i;
    int idx;
    int len;
    int     table_idx;

    string[0] = '<';
    idx = 1;

    if ( ((c) < 0)  &&  ((-(c)) & 0xff)  == KS_KEY)
    {
        c =  (((unsigned)(-(c)) >> 8) & 0xff) ;
    }

    if ( ((c) < 0) )
    {
        for (i = 0; modifier_keys_table[i] != 0; i += MOD_KEYS_ENTRY_SIZE)
        {
            if (        ((-(c)) & 0xff)  == (int)modifier_keys_table[i + 1] && (int) (((unsigned)(-(c)) >> 8) & 0xff)  == (int)modifier_keys_table[i + 2])
            {
                modifiers |= modifier_keys_table[i];
                c =  (-((modifier_keys_table[i + 3]) + ((int)(modifier_keys_table[i + 4]) << 8))) ;
                break;
            }
        }
    }

    table_idx = find_special_key_in_table(c);

    if (c > 0 && utf_char2len(c) == 1)
    {
        if (table_idx < 0 && (!vim_isprintc(c) || (c & 0x7f) == ' ') && (c & 0x80))
        {
            c &= 0x7f;
            modifiers |= MOD_MASK_ALT;
            table_idx = find_special_key_in_table(c);
        }
        if (table_idx < 0 && !vim_isprintc(c) && c < ' ')
        {
            c += '@';
            modifiers |= MOD_MASK_CTRL;
        }
    }

    for (i = 0; mod_mask_table[i].name != 'A'; i++)
    {
        if ((modifiers & mod_mask_table[i].mod_mask) == mod_mask_table[i].mod_flag)
        {
            string[idx++] = mod_mask_table[i].name;
            string[idx++] = (char_u)'-';
        }
    }

    if (table_idx < 0)
    {
        if ( ((c) < 0) )
        {
            string[idx++] = 't';
            string[idx++] = '_';
            string[idx++] =  ((-(c)) & 0xff) ;
            string[idx++] =  (((unsigned)(-(c)) >> 8) & 0xff) ;
        }
        else
        {
            len = utf_char2len(c);
            if (len == 1 && vim_isprintc(c))
            {
                string[idx++] = c;
            }
            else if (len > 1)
            {
                idx += utf_char2bytes(c, string + idx);
            }
            else
            {
                char_u  *s = transchar(c);
                while (*s)
                {
                    string[idx++] = *s++;
                }
            }
        }
    }
    else
    {
        string_T    *s;

        s = &key_names_table[table_idx].name;

        if (s->length + idx + 2 <= MAX_KEY_NAME_LEN)
        {
             strcpy((char *)(string + idx), (char *)(s->string)) ;
            idx += (int)s->length;
        }
    }
    string[idx++] = '>';
    string[idx] = NUL;

    return string;
}

    static int
trans_special(char_u      **srcp, char_u      *dst, int         flags, int         escape_ks, int         *did_simplify)
{
    int         modifiers = 0;
    int         key;

    key = find_special_key(srcp, &modifiers, flags, did_simplify);
    if (key == 0)
    {
        return 0;
    }

    return special_to_buf(key, modifiers, escape_ks, dst);
}

    static int
special_to_buf(int key, int modifiers, int escape_ks, char_u *dst)
{
    int         dlen = 0;

    if (modifiers != 0)
    {
        dst[dlen++] =  (0x80) ;
        dst[dlen++] = KS_MODIFIER;
        dst[dlen++] = modifiers;
    }

    if ( ((key) < 0) )
    {
        dst[dlen++] =  (0x80) ;
        dst[dlen++] =  ((-(key)) & 0xff) ;
        dst[dlen++] =  (((unsigned)(-(key)) >> 8) & 0xff) ;
    }
    else if (escape_ks)
    {
        dlen = (int)(add_char2buf(key, dst + dlen) - dst);
    }
    else
    {
        dlen += utf_char2bytes(key, dst + dlen);
    }

    return dlen;
}

    static int
find_special_key(char_u      **srcp, int         *modp, int         flags, int         *did_simplify)
{
    char_u      *last_dash;
    char_u      *end_of_name;
    char_u      *src;
    char_u      *bp;
    int         in_string = flags & FSK_IN_STRING;
    int         modifiers;
    int         bit;
    int         key;
    uvarnumber_T        n;
    int         l;

    src = *srcp;
    if (src[0] != '<')
    {
        return 0;
    }
    if (src[1] == '*')
    {
        ++src;
    }

    last_dash = src;
    for (bp = src + 1; *bp == '-' || vim_isNormalIDc(*bp); bp++)
    {
        if (*bp == '-')
        {
            last_dash = bp;
            if (bp[1] != NUL)
            {
                l = utfc_ptr2len(bp + 1);
                if (!(in_string && bp[1] == '"') && bp[l + 1] == '>')
                {
                    bp += l;
                }
                else if (in_string && bp[1] == '\\' && bp[2] == '"' && bp[3] == '>')
                {
                    bp += 2;
                }
            }
        }
        if (bp[0] == 't' && bp[1] == '_' && bp[2] && bp[3])
        {
            bp += 3;
        }
        else if ( strncasecmp((char *)(bp), (char *)("char-"), (5))  == 0)
        {
            vim_str2nr(bp + 5, NULL, &l,  (STR2NR_BIN + STR2NR_OCT + STR2NR_HEX + STR2NR_OOCT) , NULL, NULL, 0, TRUE, NULL);
            if (l == 0)
            {
                emsg(_(e_invalid_argument));
                return 0;
            }
            bp += l + 5;
            break;
        }
    }

    if (*bp == '>')
    {
        end_of_name = bp + 1;

        modifiers = 0x0;
        for (bp = src + 1; bp < last_dash; bp++)
        {
            if (*bp != '-')
            {
                bit = name_to_mod_mask(*bp);
                if (bit == 0x0)
                {
                    break;
                }
                modifiers |= bit;
            }
        }

        if (bp >= last_dash)
        {
            if ( strncasecmp((char *)(last_dash + 1), (char *)("char-"), (5))  == 0 &&  ((unsigned)(last_dash[6]) - '0' < 10) )
            {
                vim_str2nr(last_dash + 6, NULL, &l,  (STR2NR_BIN + STR2NR_OCT + STR2NR_HEX + STR2NR_OOCT) , NULL, &n, 0, TRUE, NULL);
                if (l == 0)
                {
                    emsg(_(e_invalid_argument));
                    return 0;
                }
                key = (int)n;
            }
            else
            {
                int off = 1;

                if (in_string && last_dash[1] == '\\' && last_dash[2] == '"')
                {
                    off = 2;
                }
                l = utfc_ptr2len(last_dash + off);
                if (modifiers != 0 && last_dash[l + off] == '>')
                {
                    key =  (utf_ptr2char(last_dash + off)) ;
                }
                else
                {
                    key = get_special_key_code(last_dash + off);
                    if (!(flags & FSK_KEEP_X_KEY))
                    {
                        key = handle_x_keys(key);
                    }
                }
            }

            if (key != NUL)
            {
                key = simplify_key(key, &modifiers);

                if ((flags & FSK_KEYCODE) == 0)
                {
                    if (key ==   (-(('k') + ((int)('b') << 8)))  )
                    {
                        key = BS;
                    }
                    else if (key ==   (-(('k') + ((int)('D') << 8)))   || key ==   (-((KS_EXTRA) + ((int)(KE_KDEL) << 8)))  )
                    {
                        key = DEL;
                    }
                }
                else if (key == 27 && (flags & FSK_FROM_PART) != 0 && (kitty_protocol_state == KKPS_ENABLED || kitty_protocol_state == KKPS_DISABLED))
                {
                    if ((flags & FSK_SIMPLIFY) != 0)
                    {
                        if (did_simplify != NULL)
                        {
                            *did_simplify = TRUE;
                        }
                    }
                    else
                    {
                        key =   (-((KS_EXTRA) + ((int)(KE_ESC) << 8)))  ;
                    }
                }

                if (! ((key) < 0) )
                {
                    key = extract_modifiers(key, &modifiers, flags & FSK_SIMPLIFY, did_simplify);
                }

                *modp = modifiers;
                *srcp = end_of_name;
                return key;
            }
        }
    }
    return 0;
}

    static int
may_adjust_key_for_ctrl(int modifiers, int key)
{
    if ((modifiers & MOD_MASK_CTRL) == 0)
    {
        return key;
    }

    if ( ( ((unsigned)(key) - 'A' < 26)  ||  ((unsigned)(key) - 'a' < 26) ) )
    {
        return no_reduce_keys == 0 ?  (((key) < 'a' || (key) > 'z') ? (key) : (key) - ('a' - 'A'))  : key;
    }
    if (key == '2')
    {
        return '@';
    }
    if (key == '6')
    {
        return '^';
    }
    if (key == '-')
    {
        return '_';
    }

    if (key == '$' && (modifiers & MOD_MASK_SHIFT) == 0)
    {
        return ']';
    }

    return key;
}

    static int
may_remove_shift_modifier(int modifiers, int key)
{
    if ((modifiers == MOD_MASK_SHIFT || modifiers == (MOD_MASK_SHIFT | MOD_MASK_ALT) || modifiers == (MOD_MASK_SHIFT | MOD_MASK_META)) && ((key >= '!' && key <= '/') || (key >= ':' && key <= 'Z') || vim_isdigit(key) || (key >= '[' && key <= '`') || (key >= '{' && key <= '~')))
    {
        return modifiers & ~MOD_MASK_SHIFT;
    }

    if (modifiers == (MOD_MASK_SHIFT | MOD_MASK_CTRL) && (key == '{' || key == '}' || key == '|'))
    {
        return modifiers & ~MOD_MASK_SHIFT;
    }

    return modifiers;
}

    static int
extract_modifiers(int key, int *modp, int simplify, int *did_simplify)
{
    int modifiers = *modp;

    if ((modifiers & MOD_MASK_SHIFT) &&  ( ((unsigned)(key) - 'A' < 26)  ||  ((unsigned)(key) - 'a' < 26) ) )
    {
        key =  (((key) < 'a' || (key) > 'z') ? (key) : (key) - ('a' - 'A')) ;
        if (simplify || modifiers == MOD_MASK_SHIFT || modifiers == (MOD_MASK_SHIFT | MOD_MASK_ALT) || modifiers == (MOD_MASK_SHIFT | MOD_MASK_META))
        {
            modifiers &= ~MOD_MASK_SHIFT;
        }
    }

    if ((modifiers & MOD_MASK_CTRL) &&  ( ((unsigned)(key) - 'A' < 26)  ||  ((unsigned)(key) - 'a' < 26) ) )
    {
        key =  (((key) < 'a' || (key) > 'z') ? (key) : (key) - ('a' - 'A')) ;
    }

    if (simplify && (modifiers & MOD_MASK_CTRL) && ((key >= '?' && key <= '_') ||  ( ((unsigned)(key) - 'A' < 26)  ||  ((unsigned)(key) - 'a' < 26) ) ))
    {
        key =  ( (((key) < 'a' || (key) > 'z') ? (key) : (key) - ('a' - 'A'))  ^ 0x40) ;
        modifiers &= ~MOD_MASK_CTRL;
        if (key == NUL)
        {
            key =   (-((KS_ZERO) + ((int)( ('X') ) << 8)))  ;
        }
        if (did_simplify != NULL)
        {
            *did_simplify = TRUE;
        }
    }

    if (simplify && (modifiers & MOD_MASK_ALT) && key < 0x80)
    {
        key |= 0x80;
        modifiers &= ~MOD_MASK_ALT;
        if (did_simplify != NULL)
        {
            *did_simplify = TRUE;
        }
    }

    *modp = modifiers;
    return key;
}

    static int
find_special_key_in_table(int c)
{
    int     i;

    for (i = 0; i < (int) (sizeof(key_names_table) / sizeof((key_names_table)[0])) ; i++)
    {
        if (c == key_names_table[i].key && !key_names_table[i].is_alt)
        {
            return key_names_table[i].enabled ? i : -1;
        }
    }

    return -1;
}

    static int
cmp_key_name_entry(const void *a, const void *b)
{
    char_u  *p1 = ((struct key_name_entry *)a)->name.string;
    char_u  *p2 = ((struct key_name_entry *)b)->name.string;
    int     result = 0;

    if (p1 == p2)
    {
        return 0;
    }

    while (vim_isNormalIDc(*p1) && *p2 != NUL)
    {
        if ((result =  (((*p1) < 'A' || (*p1) > 'Z') ? (*p1) : (*p1) + ('a' - 'A'))  -  (((*p2) < 'A' || (*p2) > 'Z') ? (*p2) : (*p2) + ('a' - 'A')) ) != 0)
        {
            break;
        }
        ++p1;
        ++p2;
    }

    if (result == 0)
    {
        if (*p2 == NUL)
        {
            if (vim_isNormalIDc(*p1))
            {
                result = 1;
            }
        }
        else
        {
            result = -1;
        }
    }

    return result;
}

    static int
get_special_key_code(char_u *name)
{
    if (name[0] == 't' && name[1] == '_' && name[2] != NUL && name[3] != NUL)
    {
        char_u  string[3];

        string[0] = name[2];
        string[1] = name[3];
        string[2] = NUL;
        if (add_termcap_entry(string, FALSE) == OK)
        {
            return  (-((name[2]) + ((int)(name[3]) << 8))) ;
        }
    }
    else
    {
        struct key_name_entry   target;
        struct key_name_entry   *entry;

        target.enabled = TRUE;
        target.key = 0;
        target.name.string = name;
        target.name.length = 0;

        entry = (struct key_name_entry *)bsearch(&target, &key_names_table,  (sizeof(key_names_table) / sizeof((key_names_table)[0])) , sizeof(key_names_table[0]), cmp_key_name_entry);
        if (entry != NULL && entry->enabled)
        {
            int key = entry->key;
            return key ==   (-((KS_EXTRA) + ((int)(KE_TAB) << 8)))   ? TAB : key;
        }
    }

    return 0;
}

    static int
get_real_state(void)
{
    if (State & MODE_NORMAL)
    {
        if (VIsual_active)
        {
            if (VIsual_select)
            {
                return MODE_SELECT;
            }
            return MODE_VISUAL;
        }
        else if (finish_op)
        {
            return MODE_OP_PENDING;
        }
    }
    return State;
}

    static int
after_pathsep(char_u *b, char_u *p)
{
    return p > b && vim_ispathsep(p[-1])
                             && (utf_head_off(b, p - 1) == 0);
}

    static long
elapsed(struct timeval *start_tv)
{
    struct timeval  now_tv;

    gettimeofday(&now_tv, NULL);
    return (now_tv.tv_sec - start_tv->tv_sec) * 1000L
         + (now_tv.tv_usec - start_tv->tv_usec) / 1000L;
}

    static int
cmp_keyvalue_value_n(const void *a, const void *b)
{
    keyvalue_T *kv1 = (keyvalue_T *)a;
    keyvalue_T *kv2 = (keyvalue_T *)b;

    return  strncmp((char *)(kv1->value.string), (char *)(kv2->value.string), (MAX(kv1->value.length, kv2->value.length))) ;
}

    static int
cmp_keyvalue_value_i(const void *a, const void *b)
{
    keyvalue_T *kv1 = (keyvalue_T *)a;
    keyvalue_T *kv2 = (keyvalue_T *)b;

    return  strcasecmp((char *)(kv1->value.string), (char *)(kv2->value.string)) ;
}

    static int
cmp_keyvalue_value_ni(const void *a, const void *b)
{
    keyvalue_T *kv1 = (keyvalue_T *)a;
    keyvalue_T *kv2 = (keyvalue_T *)b;

    return vim_strnicmp_asc((char *)kv1->value.string, (char *)kv2->value.string, MAX(kv1->value.length, kv2->value.length));
}

static void redraw_for_cursorline(win_T *wp);
static int scrolljump_value(void);
static int check_top_offset(void);
typedef struct
{
    linenr_T        lnum;
    int             height;
} lineoff_T;

static void topline_back(lineoff_T *lp);
static void botline_forw(lineoff_T *lp);

    static int
adjust_plines_for_skipcol(win_T *wp)
{
    if (wp->w_skipcol == 0)
    {
        return 0;
    }

    int width = wp->w_width - win_col_off(wp);
    int w2 = width + win_col_off2(wp);
    if (wp->w_skipcol >= width && w2 > 0)
    {
        return (wp->w_skipcol - width) / w2 + 1;
    }

    return 0;
}

    static int
plines_correct_topline(win_T *wp, linenr_T lnum, int limit_winheight)
{
    int n;
        n = plines_win(wp, lnum, FALSE);
    if (lnum == wp->w_topline)
    {
        n -= adjust_plines_for_skipcol(wp);
    }
    if (limit_winheight && n > wp->w_height)
    {
        n = wp->w_height;
    }
    return n;
}

    static void
comp_botline(win_T *wp)
{
    int         n;
    linenr_T    lnum;
    int         done;

    check_cursor_moved(wp);
    if (wp->w_valid & VALID_CROW)
    {
        lnum = wp->w_cursor.lnum;
        done = wp->w_cline_row;
    }
    else
    {
        lnum = wp->w_topline;
        done = 0;
    }

    for ( ; lnum <= wp->w_buffer->b_ml.ml_line_count; ++lnum)
    {
        {
            n = plines_correct_topline(wp, lnum, TRUE);
        }
        if (lnum == wp->w_cursor.lnum)
        {
            wp->w_cline_row = done;
            wp->w_cline_height = n;
            redraw_for_cursorline(wp);
            wp->w_valid |= (VALID_CROW|VALID_CHEIGHT);
        }
        if (done + n > wp->w_height)
        {
            break;
        }
        done += n;
    }

    wp->w_botline = lnum;
    wp->w_valid |= VALID_BOTLINE|VALID_BOTLINE_AP;

    set_empty_rows(wp, done);
}

    static void
redraw_for_cursorline(win_T *wp)
{
    if ((wp-> w_onebuf_opt.wo_rnu ) && (wp->w_valid & VALID_CROW) == 0)
    {
        redraw_win_later(wp, UPD_VALID);
    }
}

    static void
set_valid_virtcol(win_T *wp, colnr_T vcol)
{
    wp->w_virtcol = vcol;
    wp->w_valid |= VALID_VIRTCOL;
}

    static int
sms_marker_overlap(win_T *wp, int extra2)
{
    if (extra2 == -1)
    {
        extra2 = win_col_off(wp) - win_col_off2(wp);
    }
    if (wp-> w_onebuf_opt.wo_list  && wp->w_lcs_chars.prec)
    {
        return 1;
    }

    return extra2 > 3 ? 0 : 3 - extra2;
}

    static int
skipcol_from_plines(win_T *wp, int plines_off)
{
    int width1 = wp->w_width - win_col_off(wp);

    int skipcol = 0;
    if (plines_off > 0)
    {
        skipcol += width1;
    }
    if (plines_off > 1)
    {
        skipcol += (width1 + win_col_off2(wp)) * (plines_off - 1);
    }
    return skipcol;
}

    static void
reset_skipcol(void)
{
    if (curwin->w_skipcol == 0)
    {
        return;
    }

    curwin->w_skipcol = 0;

    redraw_later(UPD_SOME_VALID);
}

    static void
update_topline_redraw(void)
{
    update_topline();
    if (must_redraw)
    {
        update_screen(0);
    }
}

    static bool
use_scrolloffpad(void)
{
    return get_scrolloff_value() > 0 && get_scrolloffpad_value() > 0;
}

    static bool
scrolloffpad_eof_pressure(linenr_T lnum, long so)
{
    if (!use_scrolloffpad() || so <= 0)
    {
        return false;
    }

    return lnum > curbuf->b_ml.ml_line_count - so;
}

    static void
update_topline(void)
{
    long        line_count;
    int         halfheight;
    int         n;
    int         check_topline = FALSE;
    int         check_botline = FALSE;
    long        *so_ptr = curwin-> w_onebuf_opt.wo_so  >= 0 ? &curwin-> w_onebuf_opt.wo_so  : &p_so;
    int         save_so = *so_ptr;
    bool        eof_pressure;

    if (skip_update_topline)
    {
        return;
    }

    if (!screen_valid(TRUE) || curwin->w_height == 0)
    {
        check_cursor_lnum();
        curwin->w_topline = curwin->w_cursor.lnum;
        curwin->w_botline = curwin->w_topline;
        curwin->w_scbind_pos = 1;
        return;
    }

    check_cursor_moved(curwin);
    if (curwin->w_valid & VALID_TOPLINE)
    {
        return;
    }

    if (mouse_dragging > 0)
    {
        *so_ptr = mouse_dragging - 1;
    }
    eof_pressure = scrolloffpad_eof_pressure(curwin->w_cursor.lnum, *so_ptr);

    linenr_T old_topline = curwin->w_topline;

    if ( (curbuf->b_ml.ml_line_count == 1 && *ml_get((linenr_T)1) == NUL) )
    {
        if (curwin->w_topline != 1)
        {
            redraw_later(UPD_NOT_VALID);
        }
        curwin->w_topline = 1;
        curwin->w_botline = 2;
        curwin->w_skipcol = 0;
        curwin->w_valid |= VALID_BOTLINE|VALID_BOTLINE_AP;
        curwin->w_scbind_pos = 1;
    }

    else
    {
        if (curwin->w_topline > 1 || curwin->w_skipcol > 0)
        {
            if (curwin->w_cursor.lnum < curwin->w_topline)
            {
                check_topline = TRUE;
            }
            else if (check_top_offset())
            {
                check_topline = TRUE;
            }
            else if (curwin->w_skipcol > 0 && curwin->w_cursor.lnum == curwin->w_topline)
            {
                colnr_T vcol;
                int overlap;

                getvvcol(curwin, &curwin->w_cursor, &vcol, NULL, NULL, 0);
                overlap = sms_marker_overlap(curwin, -1);
                if (curwin->w_skipcol + overlap > vcol)
                {
                    check_topline = TRUE;
                }
            }
        }

        if (check_topline)
        {
            halfheight = curwin->w_height / 2 - 1;
            if (halfheight < 2)
            {
                halfheight = 2;
            }

                n = curwin->w_topline + *so_ptr - curwin->w_cursor.lnum;

            int min_scroll = scrolljump_value();
            if (eof_pressure)
            {
                scroll_cursor_halfway(TRUE, TRUE);
            }
            else if (n >= halfheight && min_scroll < halfheight)
            {
                scroll_cursor_halfway(FALSE, FALSE);
            }
            else
            {
                scroll_cursor_top(min_scroll, FALSE);
                check_botline = TRUE;
            }
        }

        else
        {
            check_botline = TRUE;
        }
    }

    if (check_botline)
    {
        if (!(curwin->w_valid & VALID_BOTLINE_AP))
        {
            validate_botline();
        }

        if (curwin->w_botline <= curbuf->b_ml.ml_line_count || use_scrolloffpad())
        {
            if (curwin->w_cursor.lnum < curwin->w_botline)
            {
                if (((long)curwin->w_cursor.lnum >= (long)curwin->w_botline - *so_ptr))
                {
                    lineoff_T   loff;

                    n = eof_pressure ? 0 : curwin->w_empty_rows;
                    loff.lnum = curwin->w_cursor.lnum;
                    loff.height = 0;
                    while (loff.lnum < curwin->w_botline)
                    {
                        n += loff.height;
                        if (n >= *so_ptr)
                        {
                            break;
                        }
                        botline_forw(&loff);
                    }
                    if (n >= *so_ptr && !eof_pressure)
                    {
                        check_botline = FALSE;
                    }
                }
                else
                {
                    check_botline = FALSE;
                }
            }
            if (check_botline)
            {
                    line_count = curwin->w_cursor.lnum - curwin->w_botline
                                                                 + 1 + *so_ptr;
                if (line_count <= curwin->w_height + 1)
                {
                    if (eof_pressure)
                    {
                        scroll_cursor_halfway(TRUE, TRUE);
                    }
                    else
                    {
                        scroll_cursor_bot(scrolljump_value(), FALSE);
                    }
                }
                else
                {
                    scroll_cursor_halfway(eof_pressure, eof_pressure);
                }
            }
        }
    }
    curwin->w_valid |= VALID_TOPLINE;

    if (curwin->w_topline != old_topline)
    {
        dollar_vcol = -1;
        redraw_later(UPD_VALID);

        if (!curwin-> w_onebuf_opt.wo_sms )
        {
            reset_skipcol();
        }
        else if (curwin->w_skipcol != 0)
        {
            redraw_later(UPD_SOME_VALID);
        }

        if (curwin->w_cursor.lnum == curwin->w_topline)
        {
            validate_cursor();
        }
    }

    *so_ptr = save_so;
}

    static int
scrolljump_value(void)
{
    if (p_sj >= 0)
    {
        return (int)p_sj;
    }
    return (curwin->w_height * -p_sj) / 100;
}

    static int
check_top_offset(void)
{
    lineoff_T   loff;
    int         n;
    long        so = get_scrolloff_value();

    if (curwin->w_cursor.lnum < curwin->w_topline + so)
    {
        loff.lnum = curwin->w_cursor.lnum;
        n = 0;
        while (n < so)
        {
            topline_back(&loff);
            if (loff.lnum < curwin->w_topline)
            {
                break;
            }
            n += loff.height;
        }
        if (n < so)
        {
            return TRUE;
        }
    }
    return FALSE;
}

