    static void
validate_cursor(void)
{
    check_cursor_lnum();
    check_cursor_moved(curwin);
    if ((curwin->w_valid & (VALID_WCOL|VALID_WROW)) != (VALID_WCOL|VALID_WROW))
    {
        curs_columns(TRUE);
    }
}

    static void
curs_rows(win_T *wp)
{
    linenr_T    lnum;
    int         i;
    int         all_invalid;
    int         valid;

    all_invalid = (!redrawing() || wp->w_lines_valid == 0 || wp->w_lines[0].wl_lnum > wp->w_topline);
    i = 0;
    wp->w_cline_row = 0;
    for (lnum = wp->w_topline; lnum < wp->w_cursor.lnum; ++i)
    {
        valid = FALSE;
        if (!all_invalid && i < wp->w_lines_valid)
        {
            if (wp->w_lines[i].wl_lnum < lnum || !wp->w_lines[i].wl_valid)
            {
                continue;
            }
            if (wp->w_lines[i].wl_lnum == lnum)
            {
                valid = TRUE;
            }
            else if (wp->w_lines[i].wl_lnum > lnum)
            {
                --i;
            }
        }
        if (valid && (lnum != wp->w_topline || (wp->w_skipcol == 0)))
        {
            ++lnum;
            wp->w_cline_row += wp->w_lines[i].wl_size;
        }
        else
        {
            {
                wp->w_cline_row += plines_correct_topline(wp, lnum, TRUE);
                ++lnum;
            }
        }
    }

    check_cursor_moved(wp);
    if (!(wp->w_valid & VALID_CHEIGHT))
    {
        if (all_invalid || i == wp->w_lines_valid || (i < wp->w_lines_valid && (!wp->w_lines[i].wl_valid || wp->w_lines[i].wl_lnum != wp->w_cursor.lnum)))
        {
                wp->w_cline_height = plines_win(wp, wp->w_cursor.lnum, TRUE);
        }
        else if (i > wp->w_lines_valid)
        {
            wp->w_cline_height = 0;
        }
        else
        {
            wp->w_cline_height = wp->w_lines[i].wl_size;
        }
    }

    redraw_for_cursorline(curwin);
    wp->w_valid |= VALID_CROW|VALID_CHEIGHT;
}

