static const int nv_max_linear = 126;

    static int
find_command(int cmdchar)
{
    int         i;
    int         idx;
    int top;
    int bot;
    int         c;

    if (cmdchar >= 0x100)
    {
        return -1;
    }

    if (cmdchar < 0)
    {
        cmdchar = -cmdchar;
    }

    if (cmdchar <= nv_max_linear)
    {
        return nv_cmd_idx[cmdchar];
    }

    bot = nv_max_linear + 1;
    top =   (sizeof(nv_cmds) / sizeof((nv_cmds)[0]))   - 1;
    idx = -1;
    while (bot <= top)
    {
        i = (top + bot) / 2;
        c = nv_cmds[nv_cmd_idx[i]].cmd_char;
        if (c < 0)
        {
            c = -c;
        }
        if (cmdchar == c)
        {
            idx = nv_cmd_idx[i];
            break;
        }
        if (cmdchar > c)
        {
            bot = i + 1;
        }
        else
        {
            top = i - 1;
        }
    }
    return idx;
}

    static int
check_text_locked(oparg_T *oap)
{
    if (!text_locked())
    {
        return FALSE;
    }

    if (oap != NULL)
    {
        clearopbeep(oap);
    }
    text_locked_msg();
    return TRUE;
}

    static int
check_text_or_curbuf_locked(oparg_T *oap)
{
    if (check_text_locked(oap))
    {
        return TRUE;
    }

    if (!curbuf_locked())
    {
        return FALSE;
    }

    if (oap != NULL)
    {
        clearop(oap);
    }
    return TRUE;
}

    static int
normal_cmd_get_count(cmdarg_T        *cap, int             c, int             toplevel  __attribute__((unused)) , int             set_prevcount  __attribute__((unused)) , int             *ctrl_w, int             *need_flushbuf  __attribute__((unused)) )
{
getcount:
    if (!(VIsual_active && VIsual_select))
    {
        while ((c >= '1' && c <= '9') || (cap->count0 != 0 && (c ==   (-(('k') + ((int)('D') << 8)))   || c ==   (-((KS_EXTRA) + ((int)(KE_KDEL) << 8)))   || c == '0')))
        {
            if (c ==   (-(('k') + ((int)('D') << 8)))   || c ==   (-((KS_EXTRA) + ((int)(KE_KDEL) << 8)))  )
            {
                cap->count0 /= 10;
                del_from_showcmd(4);
            }
            else if (cap->count0 > 99999999L)
            {
                cap->count0 = 999999999L;
            }
            else
            {
                cap->count0 = cap->count0 * 10 + (c - '0');
            }
            if (*ctrl_w)
            {
                ++no_mapping;
                ++allow_keys;
            }
            ++no_zero_mapping;
            c = plain_vgetc();
              ;
            --no_zero_mapping;
            if (*ctrl_w)
            {
                --no_mapping;
                --allow_keys;
            }
            *need_flushbuf |= add_to_showcmd(c);
        }

        if (c == Ctrl_W && !*ctrl_w && cap->oap->op_type == OP_NOP)
        {
            *ctrl_w = TRUE;
            cap->opcount = cap->count0;
            cap->count0 = 0;
            ++no_mapping;
            ++allow_keys;
            c = plain_vgetc();
              ;
            --no_mapping;
            --allow_keys;
            *need_flushbuf |= add_to_showcmd(c);
            goto getcount;
        }
    }

    if (c ==   (-((KS_EXTRA) + ((int)(KE_CURSORHOLD) << 8)))  )
    {
        cap->oap->prev_opcount = cap->opcount;
        cap->oap->prev_count0 = cap->count0;
    }
    else if (cap->opcount != 0)
    {
        if (cap->count0)
        {
            if (cap->opcount >= 999999999L / cap->count0)
            {
                cap->count0 = 999999999L;
            }
            else
            {
                cap->count0 *= cap->opcount;
            }
        }
        else
        {
            cap->count0 = cap->opcount;
        }
    }

    cap->opcount = cap->count0;
    cap->count1 = (cap->count0 == 0 ? 1 : cap->count0);

    return c;
}

    static int
normal_cmd_needs_more_chars(cmdarg_T *cap, short_u cmd_flags)
{
    return ((cmd_flags & NV_NCH) && (((cmd_flags &  (0x02|NV_NCH) ) ==  (0x02|NV_NCH)  && cap->oap->op_type == OP_NOP) || (cmd_flags &  (0x04|NV_NCH) ) ==  (0x04|NV_NCH)  || (cap->cmdchar == 'q' && cap->oap->op_type == OP_NOP && reg_recording == 0 && reg_executing == 0) || ((cap->cmdchar == 'a' || cap->cmdchar == 'i') && (cap->oap->op_type != OP_NOP || VIsual_active))));
}

    static int
normal_cmd_get_more_chars(int         idx_arg, cmdarg_T    *cap, int         *need_flushbuf  __attribute__((unused)) )
{
    int         idx = idx_arg;
    int         c;
    int         *cp;
    int         repl = FALSE;
    int         lit = FALSE;
    int         lang;

    ++no_mapping;
    ++allow_keys;
    did_cursorhold = TRUE;
    if (cap->cmdchar == 'g')
    {
        cap->nchar = plain_vgetc();
          ;
        *need_flushbuf |= add_to_showcmd(cap->nchar);
        if (cap->nchar == 'r' || cap->nchar == '\'' || cap->nchar == '`' || cap->nchar == Ctrl_BSL)
        {
            cp = &cap->extra_char;
            if (cap->nchar != 'r')
            {
                lit = TRUE;
            }
            else
            {
                repl = TRUE;
            }
        }
        else
        {
            cp = NULL;
        }
    }
    else
    {
        if (cap->cmdchar == 'r')
        {
            repl = TRUE;
        }
        cp = &cap->nchar;
    }
    lang = (repl || (nv_cmds[idx].cmd_flags & NV_LANG));

    if (cp != NULL)
    {
        if (repl)
        {
            State =  (REPLACE_FLAG | MODE_INSERT) ;
        }
        if ((State & MODE_INSERT) && !p_ek)
        {
              ;

            out_str( ( term_strings[(int)(KS_CBD)] ) );
            out_str_t_TE();
        }

        *cp = plain_vgetc();

        if ((State & MODE_INSERT) && !p_ek)
        {
              ;

            out_str_t_BE();
            out_str_t_TI();
        }

        State =  (0x1000 | MODE_NORMAL) ;
        *need_flushbuf |= add_to_showcmd(*cp);

        if (!lit)
        {
              ;
        }

        if (cp == &cap->extra_char && cap->nchar == Ctrl_BSL && (cap->extra_char == Ctrl_N || cap->extra_char == Ctrl_G))
        {
            cap->cmdchar = Ctrl_BSL;
            cap->nchar = cap->extra_char;
            idx = find_command(cap->cmdchar);
        }
        else if ((cap->nchar == 'n' || cap->nchar == 'N') && cap->cmdchar == 'g')
        {
            cap->oap->op_type = get_op_type(*cp, NUL);
        }
        else if (*cp == Ctrl_BSL)
        {
            long towait = (p_ttm >= 0 ? p_ttm : p_tm);

            while ((c = vpeekc()) <= 0 && towait > 0L)
            {
                do_sleep(towait > 50L ? 50L : towait, FALSE);
                towait -= 50L;
            }
            if (c > 0)
            {
                c = plain_vgetc();
                if (c != Ctrl_N && c != Ctrl_G)
                {
                    vungetc(c);
                }
                else
                {
                    cap->cmdchar = Ctrl_BSL;
                    cap->nchar = c;
                    idx = find_command(cap->cmdchar);
                }
            }
        }

        if (lang)
        {
            --no_mapping;
            while ((c = vpeekc()) > 0 && (c >= 0x100 ||  mb_bytelen_tab[vpeekc()]  > 1))
            {
                c = plain_vgetc();
                if (!utf_iscomposing(c))
                {
                    vungetc(c);
                    break;
                }
                else if (cap->ncharC1 == 0)
                {
                    cap->ncharC1 = c;
                }
                else
                {
                    cap->ncharC2 = c;
                }
            }
            ++no_mapping;
            ++no_u_sync;
            gotchars_ignore();
            --no_u_sync;
        }
    }
    --no_mapping;
    --allow_keys;

    return idx;
}

    static int
normal_cmd_need_to_wait_for_msg(cmdarg_T *cap, pos_T *old_pos)
{
    return (       ((p_smd && msg_silent == 0 && (restart_edit != 0 || (VIsual_active && old_pos->lnum == curwin->w_cursor.lnum && old_pos->col == curwin->w_cursor.col)) && (clear_cmdline || redraw_cmdline) && (msg_didout || (msg_didany && msg_scroll)) && !msg_nowait && KeyTyped) || (restart_edit != 0 && !VIsual_active && (msg_scroll || emsg_on_display))) && cap->oap->regname == 0 && !(cap->retval & CA_COMMAND_BUSY) && stuff_empty() && typebuf_typed() && emsg_silent == 0 && !in_assert_fails && !did_wait_return && cap->oap->op_type == OP_NOP);
}

    static void
normal_cmd_wait_for_msg(void)
{
    int save_State = State;

    if (restart_edit != 0)
    {
        State = MODE_INSERT;
    }

    if (must_redraw && keep_msg != NULL && !emsg_on_display)
    {
        char_u  *kmsg;

        kmsg = keep_msg;
        keep_msg = NULL;
        setcursor();
        update_screen(0);
        keep_msg = kmsg;

        kmsg = vim_strsave(keep_msg);
        if (kmsg != NULL)
        {
            msg_attr((char *)kmsg, keep_msg_attr);
            vim_free(kmsg);
        }
    }
    setcursor();
    cursor_on();
    out_flush();
    if (msg_scroll || emsg_on_display)
    {
        ui_delay(1003L, TRUE);
    }
    ui_delay(3003L, FALSE);
    State = save_State;

    msg_scroll = FALSE;
    emsg_on_display = FALSE;
}

    static void
normal_cmd(oparg_T     *oap, int         toplevel  __attribute__((unused)) )
{
    cmdarg_T    ca;
    int         c;
    int         ctrl_w = FALSE;
    int         old_col = curwin->w_curswant;
    int         need_flushbuf = FALSE;
    pos_T       old_pos;
    int         mapped_len;
    static int  old_mapped_len = 0;
    int         idx;
    int         set_prevcount = FALSE;
    int         save_did_cursorhold = did_cursorhold;

      memset((&(ca)), (0), (sizeof(ca)))  ;
    ca.oap = oap;

    ca.opcount = opcount;

    finish_op = (oap->op_type != OP_NOP);

    if (!finish_op && !oap->regname)
    {
        ca.opcount = 0;
    }

    if (oap->prev_opcount > 0 || oap->prev_count0 > 0)
    {
        ca.opcount = oap->prev_opcount;
        ca.count0 = oap->prev_count0;
        oap->prev_opcount = 0;
        oap->prev_count0 = 0;
    }

    mapped_len = typebuf_maplen();

    State =  (0x1000 | MODE_NORMAL) ;

    c = safe_vgetc();
      ;

    if (restart_edit == 0)
    {
        old_mapped_len = 0;
    }
    else if (old_mapped_len || (VIsual_active && mapped_len == 0 && typebuf_maplen() > 0))
    {
        old_mapped_len = typebuf_maplen();
    }

    if (c == NUL)
    {
        c =   (-((KS_ZERO) + ((int)( ('X') ) << 8)))  ;
    }

    if (VIsual_active && VIsual_select && (vim_isprintc(c) || c == NL || c == CAR || c ==   (-(('K') + ((int)('A') << 8)))  ))
    {
        int len;

        len = ins_char_typebuf(vgetc_char, vgetc_mod_mask);

        if (KeyTyped)
        {
            ungetchars(len);
        }

        if (restart_edit != 0)
        {
            c = 'd';
        }
        else
        {
            c = 'c';
        }
        msg_nowait = TRUE;
        old_mapped_len = 0;
    }

    if (KeyTyped && !KeyStuffed)
    {
        win_ensure_size();
    }

    need_flushbuf = add_to_showcmd(c);

    c = normal_cmd_get_count(&ca, c, toplevel, set_prevcount, &ctrl_w, &need_flushbuf);

    if (ctrl_w)
    {
        ca.nchar = c;
        ca.cmdchar = Ctrl_W;
    }
    else
    {
        ca.cmdchar = c;
    }
    idx = find_command(ca.cmdchar);
    if (idx < 0)
    {
        clearopbeep(oap);
        goto normal_end;
    }

    if ((nv_cmds[idx].cmd_flags & NV_NCW) && check_text_or_curbuf_locked(oap))
    {
        goto normal_end;
    }

    if (VIsual_active)
    {
        if (km_stopsel && (nv_cmds[idx].cmd_flags & NV_STS) && !(mod_mask & MOD_MASK_SHIFT))
        {
            end_visual_mode();
            redraw_curbuf_later(UPD_INVERTED);
        }

        if (km_startsel)
        {
            if (nv_cmds[idx].cmd_flags & NV_SS)
            {
                unshift_special(&ca);
                idx = find_command(ca.cmdchar);
                if (idx < 0)
                {
                    clearopbeep(oap);
                    goto normal_end;
                }
            }
            else if ((nv_cmds[idx].cmd_flags & NV_SSS) && (mod_mask & MOD_MASK_SHIFT))
            {
                mod_mask &= ~MOD_MASK_SHIFT;
            }
        }
    }

    if (normal_cmd_needs_more_chars(&ca, nv_cmds[idx].cmd_flags))
    {
        idx = normal_cmd_get_more_chars(idx, &ca, &need_flushbuf);
    }

    if (need_flushbuf)
    {
        out_flush();
    }

    if (ca.cmdchar !=   (-((KS_EXTRA) + ((int)(KE_IGNORE) << 8)))  )
    {
        if (ex_normal_busy)
        {
            did_cursorhold = save_did_cursorhold;
        }
        else
        {
            did_cursorhold = FALSE;
        }
    }

    State = MODE_NORMAL;

    if (ca.nchar == ESC || ca.extra_char == ESC)
    {
        clearop(oap);
        if (restart_edit == 0 && goto_im())
        {
            restart_edit = 'a';
        }
        goto normal_end;
    }

    if (ca.cmdchar !=   (-((KS_EXTRA) + ((int)(KE_IGNORE) << 8)))  )
    {
        msg_didout = FALSE;
        msg_col = 0;
    }

    old_pos = curwin->w_cursor;

    if (!VIsual_active && km_startsel)
    {
        if (nv_cmds[idx].cmd_flags & NV_SS)
        {
            start_selection();
            unshift_special(&ca);
            idx = find_command(ca.cmdchar);
        }
        else if ((nv_cmds[idx].cmd_flags & NV_SSS) && (mod_mask & MOD_MASK_SHIFT))
        {
            start_selection();
            mod_mask &= ~MOD_MASK_SHIFT;
        }
    }

    ca.arg = nv_cmds[idx].cmd_arg;
    (nv_cmds[idx].cmd_func)(&ca);

    if (!finish_op && !oap->op_type && (idx < 0 || !(nv_cmds[idx].cmd_flags & NV_KEEPREG)))
    {
        clearop(oap);
    }

    if (old_mapped_len > 0)
    {
        old_mapped_len = typebuf_maplen();
    }

    if (ca.cmdchar !=   (-((KS_EXTRA) + ((int)(KE_IGNORE) << 8)))   && ca.cmdchar !=   (-((KS_EXTRA) + ((int)(KE_MOUSEMOVE) << 8)))  )
    {
        do_pending_operator(&ca, old_col, FALSE);
    }

    if (normal_cmd_need_to_wait_for_msg(&ca, &old_pos))
    {
        normal_cmd_wait_for_msg();
    }

normal_end:

    msg_nowait = FALSE;

    if (oap->op_type == OP_NOP)
    {
        finish_op = FALSE;
    }

    if (oap->op_type == OP_NOP && oap->regname == 0 && ca.cmdchar !=   (-((KS_EXTRA) + ((int)(KE_CURSORHOLD) << 8)))  )
    {
        clear_showcmd();
    }

    checkpcmark();
    vim_free(ca.searchbuf);

    mb_adjust_cursor();

    if (       oap->op_type == OP_NOP && ((restart_edit != 0 && !VIsual_active && old_mapped_len == 0) || restart_VIsual_select == 1) && !(ca.retval & CA_COMMAND_BUSY) && stuff_empty() && oap->regname == 0)
    {
        if (restart_VIsual_select == 1)
        {
            VIsual_select = TRUE;
            showmode();
            restart_VIsual_select = 0;
            VIsual_select_reg = 0;
        }
        if (restart_edit != 0 && !VIsual_active && old_mapped_len == 0)
        {
            (void)edit(restart_edit, FALSE, 1L);
        }
    }

    if (restart_VIsual_select == 2)
    {
        restart_VIsual_select = 1;
    }

    opcount = ca.opcount;
}

    static void
check_visual_highlight(void)
{
    static int      did_check = FALSE;

    if (full_screen)
    {
        if (!did_check &&  highlight_attr[(int)(HLF_V)]  == 0)
        {
            msg(_("Warning: terminal cannot highlight"));
        }
        did_check = TRUE;
    }
}

    static void
end_visual_mode(void)
{
    VIsual_select_exclu_adj = FALSE;
    end_visual_mode_keep_button();
}

    static void
end_visual_mode_keep_button(void)
{
    VIsual_active = FALSE;
    mouse_dragging = 0;

    curbuf->b_visual.vi_mode = VIsual_mode;
    curbuf->b_visual.vi_start = VIsual;
    curbuf->b_visual.vi_end = curwin->w_cursor;
    curbuf->b_visual.vi_curswant = curwin->w_curswant;
    if (!virtual_active())
    {
        curwin->w_cursor.coladd = 0;
    }
    may_clear_cmdline();

    adjust_cursor_eol();
}

    static void
reset_VIsual_and_resel(void)
{
    if (VIsual_active)
    {
        end_visual_mode();
        redraw_curbuf_later(UPD_INVERTED);
    }
    VIsual_reselect = FALSE;
}

    static void
reset_VIsual(void)
{
    if (VIsual_active)
    {
        end_visual_mode();
        redraw_curbuf_later(UPD_INVERTED);
        VIsual_reselect = FALSE;
    }
}

    static void
restore_visual_mode(void)
{
    if (VIsual_mode_orig != NUL)
    {
        curbuf->b_visual.vi_mode = VIsual_mode_orig;
        VIsual_mode_orig = NUL;
    }
}

    static int
find_is_eval_item(char_u      *ptr, int         *colp, int         *bnp, int         dir)
{
    if ((*ptr == ']' && dir ==  (-1) ) || (*ptr == '[' && dir == FORWARD))
    {
        ++*bnp;
    }
    if (*bnp > 0)
    {
        if ((*ptr == '[' && dir ==  (-1) ) || (*ptr == ']' && dir == FORWARD))
        {
            --*bnp;
        }
        return TRUE;
    }

    if (*ptr == '.')
    {
        return TRUE;
    }

    if (ptr[dir ==  (-1)  ? 0 : 1] == '>' && ptr[dir ==  (-1)  ? -1 : 0] == '-')
    {
        *colp += dir;
        return TRUE;
    }
    return FALSE;
}

    static int
find_ident_under_cursor(char_u **text, int find_type)
{
    return find_ident_at_pos(curwin, curwin->w_cursor.lnum, curwin->w_cursor.col, text, NULL, find_type);
}

    static int
find_ident_at_pos(win_T       *wp, linenr_T    lnum, colnr_T     startcol, char_u      **text, int         *textcol, int         find_type)
{
    char_u      *ptr;
    int         col = 0;
    int         i;
    int         this_class = 0;
    int         prev_class;
    int         prevcol;
    int         bn = 0;

    ptr = ml_get_buf(wp->w_buffer, lnum, FALSE);
    for (i = (find_type & FIND_IDENT) ? 0 : 1;  i < 2; ++i)
    {
        col = startcol;
        while (ptr[col] != NUL)
        {
            if ((find_type & FIND_EVAL) && ptr[col] == ']')
            {
                break;
            }
            this_class = mb_get_class(ptr + col);
            if (this_class != 0 && (i == 1 || this_class != 1))
            {
                break;
            }
            col += utfc_ptr2len(ptr + col);
        }

        bn = ptr[col] == ']';

        if ((find_type & FIND_EVAL) && ptr[col] == ']')
        {
            this_class = mb_get_class((char_u *)"a");
        }
        else
        {
            this_class = mb_get_class(ptr + col);
        }
        while (col > 0 && this_class != 0)
        {
            prevcol = col - 1 - utf_head_off(ptr, ptr + col - 1);
            prev_class = mb_get_class(ptr + prevcol);
            if (this_class != prev_class && (i == 0 || prev_class == 0 || (find_type & FIND_IDENT)) && (!(find_type & FIND_EVAL) || prevcol == 0 || !find_is_eval_item(ptr + prevcol, &prevcol, &bn,  (-1) )))
            {
                break;
            }
            col = prevcol;
        }

        if (this_class > 2)
        {
            this_class = 2;
        }
        if (!(find_type & FIND_STRING) || this_class == 2)
        {
            break;
        }
    }

    if (ptr[col] == NUL || (i == 0 && (this_class != 2)))
    {
        if ((find_type & FIND_NOERROR) == 0)
        {
            if (find_type & FIND_STRING)
            {
                emsg(_(e_no_string_under_cursor));
            }
            else
            {
                emsg(_(e_no_identifier_under_cursor));
            }
        }
        return 0;
    }
    ptr += col;
    *text = ptr;
    if (textcol != NULL)
    {
        *textcol = col;
    }

    bn = 0;
    startcol -= col;
    col = 0;
    this_class = mb_get_class(ptr);
    while (ptr[col] != NUL && ((i == 0 ? mb_get_class(ptr + col) == this_class : mb_get_class(ptr + col) != 0) || ((find_type & FIND_EVAL) && col <= (int)startcol && find_is_eval_item(ptr + col, &col, &bn, FORWARD))))
    {
        col += utfc_ptr2len(ptr + col);
    }

    return col;
}

    static void
prep_redo_cmd(cmdarg_T *cap)
{
    prep_redo(cap->oap->regname, cap->count0, NUL, cap->cmdchar, NUL, NUL, cap->nchar);
}

    static void
prep_redo(int     regname, long    num, int     cmd1, int     cmd2, int     cmd3, int     cmd4, int     cmd5)
{
    prep_redo_num2(regname, num, cmd1, cmd2, 0L, cmd3, cmd4, cmd5);
}

    static void
prep_redo_num2(int     regname, long    num1, int     cmd1, int     cmd2, long    num2, int     cmd3, int     cmd4, int     cmd5)
{
    ResetRedobuff();

    if (regname != 0)
    {
        AppendCharToRedobuff('"');
        AppendCharToRedobuff(regname);
    }
    if (num1 != 0)
    {
        AppendNumberToRedobuff(num1);
    }
    if (cmd1 != NUL)
    {
        AppendCharToRedobuff(cmd1);
    }
    if (cmd2 != NUL)
    {
        AppendCharToRedobuff(cmd2);
    }
    if (num2 != 0)
    {
        AppendNumberToRedobuff(num2);
    }
    if (cmd3 != NUL)
    {
        AppendCharToRedobuff(cmd3);
    }
    if (cmd4 != NUL)
    {
        AppendCharToRedobuff(cmd4);
    }
    if (cmd5 != NUL)
    {
        AppendCharToRedobuff(cmd5);
    }
}

