    static void
nv_ident(cmdarg_T *cap)
{
    char_u      *ptr = NULL;
    char_u      *buf;
    size_t      bufsize;
    size_t      buflen;
    char_u      *p;
    int         n = 0;
    int         cmdchar;
    int         g_cmd;
    char_u      *aux_ptr;

    if (cap->cmdchar == 'g')
    {
        cmdchar = cap->nchar;
        g_cmd = TRUE;
    }
    else
    {
        cmdchar = cap->cmdchar;
        g_cmd = FALSE;
    }

    if (cmdchar == POUND)
    {
        cmdchar = '#';
    }

    if (ptr == NULL && (n = find_ident_under_cursor(&ptr, (cmdchar == '*' || cmdchar == '#') ? FIND_IDENT|FIND_STRING : FIND_IDENT)) == 0)
    {
        clearop(cap->oap);
        return;
    }

    bufsize = (size_t)(n * 2 + 30);
    buf = alloc(bufsize);
    if (buf == NULL)
    {
        return;
    }
    buf[0] = NUL;
    buflen = 0;

    setpcmark();
    curwin->w_cursor.col = (colnr_T) (ptr - ml_get_curline());

    if (!g_cmd && vim_iswordp(ptr))
    {
         strcpy((char *)(buf), (char *)("\\<")) ;
        buflen =  (sizeof("\\<" "") - 1) ;
    }
    no_smartcase = TRUE;

    if (cmdchar == '*')
    {
        aux_ptr = (char_u *)(magic_isset() ? "/.*~[^$\\" : "/^$\\");
    }
    else
    {
        aux_ptr = (char_u *)(magic_isset() ? "/?.*~[^$\\" : "/?^$\\");
    }

    p = buf + buflen;
    while (n-- > 0)
    {
        if (vim_strchr(aux_ptr, *ptr) != NULL)
        {
            *p++ = '\\';
        }

        int i;
        int len = utfc_ptr2len(ptr) - 1;

        for (i = 0; i < len && n >= 1; ++i, --n)
        {
            *p++ = *ptr++;
        }
        *p++ = *ptr++;
    }
    *p = NUL;
    buflen = p - buf;

    if (!g_cmd && (vim_iswordp(mb_prevptr(ml_get_curline(), ptr))))
    {
         strcpy((char *)(buf + buflen), (char *)("\\>")) ;
        buflen +=  (sizeof("\\>" "") - 1) ;
    }

    init_history();
    add_to_history(HIST_SEARCH, buf, buflen, TRUE, NUL);

    (void)normal_search(cap, cmdchar == '*' ? '/' : '?', buf, buflen, 0, NULL);

    vim_free(buf);
}

    static int
get_visual_text(cmdarg_T    *cap, char_u      **pp, int         *lenp)
{
    if (VIsual_mode != 'V')
    {
        unadjust_for_sel();
    }
    if (VIsual.lnum != curwin->w_cursor.lnum)
    {
        if (cap != NULL)
        {
            clearopbeep(cap->oap);
        }
        return FAIL;
    }
    if (VIsual_mode == 'V')
    {
        *pp = ml_get_curline();
        *lenp = (int)ml_get_curline_len();
    }
    else
    {
        if ( (((curwin->w_cursor).lnum != (VIsual).lnum)               ? (curwin->w_cursor).lnum < (VIsual).lnum                   : (curwin->w_cursor).col != (VIsual).col                        ? (curwin->w_cursor).col < (VIsual).col                     : (curwin->w_cursor).coladd < (VIsual).coladd) )
        {
            *pp = ml_get_pos(&curwin->w_cursor);
            *lenp = VIsual.col - curwin->w_cursor.col + 1;
        }
        else
        {
            *pp = ml_get_pos(&VIsual);
            *lenp = curwin->w_cursor.col - VIsual.col + 1;
        }
        if (**pp == NUL)
        {
            *lenp = 0;
        }
        if (*lenp > 0)
        {
            *lenp += utfc_ptr2len(*pp + (*lenp - 1)) - 1;
        }
    }
    reset_VIsual_and_resel();
    return OK;
}

