    static void
set_option_default(int         opt_idx, int         opt_flags, int         compatible)
{
    char_u      *varp;
    int         dvi;
    long_u      flags;
    long_u      *flagsp;
    int         both = (opt_flags & (OPT_LOCAL | OPT_GLOBAL)) == 0;

    varp = get_varp_scope(&(options[opt_idx]), both ? OPT_LOCAL : opt_flags);
    flags = options[opt_idx].flags;
    if (varp != NULL)
    {
        dvi = ((flags & P_VI_DEF) || compatible) ? VI_DEFAULT : VIM_DEFAULT;
        if (flags & P_STRING)
        {
            if (options[opt_idx].indir != PV_NONE)
            {
                set_string_option_direct(NULL, opt_idx, options[opt_idx].def_val[dvi], opt_flags, 0);
            }
            else
            {
                if ((opt_flags & OPT_FREE) && (flags & P_ALLOCED))
                {
                    free_string_option(*(char_u **)(varp));
                }
                *(char_u **)varp = options[opt_idx].def_val[dvi];
                options[opt_idx].flags &= ~P_ALLOCED;
            }
        }
        else if (flags & P_NUM)
        {
            if (options[opt_idx].indir ==   (idopt_T)(PV_WIN + (int)(WV_SCROLL))  )
            {
                win_comp_scroll(curwin);
            }
            else
            {
                long def_val = (long)(long_i)options[opt_idx].def_val[dvi];

                if ((long *)varp == &curwin-> w_onebuf_opt.wo_so  || (long *)varp == &curwin-> w_onebuf_opt.wo_siso  || (long *)varp == &curwin-> w_onebuf_opt.wo_sop )
                {
                    *(long *)varp = -1;
                }
                else
                {
                    *(long *)varp = def_val;
                }
                if (both)
                {
                    *(long *)get_varp_scope(&(options[opt_idx]), OPT_GLOBAL) =
                                                                def_val;
                }
            }
        }
        else
        {
            *(int *)varp = (int)(long)(long_i)options[opt_idx].def_val[dvi];
            if (both)
            {
                *(int *)get_varp_scope(&(options[opt_idx]), OPT_GLOBAL) =
                                                                *(int *)varp;
            }
        }

        flagsp =  (&options[opt_idx].flags) ;
        *flagsp = *flagsp & ~P_INSECURE;
        if (both)
        {
            flagsp =  (&options[opt_idx].flags) ;
            *flagsp = *flagsp & ~P_INSECURE;
        }
    }

}

    static void
set_options_default(int         opt_flags)
{
    int         i;
    win_T       *wp;

    for (i = 0; !istermoption_idx(i); i++)
    {
        if (!(options[i].flags & P_NODEFAULT))
        {
            set_option_default(i, opt_flags, p_cp);
        }
    }

     wp = curwin;
win_comp_scroll(wp);
}

    static void
set_string_default_esc(char *name, char_u *val, int escape)
{
    char_u      *p;
    int         opt_idx;

    if (escape && vim_strchr(val, ' ') != NULL)
    {
        p = vim_strsave_escaped(val, (char_u *)" ");
    }
    else
    {
        p = vim_strsave(val);
    }
    if (p == NULL)
    {
        return;
    }

    opt_idx = findoption((char_u *)name);
    if (opt_idx < 0)
    {
        vim_free(p);
        return;
    }

    if (options[opt_idx].flags & P_DEF_ALLOCED)
    {
        vim_free(options[opt_idx].def_val[VI_DEFAULT]);
    }
    options[opt_idx].def_val[VI_DEFAULT] = p;
    options[opt_idx].flags |= P_DEF_ALLOCED;
}

    static void
set_string_default(char *name, char_u *val)
{
    set_string_default_esc(name, val, FALSE);
}

    static char_u *
find_dup_item(char_u *origval, char_u *newval, size_t newvallen, long_u flags)
{
    int     bs = 0;
    char_u  *s;

    if (origval == NULL)
    {
        return NULL;
    }

    for (s = origval; *s != NUL; ++s)
    {
        if ((!(flags & P_COMMA) || s == origval || (s[-1] == ',' && !(bs & 1))) &&  strncmp((char *)(s), (char *)(newval), (newvallen))  == 0 && (!(flags & P_COMMA) || s[newvallen] == ',' || s[newvallen] == NUL))
        {
            return s;
        }
        if ((s > origval + 1 && s[-1] == '\\' && s[-2] != ',') || (s == origval + 1 && s[-1] == '\\'))
        {
            ++bs;
        }
        else
        {
            bs = 0;
        }
    }
    return NULL;
}

    static void
set_number_default(char *name, long val)
{
    int         opt_idx;

    opt_idx = findoption((char_u *)name);
    if (opt_idx >= 0)
    {
        options[opt_idx].def_val[VI_DEFAULT] = (char_u *)(long_i)val;
    }
}

