typedef enum {
    PREFIX_NO = 0,
    PREFIX_NONE,
    PREFIX_INV,
} set_prefix_T;

    static set_prefix_T
get_option_prefix(char_u **argp)
{
    int         prefix = PREFIX_NONE;
    char_u      *arg = *argp;

    if ( strncmp((char *)(arg), (char *)("no"), (2))  == 0 &&  strncmp((char *)(arg), (char *)("novice"), (6))  != 0)
    {
        prefix = PREFIX_NO;
        arg += 2;
    }
    else if ( strncmp((char *)(arg), (char *)("inv"), (3))  == 0)
    {
        prefix = PREFIX_INV;
        arg += 3;
    }

    *argp = arg;
    return prefix;
}

    static int
parse_option_name(char_u *arg, int *opt_idxp, int *lenp, int *keyp)
{
    int key = 0;
    int len;
    int opt_idx;

    if (*arg == '<')
    {
        opt_idx = -1;
        if (arg[1] == 't' && arg[2] == '_' && arg[3] && arg[4])
        {
            len = 5;
        }
        else
        {
            len = 1;
            while (arg[len] != NUL && arg[len] != '>')
            {
                ++len;
            }
        }
        if (arg[len] != '>')
        {
            return FAIL;
        }

        arg[len] = NUL;
        if (arg[1] == 't' && arg[2] == '_')
        {
            opt_idx = findoption(arg + 1);
        }
        arg[len++] = '>';
        if (opt_idx == -1)
        {
            key = find_key_option(arg + 1, TRUE);
        }
    }
    else
    {
        int     nextchar;

        len = 0;
        if (arg[0] == 't' && arg[1] == '_' && arg[2] && arg[3])
        {
            len = 4;
        }
        else
        {
            while ( ( ( ((unsigned)(arg[len]) - 'A' < 26)  ||  ((unsigned)(arg[len]) - 'a' < 26) )  ||  ((unsigned)(arg[len]) - '0' < 10) )  || arg[len] == '_')
            {
                ++len;
            }
        }
        nextchar = arg[len];
        arg[len] = NUL;
        opt_idx = findoption(arg);
        arg[len] = nextchar;
        if (opt_idx == -1)
        {
            key = find_key_option(arg, FALSE);
        }
    }

    *keyp = key;
    *lenp = len;
    *opt_idxp = opt_idx;

    return OK;
}

    static set_op_T
get_opt_op(char_u *arg)
{
    set_op_T op = OP_NONE;

    if (*arg != NUL && *(arg + 1) == '=')
    {
        if (*arg == '+')
        {
            op = OP_ADDING;
        }
        else if (*arg == '^')
        {
            op = OP_PREPENDING;
        }
        else if (*arg == '-')
        {
            op = OP_REMOVING;
        }
    }

    return op;
}

    static int
validate_opt_idx(int opt_idx, int opt_flags, long_u flags, char **errmsg, set_prefix_T prefix)
{
    if ((opt_flags & OPT_WINONLY) && (opt_idx < 0 || options[opt_idx].var !=  ((char_u *)-1) ))
    {
        return FAIL;
    }

    if ((opt_flags & OPT_NOWIN) && opt_idx >= 0 && options[opt_idx].var ==  ((char_u *)-1) )
    {
        return FAIL;
    }

    return OK;
}

    static char_u *
stropt_get_default_val(int         opt_idx, char_u      *varp, int         flags, int         cp_val)
{
    char_u      *newval;

    newval = options[opt_idx].def_val[((flags & P_VI_DEF) || cp_val) ? VI_DEFAULT : VIM_DEFAULT];
    if ((char_u **)varp == &p_bg)
    {
            newval = term_bg_default();
    }

    if (newval == NULL)
    {
        newval = empty_option;
    }
    else
    {
        char_u *s = option_expand(opt_idx, newval);
        if (s == NULL)
        {
            s = newval;
        }
        newval = vim_strsave(s);
    }

    return newval;
}

    static void
opt_backspace_nr2str(char_u      *varp, char_u      **origval_p, char_u      **origval_l_p, char_u      **origval_g_p, char_u      **oldval_p)
{
    int         i = getdigits((char_u **)varp);

    switch (i)
    {
        case 0:
            *(char_u **)varp = empty_option;
            break;
        case 1:
            *(char_u **)varp = vim_strnsave((char_u *)"indent,eol",  (sizeof("indent,eol" "") - 1) );
            break;
        case 2:
            *(char_u **)varp = vim_strnsave((char_u *)"indent,eol,start",  (sizeof("indent,eol,start" "") - 1) );
            break;
        case 3:
            *(char_u **)varp = vim_strnsave((char_u *)"indent,eol,nostop",  (sizeof("indent,eol,nostop" "") - 1) );
            break;
    }
    vim_free(*oldval_p);
    if (*origval_p == *oldval_p)
    {
        *origval_p = *(char_u **)varp;
    }
    if (*origval_l_p == *oldval_p)
    {
        *origval_l_p = *(char_u **)varp;
    }
    if (*origval_g_p == *oldval_p)
    {
        *origval_g_p = *(char_u **)varp;
    }
    *oldval_p = *(char_u **)varp;
}

    static char_u *
opt_whichwrap_nr2str(char_u **argp, char_u *whichwrap)
{
    size_t  len = 0;

    *whichwrap = NUL;
    int i = getdigits(argp);
    if (i & 1)
    {
         strcpy((char *)(whichwrap), (char *)("b,")) ;
        len += 2;
    }
    if (i & 2)
    {
         strcpy((char *)(whichwrap + len), (char *)("s,")) ;
        len += 2;
    }
    if (i & 4)
    {
         strcpy((char *)(whichwrap + len), (char *)("h,l,")) ;
        len += 4;
    }
    if (i & 8)
    {
         strcpy((char *)(whichwrap + len), (char *)("<,>,")) ;
        len += 4;
    }
    if (i & 16)
    {
         strcpy((char *)(whichwrap + len), (char *)("[,],")) ;
        len += 4;
    }
    if (*whichwrap != NUL)
    {
        whichwrap[len - 1] = NUL;
    }

    return whichwrap;
}

    static char_u *
stropt_copy_value(char_u      *origval, char_u      **argp, set_op_T    op, int         flags  __attribute__((unused)) )
{
    char_u      *arg = *argp;
    unsigned    newlen;
    char_u      *newval;
    char_u      *s = NULL;

    newlen = (unsigned) strlen((char *)(arg))  + 1;
    if (op != OP_NONE)
    {
        newlen += (unsigned) strlen((char *)(origval))  + 1;
    }
    newval = alloc(newlen);
    if (newval == NULL)
    {
        return NULL;
    }
    s = newval;

    while (*arg != NUL && ! ((*arg) == ' ' || (*arg) == '\t') )
    {
        int i;

        if (*arg == '\\' && arg[1] != NUL)
        {
            ++arg;
        }
        if ((i = utfc_ptr2len(arg)) > 1)
        {
             memmove((char *)(s), (char *)(arg), (size_t)i) ;
            arg += i;
            s += i;
        }
        else
        {
            *s++ = *arg++;
        }
    }
    *s = NUL;

    *argp = arg;
    return newval;
}

    static char_u *
stropt_expand_envvar(int         opt_idx, char_u      *origval, char_u      *newval, set_op_T    op)
{
    char_u *s = option_expand(opt_idx, newval);
    if (s == NULL)
    {
        return newval;
    }

    vim_free(newval);
    unsigned newlen = (unsigned) strlen((char *)(s))  + 1;
    if (op != OP_NONE)
    {
        newlen += (unsigned) strlen((char *)(origval))  + 1;
    }

    newval = alloc(newlen);
    if (newval == NULL)
    {
        return NULL;
    }

     strcpy((char *)(newval), (char *)(s)) ;

    return newval;
}

    static void
stropt_concat_with_comma(char_u      *origval, char_u      *newval, set_op_T    op, int         flags)
{
    int         len = 0;

    int comma = ((flags & P_COMMA) && *origval != NUL && *newval != NUL);
    if (op == OP_ADDING)
    {
        len = (int) strlen((char *)(origval)) ;
        if (comma && len > 1 && (flags & P_ONECOMMA) == P_ONECOMMA && origval[len - 1] == ',' && origval[len - 2] != '\\')
        {
            len--;
        }
         memmove((char *)(newval + len + comma), (char *)(newval),  strlen((char *)(newval))  + 1) ;
         memmove((char *)(newval), (char *)(origval), (size_t)len) ;
    }
    else
    {
        len = (int) strlen((char *)(newval)) ;
          memmove((char *)((newval + len + comma)), (char *)((origval)),  strlen((char *)(origval))  + 1)  ;
    }
    if (comma)
    {
        newval[len] = ',';
    }
}

    static void
stropt_remove_val(char_u      *origval, char_u      *newval, int         flags, char_u      *strval, int         len)
{
     strcpy((char *)(newval), (char *)(origval)) ;
    if (*strval)
    {
        if (flags & P_COMMA)
        {
            if (strval == origval)
            {
                if (strval[len] == ',')
                {
                    ++len;
                }
            }
            else
            {
                --strval;
                ++len;
            }
        }
          memmove((char *)((newval + (strval - origval))), (char *)((strval + len)),  strlen((char *)(strval + len))  + 1)  ;
    }
}

    static char_u *
find_key_item(char_u *src, char_u *key, int keylen, int *itemlenp)
{
    char_u  *p = src;

    while (*p != NUL)
    {
        if ((p == src || *(p - 1) == ',') &&  strncmp((char *)(p), (char *)(key), (keylen))  == 0)
        {
            char_u *end = vim_strchr(p, ',');
            if (end == NULL)
            {
                end = p +  strlen((char *)(p)) ;
            }
            *itemlenp = (int)(end - p);
            return p;
        }
        ++p;
    }
    return NULL;
}

    static void
remove_comma_item(char_u *str, char_u *item, int itemlen)
{
    if (item[itemlen] == ',')
    {
          memmove((char *)((item)), (char *)((item + itemlen + 1)),  strlen((char *)(item + itemlen + 1))  + 1)  ;
    }
    else if (item > str && *(item - 1) == ',')
    {
          memmove((char *)((item - 1)), (char *)((item + itemlen)),  strlen((char *)(item + itemlen))  + 1)  ;
    }
    else
    {
        *item = NUL;
    }
}

    static void
remove_key_item(char_u *str, char_u *key, int keylen, char_u *skip)
{
    int     itemlen;
    char_u  *found;

    while ((found = find_key_item(str, key, keylen, &itemlen)) != NULL)
    {
        if (found == skip)
        {
            char_u *next = found + itemlen;
            if (*next == ',')
            {
                ++next;
            }
            found = find_key_item(next, key, keylen, &itemlen);
            if (found == NULL)
            {
                break;
            }
        }

        remove_comma_item(str, found, itemlen);
    }
}

    static void
append_item(char_u *str, char_u *item, int item_len)
{
    int len = (int) strlen((char *)(str)) ;

    if (len > 0)
    {
        str[len++] = ',';
    }
     memmove((char *)(str + len), (char *)(item), (size_t)item_len) ;
    str[len + item_len] = NUL;
}

    static void
prepend_item(char_u *str, char_u *item, int item_len)
{
    int len = (int) strlen((char *)(str)) ;
    int comma = (len > 0) ? 1 : 0;

     memmove((char *)(str + item_len + comma), (char *)(str), (size_t)len + 1) ;
     memmove((char *)(str), (char *)(item), (size_t)item_len) ;
    if (comma)
    {
        str[item_len] = ',';
    }
}

    static bool
stropt_handle_keymatch(char_u      *origval, char_u      *newval, set_op_T    op, int         flags  __attribute__((unused)) )
{
    char_u  *p;
    char_u  *item_start;

    if (vim_strchr(newval, ':') == NULL && vim_strchr(newval, ',') == NULL)
    {
        return false;
    }

    char_u *newval_copy = vim_strsave(newval);
    if (newval_copy == NULL)
    {
        return false;
    }

     strcpy((char *)(newval), (char *)(origval)) ;

    item_start = newval_copy;
    for (;;)
    {
        p = vim_strchr(item_start, ',');
        int item_len = (p == NULL)
                            ? (int) strlen((char *)(item_start))  : (int)(p - item_start);

        if (item_len > 0)
        {
            char_u *colon = vim_strchr(item_start, ':');
            if (colon != NULL && colon < item_start + item_len)
            {
                int keylen = (int)(colon - item_start) + 1;

                if (op == OP_ADDING || op == OP_PREPENDING)
                {
                    int old_itemlen;
                    char_u *found = find_key_item(newval, item_start, keylen, &old_itemlen);
                    if (found != NULL)
                    {
                        if (old_itemlen == item_len &&  strncmp((char *)(found), (char *)(item_start), (item_len))  == 0)
                        {
                            remove_key_item(newval, item_start, keylen, found);
                        }
                        else
                        {
                            remove_key_item(newval, item_start, keylen, NULL);
                            if (op == OP_PREPENDING)
                            {
                                prepend_item(newval, item_start, item_len);
                            }
                            else
                            {
                                append_item(newval, item_start, item_len);
                            }
                        }
                    }
                    else
                    {
                        if (op == OP_PREPENDING)
                        {
                            prepend_item(newval, item_start, item_len);
                        }
                        else
                        {
                            append_item(newval, item_start, item_len);
                        }
                    }
                }
                else if (op == OP_REMOVING)
                {
                    remove_key_item(newval, item_start, keylen, NULL);
                }
            }
            else
            {
                if (op == OP_ADDING || op == OP_PREPENDING)
                {
                    char_u *found = find_dup_item(newval, item_start, item_len, P_COMMA);
                    if (found == NULL)
                    {
                        if (op == OP_PREPENDING)
                        {
                            prepend_item(newval, item_start, item_len);
                        }
                        else
                        {
                            append_item(newval, item_start, item_len);
                        }
                    }
                }
                else if (op == OP_REMOVING)
                {
                    char_u *found = find_dup_item(newval, item_start, item_len, P_COMMA);
                    if (found != NULL)
                    {
                        remove_comma_item(newval, found, item_len);
                    }
                }
            }
        }

        if (p == NULL)
        {
            break;
        }
        item_start = p + 1;
    }

    vim_free(newval_copy);

    return true;
}

    static void
stropt_remove_dupflags(char_u *newval, int flags)
{
    char_u      *s = newval;

    while (*s)
    {
        if (flags & P_ONECOMMA)
        {
            if (*s != ',' && *(s + 1) == ',' && vim_strchr(s + 2, *s) != NULL)
            {
                  memmove((char *)((s)), (char *)((s + 2)),  strlen((char *)(s + 2))  + 1)  ;
                continue;
            }
        }
        else
        {
            if ((!(flags & P_COMMA) || *s != ',') && vim_strchr(s + 1, *s) != NULL)
            {
                  memmove((char *)((s)), (char *)((s + 1)),  strlen((char *)(s + 1))  + 1)  ;
                continue;
            }
        }
        ++s;
    }
}

    static char_u *
stropt_get_newval(int         nextchar, int         opt_idx, char_u      **argp, char_u      *varp, char_u      **origval_arg, char_u      **origval_l_arg, char_u      **origval_g_arg, char_u      **oldval_arg, set_op_T    *op_arg, int         flags, int         cp_val)
{
    char_u      *arg = *argp;
    char_u      *origval = *origval_arg;
    char_u      *origval_l = *origval_l_arg;
    char_u      *origval_g = *origval_g_arg;
    char_u      *oldval = *oldval_arg;
    set_op_T    op = *op_arg;
    char_u      *save_arg = NULL;
    char_u      *newval;
    char_u      *s = NULL;
    char_u      whichwrap[80];

    if (nextchar == '&')
    {
        newval = stropt_get_default_val(opt_idx, varp, flags, cp_val);
    }
    else
    {
        ++arg;

        if (varp == (char_u *)&p_bs &&  ((unsigned)(**(char_u **)varp) - '0' < 10) )
        {
            opt_backspace_nr2str(varp, &origval, &origval_l, &origval_g, &oldval);
        }
        else if (varp == (char_u *)&p_ww &&  ((unsigned)(*arg) - '0' < 10) )
        {
            char_u *t = opt_whichwrap_nr2str(&arg, whichwrap);
            save_arg = arg;
            arg = t;
        }
        newval = stropt_copy_value(origval, &arg, op, flags);
        if (newval == NULL)
        {
            goto done;
        }

        if (op == OP_NONE || (flags & P_COMMA))
        {
            newval = stropt_expand_envvar(opt_idx, origval, newval, op);
            if (newval == NULL)
            {
                goto done;
            }
        }

        if ((flags & P_COMMA) && (flags & P_COLON) && op != OP_NONE && stropt_handle_keymatch(origval, newval, op, flags))
        {
            ;
        }
        else
        {
            int len = 0;
            if (op == OP_REMOVING || (flags & P_NODUP))
            {
                len = (int) strlen((char *)(newval)) ;
                s = find_dup_item(origval, newval, len, flags);

                if ((op == OP_ADDING || op == OP_PREPENDING) && s != NULL)
                {
                    op = OP_NONE;
                     strcpy((char *)(newval), (char *)(origval)) ;
                }

                if (s == NULL)
                {
                    s = origval + (int) strlen((char *)(origval)) ;
                }
            }

            if (op == OP_ADDING || op == OP_PREPENDING)
            {
                stropt_concat_with_comma(origval, newval, op, flags);
            }
            else if (op == OP_REMOVING)
            {
                stropt_remove_val(origval, newval, flags, s, len);
            }
        }

        if (flags & P_FLAGLIST)
        {
            stropt_remove_dupflags(newval, flags);
        }
    }

done:
    if (save_arg != NULL)
    {
        arg = save_arg;
    }
    *argp = arg;
    *origval_arg = origval;
    *origval_l_arg = origval_l;
    *origval_g_arg = origval_g;
    *oldval_arg = oldval;
    *op_arg = op;

    return newval;
}

    static int
do_set_option_string(int         opt_idx, int         opt_flags, char_u      **argp, int         nextchar, set_op_T    op_arg, long_u      flags, int         cp_val, char_u      *varp_arg, char        *errbuf, size_t      errbuflen, int         *value_checked, char        **errmsg)
{
    char_u      *arg = *argp;
    set_op_T    op = op_arg;
    char_u      *varp = varp_arg;
    char_u      *oldval = NULL;
    char_u      *newval;
    char_u      *origval = NULL;
    char_u      *origval_l = NULL;
    char_u      *origval_g = NULL;

    if ((opt_flags & (OPT_LOCAL | OPT_GLOBAL)) == 0 && ((int)options[opt_idx].indir & PV_BOTH))
    {
        varp = options[opt_idx].var;
    }

    oldval = *(char_u **)varp;

    if ((opt_flags & (OPT_LOCAL | OPT_GLOBAL)) == 0)
    {
        origval_l = *(char_u **)get_varp_scope(&(options[opt_idx]), OPT_LOCAL);
        origval_g = *(char_u **)get_varp_scope(&(options[opt_idx]), OPT_GLOBAL);

        if (((int)options[opt_idx].indir & PV_BOTH) && origval_l == empty_option)
        {
            origval_l = origval_g;
        }
    }

    if (((int)options[opt_idx].indir & PV_BOTH) && (opt_flags & OPT_LOCAL))
    {
        origval = *(char_u **)get_varp(&options[opt_idx]);
    }
    else
    {
        origval = oldval;
    }

    newval = stropt_get_newval(nextchar, opt_idx, &arg, varp, &origval, &origval_l, &origval_g, &oldval, &op, flags, cp_val);

    *(char_u **)(varp) = newval;
    if (newval == NULL)
    {
        *(char_u **)(varp) = empty_option;
    }

    {
        long_u  *p =  (&options[opt_idx].flags) ;
        int     secure_saved = secure;

        if ((op != OP_NONE && (*p & P_INSECURE)))
        {
            secure = 1;
        }

        *errmsg = did_set_string_option(opt_idx, (char_u **)varp, oldval, newval, errbuf, errbuflen, opt_flags, op, value_checked);

        secure = secure_saved;
    }

    *argp = arg;
    return *errmsg == NULL ? OK : FAIL;
}

    static char *
do_set_option_bool(int         opt_idx, int         opt_flags, set_prefix_T prefix, long_u      flags, char_u      *varp, int         nextchar, int         afterchar, int         cp_val)

{
    varnumber_T value;

    if (nextchar == '=' || nextchar == ':')
    {
        return e_invalid_argument;
    }
    if (opt_idx < 0 || varp == NULL)
    {
        return NULL;
    }

    if (nextchar == '!')
    {
        value = *(int *)(varp) ^ 1;
    }
    else if (nextchar == '&')
    {
        value = (int)(long)(long_i)options[opt_idx].def_val[((flags & P_VI_DEF) || cp_val) ? VI_DEFAULT : VIM_DEFAULT];
    }
    else
    {
        if (nextchar != NUL && ! ((afterchar) == ' ' || (afterchar) == '\t') )
        {
            return e_trailing_characters;
        }
        if (prefix == PREFIX_INV)
        {
            value = *(int *)(varp) ^ 1;
        }
        else
        {
            value = prefix == PREFIX_NO ? 0 : 1;
        }
    }

    return set_bool_option(opt_idx, varp, (int)value, opt_flags);
}

    static char *
do_set_option_numeric(int         opt_idx, int         opt_flags, char_u      **argp, int         nextchar, set_op_T    op, long_u      flags, int         cp_val, char_u      *varp, char        *errbuf, size_t      errbuflen)
{
    char_u              *arg = *argp;
    varnumber_T         value;
    int                 i;
    char                *errmsg = NULL;

    if (opt_idx < 0 || varp == NULL)
    {
        return NULL;
    }
    ++arg;
    if (nextchar == '&')
    {
        value = (long)(long_i)options[opt_idx].def_val[((flags & P_VI_DEF) || cp_val) ? VI_DEFAULT : VIM_DEFAULT];
    }
    else if (*arg == '-' ||  ((unsigned)(*arg) - '0' < 10) )
    {
        vim_str2nr(arg, NULL, &i,  (STR2NR_BIN + STR2NR_OCT + STR2NR_HEX + STR2NR_OOCT) , &value, NULL, 0, TRUE, NULL);
        if (i == 0 || (arg[i] != NUL && ! ((arg[i]) == ' ' || (arg[i]) == '\t') ))
        {
            errmsg = e_number_required_after_equal;
            goto skip;
        }
    }
    else
    {
        errmsg = e_number_required_after_equal;
        goto skip;
    }

    if (op == OP_ADDING)
    {
        value = *(long *)varp + value;
    }
    else if (op == OP_PREPENDING)
    {
        value = *(long *)varp * value;
    }
    else if (op == OP_REMOVING)
    {
        value = *(long *)varp - value;
    }

    if ((long *)varp == &curwin-> w_onebuf_opt.wo_sop  && value < -1)
    {
        errmsg = e_invalid_argument;
        goto skip;
    }

    errmsg = set_num_option(opt_idx, varp, value, errbuf, errbuflen, opt_flags);

skip:
    *argp = arg;
    return errmsg;
}

    static char *
do_set_option_keycode(char_u **argp, char_u *key_name, int nextchar)
{
    char_u      *arg = *argp;
    char_u      *p;

    if (nextchar == '&')
    {
        if (add_termcap_entry(key_name, TRUE) == FAIL)
        {
            return e_not_found_in_termcap;
        }
    }
    else
    {
        ++arg;
        for (p = arg; *p && ! ((*p) == ' ' || (*p) == '\t') ; ++p)
        {
            if (*p == '\\' && p[1] != NUL)
            {
                ++p;
            }
        }
        nextchar = *p;
        *p = NUL;
        add_termcode(key_name, arg, FALSE);
        *p = nextchar;
    }
    if (full_screen)
    {
        ttest(FALSE);
    }
    redraw_all_later(UPD_CLEAR);

    *argp = arg;
    return NULL;
}

    static char *
do_set_option_value(int         opt_idx, int         opt_flags, char_u      **argp, set_prefix_T prefix, set_op_T    op, long_u      flags, char_u      *varp, char_u      *key_name, int         nextchar, int         afterchar, int         cp_val, int         *stopopteval, char        *errbuf, size_t      errbuflen)
{
    int         value_checked = FALSE;
    char        *errmsg = NULL;
    char_u      *arg = *argp;

    if (flags & P_BOOL)
    {
        errmsg = do_set_option_bool(opt_idx, opt_flags, prefix, flags, varp, nextchar, afterchar, cp_val);
        if (errmsg != NULL)
        {
            goto skip;
        }
    }
    else
    {
        if (vim_strchr((char_u *)"=:&<", nextchar) == NULL || prefix != PREFIX_NONE)
        {
            errmsg = e_invalid_argument;
            goto skip;
        }

        if (flags & P_NUM)
        {
            errmsg = do_set_option_numeric(opt_idx, opt_flags, &arg, nextchar, op, flags, cp_val, varp, errbuf, errbuflen);
            if (errmsg != NULL)
            {
                goto skip;
            }
        }
        else if (opt_idx >= 0)
        {
            if (do_set_option_string(opt_idx, opt_flags, &arg, nextchar, op, flags, cp_val, varp, errbuf, errbuflen, &value_checked, &errmsg) == FAIL)
            {
                if (errmsg != NULL)
                {
                    goto skip;
                }
                *stopopteval = TRUE;
                goto skip;
            }
        }
        else
        {
            errmsg = do_set_option_keycode(&arg, key_name, nextchar);
            if (errmsg != NULL)
            {
                goto skip;
            }
        }
    }

    if (opt_idx >= 0)
    {
        did_set_option(opt_idx, opt_flags, op == OP_NONE, value_checked);
    }

skip:
    *argp = arg;
    return errmsg;
}

    static char *
do_set_option(int         opt_flags, char_u      **argp, char_u      *arg_start, char_u      **startarg, int         *did_show, int         *stopopteval, char        *errbuf, size_t      errbuflen)
{
    int         opt_idx;
    char_u      *arg;
    set_prefix_T prefix;
    set_op_T    op;
    long_u      flags;
    char_u      *varp;
    char_u      key_name[2];
    int         nextchar;
    int         afterchar;
    char        *errmsg = NULL;
    int         key;
    int         len;

    prefix = get_option_prefix(argp);
    arg = *argp;

    key = 0;
    if (parse_option_name(arg, &opt_idx, &len, &key) == FAIL)
    {
        return e_invalid_argument;
    }

    afterchar = arg[len];

    while ( ((arg[len]) == ' ' || (arg[len]) == '\t') )
    {
        ++len;
    }

    op = get_opt_op(arg + len);
    if (op != OP_NONE)
    {
        len++;
    }

    nextchar = arg[len];

    if (opt_idx == -1 && key == 0)
    {
        errmsg = e_unknown_option;
        goto skip;
    }

    if (opt_idx >= 0)
    {
        if (options[opt_idx].var == NULL)
        {
            if (vim_strchr((char_u *)"=:!&<", nextchar) == NULL && (!(options[opt_idx].flags & P_BOOL) || nextchar == '?'))
            {
                errmsg = e_option_not_supported;
            }
            goto skip;
        }

        flags = options[opt_idx].flags;
        varp = get_varp_scope(&(options[opt_idx]), opt_flags);
    }
    else
    {
        flags = P_STRING;
        varp = NULL;
        if (key < 0)
        {
            key_name[0] =  ((-(key)) & 0xff) ;
            key_name[1] =  (((unsigned)(-(key)) >> 8) & 0xff) ;
        }
        else
        {
            key_name[0] = KS_KEY;
            key_name[1] = (key & 0xff);
        }
    }

    if (validate_opt_idx(opt_idx, opt_flags, flags, &errmsg, prefix) == FAIL)
    {
        goto skip;
    }

    int cp_val = p_cp;
    if (vim_strchr((char_u *)"?=:!&", nextchar) != NULL)
    {
        arg += len;
        if (nextchar == '&' && arg[1] == 'v' && arg[2] == 'i')
        {
            if (arg[3] == 'm')
            {
                cp_val = FALSE;
                arg += 3;
            }
            else
            {
                cp_val = TRUE;
                arg += 2;
            }
        }
        if (vim_strchr((char_u *)"?!&<", nextchar) != NULL && arg[1] != NUL && ! ((arg[1]) == ' ' || (arg[1]) == '\t') )
        {
            errmsg = e_trailing_characters;
            goto skip;
        }
    }

    if (nextchar == '?' || (prefix == PREFIX_NONE && vim_strchr((char_u *)"=:&<", nextchar) == NULL && !(flags & P_BOOL)))
    {
        if (*did_show)
        {
            msg_putchar('\n');
        }
        else
        {
            gotocmdline(TRUE);
            *did_show = TRUE;
        }
        if (opt_idx >= 0)
        {
            showoneopt(&options[opt_idx], opt_flags);
        }
        else
        {
            char_u          *p;

            p = find_termcode(key_name);
            if (p == NULL)
            {
                errmsg = e_key_code_not_set;
                goto skip;
            }
            else
            {
                (void)show_one_termcode(key_name, p, TRUE);
            }
        }
        if (nextchar != '?' && nextchar != NUL && ! ((afterchar) == ' ' || (afterchar) == '\t') )
        {
            errmsg = e_trailing_characters;
        }
    }
    else
    {
        errmsg = do_set_option_value(opt_idx, opt_flags, &arg, prefix, op, flags, varp, key_name, nextchar, afterchar, cp_val, stopopteval, errbuf, errbuflen);
    }

skip:
    *argp = arg;
    return errmsg;
}

    static int
do_set(char_u      *arg_start, int         opt_flags)
{
    char_u      *arg = arg_start;
    int         i;
    int         did_show = FALSE;

    if (*arg == NUL)
    {
        showoptions(0, opt_flags);
        did_show = TRUE;
        goto theend;
    }

    while (*arg != NUL)
    {
        if ( strncmp((char *)(arg), (char *)("all"), (3))  == 0 && ! ( ((unsigned)(arg[3]) - 'A' < 26)  ||  ((unsigned)(arg[3]) - 'a' < 26) ) )
        {
            arg += 3;
            if (*arg == '&')
            {
                ++arg;
                set_options_default(OPT_FREE | opt_flags);
                didset_options();
                didset_options2();
                redraw_all_later(UPD_CLEAR);
            }
            else
            {
                showoptions(1, opt_flags);
                did_show = TRUE;
            }
        }
        else if ( strncmp((char *)(arg), (char *)("termcap"), (7))  == 0)
        {
            showoptions(2, opt_flags);
            show_termcodes(opt_flags);
            did_show = TRUE;
            arg += 7;
        }
        else
        {
            int         stopopteval = FALSE;
            char        *errmsg = NULL;
            char        errbuf[ERR_BUFLEN];
            char_u      *startarg = arg;

            errmsg = do_set_option(opt_flags, &arg, arg_start, &startarg, &did_show, &stopopteval, errbuf, ERR_BUFLEN);
            if (stopopteval)
            {
                break;
            }

            for (i = 0; i < 2 ; ++i)
            {
                while (*arg != NUL && ! ((*arg) == ' ' || (*arg) == '\t') )
                {
                    if (*arg++ == '\\' && *arg != NUL)
                    {
                        ++arg;
                    }
                }
                arg = skipwhite(arg);
                if (*arg != '=')
                {
                    break;
                }
            }

            if (errmsg != NULL)
            {
                i = vim_snprintf((char *)IObuff,  (1024+1) , "%s", (char_u *)_(errmsg)) + 2;
                if (i + (arg - startarg) <  (1024+1) )
                {
                     strcpy((char *)(IObuff + i - 2), (char *)(": ")) ;
                     memmove((char *)(IObuff + i), (char *)(startarg), (arg - startarg)) ;
                    IObuff[i + (arg - startarg)] = NUL;
                }
                trans_characters(IObuff,  (1024+1) );

                ++no_wait_return;
                emsg((char *)IObuff);
                --no_wait_return;

                return FAIL;
            }
        }

        arg = skipwhite(arg);
    }

theend:
    if (silent_mode && did_show)
    {
        silent_mode = FALSE;
        info_message = TRUE;
        msg_putchar('\n');
        cursor_on();
        out_flush();
        silent_mode = TRUE;
        info_message = FALSE;
    }

    return OK;
}

    static void
did_set_option(int     opt_idx, int     opt_flags, int     new_value, int     value_checked)
{
    long_u      *flagsp;
    long_u      *flagsp_local = NULL;
    int         both = (opt_flags & (OPT_LOCAL | OPT_GLOBAL)) == 0;

    options[opt_idx].flags |= P_WAS_SET;

    flagsp =  (&options[opt_idx].flags) ;
    if (both)
    {
        flagsp_local =  (&options[opt_idx].flags) ;
    }
    if (!value_checked && secure)
    {
        *flagsp = *flagsp | P_INSECURE;
        if (flagsp_local != NULL)
        {
            *flagsp_local = *flagsp_local | P_INSECURE;
        }
    }
    else if (new_value)
    {
        *flagsp = *flagsp & ~P_INSECURE;
        if (flagsp_local != NULL)
        {
            *flagsp_local = *flagsp_local & ~P_INSECURE;
        }
    }
}

    static char_u *
option_expand(int opt_idx, char_u *val)
{
    if (!(options[opt_idx].flags & P_EXPAND) || options[opt_idx].var == NULL)
    {
        return NULL;
    }

    if (val != NULL &&  strlen((char *)(val))  >  PATH_MAX )
    {
        return NULL;
    }

    if (val == NULL)
    {
        val = *(char_u **)options[opt_idx].var;
    }

    int esc = FALSE;

    expand_env_esc(val, NameBuff,  PATH_MAX , esc ? (char_u *)" \t" : NULL, FALSE, NULL);
    if ( strcmp((char *)(NameBuff), (char *)(val))  == 0)
    {
        return NULL;
    }

    return NameBuff;
}

