    static char *
set_bool_option(int         opt_idx, char_u      *varp, int         value, int         opt_flags)
{
    int         old_value = *(int *)varp;
    char        *errmsg = NULL;

    if ((secure) && (options[opt_idx].flags & P_SECURE))
    {
        return e_not_allowed_here;
    }

    *(int *)varp = value;

    if ((opt_flags & (OPT_LOCAL | OPT_GLOBAL)) == 0)
    {
        *(int *)get_varp_scope(&(options[opt_idx]), OPT_GLOBAL) = value;
    }

    if (options[opt_idx].opt_did_set_cb != NULL)
    {
        optset_T args;

          memset((&(args)), (0), (sizeof(args)))  ;
        args.os_varp = varp;
        args.os_flags = opt_flags;
        args.os_oldval.boolean = old_value;
        args.os_newval.boolean = value;
        args.os_errbuf = NULL;
        errmsg = options[opt_idx].opt_did_set_cb(&args);
        if (errmsg != NULL)
        {
            return errmsg;
        }
    }

    options[opt_idx].flags |= P_WAS_SET;

    comp_col();

    if (curwin->w_curswant != MAXCOL && (options[opt_idx].flags & (P_CURSWANT | P_RALL)) != 0 && (options[opt_idx].flags & P_HLONLY) == 0)
    {
        curwin->w_set_curswant = true;
    }

    if ((opt_flags & OPT_NO_REDRAW) == 0)
    {
        check_redraw(options[opt_idx].flags);
    }

    return errmsg;
}

    static char *
check_num_option_bounds(long        *pp, long        old_value, long        old_Rows, long        old_Columns, char        *errbuf, size_t      errbuflen, char        *errmsg)
{
    if (Rows < min_rows_for_all_tabpages() && full_screen)
    {
        if (errbuf != NULL)
        {
            vim_snprintf(errbuf, errbuflen, _(e_need_at_least_nr_lines), min_rows_for_all_tabpages());
            errmsg = errbuf;
        }
        Rows = min_rows_for_all_tabpages();
    }
    if (Columns < MIN_COLUMNS && full_screen)
    {
        if (errbuf != NULL)
        {
            vim_snprintf(errbuf, errbuflen, _(e_need_at_least_nr_columns), MIN_COLUMNS);
            errmsg = errbuf;
        }
        Columns = MIN_COLUMNS;
    }
    limit_screen_size();

    if (old_Rows != Rows || old_Columns != Columns)
    {
        if (updating_screen)
        {
            *pp = old_value;
        }
        else if (full_screen)
        {
            set_shellsize((int)Columns, (int)Rows, TRUE);
        }
        else
        {
            check_shellsize();
            if (cmdline_row > Rows - p_ch && Rows > p_ch)
            {
                cmdline_row = Rows - p_ch;
            }
        }
        if (p_window >= Rows || !option_was_set((char_u *)"window"))
        {
            p_window = Rows - 1;
        }
    }

    if (p_tm < 0)
    {
        errmsg = e_argument_must_be_positive;
        p_tm = 0;
    }
    if ((curwin-> w_onebuf_opt.wo_scr  <= 0 || (curwin-> w_onebuf_opt.wo_scr  > curwin->w_height && curwin->w_height > 0)) && full_screen)
    {
        if (pp == &(curwin-> w_onebuf_opt.wo_scr ))
        {
            if (curwin-> w_onebuf_opt.wo_scr  != 0)
            {
                errmsg = e_invalid_scroll_size;
            }
            win_comp_scroll(curwin);
        }
        else if (curwin-> w_onebuf_opt.wo_scr  <= 0)
        {
            curwin-> w_onebuf_opt.wo_scr  = 1;
        }
        else
        {
            curwin-> w_onebuf_opt.wo_scr  = curwin->w_height;
        }
    }
    if (p_hi < 0)
    {
        errmsg = e_argument_must_be_positive;
        p_hi = 0;
    }
    else if (p_hi > 10000)
    {
        errmsg = e_invalid_argument;
        p_hi = 10000;
    }
    if (p_report < 0)
    {
        errmsg = e_argument_must_be_positive;
        p_report = 1;
    }
    if ((p_sj < -100 || p_sj >= Rows) && full_screen)
    {
        if (Rows != old_Rows)
        {
            p_sj = Rows / 2;
        }
        else
        {
            errmsg = e_invalid_scroll_size;
            p_sj = 1;
        }
    }
    if (p_so < 0 && full_screen)
    {
        errmsg = e_argument_must_be_positive;
        p_so = 0;
    }
    if (p_sop < 0 && full_screen)
    {
        errmsg = e_invalid_argument;
        p_sop = 0;
    }
    if (p_siso < 0 && full_screen)
    {
        errmsg = e_argument_must_be_positive;
        p_siso = 0;
    }
    if (p_ss < 0)
    {
        errmsg = e_argument_must_be_positive;
        p_ss = 0;
    }

    return errmsg;
}

    static char *
set_num_option(int         opt_idx, char_u      *varp, long        value, char        *errbuf, size_t      errbuflen, int         opt_flags)
{
    char        *errmsg = NULL;
    long        old_value = *(long *)varp;
    long        old_Rows = Rows;
    long        old_Columns = Columns;
    long        *pp = (long *)varp;

    if ((secure) && (options[opt_idx].flags & P_SECURE))
    {
        return e_not_allowed_here;
    }

    *pp = value;

    if ((opt_flags & (OPT_LOCAL | OPT_GLOBAL)) == 0)
    {
        *(long *)get_varp_scope(&(options[opt_idx]), OPT_GLOBAL) = value;
    }

    if (options[opt_idx].opt_did_set_cb != NULL)
    {
        optset_T args;

          memset((&(args)), (0), (sizeof(args)))  ;
        args.os_varp = varp;
        args.os_flags = opt_flags;
        args.os_oldval.number = old_value;
        args.os_newval.number = value;
        args.os_errbuf = NULL;
        errmsg = options[opt_idx].opt_did_set_cb(&args);
    }

    errmsg = check_num_option_bounds(pp, old_value, old_Rows, old_Columns, errbuf, errbuflen, errmsg);

    options[opt_idx].flags |= P_WAS_SET;

    comp_col();

    if (curwin->w_curswant != MAXCOL && (options[opt_idx].flags & (P_CURSWANT | P_RALL)) != 0 && (options[opt_idx].flags & P_HLONLY) == 0)
    {
        curwin->w_set_curswant = true;
    }

    if ((opt_flags & OPT_NO_REDRAW) == 0)
    {
        check_redraw(options[opt_idx].flags);
    }

    return errmsg;
}

    static void
check_redraw(long_u flags)
{
    int         doclear = (flags & P_RCLR) == P_RCLR;
    int         all = ((flags & P_RALL) == P_RALL || doclear);

    if ((flags & P_RSTAT) || all)
    {
        status_redraw_all();
    }

    if ((flags & P_RBUF) || (flags & P_RWIN) || all)
    {
        if (flags & P_HLONLY)
        {
            redraw_later(UPD_NOT_VALID);
        }
        else
        {
            changed_window_setting();
        }
    }
    if (flags & P_RBUF)
    {
        redraw_curbuf_later(UPD_NOT_VALID);
    }
    if (doclear)
    {
        redraw_all_later(UPD_CLEAR);
    }
    else if (all)
    {
        redraw_all_later(UPD_NOT_VALID);
    }
}

    static int
findoption(char_u *arg)
{
    int             opt_idx;
    char *s;
    char *p;
    static short    quick_tab[27] = {0, 0};
    int             is_term_opt;

    if (quick_tab[1] == 0)
    {
        int last_opt_idx;
        for (last_opt_idx = 0; options[last_opt_idx].fullname != NULL; last_opt_idx++)
        {
            ;
        }
        for (int tab_idx = 1; tab_idx < 27; tab_idx++)
        {
            quick_tab[tab_idx] = last_opt_idx;
        }

        p = options[0].fullname;
        for (opt_idx = 1; opt_idx < last_opt_idx; opt_idx++)
        {
            s = options[opt_idx].fullname;
            if (s[0] != p[0])
            {
                if (s[0] == 't' && s[1] == '_')
                {
                    quick_tab[26] = opt_idx;
                }
                else
                {
                    quick_tab[ ((s[0]) - 'a') ] = opt_idx;
                }
            }
            p = s;
        }
    }

    if (arg[0] < 'a' || arg[0] > 'z')
    {
        return -1;
    }

    is_term_opt = (arg[0] == 't' && arg[1] == '_');
    if (is_term_opt)
    {
        opt_idx = quick_tab[26];
    }
    else
    {
        opt_idx = quick_tab[ ((arg[0]) - 'a') ];
    }
    for (; (s = options[opt_idx].fullname) != NULL && s[0] == arg[0]; opt_idx++)
    {
        if ( strcmp((char *)(arg), (char *)(s))  == 0)
        {
            break;
        }
    }
    if (s != NULL && s[0] != arg[0])
    {
        s = NULL;
    }
    if (s == NULL && !is_term_opt)
    {
        opt_idx = quick_tab[ ((arg[0]) - 'a') ];
        for ( ; options[opt_idx].fullname != NULL; opt_idx++)
        {
            s = options[opt_idx].shortname;
            if (s != NULL &&  strcmp((char *)(arg), (char *)(s))  == 0)
            {
                break;
            }
            s = NULL;
        }
    }
    if (s == NULL)
    {
        opt_idx = -1;
    }
    return opt_idx;
}

    static long_u
get_option_flags(int opt_idx)
{
    return options[opt_idx].flags;
}

    static void
set_option_flag(int opt_idx, long_u flag)
{
    options[opt_idx].flags |= flag;
}

    static int
is_global_option(int opt_idx)
{
    return options[opt_idx].indir == PV_NONE;
}

    static int
is_global_local_option(int opt_idx)
{
    return options[opt_idx].indir & PV_BOTH;
}

    static int
is_window_local_option(int opt_idx)
{
    return options[opt_idx].var ==  ((char_u *)-1) ;
}

    static int
is_hidden_option(int opt_idx)
{
    return options[opt_idx].var == NULL;
}

    static char *
set_option_value(char_u      *name, long        number, char_u      *string, int         opt_flags)
{
    int         opt_idx;
    char_u      *varp;
    long_u      flags;
    static char errbuf[ERR_BUFLEN];
    int         errbuflen = ERR_BUFLEN;

    opt_idx = findoption(name);
    if (opt_idx < 0)
    {
        int key;

        if ( strlen((char *)(name))  == 4 && name[0] == 't' && name[1] == '_' && (key = find_key_option(name, FALSE)) != 0)
        {
            char_u key_name[2];

            if (key < 0)
            {
                key_name[0] =  ((-(key)) & 0xff) ;
                key_name[1] =  (((unsigned)(-(key)) >> 8) & 0xff) ;
            }
            else
            {
                key_name[0] = KS_KEY;
                key_name[1] = (key & 0xff);
            }
            add_termcode(key_name, string, FALSE);
            if (full_screen)
            {
                ttest(FALSE);
            }
            redraw_all_later(UPD_CLEAR);
            return NULL;
        }

        semsg(_(e_unknown_option_str_2), name);
    }
    else
    {
        flags = options[opt_idx].flags;
        if (flags & P_STRING)
        {
            return set_string_option(opt_idx, string, opt_flags, errbuf, errbuflen);
        }

        varp = get_varp_scope(&(options[opt_idx]), opt_flags);
        if (varp != NULL)
        {
            if (number == 0 && string != NULL)
            {
                int idx;

                for (idx = 0; string[idx] == '0'; ++idx)
                {
                    ;
                }
                if (string[idx] != NUL || idx == 0)
                {
                    semsg(_(e_number_required_after_str_equal_str), name, string);
                    return NULL;

                }
            }
            if (flags & P_NUM)
            {
                return set_num_option(opt_idx, varp, number, errbuf, sizeof(errbuf), opt_flags);
            }
            else
            {
                return set_bool_option(opt_idx, varp, (int)number, opt_flags);
            }
        }

    }
    return NULL;
}

    static void
set_option_value_give_err(char_u      *name, long        number, char_u      *string, int         opt_flags)
{
    char *errmsg = set_option_value(name, number, string, opt_flags);

    if (errmsg != NULL)
    {
        emsg(_(errmsg));
    }
}

    static char_u *
get_term_code(char_u *tname)
{
    int     opt_idx;
    char_u  *varp;

    if (tname[0] != 't' || tname[1] != '_' || tname[2] == NUL || tname[3] == NUL)
    {
        return NULL;
    }
    if ((opt_idx = findoption(tname)) >= 0)
    {
        varp = get_varp(&(options[opt_idx]));
        if (varp != NULL)
        {
            varp = *(char_u **)(varp);
        }
        return varp;
    }
    return find_termcode(tname + 2);
}

    static char_u *
get_highlight_default(void)
{
    int i;

    i = findoption((char_u *)"hl");
    if (i >= 0)
    {
        return options[i].def_val[VI_DEFAULT];
    }
    return (char_u *)NULL;
}

    static int
find_key_option(char_u *arg_arg, int has_lt)
{
    int         key = 0;
    int         modifiers;
    char_u      *arg = arg_arg;

    if (arg[0] == 't' && arg[1] == '_' && arg[2] && arg[3])
    {
        if (!has_lt || arg[4] == '>')
        {
            key =  (-((arg[2]) + ((int)(arg[3]) << 8))) ;
        }
    }
    else if (has_lt)
    {
        --arg;
        modifiers = 0;
        key = find_special_key(&arg, &modifiers, FSK_KEYCODE | FSK_KEEP_X_KEY | FSK_SIMPLIFY, NULL);
        if (modifiers)
        {
            key = 0;
        }
    }
    return key;
}

    static void
showoptions(int         all, int         opt_flags)
{
    struct vimoption    *p;
    int                 col;
    int                 isterm;
    char_u              *varp;
    struct vimoption    **items;
    int                 item_count;
    int                 run;
    int row;
    int rows;
    int                 cols;
    int                 i;
    int                 len;

    items =  (struct vimoption * *)alloc(sizeof(struct vimoption *) * (  (sizeof(options) / sizeof((options)[0]))  )) ;
    if (items == NULL)
    {
        return;
    }

    if (all == 2)
    {
        msg_puts_title(_("\n--- Terminal codes ---"));
    }
    else if (opt_flags & OPT_GLOBAL)
    {
        msg_puts_title(_("\n--- Global option values ---"));
    }
    else if (opt_flags & OPT_LOCAL)
    {
        msg_puts_title(_("\n--- Local option values ---"));
    }
    else
    {
        msg_puts_title(_("\n--- Options ---"));
    }

    for (run = 1; run <= 2 && !got_int; ++run)
    {
        item_count = 0;
        for (p = &options[0]; p->fullname != NULL; p++)
        {
            if (message_filtered((char_u *)p->fullname))
            {
                continue;
            }

            varp = NULL;
            isterm = istermoption(p);
            if ((opt_flags & (OPT_LOCAL | OPT_GLOBAL)) != 0)
            {
                if (p->indir != PV_NONE && !isterm)
                {
                    varp = get_varp_scope(p, opt_flags);
                }
            }
            else
            {
                varp = get_varp(p);
            }
            if (varp != NULL && ((all == 2 && isterm) || (all == 1 && !isterm) || (all == 0 && !optval_default(p, varp, p_cp))))
            {
                if (opt_flags & OPT_ONECOLUMN)
                {
                    len = Columns;
                }
                else if (p->flags & P_BOOL)
                {
                    len = 1;
                }
                else
                {
                    option_value2string(p, opt_flags);
                    len = (int) strlen((char *)(p->fullname))  + vim_strsize(NameBuff) + 1;
                }
                if ((len <= INC - GAP && run == 1) || (len > INC - GAP && run == 2))
                {
                    items[item_count++] = p;
                }
            }
        }

        if (run == 1)
        {
            cols = (Columns + GAP - 3) / INC;
            if (cols == 0)
            {
                cols = 1;
            }
            rows = (item_count + cols - 1) / cols;
        }
        else
        {
            rows = item_count;
        }
        for (row = 0; row < rows && !got_int; ++row)
        {
            msg_putchar('\n');
            if (got_int)
            {
                break;
            }
            col = 0;
            for (i = row; i < item_count; i += rows)
            {
                msg_col = col;
                showoneopt(items[i], opt_flags);
                col += INC;
            }
            out_flush();
            ui_breakcheck();
        }
    }
    vim_free(items);
}

    static int
optval_default(struct vimoption *p, char_u *varp, int compatible)
{
    int         dvi;

    if (varp == NULL)
    {
        return TRUE;
    }
    dvi = ((p->flags & P_VI_DEF) || compatible) ? VI_DEFAULT : VIM_DEFAULT;
    if (p->flags & P_NUM)
    {
        return (*(long *)varp == (long)(long_i)p->def_val[dvi]);
    }
    if (p->flags & P_BOOL)
    {
        return (*(int *)varp == (int)(long)(long_i)p->def_val[dvi]);
    }
    return ( strcmp((char *)(*(char_u **)varp), (char *)(p->def_val[dvi]))  == 0);
}

    static void
showoneopt(struct vimoption    *p, int                 opt_flags)
{
    char_u      *varp;
    int         save_silent = silent_mode;

    silent_mode = FALSE;
    info_message = TRUE;

    varp = get_varp_scope(p, opt_flags);

    if ((p->flags & P_BOOL) && ((int *)varp == &curbuf->b_changed ? !curbufIsChanged() : !*(int *)varp))
    {
        msg_puts("no");
    }
    else if ((p->flags & P_BOOL) && *(int *)varp < 0)
    {
        msg_puts("--");
    }
    else
    {
        msg_puts("  ");
    }
    msg_puts(p->fullname);
    if (!(p->flags & P_BOOL))
    {
        msg_putchar('=');
        option_value2string(p, opt_flags);
        msg_outtrans(NameBuff);
    }

    silent_mode = save_silent;
    info_message = FALSE;
}

    static void
clear_termoptions(void)
{
    stoptermcap();

    free_termoptions();
}

    static void
free_termoptions(void)
{
    struct vimoption   *p;

    for (p = options; p->fullname != NULL; p++)
    {
        if (istermoption(p))
        {
            if (p->flags & P_ALLOCED)
            {
                free_string_option(*(char_u **)(p->var));
            }
            if (p->flags & P_DEF_ALLOCED)
            {
                free_string_option(p->def_val[VI_DEFAULT]);
            }
            *(char_u **)(p->var) = empty_option;
            p->def_val[VI_DEFAULT] = empty_option;
            p->flags &= ~(P_ALLOCED|P_DEF_ALLOCED);
        }
    }
    clear_termcodes();
}

    static void
free_one_termoption(char_u *var)
{
    struct vimoption   *p;

    for (p = &options[0]; p->fullname != NULL; p++)
    {
        if (p->var == var)
        {
            if (p->flags & P_ALLOCED)
            {
                free_string_option(*(char_u **)(p->var));
            }
            *(char_u **)(p->var) = empty_option;
            p->flags &= ~P_ALLOCED;
            break;
        }
    }
}

    static void
set_term_defaults(void)
{
    struct vimoption   *p;

    for (p = &options[0]; p->fullname != NULL; p++)
    {
        if (istermoption(p) && p->def_val[VI_DEFAULT] != *(char_u **)(p->var))
        {
            if (p->flags & P_DEF_ALLOCED)
            {
                free_string_option(p->def_val[VI_DEFAULT]);
                p->flags &= ~P_DEF_ALLOCED;
            }
            p->def_val[VI_DEFAULT] = *(char_u **)(p->var);
            if (p->flags & P_ALLOCED)
            {
                p->flags |= P_DEF_ALLOCED;
                p->flags &= ~P_ALLOCED;
            }
        }
    }
}

    static int
istermoption(struct vimoption *p)
{
    return (p->fullname[0] == 't' && p->fullname[1] == '_');
}

    static int
istermoption_idx(int opt_idx)
{
    return istermoption(&options[opt_idx]);
}

    static char_u *
get_varp_scope(struct vimoption *p, int scope)
{
    if ((scope & OPT_GLOBAL) && p->indir != PV_NONE)
    {
        if (p->var ==  ((char_u *)-1) )
        {
            return (char_u *) ((char *)(get_varp(p)) + sizeof(winopt_T)) ;
        }
        return p->var;
    }
    if ((scope & OPT_LOCAL) && ((int)p->indir & PV_BOTH))
    {
        switch ((int)p->indir)
        {
            case   (idopt_T)(PV_BOTH + (int)( (idopt_T)(PV_BUF + (int)(BV_FS)) ))  :
                return (char_u *)&(curbuf->b_p_fs);
            case   (idopt_T)(PV_BOTH + (int)( (idopt_T)(PV_WIN + (int)(WV_SISO)) ))  :
                return (char_u *)&(curwin-> w_onebuf_opt.wo_siso );
            case   (idopt_T)(PV_BOTH + (int)( (idopt_T)(PV_WIN + (int)(WV_SO)) ))  :
                return (char_u *)&(curwin-> w_onebuf_opt.wo_so );
            case   (idopt_T)(PV_BOTH + (int)( (idopt_T)(PV_WIN + (int)(WV_SOP)) ))  :
                return (char_u *)&(curwin-> w_onebuf_opt.wo_sop );
            case   (idopt_T)(PV_BOTH + (int)( (idopt_T)(PV_BUF + (int)(BV_UL)) ))  :
                return (char_u *)&(curbuf->b_p_ul);
            case   (idopt_T)(PV_BOTH + (int)( (idopt_T)(PV_WIN + (int)(WV_LCS)) ))  :
                return (char_u *)&(curwin-> w_onebuf_opt.wo_lcs );
            case   (idopt_T)(PV_BOTH + (int)( (idopt_T)(PV_WIN + (int)(WV_FCS)) ))  :
                return (char_u *)&(curwin-> w_onebuf_opt.wo_fcs );
            case   (idopt_T)(PV_BOTH + (int)( (idopt_T)(PV_WIN + (int)(WV_VE)) ))  :
                return (char_u *)&(curwin-> w_onebuf_opt.wo_ve );

        }
        return NULL;
    }
    return get_varp(p);
}

    static char_u *
get_option_varp_scope(int opt_idx, int scope)
{
    return get_varp_scope(&(options[opt_idx]), scope);
}

    static char_u *
get_varp(struct vimoption *p)
{
    if (p->var == NULL)
    {
        return NULL;
    }

    switch ((int)p->indir)
    {
        case PV_NONE:
            return p->var;

        case   (idopt_T)(PV_BOTH + (int)( (idopt_T)(PV_WIN + (int)(WV_SISO)) ))  :
            return curwin-> w_onebuf_opt.wo_siso  >= 0
                                    ? (char_u *)&(curwin-> w_onebuf_opt.wo_siso ) : p->var;
        case   (idopt_T)(PV_BOTH + (int)( (idopt_T)(PV_WIN + (int)(WV_SO)) ))  :
            return curwin-> w_onebuf_opt.wo_so  >= 0
                                    ? (char_u *)&(curwin-> w_onebuf_opt.wo_so ) : p->var;
        case   (idopt_T)(PV_BOTH + (int)( (idopt_T)(PV_WIN + (int)(WV_SOP)) ))  :
            return curwin-> w_onebuf_opt.wo_sop  != -1
                                    ? (char_u *)&(curwin-> w_onebuf_opt.wo_sop ) : p->var;
        case   (idopt_T)(PV_BOTH + (int)( (idopt_T)(PV_BUF + (int)(BV_FS)) ))  :
            return curbuf->b_p_fs >= 0
                                    ? (char_u *)&(curbuf->b_p_fs) : p->var;
        case   (idopt_T)(PV_BOTH + (int)( (idopt_T)(PV_BUF + (int)(BV_UL)) ))  :
            return curbuf->b_p_ul !=  (-123456) 
                                    ? (char_u *)&(curbuf->b_p_ul) : p->var;
        case   (idopt_T)(PV_WIN + (int)(WV_LIST))  :
            return (char_u *)&(curwin-> w_onebuf_opt.wo_list );
        case   (idopt_T)(PV_BOTH + (int)( (idopt_T)(PV_WIN + (int)(WV_LCS)) ))  :
            return *curwin-> w_onebuf_opt.wo_lcs  != NUL
                                    ? (char_u *)&(curwin-> w_onebuf_opt.wo_lcs ) : p->var;
        case   (idopt_T)(PV_BOTH + (int)( (idopt_T)(PV_WIN + (int)(WV_FCS)) ))  :
            return *curwin-> w_onebuf_opt.wo_fcs  != NUL
                                    ? (char_u *)&(curwin-> w_onebuf_opt.wo_fcs ) : p->var;
        case   (idopt_T)(PV_BOTH + (int)( (idopt_T)(PV_WIN + (int)(WV_VE)) ))  :
            return *curwin-> w_onebuf_opt.wo_ve  != NUL
                                    ? (char_u *)&(curwin-> w_onebuf_opt.wo_ve ) : p->var;
        case   (idopt_T)(PV_WIN + (int)(WV_NU))  :
            return (char_u *)&(curwin-> w_onebuf_opt.wo_nu );
        case   (idopt_T)(PV_WIN + (int)(WV_RNU))  :
            return (char_u *)&(curwin-> w_onebuf_opt.wo_rnu );
        case   (idopt_T)(PV_WIN + (int)(WV_SCROLL))  :
            return (char_u *)&(curwin-> w_onebuf_opt.wo_scr );
        case   (idopt_T)(PV_WIN + (int)(WV_SMS))  :
            return (char_u *)&(curwin-> w_onebuf_opt.wo_sms );
        case   (idopt_T)(PV_WIN + (int)(WV_WRAP))  :
            return (char_u *)&(curwin-> w_onebuf_opt.wo_wrap );
        case   (idopt_T)(PV_WIN + (int)(WV_WCR))  :
            return (char_u *)&(curwin-> w_onebuf_opt.wo_wcr );
        case   (idopt_T)(PV_WIN + (int)(WV_WHL))  :
            return (char_u *)&(curwin-> w_onebuf_opt.wo_whl );

        case   (idopt_T)(PV_BUF + (int)(BV_AI))  :
            return (char_u *)&(curbuf->b_p_ai);
        case   (idopt_T)(PV_BUF + (int)(BV_CI))  :
            return (char_u *)&(curbuf->b_p_ci);
        case   (idopt_T)(PV_BUF + (int)(BV_ET))  :
            return (char_u *)&(curbuf->b_p_et);
        case   (idopt_T)(PV_BUF + (int)(BV_ISK))  :
            return (char_u *)&(curbuf->b_p_isk);
        case   (idopt_T)(PV_BUF + (int)(BV_MPS))  :
            return (char_u *)&(curbuf->b_p_mps);
        case   (idopt_T)(PV_BUF + (int)(BV_MA))  :
            return (char_u *)&(curbuf->b_p_ma);
        case   (idopt_T)(PV_BUF + (int)(BV_MOD))  :
            return (char_u *)&(curbuf->b_changed);
        case   (idopt_T)(PV_BUF + (int)(BV_NF))  :
            return (char_u *)&(curbuf->b_p_nf);
        case   (idopt_T)(PV_BUF + (int)(BV_PI))  :
            return (char_u *)&(curbuf->b_p_pi);
        case   (idopt_T)(PV_BUF + (int)(BV_QE))  :
            return (char_u *)&(curbuf->b_p_qe);
        case   (idopt_T)(PV_BUF + (int)(BV_RO))  :
            return (char_u *)&(curbuf->b_p_ro);
        case   (idopt_T)(PV_BUF + (int)(BV_SI))  :
            return (char_u *)&(curbuf->b_p_si);
        case   (idopt_T)(PV_BUF + (int)(BV_STS))  :
            return (char_u *)&(curbuf->b_p_sts);
        case   (idopt_T)(PV_BUF + (int)(BV_SW))  :
            return (char_u *)&(curbuf->b_p_sw);
        case   (idopt_T)(PV_BUF + (int)(BV_TS))  :
            return (char_u *)&(curbuf->b_p_ts);
        case   (idopt_T)(PV_BUF + (int)(BV_TW))  :
            return (char_u *)&(curbuf->b_p_tw);
        case   (idopt_T)(PV_BUF + (int)(BV_WM))  :
            return (char_u *)&(curbuf->b_p_wm);
        default:
            iemsg(e_get_varp_error);
    }
    return (char_u *)&(curbuf->b_p_wm);
}

