    static char *
did_set_matchpairs(optset_T *args)
{
    char_u      **varp = (char_u **)args->os_varp;
    char_u      *p;

    for (p = *varp; *p != NUL; ++p)
    {
        int x2 = -1;
        int x3 = -1;

        p += utfc_ptr2len(p);
        if (*p != NUL)
        {
            x2 = *p++;
        }
        if (*p != NUL)
        {
            x3 = utf_ptr2char(p);
            p += utfc_ptr2len(p);
        }
        if (x2 != ':' || x3 == -1 || (*p != NUL && *p != ','))
        {
            return e_invalid_argument;
        }
        if (*p == NUL)
        {
            break;
        }
    }

    return NULL;
}

