    static char *
did_set_string_option(int         opt_idx, char_u      **varp, char_u      *oldval, char_u      *value, char        *errbuf, size_t      errbuflen, int         opt_flags, set_op_T    op, int         *value_checked)
{
    char        *errmsg = NULL;
    long_u      free_oldval = (get_option_flags(opt_idx) & P_ALLOCED);
    opt_did_set_cb_T did_set_cb = get_option_did_set_cb(opt_idx);
    optset_T    args;

    if (varp == & ( term_strings[(int)(KS_NAME)] ) )
    {
        opt_idx = findoption((char_u *)"term");
        if (opt_idx >= 0)
        {
            free_oldval = (get_option_flags(opt_idx) & P_ALLOCED);
            did_set_cb = get_option_did_set_cb(opt_idx);
        }
    }

      memset((&(args)), (0), (sizeof(args)))  ;

    if ((secure) && (get_option_flags(opt_idx) & P_SECURE))
    {
        errmsg = e_not_allowed_here;
    }
    else if (check_illegal_path_names(opt_idx, varp))
    {
        errmsg = e_invalid_argument;
    }
    else if (did_set_cb != NULL)
    {
        args.os_varp = (char_u *)varp;
        args.os_idx = opt_idx;
        args.os_flags = opt_flags;
        args.os_op = op;
        args.os_oldval.string = oldval;
        args.os_newval.string = value;
        args.os_errbuf = errbuf;
        args.os_errbuflen = errbuflen;
        errmsg = did_set_cb(&args);

        *value_checked = args.os_value_checked;
    }

    if (errmsg != NULL)
    {
        free_string_option(*varp);
        *varp = oldval;
        if (args.os_restore_chartab)
        {
            (void)init_chartab();
        }
        if (varp == &p_hl)
        {
            (void)highlight_changed();
        }
    }
    else
    {
        if (free_oldval)
        {
            free_string_option(oldval);
        }
        set_option_flag(opt_idx, P_ALLOCED);

        if ((opt_flags & (OPT_LOCAL | OPT_GLOBAL)) == 0 && is_global_local_option(opt_idx))
        {
            char_u *p = get_option_varp_scope(opt_idx, OPT_LOCAL);
            free_string_option(*(char_u **)p);
            *(char_u **)p = empty_option;
        }

        else if (!(opt_flags & OPT_LOCAL) && opt_flags != OPT_GLOBAL)
        {
            set_string_option_global(opt_idx, varp);
        }

    }

    if (curwin->w_curswant != MAXCOL && (get_option_flags(opt_idx) & (P_CURSWANT | P_RALL)) != 0 && (get_option_flags(opt_idx) & P_HLONLY) == 0)
    {
        curwin->w_set_curswant = true;
    }

    if ((opt_flags & OPT_NO_REDRAW) == 0)
    {
            check_redraw(get_option_flags(opt_idx));
    }

    return errmsg;
}

    static int
check_opt_strings(char_u      *val, char        **values, int         list)
{
    return opt_strings_flags(val, values, NULL, list);
}

    static int
opt_strings_flags(char_u      *val, char        **values, unsigned    *flagp, int         list)
{
    int         i;
    int         len;
    unsigned    new_flags = 0;

    while (*val)
    {
        for (i = 0; ; ++i)
        {
            if (values[i] == NULL)
            {
                return FAIL;
            }

            len = (int) strlen((char *)(values[i])) ;
            if ( strncmp((char *)(values[i]), (char *)(val), (len))  == 0 && ((list && val[len] == ',') || val[len] == NUL))
            {
                val += len + (val[len] == ',');
                new_flags |= (1 << i);
                break;
            }
        }
    }
    if (flagp != NULL)
    {
        *flagp = new_flags;
    }

    return OK;
}

