static struct signalinfo
{
    int     sig;
    char    *name;
    char    deadly;
} signal_info[] =
{
    {SIGHUP,        "HUP",      TRUE},
    {SIGTERM,       "TERM",     TRUE},
    {SIGINT,        "INT",      FALSE},
    {SIGWINCH,      "WINCH",    FALSE},
    {SIGTSTP,       "TSTP",     FALSE},
    {-1,            "Unknown!", FALSE}
};

    static sighandler_T
mch_signal(int sig, sighandler_T func)
{
    struct sigaction sa;
    struct sigaction old;
    sigset_t            curset;
    int                 blocked;

    if (sigprocmask(SIG_BLOCK, NULL, &curset) == -1)
    {
        return SIG_ERR;
    }

    blocked = sigismember(&curset, sig);

    if (func == SIG_HOLD)
    {
        if (blocked)
        {
            return SIG_HOLD;
        }

        sigemptyset(&curset);
        sigaddset(&curset, sig);

        if (sigaction(sig, NULL, &old) == -1 || sigprocmask(SIG_BLOCK, &curset, NULL) == -1)
        {
            return SIG_ERR;
        }
        return old.sa_handler;
    }

    if (blocked)
    {
        sigemptyset(&curset);
        sigaddset(&curset, sig);

        if (sigprocmask(SIG_UNBLOCK, &curset, NULL) == -1)
        {
            return SIG_ERR;
        }
    }

    sa.sa_handler = func;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(sig, &sa, &old) == -1)
    {
        return SIG_ERR;
    }
    return blocked ? SIG_HOLD: old.sa_handler;
}

