    static void
mch_delay(long msec, int flags)
{
    tmode_T     old_tmode;
    int         call_settmode;

    if (flags & MCH_DELAY_IGNOREINPUT)
    {
        call_settmode = mch_cur_tmode == TMODE_RAW
                               && (msec > 500 || (flags & MCH_DELAY_SETTMODE));
        if (call_settmode)
        {
            old_tmode = mch_cur_tmode;
            settmode(TMODE_SLEEP);
        }

        {
            struct timespec ts;

            ts.tv_sec = msec / 1000;
            ts.tv_nsec = (msec % 1000) * 1000000;
            (void)nanosleep(&ts, NULL);
        }

        if (call_settmode)
        {
            settmode(old_tmode);
        }
    }
    else
    {
        WaitForChar(msec, NULL, FALSE);
    }
}

    static void
sig_winch  (int sigarg  __attribute__((unused)) ) 
{
    mch_signal(SIGWINCH, sig_winch);
    do_resize = TRUE;
}

    static void
sig_tstp  (int sigarg  __attribute__((unused)) ) 
{
    if (in_mch_suspend)
    {
        mch_signal(SIGTSTP, ignore_sigtstp ? SIG_IGN : SIG_DFL);
        raise(sigarg);
    }
    else
    {
        got_tstp = TRUE;
    }

    mch_signal(SIGTSTP, sig_tstp);
}

    static void
catch_sigint  (int sigarg  __attribute__((unused)) ) 
{
    mch_signal(SIGINT, catch_sigint);
    got_int = TRUE;
}

    static void
deathtrap  (int sigarg  __attribute__((unused)) ) 
{
    static int  entered = 0;
    int         i;

    if (entered == 0 && (sigarg == SIGHUP || sigarg == SIGTERM) && !vim_handle_signal(sigarg))
    {
        return;
    }

    ++entered;

    block_autocmds();

    v_dying = entered;

    for (i = 0; signal_info[i].sig != -1; i++)
    {
        if (sigarg == signal_info[i].sig)
        {
            break;
        }
    }

    full_screen = FALSE;
    if (entered >= 3)
    {
        reset_signals();
        if (entered >= 4)
        {
            _exit(8);
        }
        exit(7);
    }
    if (entered == 2)
    {
         out_str((char_u *)("Vim: Double signal, exiting\n")) ;
        out_flush();
        getout(1);
    }

    sprintf((char *)IObuff, "Vim: Caught deadly signal %s\r\n", signal_info[i].name);

    preserve_exit();

}

    static void
after_sigcont(void)
{

    settmode(TMODE_RAW);
}

static void sigcont_handler  (int) ;

static volatile sig_atomic_t sigcont_received;
static void sigcont_handler  (int) ;

    static void
sigcont_handler  (int sigarg  __attribute__((unused)) ) 
{
    if (in_mch_suspend)
    {
        sigcont_received = TRUE;
    }
    else
    {
        after_sigcont();
        redraw_later(UPD_CLEAR);
        cursor_on_force();
        out_flush();
    }
}

    static void
mch_suspend(void)
{
    if (ignore_sigtstp)
    {
        return;
    }

    in_mch_suspend = TRUE;

    out_flush();
    settmode(TMODE_COOK);
    out_flush();

    sigcont_received = FALSE;

    kill(0, SIGTSTP);

    {
        long wait_time;

        for (wait_time = 0; !sigcont_received && wait_time <= 3L; wait_time++)
        {
            mch_delay(wait_time, 0);
        }
    }
    in_mch_suspend = FALSE;

    after_sigcont();
}

    static void
mch_init(void)
{
    Columns = 80;
    Rows = 24;

    out_flush();

    ignore_sigtstp = SIG_IGN == mch_signal(SIGTSTP, SIG_ERR);
    set_signals();

}

    static void
set_sigwinch_handler(void)
{
    mch_signal(SIGWINCH, sig_winch);
}

    static void
set_signals(void)
{
    mch_signal(SIGWINCH, sig_winch);

    mch_signal(SIGTSTP, ignore_sigtstp ? SIG_IGN : sig_tstp);
    mch_signal(SIGCONT, sigcont_handler);
    mch_signal(SIGPIPE, SIG_IGN);

    catch_int_signal();

    mch_signal(SIGALRM, SIG_IGN);

    catch_signals(deathtrap, SIG_ERR);

}

    static void
catch_int_signal(void)
{
    mch_signal(SIGINT, catch_sigint);
}

    static void
reset_signals(void)
{
    catch_signals(SIG_DFL, SIG_DFL);
    mch_signal(SIGCONT, SIG_DFL);
}

    static void
catch_signals(void (*func_deadly)(int), void (*func_other)(int))
{
    int     i;

    for (i = 0; signal_info[i].sig != -1; i++)
    {
        if (signal_info[i].deadly)
        {
            struct sigaction sa;

            sa.sa_handler = func_deadly;
            sigemptyset(&sa.sa_mask);
            sa.sa_flags = 0;
            sigaction(signal_info[i].sig, &sa, NULL);
        }
        else if (func_other != SIG_ERR)
        {
            mch_signal(signal_info[i].sig, signal_info[i].sig == SIGTSTP && ignore_sigtstp ? SIG_IGN : func_other);
        }
    }
}

    static int
vim_handle_signal(int sig)
{
    static int got_signal = 0;
    static int blocked = TRUE;

    switch (sig)
    {
        case  (-1) :
            blocked = TRUE;
                             break;

        case  (-2) :
            blocked = FALSE;
                             if (got_signal != 0)
                             {
                                 kill(getpid(), got_signal);
                                 got_signal = 0;
                             }
                             break;

        default:
            if (!blocked)
            {
                                 return TRUE;
            }
                             got_signal = sig;
                             got_int = TRUE;
                             break;
    }
    return FALSE;
}

