    static int
re_multi_type(int c)
{
    if (c ==  ((int)('@') - 256)  || c ==  ((int)('=') - 256)  || c ==  ((int)('?') - 256) )
    {
        return MULTI_ONE;
    }
    if (c ==  ((int)('*') - 256)  || c ==  ((int)('+') - 256)  || c ==  ((int)('{') - 256) )
    {
        return MULTI_MULT;
    }
    return NOT_MULTI;
}

