    static void
check_shellsize(void)
{
    if (Rows < min_rows_for_all_tabpages())
    {
        Rows = min_rows_for_all_tabpages();
    }
    limit_screen_size();

    if (cmdline_row >= Rows)
    {
        cmdline_row = Rows - 1;
    }
    if (msg_row >= Rows)
    {
        msg_row = Rows - 1;
    }
}

    static void
limit_screen_size(void)
{
    if (Columns < MIN_COLUMNS)
    {
        Columns = MIN_COLUMNS;
    }
    else if (Columns > 10000)
    {
        Columns = 10000;
    }
    if (Rows > 1000)
    {
        Rows = 1000;
    }
}

    static void
win_new_shellsize(void)
{
    static int  old_Rows = 0;
    static int  old_Columns = 0;
    static int  old_coloff = 0;

    if (old_Rows != Rows || old_Columns !=  Columns  || old_coloff !=  0 )
    {
        ui_new_shellsize();
    }
    if (old_Columns !=  Columns  || old_coloff !=  0 )
    {
        old_Columns =  Columns ;
        old_coloff =  0 ;

        shell_new_columns();
    }
    if (old_Rows != Rows)
    {
        if (p_window == old_Rows - 1 || (old_Rows == 0 && !option_was_set((char_u *)"window")))
        {
            p_window = Rows - 1;
        }
        old_Rows = Rows;
        shell_new_rows();
    }
}

    static void
shell_resized(void)
{
    set_shellsize(0, 0, FALSE);
}

    static void
set_shellsize_inner(int width, int height, int mustset)
{
    if (updating_screen)
    {
        return;
    }

    if (curwin->w_buffer == NULL || curwin->w_lines == NULL)
    {
        return;
    }

    if (mustset || (ui_get_shellsize() == FAIL && height != 0))
    {
        Rows = height;
        Columns = width;
        check_shellsize();
        ui_set_shellsize(mustset);
    }
    else
    {
        check_shellsize();
    }

    if (State != MODE_ASKMORE && State != MODE_EXTERNCMD && State != MODE_CONFIRM)
    {
        screenclear();
    }
    else
    {
        screen_start();
    }

    if (starting != NO_SCREEN)
    {

        changed_line_abv_curs();
        invalidate_botline();

        if (State == MODE_ASKMORE || State == MODE_EXTERNCMD || State == MODE_CONFIRM || exmode_active)
        {
            screenalloc(FALSE);
            repeat_message();
        }
        else
        {
            if (State & MODE_CMDLINE)
            {
                update_screen(UPD_NOT_VALID);
                redrawcmdline();
            }
            else
            {
                update_topline();
                update_screen(UPD_NOT_VALID);
                if (redrawing())
                {
                    setcursor();
                }
            }
        }
        cursor_on();
    }
    out_flush();
}

    static void
set_shellsize(int width, int height, int mustset)
{
    static int  busy = FALSE;
    static int  do_run = FALSE;

    if (width < 0 || height < 0)
    {
        return;
    }

    if (State ==  (0x2000 | MODE_NORMAL)  || State == MODE_SETWSIZE)
    {
        State = MODE_SETWSIZE;
        return;
    }

    do_run = TRUE;
    if (busy)
    {
        return;
    }

    while (do_run)
    {
        do_run = FALSE;
        busy = TRUE;
        set_shellsize_inner(width, height, mustset);
        busy = FALSE;
    }
}

