static struct termcode
{
    char_u  name[2];
    char_u  *code;
    int     len;
    int     modlen;
} *termcodes = NULL;

static int  tc_max_len = 0;
static int  tc_len = 0;

static int termcode_star(char_u *code, int len);

    static void
clear_termcodes(void)
{
    while (tc_len > 0)
    {
        vim_free(termcodes[--tc_len].code);
    }
     vim_free(termcodes);
     (termcodes) = NULL;
    tc_max_len = 0;

    need_gather = TRUE;
}

enum { ATC_FROM_TERM = 55 };

    static void
adjust_modlen(int idx)
{
    termcodes[idx].modlen = 0;
    int j = termcode_star(termcodes[idx].code, termcodes[idx].len);
    if (j <= 0)
    {
        return;
    }

    termcodes[idx].modlen = termcodes[idx].len - 1 - j;
    if (termcodes[idx].code[termcodes[idx].modlen - 1] == '@')
    {
        --termcodes[idx].modlen;
    }
}

    static void
add_termcode(char_u *name, char_u *string, int flags)
{
    struct termcode *new_tc;
    int i;
    int j;
    char_u          *s;
    int             len;

    if (string == NULL || *string == NUL)
    {
        del_termcode(name);
        return;
    }

        s = vim_strsave(string);
    if (s == NULL)
    {
        return;
    }

    if (flags != 0 && flags != ATC_FROM_TERM && term_7to8bit(string) != 0)
    {
          memmove((char *)((s)), (char *)((s + 1)),  strlen((char *)(s + 1))  + 1)  ;
        s[0] = term_7to8bit(string);
    }

    len = (int) strlen((char *)(s)) ;

    need_gather = TRUE;

    if (tc_len == tc_max_len)
    {
        tc_max_len += 20;
        new_tc =  (struct termcode *)alloc(sizeof(struct termcode) * (tc_max_len)) ;
        if (new_tc == NULL)
        {
            tc_max_len -= 20;
            vim_free(s);
            return;
        }
        for (i = 0; i < tc_len; ++i)
        {
            new_tc[i] = termcodes[i];
        }
        vim_free(termcodes);
        termcodes = new_tc;
    }

    for (i = 0; i < tc_len; ++i)
    {
        if (termcodes[i].name[0] < name[0])
        {
            continue;
        }
        if (termcodes[i].name[0] == name[0])
        {
            if (termcodes[i].name[1] < name[1])
            {
                continue;
            }
            if (termcodes[i].name[1] == name[1])
            {
                if (flags == ATC_FROM_TERM && (j = termcode_star(termcodes[i].code, termcodes[i].len)) > 0)
                {
                    if (len == termcodes[i].len - j &&  strncmp((char *)(s), (char *)(termcodes[i].code), (len - 1))  == 0 && s[len - 1] == termcodes[i].code[termcodes[i].len - 1])
                    {
                        vim_free(s);
                        return;
                    }
                }
                else
                {
                    vim_free(termcodes[i].code);
                    --tc_len;
                    break;
                }
            }
        }
        for (j = tc_len; j > i; --j)
        {
            termcodes[j] = termcodes[j - 1];
        }
        break;
    }

    termcodes[i].name[0] = name[0];
    termcodes[i].name[1] = name[1];
    termcodes[i].code = s;
    termcodes[i].len = len;
    adjust_modlen(i);

    ++tc_len;
}

    static void
accept_modifiers_for_function_keys(void)
{
    regmatch_T regmatch;
      memset((&(regmatch)), (0), (sizeof(regmatch)))  ;
    regmatch.rm_ic = TRUE;
    regmatch.regprog = vim_regcomp((char_u *)"^\033[\\d\\+\\~$", RE_MAGIC);

    for (int i = 0; i < tc_len; ++i)
    {
        if (regmatch.regprog == NULL)
        {
            return;
        }

        if (termcodes[i].name[0] == 'P' && (termcodes[i].name[1] == 'S' || termcodes[i].name[1] == 'E'))
        {
            continue;
        }

        char_u *s = termcodes[i].code;
        if (s != NULL && vim_regexec(&regmatch, s, (colnr_T)0))
        {
            size_t len =  strlen((char *)(s)) ;
            char_u *ns = alloc(len + 3);
            if (ns != NULL)
            {
                 memmove((char *)(ns), (char *)(s), len - 1) ;
                 memmove((char *)(ns + len - 1), (char *)(";*~"), 4) ;
                vim_free(s);
                termcodes[i].code = ns;
                termcodes[i].len += 2;
                adjust_modlen(i);
            }
        }
    }

    vim_regfree(regmatch.regprog);
}

    static int
termcode_star(char_u *code, int len)
{
    if (len >= 3 && code[len - 2] == '*')
    {
        if (len >= 5 && code[len - 3] == ';')
        {
            return 2;
        }
        else
        {
            return 1;
        }
    }
    return 0;
}

    static char_u  *
find_termcode(char_u *name)
{
    int     i;

    for (i = 0; i < tc_len; ++i)
    {
        if (termcodes[i].name[0] == name[0] && termcodes[i].name[1] == name[1])
        {
            return termcodes[i].code;
        }
    }
    return NULL;
}

    static void
del_termcode(char_u *name)
{
    int     i;

    if (termcodes == NULL)
    {
        return;
    }

    need_gather = TRUE;

    for (i = 0; i < tc_len; ++i)
    {
        if (termcodes[i].name[0] == name[0] && termcodes[i].name[1] == name[1])
        {
            del_termcode_idx(i);
            return;
        }
    }
}

    static void
del_termcode_idx(int idx)
{
    int         i;

    vim_free(termcodes[idx].code);
    --tc_len;
    for (i = idx; i < tc_len; ++i)
    {
        termcodes[i] = termcodes[i + 1];
    }
}

    static void
switch_to_8bit(void)
{
    int         i;
    int         c;

    if (!term_is_8bit( ( term_strings[(int)(KS_NAME)] ) ))
    {
        for (i = 0; i < tc_len; ++i)
        {
            c = term_7to8bit(termcodes[i].code);
            if (c != 0)
            {
                  memmove((char *)((termcodes[i].code + 1)), (char *)((termcodes[i].code + 2)),  strlen((char *)(termcodes[i].code + 2))  + 1)  ;
                termcodes[i].code[0] = c;
            }
        }
        need_gather = TRUE;
    }
    detected_8bit = TRUE;
}

    static int
put_string_in_typebuf(int     offset, int     slen, char_u  *string, int     new_slen, char_u  *buf, int     bufsize, int     *buflen)
{
    int         extra = new_slen - slen;

    string[new_slen] = NUL;
    if (buf == NULL)
    {
        if (extra < 0)
        {
            del_typebuf(-extra, offset);
        }
        else if (extra > 0)
        {
            if (ins_typebuf(string + slen, REMAP_YES, offset, FALSE, FALSE) == FAIL)
            {
                return FAIL;
            }
        }

         memmove((char *)(typebuf.tb_buf + typebuf.tb_off + offset), (char *)(string), (size_t)new_slen) ;
    }
    else
    {
        if (extra < 0)
        {
             memmove((char *)(buf + offset), (char *)(buf + offset - extra), (size_t)(*buflen + offset + extra)) ;
        }
        else if (extra > 0)
        {
            if (*buflen + extra + new_slen >= bufsize)
            {
                return FAIL;
            }
             memmove((char *)(buf + offset + extra), (char *)(buf + offset), (size_t)(*buflen - offset)) ;
        }
         memmove((char *)(buf + offset), (char *)(string), (size_t)new_slen) ;
        *buflen = *buflen + extra + new_slen;
    }
    return OK;
}

    static int
decode_modifiers(int n)
{
    int     code = n - 1;
    int     modifiers = 0;

    if (code & 1)
    {
        modifiers |= MOD_MASK_SHIFT;
    }
    if (code & 2)
    {
        modifiers |= MOD_MASK_ALT;
    }
    if (code & 4)
    {
        modifiers |= MOD_MASK_CTRL;
    }
    if (code & 8)
    {
        modifiers |= MOD_MASK_META;
    }

    return modifiers;
}

    static int
modifiers2keycode(int modifiers, int *key, char_u *string)
{
    int new_slen = 0;

    if (modifiers == 0)
    {
        return 0;
    }

    *key = simplify_key(*key, &modifiers);
    if (modifiers != 0)
    {
        string[new_slen++] =  (0x80) ;
        string[new_slen++] = (int)KS_MODIFIER;
        string[new_slen++] = modifiers;
    }
    return new_slen;
}

    static void
handle_u7_response(int *arg, char_u *tp  __attribute__((unused)) , int csi_len  __attribute__((unused)) )
{
    if (arg[0] == 2 && arg[1] >= 2)
    {
        char *aw = NULL;

        u7_status.tr_progress = STATUS_GOT;
        did_cursorhold = TRUE;
        if (arg[1] == 2)
        {
            aw = "single";
        }
        else if (arg[1] == 3)
        {
            aw = "double";
        }
        if (aw != NULL &&  strcmp((char *)(aw), (char *)(p_ambw))  != 0)
        {
            set_option_value_give_err((char_u *)"ambw", 0L, (char_u *)aw, 0);
            redraw_asap(UPD_CLEAR);
        }
    }
    else if (arg[0] == 3)
    {
        int value;

        xcc_status.tr_progress = STATUS_GOT;

        value = arg[1] == 1 ? TPR_YES : TPR_NO;
        term_props[TPR_CURSOR_STYLE].tpr_status = value;
        term_props[TPR_CURSOR_BLINK].tpr_status = value;
    }
}

    static void
handle_version_response(int first, int *arg, int argc, char_u *tp)
{
    int version = arg[1];

    crv_status.tr_progress = STATUS_GOT;
    did_cursorhold = TRUE;

    init_term_props(FALSE);

    if (tp[0] == CSI)
    {
        switch_to_8bit();
    }

    if (version > 20000)
    {
        version = 0;
    }

    if (first == '>' && argc == 3)
    {
        if (arg[0] == 77)
        {
            term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
        }

        if ((version == 100 || version == 115) && arg[0] == 0 && arg[2] == 0)
        {
                may_adjust_color_count(256);
            term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
        }

        if (version == 95)
        {
            if (arg[0] == 1 && arg[2] == 0)
            {
                term_props[TPR_UNDERLINE_RGB].tpr_status = TPR_YES;
                term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
                term_props[TPR_DECRQM].tpr_status = TPR_NO;
            }
            else if (arg[0] == 0 && arg[2] == 0)
            {
                term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
                term_props[TPR_DECRQM].tpr_status = TPR_YES;
            }
            else if (arg[0] == 0 && arg[2] == -1)
            {
                term_props[TPR_UNDERLINE_RGB].tpr_status = TPR_YES;
            }
        }

        if (arg[0] == 83)
        {
            if (arg[1] >= 40700)
            {
                term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
            }
            else
            {
                term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_XTERM;
            }
        }

        if (term_props[TPR_MOUSE].tpr_status == TPR_UNKNOWN)
        {
            if (version >= 277)
            {
                term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
            }
            else if (version >= 95)
            {
                term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_XTERM2;
            }
        }

        if (arg[1] >= 2500)
        {
            term_props[TPR_UNDERLINE_RGB].tpr_status = TPR_YES;
        }

        else if (version == 136 && arg[2] == 0)
        {
            term_props[TPR_UNDERLINE_RGB].tpr_status = TPR_YES;

            if (arg[0] == 0)
            {
                term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
            }
        }

        if (arg[0] == 1 && arg[1] >= 4000 && arg[1] <= 4009)
        {
            term_props[TPR_KITTY].tpr_status = TPR_YES;
            term_props[TPR_KITTY].tpr_set_by_termresponse = TRUE;

            term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
            term_props[TPR_DECRQM].tpr_status = TPR_YES;
        }

        if (arg[0] == 1 && version == 12700 && arg[2] == 0)
        {
            term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
            term_props[TPR_DECRQM].tpr_status = TPR_YES;
        }

        if (arg[0] == 83 && arg[1] >= 30600)
        {
            term_props[TPR_CURSOR_STYLE].tpr_status = TPR_NO;
            term_props[TPR_CURSOR_BLINK].tpr_status = TPR_NO;
            term_props[TPR_DECRQM].tpr_status = TPR_NO;
        }

        if (version < 95)
        {
            term_props[TPR_UNDERLINE_RGB].tpr_status = TPR_YES;
        }

        if (version < 279)
        {
            term_props[TPR_CURSOR_STYLE].tpr_status = TPR_NO;
        }

        if (term_props[TPR_UNDERLINE_RGB].tpr_status != TPR_YES && * ( term_strings[(int)(KS_8U)] )  != NUL && !option_was_set((char_u *)"t_8u"))
        {
            set_string_option_direct((char_u *)"t_8u", -1, (char_u *)"", OPT_FREE, 0);
        }

    }
}

    static int
add_key_to_buf(int key, char_u *buf)
{
    int idx = 0;

    if ( ((key) < 0) )
    {
        buf[idx++] =  (0x80) ;
        buf[idx++] =  ((-(key)) & 0xff) ;
        buf[idx++] =  (((unsigned)(-(key)) >> 8) & 0xff) ;
    }
    else
    {
        idx += utf_char2bytes(key, buf + idx);
    }
    return idx;
}

    static int
put_key_modifiers_in_typebuf(int     key_arg, int     modifiers_arg, int     csi_len, int     offset, char_u  *buf, int     bufsize, int     *buflen)
{
    int key = key_arg;
    int modifiers = modifiers_arg;

    key = may_adjust_key_for_ctrl(modifiers, key);

    modifiers = may_remove_shift_modifier(modifiers, key);

    char_u string[MAX_KEY_CODE_LEN + 2];
    int new_slen = modifiers2keycode(modifiers, &key, string);

    if (key > 0x10FFFF)
    {
        return -1;
    }

    new_slen += add_key_to_buf(key, string + new_slen);

    string[new_slen] = NUL;
    if (put_string_in_typebuf(offset, csi_len, string, new_slen, buf, bufsize, buflen) == FAIL)
    {
        return -1;
    }
    return new_slen - csi_len + offset;
}

    static int
parse_csi_f_keys(int arg)
{
    char_u key_name[2] = { 0, 0 };

    switch (arg)
    {
        case 11:
            key_name[0] = 'k';
            key_name[1] = '1';
            break;
        case 12:
            key_name[0] = 'k';
            key_name[1] = '2';
            break;
        case 13:
            key_name[0] = 'k';
            key_name[1] = '3';
            break;
        case 14:
            key_name[0] = 'k';
            key_name[1] = '4';
            break;
        case 15:
            key_name[0] = 'k';
            key_name[1] = '5';
            break;
        case 17:
            key_name[0] = 'k';
            key_name[1] = '6';
            break;
        case 18:
            key_name[0] = 'k';
            key_name[1] = '7';
            break;
        case 19:
            key_name[0] = 'k';
            key_name[1] = '8';
            break;
        case 20:
            key_name[0] = 'k';
            key_name[1] = '9';
            break;
        case 21:
            key_name[0] = 'F';
            key_name[1] = ';';
            break;
        case 23:
            key_name[0] = 'F';
            key_name[1] = '1';
            break;
        case 24:
            key_name[0] = 'F';
            key_name[1] = '2';
            break;
    }
    if (key_name[0])
    {
        return  (-((key_name[0]) + ((int)(key_name[1]) << 8))) ;
    }
    return arg;
}

    static int
handle_key_with_modifier(int     *arg, int     csi_len, int     offset, char_u  *buf, int     bufsize, int     *buflen, int     iskitty, int     trail)
{
    if (!iskitty && (kitty_protocol_state == KKPS_INITIAL || kitty_protocol_state == KKPS_OFF || kitty_protocol_state == KKPS_AFTER_T_TE) && term_props[TPR_KITTY].tpr_status != TPR_YES)
    {
        seenModifyOtherKeys = TRUE;
    }

    int key = iskitty ? arg[0] : arg[2];
    int modifiers = decode_modifiers(arg[1]);

    if ((modifiers & MOD_MASK_SHIFT) && key >= 'a' && key <= 'z')
    {
        key += 'A' - 'a';
    }

    if (key == ESC)
    {
        key =   (-((KS_EXTRA) + ((int)(KE_ESC) << 8)))  ;
    }

    else if (arg[0] >= 11 && arg[0] <= 24 && trail == '~')
    {
        key = parse_csi_f_keys(arg[0]);
    }

    return put_key_modifiers_in_typebuf(key, modifiers, csi_len, offset, buf, bufsize, buflen);
}

    static int
handle_key_without_modifier(int     *arg, int     csi_len, int     offset, char_u  *buf, int     bufsize, int     *buflen, int     trail)
{
    char_u  string[MAX_KEY_CODE_LEN + 1];
    int     new_slen;

    if (arg[0] == ESC)
    {
        string[0] =  (0x80) ;
        string[1] = KS_EXTRA;
        string[2] = KE_ESC;
        new_slen = 3;
    }
    else if (arg[0] >= 11 && arg[0] <= 24 && trail == '~')
    {
        int key = parse_csi_f_keys(arg[0]);
        string[0] =  (0x80) ;
        string[1] =  ((-(key)) & 0xff) ;
        string[2] =  (((unsigned)(-(key)) >> 8) & 0xff) ;
        new_slen = 3;
    }
    else
    {
        new_slen = add_key_to_buf(arg[0], string);
    }

    if (put_string_in_typebuf(offset, csi_len, string, new_slen, buf, bufsize, buflen) == FAIL)
    {
        return -1;
    }
    return new_slen - csi_len + offset;
}

    static int
handle_csi_function_key(int     argc, int     *arg, int     trail, int     csi_len, char_u  *key_name, int     offset, char_u  *buf, int     bufsize, int     *buflen)
{
    key_name[0] = 'k';
    switch (trail)
    {
        case 'A':
            key_name[1] = 'u';
            break;
        case 'B':
            key_name[1] = 'd';
            break;
        case 'C':
            key_name[1] = 'r';
            break;
        case 'D':
            key_name[1] = 'l';
            break;

        case 'F':
            key_name[0] = '@';
            key_name[1] = '7';
            break;
        case 'H':
            key_name[1] = 'h';
            break;

        case 'P':
            key_name[1] = '1';
            break;
        case 'Q':
            key_name[1] = '2';
            break;
        case 'R':
            key_name[1] = '3';
            break;
        case 'S':
            key_name[1] = '4';
            break;

        default:
            return 0;
    }

    int key =  (-((key_name[0]) + ((int)(key_name[1]) << 8))) ;
    int modifiers = argc == 2 ? decode_modifiers(arg[1]) : 0;
    put_key_modifiers_in_typebuf(key, modifiers, csi_len, offset, buf, bufsize, buflen);
    return csi_len;
}

    static int
handle_csi(char_u  *tp, int     len, char_u  *argp, int     offset, char_u  *buf, int     bufsize, int     *buflen, char_u  *key_name, int     *slen)
{
    int         first = -1;
    int         trail;
    int         arg[3] = {-1, -1, -1};
    int         argc = 0;
    char_u      *ap = argp;
    int         csi_len;

    if (! ((unsigned)(*ap) - '0' < 10) )
    {
        first = *ap++;
    }

    if (first >= 'A' && first <= 'Z')
    {
        trail = first;
        first = -1;
        --ap;
    }
    else
    {
        for (argc = 0; argc < 3; )
        {
            if (ap >= tp + len)
            {
                return -1;
            }
            if (*ap == ';')
            {
                arg[argc++] = -1;
            }
            else if ( ((unsigned)(*ap) - '0' < 10) )
            {
                arg[argc] = 0;
                for (;;)
                {
                    if (ap >= tp + len)
                    {
                        return -1;
                    }
                    if (! ((unsigned)(*ap) - '0' < 10) )
                    {
                        break;
                    }
                    if (arg[argc] <= (INT_MAX - 9) / 10)
                    {
                        arg[argc] = arg[argc] * 10 + (*ap - '0');
                    }
                    ++ap;
                }
                ++argc;
            }
            if (*ap == ';')
            {
                ++ap;
            }
            else
            {
                break;
            }
        }

        while (ap < tp + len && !(*ap >= '{' && *ap <= '~') && ! ( ((unsigned)(*ap) - 'A' < 26)  ||  ((unsigned)(*ap) - 'a' < 26) ) )
        {
            ++ap;
        }
        if (ap >= tp + len)
        {
            return -1;
        }
        trail = *ap;
    }

    csi_len = (int)(ap - tp) + 1;

    if (first == '>' && (argc == 1 || argc == 2) && trail == 'm')
    {
        if (arg[0] == 4 && argc == 2)
        {
            modify_otherkeys_state = arg[1] == 2 ? MOKS_ENABLED : MOKS_OFF;
        }

        key_name[0] = (int)KS_EXTRA;
        key_name[1] = (int)KE_IGNORE;
        *slen = csi_len;
    }

    else if (first == -1 &&  ((unsigned)(trail) - 'A' < 26)  && (argc == 0 || (argc == 2 && arg[0] == 1)))
    {
        int res = handle_csi_function_key(argc, arg, trail, csi_len, key_name, offset, buf, bufsize, buflen);
        return res <= 0 ? res : len + res;
    }

    else if (first == -1 && argc == 2 && trail == 'R')
    {
        handle_u7_response(arg, tp, csi_len);

        key_name[0] = (int)KS_EXTRA;
        key_name[1] = (int)KE_IGNORE;
        *slen = csi_len;
    }

    else if (first == '?' && trail == 'c')
    {
        *slen = csi_len;

        key_name[0] = (int)KS_EXTRA;
        key_name[1] = (int)KE_IGNORE;
    }

    else if (first == '?' && trail == 'y' && argc == 2 && (arg[0] == 2026 || arg[0] == 2048))
    {
        int setting = arg[1];

        *slen = csi_len;
        key_name[0] = (int)KS_EXTRA;
        key_name[1] = (int)KE_IGNORE;

        if (setting >= 0 && setting <= 4)
        {
            switch (arg[0])
            {
                case 2026:
                    sync_output_setting = setting;
                    set_option_value_give_err((char_u *)"termsync", setting == 1 || setting == 2, NULL, 0);
                    break;
                case 2048:
                    win_resize_setting = setting;

                    term_set_win_resize(true);
                    break;
            }
        }
        else
        {
        }
    }

    else if (win_resize_enabled && argc >= 3 && arg[0] == 48)
    {
        int height = arg[1];
        int width = arg[2];

        *slen = csi_len;
        key_name[0] = (int)KS_EXTRA;
        key_name[1] = (int)KE_IGNORE;

        if (height != Rows || width != Columns)
        {
            set_shellsize(width, height, true);
        }
    }

    else if (* ( term_strings[(int)(KS_CRV)] )  != NUL && ap > argp + 1 && trail == 'c')
    {
        handle_version_response(first, arg, argc, tp);

        *slen = csi_len;
        key_name[0] = (int)KS_EXTRA;
        key_name[1] = (int)KE_IGNORE;
    }

    else if (first == '?' && argc == 1 && trail == 'u')
    {
        if (arg[0] == '0')
        {
            kitty_protocol_state = KKPS_OFF;
        }
        else
        {
            kitty_protocol_state = KKPS_ENABLED;

            seenModifyOtherKeys = FALSE;
        }

        key_name[0] = (int)KS_EXTRA;
        key_name[1] = (int)KE_IGNORE;
        *slen = csi_len;
    }

    else if ((arg[0] == 27 && argc == 3 && trail == '~') || (argc == 2 && (trail == 'u' || trail == '~')))
    {
        int iskitty = argc == 2 && (trail == 'u' || trail == '~');
        return len + handle_key_with_modifier(arg, csi_len, offset, buf, bufsize, buflen, iskitty, trail);
    }

    else if (argc == 1 && (trail == 'u' || trail == '~'))
    {
        return len + handle_key_without_modifier(arg, csi_len, offset, buf, bufsize, buflen, trail);
    }

    return 0;
}

static void
check_for_color_response(char_u *resp, int len)
{
    int i;
    int j;
    char_u      *argp;

    j = 1 + (resp[0] == ESC);
    argp = resp + j;

    if (len >= j + 3 && (argp[0] != '1' || (argp[1] != '1' && argp[1] != '0') || argp[2] != ';'))
    {
        i = 0;
    }
    else
    {
        for (i = j; i < len; ++i)
        {
            if (resp[i] == '\007' || (resp[0] == OSC ? resp[i] == STERM : (resp[i] == ESC && i + 1 < len && resp[i + 1] == '\\')))
            {
                int is_bg = argp[1] == '1';
                int is_4digit = i - j >= 21 && resp[j + 11] == '/'
                                                  && resp[j + 16] == '/';

                if (i - j >= 15 &&  strncmp((char *)(resp + j + 3), (char *)("rgb:"), (4))  == 0 && (is_4digit || (resp[j + 9] == '/' && resp[j + 12] == '/')))
                {
                    char_u *tp_r = resp + j + 7;
                    char_u *tp_g = resp + j + (is_4digit ? 12 : 10);
                    char_u *tp_b = resp + j + (is_4digit ? 17 : 13);
                    if (is_bg)
                    {
                        char *new_bg_val = (3 * '6' < *tp_r + *tp_g + *tp_b) ? "light" : "dark";

                        if (!option_was_set((char_u *)"bg") &&  strcmp((char *)(p_bg), (char *)(new_bg_val))  != 0)
                        {
                            set_option_value_give_err((char_u *)"bg", 0L, (char_u *)new_bg_val, 0);
                            reset_option_was_set((char_u *)"bg");
                            redraw_asap(UPD_CLEAR);
                        }
                    }
                }

                break;
            }
        }
    }
    if (i == len)
    {
    }
}

static oscstate_T osc_state;

    static bool
in_osc_sequence(void)
{
    return osc_state.processing;
}

    static int
handle_osc(char_u *tp, int len, char_u *key_name, int *slen)
{
    char_u last_char;

    if (!osc_state.processing)
    {
        int cur;

        cur = 1 + (tp[0] == ESC);

        if (len < cur + 1 + (tp[0] != OSC))
        {
            return FAIL;
        }

        ga_init2(&osc_state.buf, 1, 1024);
         gettimeofday(&(osc_state.start_tv), NULL) ;
        osc_state.processing = TRUE;
        osc_state.start_char = tp[0];
        last_char = 0;
    }
    else
    {
        last_char = ((char_u *)osc_state.buf.ga_data)[osc_state.buf.ga_len - 1];
    }

    key_name[0] = (int)KS_EXTRA;

    for (int i = 0; i < len; i++)
    {
        if (tp[i] == '\007' || (osc_state.start_char == OSC ? tp[i] == STERM : ((tp[i] == ESC && i + 1 < len && tp[i + 1] == '\\') || (i == 0 && tp[i] == '\\' && last_char == ESC))))
        {
            osc_state.processing = FALSE;

            key_name[1] = (int)KE_OSC;

            ga_concat_len(&osc_state.buf, tp, i + 1 + (tp[i] == ESC));
            ga_append(&osc_state.buf, NUL);
            *slen = i + 1 + (tp[i] == ESC);
            check_for_color_response(osc_state.buf.ga_data, osc_state.buf.ga_len - 1);

            char_u savebg = *p_bg;
            if (*p_bg != savebg)
            {
                redraw_asap(UPD_CLEAR);
            }
            return OK;
        }
    }

    key_name[1] = (int)KE_IGNORE;

    if ( elapsed(&(osc_state.start_tv))  >= p_ost)
    {
        semsg(_(e_osc_response_timed_out), osc_state.buf.ga_len, osc_state.buf.ga_data);

        ga_clear(&osc_state.buf);
        osc_state.processing = FALSE;
        return FAIL;
    }

    ga_concat(&osc_state.buf, tp);
    *slen = len;

    return OK;
}

    static int
handle_dcs(char_u *tp, char_u *argp, int len, char_u *key_name, int *slen)
{
    int i;
    int j;

    j = 1 + (tp[0] == ESC);
    if (len < j + 3)
    {
        i = len;
    }
    else if ((argp[1] != '+' && argp[1] != '$') || (argp[2] != 'r' && argp[2] != 'R'))
    {
        i = 0;
    }
    else if (argp[1] == '+')
    {
        for (i = j; i < len; ++i)
        {
            if ((tp[i] == ESC && i + 1 < len && tp[i + 1] == '\\') || tp[i] == STERM)
            {
                key_name[0] = (int)KS_EXTRA;
                key_name[1] = (int)KE_IGNORE;
                *slen = i + 1 + (tp[i] == ESC);
                break;
            }
        }
    }
    else
    {
        for (i = j + 3; i < len; ++i)
        {
            if (i - j == 3 && ! (isdigit ((unsigned char)(tp[i]))) )
            {
                break;
            }
            if (i - j == 4 && tp[i] != ' ')
            {
                break;
            }
            if (i - j == 5 && tp[i] != 'q')
            {
                break;
            }
            if (i - j == 6 && tp[i] != ESC && tp[i] != STERM)
            {
                break;
            }
            if ((i - j == 6 && tp[i] == STERM) || (i - j == 7 && tp[i] == '\\'))
            {
                key_name[0] = (int)KS_EXTRA;
                key_name[1] = (int)KE_IGNORE;
                *slen = i + 1;
                break;
            }
        }
    }

    if (i == len)
    {
        return FAIL;
    }
    return OK;
}

    static int
check_termcode(int         max_offset, char_u      *buf, int         bufsize, int         *buflen)
{
    char_u      *tp;
    char_u      *p;
    int         slen = 0;
    int         modslen;
    int         len;
    int         retval = 0;
    int         offset;
    char_u      key_name[2];
    int         modifiers;
    char_u      *modifiers_start = NULL;
    int         key;
    int         new_slen;
    char_u      string[MAX_KEY_CODE_LEN + 1];
    int i;
    int j;
    int         idx = 0;
    int         cpo_koffset;

    cpo_koffset = (vim_strchr(p_cpo, CPO_KOFFSET) != NULL);

    if (need_gather)
    {
        gather_termleader();
    }

    for (offset = 0; offset < max_offset; ++offset)
    {
        if (buf == NULL)
        {
            if (offset >= typebuf.tb_len)
            {
                break;
            }
            tp = typebuf.tb_buf + typebuf.tb_off + offset;
            len = typebuf.tb_len - offset;
        }
        else
        {
            if (offset >= *buflen)
            {
                break;
            }
            tp = buf + offset;
            len = *buflen - offset;
        }

        if (*tp ==  (0x80) )
        {
            offset += 2;
            continue;
        }

        if (osc_state.processing)
        {
            tp[len] = NUL;
            key_name[0] = NUL;
            key_name[1] = NUL;
            modifiers = 0;
            goto handle_osc;
        }

        i = *tp;
        for (p = termleader; *p && *p != i; ++p)
        {
            ;
        }
        if (*p == NUL)
        {
            continue;
        }

        if (*tp == ESC && !p_ek && (State & MODE_INSERT))
        {
            continue;
        }

        tp[len] = NUL;
        key_name[0] = NUL;
        key_name[1] = NUL;
        modifiers = 0;

        {
            int keypad_index_found = -1;
            int keypad_slen_found = 0;

            for (idx = 0; idx < tc_len; ++idx)
            {
                int     is_keypad = FALSE;
                slen = termcodes[idx].len;
                modifiers_start = NULL;
                if (cpo_koffset && offset && len < slen)
                {
                    continue;
                }
                if ( strncmp((char *)(termcodes[idx].code), (char *)(tp), ((size_t)(slen > len ? len : slen)))  == 0)
                {

                    if (len < slen)
                    {
                        return -1;
                    }

                    if (termcodes[idx].name[0] == 'K' && ( ((unsigned)(termcodes[idx].name[1]) - '0' < 10)  ||  ((unsigned)(termcodes[idx].name[1]) - 'A' < 26) ))
                    {
                        is_keypad = TRUE;
                        if (keypad_index_found < 0)
                        {
                            keypad_index_found = idx;
                            keypad_slen_found = slen;
                        }
                    }

                    if (!is_keypad)
                    {
                        key_name[0] = termcodes[idx].name[0];
                        key_name[1] = termcodes[idx].name[1];
                        break;
                    }
                }

                if (termcodes[idx].modlen > 0)
                {
                    modslen = termcodes[idx].modlen;
                    if (cpo_koffset && offset && len < modslen)
                    {
                        continue;
                    }
                    if ( strncmp((char *)(termcodes[idx].code), (char *)(tp), ((size_t)(modslen > len ? len : modslen)))  == 0)
                    {
                        int         n;

                        if (len <= modslen)
                        {
                            return -1;
                        }

                        if (tp[modslen] == termcodes[idx].code[slen - 1])
                        {
                            slen = modslen + 1;
                        }
                        else if (tp[modslen] != ';' && modslen == slen - 3)
                        {
                            continue;
                        }
                        else if (termcodes[idx].code[modslen] == '@' && (tp[modslen] != '1' || tp[modslen + 1] != ';'))
                        {
                            continue;
                        }
                        else
                        {
                            for (j = slen - 2; j < len && ( (isdigit ((unsigned char)(tp[j])))  || tp[j] == '-' || tp[j] == ';'); ++j)
                            {
                                ;
                            }
                            ++j;
                            if (len < j)
                            {
                                return -1;
                            }
                            if (tp[j - 1] != termcodes[idx].code[slen - 1])
                            {
                                continue;
                            }

                            modifiers_start = tp + slen - 2;

                            n = atoi((char *)modifiers_start);
                            modifiers |= decode_modifiers(n);

                            slen = j;
                        }
                        if (termcodes[idx].name[0] == 'K' && ( ((unsigned)(termcodes[idx].name[1]) - '0' < 10)  ||  ((unsigned)(termcodes[idx].name[1]) - 'A' < 26) ))
                        {
                            is_keypad = TRUE;
                            if (keypad_index_found < 0)
                            {
                                keypad_index_found = idx;
                                keypad_slen_found = slen;
                            }
                        }
                        if (!is_keypad)
                        {
                            key_name[0] = termcodes[idx].name[0];
                            key_name[1] = termcodes[idx].name[1];
                            break;
                        }
                    }
                }
            }
            if (idx == tc_len && keypad_index_found >= 0)
            {
                key_name[0] = termcodes[keypad_index_found].name[0];
                key_name[1] = termcodes[keypad_index_found].name[1];
                slen = keypad_slen_found;
            }
        }

        if (key_name[0] == NUL)
        {
            char_u *argp = tp[0] == ESC ? tp + 2 : tp + 1;

            if (((tp[0] == ESC && len >= 3 && tp[1] == '[') || (tp[0] == CSI && len >= 2)) && vim_strchr((char_u *)"0123456789>?ABCDEFHPQRS", *argp) != NULL)
            {
                int resp = handle_csi(tp, len, argp, offset, buf, bufsize, buflen, key_name, &slen);
                if (resp != 0)
                {
                    return resp;
                }
            }

            else if ((tp[0] == ESC && len >= 2 && tp[1] == ']') || tp[0] == OSC)
            {
handle_osc:
                if (handle_osc(tp, len, key_name, &slen) == FAIL)
                {
                    return -1;
                }
            }

            else if ((tp[0] == ESC && len >= 2 && tp[1] == 'P') || tp[0] == DCS)
            {
                if (handle_dcs(tp, argp, len, key_name, &slen) == FAIL)
                {
                    return -1;
                }
            }
        }

        if (key_name[0] == NUL)
        {
            continue;
        }

        if (key_name[0] == KS_EXTRA)
        {
            if (key_name[1] == KE_FOCUSGAINED)
            {
                if (!focus_state)
                {
                    ui_focus_change(TRUE);
                    did_cursorhold = TRUE;
                    focus_state = TRUE;
                }
                key_name[1] = (int)KE_IGNORE;
            }
            else if (key_name[1] == KE_FOCUSLOST)
            {
                if (focus_state)
                {
                    ui_focus_change(FALSE);
                    did_cursorhold = TRUE;
                    focus_state = FALSE;
                }
                key_name[1] = (int)KE_IGNORE;
            }
        }

        key = handle_x_keys( (-((key_name[0]) + ((int)(key_name[1]) << 8))) );

        new_slen = modifiers2keycode(modifiers, &key, string);

        key_name[0] =  ((-(key)) & 0xff) ;
        key_name[1] =  (((unsigned)(-(key)) >> 8) & 0xff) ;
        if (key_name[0] == KS_KEY)
        {
            new_slen += utf_char2bytes(key_name[1], string + new_slen);
        }
        else if (osc_state.processing || (new_slen == 0 && key_name[0] == KS_EXTRA && key_name[1] == KE_IGNORE))
        {
            retval = KEYLEN_REMOVED;
        }
        else
        {
            string[new_slen++] =  (0x80) ;
            string[new_slen++] = key_name[0];
            string[new_slen++] = key_name[1];
        }
        if (put_string_in_typebuf(offset, slen, string, new_slen, buf, bufsize, buflen) == FAIL)
        {
            return -1;
        }
        return retval == 0 ? (len + new_slen - slen + offset) : retval;
    }

    return 0;
}

    static char_u *
replace_termcodes(char_u      *from, char_u      **bufp, scid_T      sid_arg  __attribute__((unused)) , int         flags, int         *did_simplify)
{
    int         i;
    int         slen;
    int         key;
    size_t      dlen = 0;
    char_u      *src;
    int         do_backslash;
    int         do_special;
    int         do_key_code;
    char_u      *result;
    garray_T    ga;

    do_backslash = (vim_strchr(p_cpo, CPO_BSLASH) == NULL);
    do_special = (vim_strchr(p_cpo, CPO_SPECI) == NULL)
                                                  || (flags & REPTERM_SPECIAL);
    do_key_code = (vim_strchr(p_cpo, CPO_KEYCODE) == NULL);
    src = from;

    ga_init2(&ga, 1L, 100);
    if (ga_grow(&ga, (int)( strlen((char *)(src))  * 6 + 1)) == FAIL)
    {
        *bufp = NULL;
        return from;
    }
    result = ga.ga_data;

    if ((flags & REPTERM_FROM_PART) && src[0] == '#' &&  ((unsigned)(src[1]) - '0' < 10) )
    {
        result[dlen++] =  (0x80) ;
        result[dlen++] = 'k';
        if (src[1] == '0')
        {
            result[dlen++] = ';';
        }
        else
        {
            result[dlen++] = src[1];
        }
        src += 2;
    }

    while (*src != NUL)
    {
        if (do_special && ((flags & REPTERM_DO_LT) ||  strncmp((char *)(src), (char *)("<lt>"), (4))  != 0))
        {
            int fsk_flags = FSK_KEYCODE
                        | ((flags & REPTERM_NO_SIMPLIFY) ? 0 : FSK_SIMPLIFY)
                        | ((flags & REPTERM_FROM_PART) ? FSK_FROM_PART : 0);
            slen = trans_special(&src, result + dlen, fsk_flags, TRUE, did_simplify);
            if (slen > 0)
            {
                dlen += slen;
                continue;
            }
        }

        if (do_key_code)
        {
            int len;
            i = find_term_bykeys(src, &len);
            if (i >= 0)
            {
                result[dlen++] =  (0x80) ;
                result[dlen++] = termcodes[i].name[0];
                result[dlen++] = termcodes[i].name[1];
                src += len;
                continue;
            }
        }

        key = *src;
        if (key == Ctrl_V || (do_backslash && key == '\\'))
        {
            ++src;
            if (*src == NUL)
            {
                if (flags & REPTERM_FROM_PART)
                {
                    result[dlen++] = key;
                }
                break;
            }
        }

        for (i = utfc_ptr2len(src); i > 0; --i)
        {
            if (*src ==  (0x80) )
            {
                result[dlen++] =  (0x80) ;
                result[dlen++] = KS_SPECIAL;
                result[dlen++] =  ('X') ;
            }
            else
            {
                result[dlen++] = *src;
            }
            ++src;
        }
    }
    result[dlen] = NUL;

    if ((*bufp = vim_strsave(result)) != NULL)
    {
        from = *bufp;
    }
    vim_free(result);
    return from;
}

    static int
find_term_bykeys(char_u *src, int *matchlen)
{
    int i;
    int j;
    int         len = (int) strlen((char *)(src)) ;
    int         found = -1;
    int         foundlen = 1;
    int slen;
    int modslen;
    int         thislen;

    if (need_gather)
    {
        gather_termleader();
    }
    if (*src == NUL || vim_strchr(termleader, *src) == NULL)
    {
        return -1;
    }

    for (i = 0; i < tc_len; ++i)
    {
        slen = termcodes[i].len;
        modslen = termcodes[i].modlen;

        if (modslen > 0)
        {
            if (len > modslen &&  strncmp((char *)(termcodes[i].code), (char *)(src), ((size_t)modslen))  == 0)
            {
                thislen = 0;

                if (src[modslen] == termcodes[i].code[slen - 1])
                {
                    thislen = modslen + 1;
                }
                else if (src[modslen] != ';' && modslen == slen - 3)
                {
                    continue;
                }
                else if (termcodes[i].code[modslen] == '@' && (src[modslen] != '1' || src[modslen + 1] != ';'))
                {
                    continue;
                }
                else
                {
                    for (j = slen - 2; j < len && ( (isdigit ((unsigned char)(src[j])))  || src[j] == '-' || src[j] == ';'); ++j)
                    {
                        ;
                    }
                    ++j;
                    if (len < j)
                    {
                        continue;
                    }
                    if (src[j - 1] != termcodes[i].code[slen - 1])
                    {
                        continue;
                    }

                    thislen = j;
                }

                if (thislen > foundlen)
                {
                    found = i;
                    foundlen = thislen;
                }
            }
        }
        else
        {
            if (slen > foundlen && len >= slen &&  strncmp((char *)(termcodes[i].code), (char *)(src), ((size_t)slen))  == 0)
            {
                found = i;
                foundlen = slen;
            }
        }
    }

    if (matchlen != NULL && found >= 0)
    {
        *matchlen = foundlen;
    }

    return found;
}

    static void
gather_termleader(void)
{
    int     i;
    int     len = 0;

    termleader[len] = NUL;

    for (i = 0; i < tc_len; ++i)
    {
        if (vim_strchr(termleader, termcodes[i].code[0]) == NULL)
        {
            termleader[len++] = termcodes[i].code[0];
            termleader[len] = NUL;
        }
    }

    need_gather = FALSE;
}

    static void
show_termcodes(int flags)
{
    int         col;
    int         *items;
    int         item_count;
    int         run;
    int row;
    int rows;
    int         cols;
    int         i;
    int         len;

    if (tc_len == 0)
    {
        return;
    }
    items =  (int *)alloc(sizeof(int) * (tc_len)) ;
    if (items == NULL)
    {
        return;
    }

    msg_puts_title(_("\n--- Terminal keys ---"));

    for (run = (flags & OPT_ONECOLUMN) ? 3 : 1; run <= 3 && !got_int; ++run)
    {
        item_count = 0;
        for (i = 0; i < tc_len; i++)
        {
            len = show_one_termcode(termcodes[i].name, termcodes[i].code, FALSE);
            if ((flags & OPT_ONECOLUMN) || (len <= INC3 - TERMCODE_GAP ? run == 1 : len <= INC2 - TERMCODE_GAP ? run == 2 : run == 3))
            {
                items[item_count++] = i;
            }
        }

        if (run <= 2)
        {
            cols = (Columns + TERMCODE_GAP) / (run == 1 ? INC3 : INC2);
            if (cols == 0)
            {
                cols = 1;
            }
            rows = (item_count + cols - 1) / cols;
        }
        else
        {
            rows = item_count;
        }
        for (row = 0; row < rows && !got_int; ++row)
        {
            msg_putchar('\n');
            if (got_int)
            {
                break;
            }
            col = 0;
            for (i = row; i < item_count; i += rows)
            {
                msg_col = col;
                show_one_termcode(termcodes[items[i]].name, termcodes[items[i]].code, TRUE);
                if (run == 2)
                {
                    col += INC2;
                }
                else
                {
                    col += INC3;
                }
            }
            out_flush();
            ui_breakcheck();
        }
    }
    vim_free(items);
}

    static int
show_one_termcode(char_u *name, char_u *code, int printit)
{
    char_u      *p;
    int         len;

    if (name[0] > '~')
    {
        IObuff[0] = ' ';
        IObuff[1] = ' ';
        IObuff[2] = ' ';
        IObuff[3] = ' ';
    }
    else
    {
        IObuff[0] = 't';
        IObuff[1] = '_';
        IObuff[2] = name[0];
        IObuff[3] = name[1];
    }
    IObuff[4] = ' ';

    p = get_special_key_name( (-((name[0]) + ((int)(name[1]) << 8))) , 0);
    if (p[1] != 't')
    {
         strcpy((char *)(IObuff + 5), (char *)(p)) ;
    }
    else
    {
        IObuff[5] = NUL;
    }
    len = (int) strlen((char *)(IObuff)) ;
    do
    {
        IObuff[len++] = ' ';
    }
    while (len < 17)
        ;
    IObuff[len] = NUL;
    if (code == NULL)
    {
        len += 4;
    }
    else
    {
        len += vim_strsize(code);
    }

    if (printit)
    {
        msg_puts((char *)IObuff);
        if (code == NULL)
        {
            msg_puts("NULL");
        }
        else
        {
            msg_outtrans(code);
        }
    }
    return len;
}

    static void
term_disable_dec(void)
{
    term_set_sync_output(TERM_SYNC_OUTPUT_OFF);
    term_set_win_resize(false);
    out_flush();
}

    static void
term_set_win_resize(bool state)
{
    if (!state || win_resize_setting == 0 || win_resize_setting == 4)
    {
        if (win_resize_enabled)
        {
            set_shellsize(0, 0, false);
            set_sigwinch_handler();
            out_str((char_u *)"\033[?2048l");
        }
        win_resize_enabled = false;
    }
    else if ((*p_trz == NUL ||  strcmp((char *)(p_trz), (char *)("inband"))  == 0) && !win_resize_enabled)
    {
        if (win_resize_setting == 2)
        {
            out_str((char_u *)"\033[?2048h");
        }
        mch_signal(SIGWINCH, SIG_DFL);
        win_resize_enabled = true;
    }
}

    static int
sync_output_active(void)
{
    return p_tsy && (sync_output_setting == 1 || sync_output_setting == 2)
        && * ( term_strings[(int)(KS_BSU)] )  != NUL && * ( term_strings[(int)(KS_ESU)] )  != NUL;
}

    static void
term_set_sync_output(int flags)
{
    bool    allowed;
    bool    in_gui = false;

    allowed = p_tsy && (sync_output_setting == 1 || sync_output_setting == 2);

    if (flags & TERM_SYNC_OUTPUT_FLUSH)
    {
        if (allowed && !in_gui && sync_output_state > 0 && * ( term_strings[(int)(KS_ESU)] )  != NUL && * ( term_strings[(int)(KS_BSU)] )  != NUL)
        {
            out_str_nf( ( term_strings[(int)(KS_ESU)] ) );
            out_str_nf( ( term_strings[(int)(KS_BSU)] ) );
            out_flush();
        }
        return;
    }

    if (flags & TERM_SYNC_OUTPUT_OFF)
    {
        if (sync_output_state > 0 && * ( term_strings[(int)(KS_ESU)] )  != NUL)
        {
            out_str_nf( ( term_strings[(int)(KS_ESU)] ) );
            out_flush();
            sync_output_state = 0;
        }
        return;
    }

    if (!allowed || in_gui || * ( term_strings[(int)(KS_BSU)] )  == NUL || * ( term_strings[(int)(KS_ESU)] )  == NUL)
    {
        return;
    }

    if (flags & TERM_SYNC_OUTPUT_ENABLE)
    {
        if (sync_output_state++ > 0)
        {
            return;
        }
        out_str_nf( ( term_strings[(int)(KS_BSU)] ) );
    }
    else if (flags & TERM_SYNC_OUTPUT_DISABLE)
    {
        if (sync_output_state == 0 || --sync_output_state > 0)
        {
            return;
        }
        out_str_nf( ( term_strings[(int)(KS_ESU)] ) );
        out_flush();
    }
    else
    {
        siemsg("Unknown sync output value %d", flags);
        return;
    }
}

    static void
internal_format(int         textwidth, int         second_indent, int         flags, int         format_only, int         c)
{
    int         cc;
    int         save_char = NUL;
    int         haveto_redraw = FALSE;
    int         safe_tw = trim_to_int(8 * (vimlong_T)textwidth);

    if (!curbuf->b_p_ai && !(State & VREPLACE_FLAG))
    {
        cc = gchar_cursor();
        if ( ((cc) == ' ' || (cc) == '\t') )
        {
            save_char = cc;
            pchar_cursor('x');
        }
    }

    while (!got_int)
    {
        int     startcol;
        int     wantcol;
        int     foundcol;
        int     end_foundcol = 0;
        colnr_T len;
        colnr_T virtcol;
        int     orig_col = 0;
        char_u  *saved_text = NULL;
        colnr_T end_col;
        int     first_pass;

        if (curwin->w_cursor.col < safe_tw)
        {
            virtcol = get_nolist_virtcol()
                + char2cells(c != NUL ? c : gchar_cursor());
            if (virtcol <= (colnr_T)textwidth)
            {
                break;
            }
        }

        if (p_paste)
        {
            break;
        }
        if ((startcol = curwin->w_cursor.col) == 0)
        {
            break;
        }

        coladvance((colnr_T)textwidth);
        wantcol = curwin->w_cursor.col;

        curwin->w_cursor.col = startcol < safe_tw ? startcol : safe_tw;

        foundcol = 0;
        first_pass = TRUE;

        for (;;)
        {
            if (first_pass && c != NUL)
            {
                cc = c;
                first_pass = FALSE;
            }
            else
            {
                cc = gchar_cursor();
            }
            if ( ( ((cc) == ' ' || (cc) == '\t')  && (!utf_iscomposing(utf_ptr2char(ml_get_cursor() + 1)))) )
            {
                end_col = curwin->w_cursor.col;

                while (curwin->w_cursor.col > 0 &&  ( ((cc) == ' ' || (cc) == '\t')  && (!utf_iscomposing(utf_ptr2char(ml_get_cursor() + 1)))) )
                {
                    dec_cursor();
                    cc = gchar_cursor();

                }
                if (curwin->w_cursor.col == 0 &&  ( ((cc) == ' ' || (cc) == '\t')  && (!utf_iscomposing(utf_ptr2char(ml_get_cursor() + 1)))) )
                {
                    break;
                }

                inc_cursor();

                end_foundcol = end_col + 1;
                foundcol = curwin->w_cursor.col;
                if (curwin->w_cursor.col <= (colnr_T)wantcol)
                {
                    break;
                }
            }
            if (curwin->w_cursor.col == 0)
            {
                break;
            }
            dec_cursor();
        }

        if (foundcol == 0)
        {
            curwin->w_cursor.col = startcol;
            break;
        }

        undisplay_dollar();

        if (State & VREPLACE_FLAG)
        {
            orig_col = startcol;
        }
        else
        {
            replace_offset = startcol - end_foundcol;
        }

        curwin->w_cursor.col = foundcol;
        while ((cc = gchar_cursor(),  ( ((cc) == ' ' || (cc) == '\t')  && (!utf_iscomposing(utf_ptr2char(ml_get_cursor() + 1)))) ))
        {
            inc_cursor();
        }
        startcol -= curwin->w_cursor.col;
        if (startcol < 0)
        {
            startcol = 0;
        }

        if (State & VREPLACE_FLAG)
        {
            saved_text = vim_strnsave(ml_get_cursor(), ml_get_cursor_len());
            curwin->w_cursor.col = orig_col;
            if (saved_text == NULL)
            {
                break;
            }
            saved_text[startcol] = NUL;

            backspace_until_column(foundcol);
        }
        else
        {
            curwin->w_cursor.col = foundcol;
        }

        open_line(FORWARD, OPENLINE_DELSPACES + OPENLINE_MARKFIX, old_indent, NULL);
        old_indent = 0;

        replace_offset = 0;
        if (State & VREPLACE_FLAG)
        {
            ins_bytes(saved_text);
            vim_free(saved_text);
        }
        else
        {
            curwin->w_cursor.col += startcol;
            len = ml_get_curline_len();
            if (curwin->w_cursor.col > len)
            {
                curwin->w_cursor.col = len;
            }
        }

        haveto_redraw = TRUE;
        did_ai = FALSE;
        did_si = FALSE;
        can_si = FALSE;
        can_si_back = FALSE;
        line_breakcheck();
    }

    if (save_char != NUL)
    {
        pchar_cursor(save_char);
    }

    if (haveto_redraw)
    {
        update_topline();
        redraw_curbuf_later(UPD_VALID);
    }
}

    static int
comp_textwidth(void)
{
    int         textwidth;

    textwidth = curbuf->b_p_tw;
    if (textwidth == 0 && curbuf->b_p_wm)
    {
        textwidth = curwin->w_width - curbuf->b_p_wm;
        if (curwin-> w_onebuf_opt.wo_nu  || curwin-> w_onebuf_opt.wo_rnu )
        {
            textwidth -= 8;
        }
    }
    if (textwidth < 0)
    {
        textwidth = 0;
    }
    return textwidth;
}

static int skip_chars(int, int);

static int      cls_bigword;

    static int
cls(void)
{
    int     c;

    c = gchar_cursor();
    if (c == ' ' || c == '\t' || c == NUL)
    {
        return 0;
    }
    c = utf_class(c);
    if (c != 0 && cls_bigword)
    {
        return 1;
    }
    return c;

    if (cls_bigword)
    {
        return 1;
    }

    if (vim_iswordc(c))
    {
        return 2;
    }
    return 1;
}

    static int
fwd_word(long        count, int         bigword, int         eol)
{
    int         sclass;
    int         i;
    int         last_line;

    curwin->w_cursor.coladd = 0;
    cls_bigword = bigword;
    while (--count >= 0)
    {
        sclass = cls();

        last_line = (curwin->w_cursor.lnum == curbuf->b_ml.ml_line_count);
        i = inc_cursor();
        if (i == -1 || (i >= 1 && last_line))
        {
            return FAIL;
        }
        if (i >= 1 && eol && count == 0)
        {
            return OK;
        }

        if (sclass != 0)
        {
            while (cls() == sclass)
            {
                i = inc_cursor();
                if (i == -1 || (i >= 1 && eol && count == 0))
                {
                    return OK;
                }
            }
        }

        while (cls() == 0)
        {
            if (curwin->w_cursor.col == 0 && *ml_get_curline() == NUL)
            {
                break;
            }

            i = inc_cursor();
            if (i == -1 || (i >= 1 && eol && count == 0))
            {
                return OK;
            }
        }
    }
    return OK;
}

    static int
bck_word(long count, int bigword, int stop)
{
    int         sclass;

    curwin->w_cursor.coladd = 0;
    cls_bigword = bigword;
    while (--count >= 0)
    {
        sclass = cls();
        if (dec_cursor() == -1)
        {
            return FAIL;
        }

        if (!stop || sclass == cls() || sclass == 0)
        {
            while (cls() == 0)
            {
                if (curwin->w_cursor.col == 0 &&  (*ml_get(curwin->w_cursor.lnum) == NUL) )
                {
                    goto finished;
                }
                if (dec_cursor() == -1)
                {
                    return OK;
                }
            }

            if (skip_chars(cls(),  (-1) ))
            {
                return OK;
            }
        }

        inc_cursor();
finished:
        stop = FALSE;
    }
    adjust_skipcol();
    return OK;
}

    static int
end_word(long        count, int         bigword, int         stop, int         empty)
{
    int         sclass;

    curwin->w_cursor.coladd = 0;
    cls_bigword = bigword;

    if (*p_sel == 'e' && VIsual_active && VIsual_mode == 'v' && VIsual_select_exclu_adj)
    {
        unadjust_for_sel();
    }

    while (--count >= 0)
    {
        sclass = cls();
        if (inc_cursor() == -1)
        {
            return FAIL;
        }

        if (cls() == sclass && sclass != 0)
        {
            if (skip_chars(sclass, FORWARD))
            {
                return FAIL;
            }
        }
        else if (!stop || sclass == 0)
        {
            while (cls() == 0)
            {
                if (empty && curwin->w_cursor.col == 0 &&  (*ml_get(curwin->w_cursor.lnum) == NUL) )
                {
                    goto finished;
                }
                if (inc_cursor() == -1)
                {
                    return FAIL;
                }
            }

            if (skip_chars(cls(), FORWARD))
            {
                return FAIL;
            }
        }
        dec_cursor();
finished:
        stop = FALSE;
    }
    return OK;
}

    static int
bckend_word(long        count, int         bigword, int         eol)
{
    int         sclass;
    int         i;

    curwin->w_cursor.coladd = 0;
    cls_bigword = bigword;
    while (--count >= 0)
    {
        sclass = cls();
        if ((i = dec_cursor()) == -1)
        {
            return FAIL;
        }
        if (eol && i == 1)
        {
            return OK;
        }

        if (sclass != 0)
        {
            while (cls() == sclass)
            {
                if ((i = dec_cursor()) == -1 || (eol && i == 1))
                {
                    return OK;
                }
            }
        }

        while (cls() == 0)
        {
            if (curwin->w_cursor.col == 0 &&  (*ml_get(curwin->w_cursor.lnum) == NUL) )
            {
                break;
            }
            if ((i = dec_cursor()) == -1 || (eol && i == 1))
            {
                return OK;
            }
        }
    }
    adjust_skipcol();
    return OK;
}

    static int
skip_chars(int cclass, int dir)
{
    while (cls() == cclass)
    {
        if ((dir == FORWARD ? inc_cursor() : dec_cursor()) == -1)
        {
            return TRUE;
        }
    }
    return FALSE;
}

    static void
back_in_line(void)
{
    int         sclass;

    sclass = cls();
    for (;;)
    {
        if (curwin->w_cursor.col == 0)
        {
            break;
        }
        dec_cursor();
        if (cls() != sclass)
        {
            inc_cursor();
            break;
        }
    }
}

    static int
current_word(oparg_T     *oap, long        count, int         include, int         bigword)
{
    pos_T       start_pos;
    pos_T       pos;
    int         inclusive = TRUE;
    int         include_white = FALSE;

    cls_bigword = bigword;
     (&start_pos)->lnum = 0;
     (&start_pos)->col = 0;
     (&start_pos)->coladd = 0;

    if (VIsual_active && *p_sel == 'e' &&  (((VIsual).lnum != (curwin->w_cursor).lnum)               ? (VIsual).lnum < (curwin->w_cursor).lnum                   : (VIsual).col != (curwin->w_cursor).col                        ? (VIsual).col < (curwin->w_cursor).col                     : (VIsual).coladd < (curwin->w_cursor).coladd) )
    {
        dec_cursor();
    }

    if (!VIsual_active ||  (((curwin->w_cursor).lnum == (VIsual).lnum) && ((curwin->w_cursor).col == (VIsual).col) && ((curwin->w_cursor).coladd == (VIsual).coladd)) )
    {
        back_in_line();
        start_pos = curwin->w_cursor;

        if ((cls() == 0) == include)
        {
            if (end_word(1L, bigword, TRUE, TRUE) == FAIL)
            {
                return FAIL;
            }
        }
        else
        {
            fwd_word(1L, bigword, TRUE);
            if (curwin->w_cursor.col == 0)
            {
                decl(&curwin->w_cursor);
            }
            else
            {
                oneleft();
            }

            if (include)
            {
                include_white = TRUE;
            }
        }

        if (VIsual_active)
        {
            VIsual = start_pos;
            redraw_curbuf_later(UPD_INVERTED);
        }
        else
        {
            oap->start = start_pos;
            oap->motion_type = MCHAR;
        }
        --count;
    }

    while (count > 0)
    {
        inclusive = TRUE;
        if (VIsual_active &&  (((curwin->w_cursor).lnum != (VIsual).lnum)               ? (curwin->w_cursor).lnum < (VIsual).lnum                   : (curwin->w_cursor).col != (VIsual).col                        ? (curwin->w_cursor).col < (VIsual).col                     : (curwin->w_cursor).coladd < (VIsual).coladd) )
        {
            if (decl(&curwin->w_cursor) == -1)
            {
                return FAIL;
            }
            if (include != (cls() != 0))
            {
                if (bck_word(1L, bigword, TRUE) == FAIL)
                {
                    return FAIL;
                }
            }
            else
            {
                if (bckend_word(1L, bigword, TRUE) == FAIL)
                {
                    return FAIL;
                }
                (void)incl(&curwin->w_cursor);
            }
        }
        else
        {
            if (incl(&curwin->w_cursor) == -1)
            {
                return FAIL;
            }
            if (include != (cls() == 0))
            {
                if (fwd_word(1L, bigword, TRUE) == FAIL && count > 1)
                {
                    return FAIL;
                }
                if (oneleft() == FAIL)
                {
                    inclusive = FALSE;
                }
            }
            else
            {
                if (end_word(1L, bigword, TRUE, TRUE) == FAIL)
                {
                    return FAIL;
                }
            }
        }
        --count;
    }

    if (include_white && (cls() != 0 || (curwin->w_cursor.col == 0 && !inclusive)))
    {
        pos = curwin->w_cursor;
        curwin->w_cursor = start_pos;
        if (oneleft() == OK)
        {
            back_in_line();
            if (cls() == 0 && curwin->w_cursor.col > 0)
            {
                if (VIsual_active)
                {
                    VIsual = curwin->w_cursor;
                }
                else
                {
                    oap->start = curwin->w_cursor;
                }
            }
        }
        curwin->w_cursor = pos;
    }

    if (VIsual_active)
    {
        if (*p_sel == 'e' && inclusive &&  ( (((VIsual).lnum != (curwin->w_cursor).lnum)               ? (VIsual).lnum < (curwin->w_cursor).lnum                   : (VIsual).col != (curwin->w_cursor).col                        ? (VIsual).col < (curwin->w_cursor).col                     : (VIsual).coladd < (curwin->w_cursor).coladd)  ||  (((VIsual).lnum == (curwin->w_cursor).lnum) && ((VIsual).col == (curwin->w_cursor).col) && ((VIsual).coladd == (curwin->w_cursor).coladd)) ) )
        {
            inc_cursor();
        }
        if (VIsual_mode == 'V')
        {
            VIsual_mode = 'v';
            redraw_cmdline = TRUE;
        }
    }
    else
    {
        oap->inclusive = inclusive;
    }

    return OK;
}

    static int
current_block(oparg_T     *oap, long        count, int         include, int         what, int         other)
{
    pos_T       old_pos;
    pos_T       *pos = NULL;
    pos_T       start_pos;
    pos_T       *end_pos;
    pos_T old_start;
    pos_T old_end;
    char_u      *save_cpo;
    int         sol = FALSE;

    old_pos = curwin->w_cursor;
    old_end = curwin->w_cursor;
    old_start = old_end;

    if (!VIsual_active ||  (((VIsual).lnum == (curwin->w_cursor).lnum) && ((VIsual).col == (curwin->w_cursor).col) && ((VIsual).coladd == (curwin->w_cursor).coladd)) )
    {
        setpcmark();
        if (what == '{')
        {
            while (inindent(1))
            {
                if (inc_cursor() != 0)
                {
                    break;
                }
            }
        }
        if (gchar_cursor() == what)
        {
            ++curwin->w_cursor.col;
        }
    }
    else if ( (((VIsual).lnum != (curwin->w_cursor).lnum)               ? (VIsual).lnum < (curwin->w_cursor).lnum                   : (VIsual).col != (curwin->w_cursor).col                        ? (VIsual).col < (curwin->w_cursor).col                     : (VIsual).coladd < (curwin->w_cursor).coladd) )
    {
        old_start = VIsual;
        curwin->w_cursor = VIsual;
    }
    else
    {
        old_end = VIsual;
    }

    save_cpo = p_cpo;
    p_cpo = (char_u *)(vim_strchr(p_cpo, CPO_MATCHBSL) != NULL ? "%M" : "%");
    if ((pos = findmatch(NULL, what)) != NULL)
    {
        while (count-- > 0)
        {
            if ((pos = findmatch(NULL, what)) == NULL)
            {
                break;
            }
            curwin->w_cursor = *pos;
            start_pos = *pos;
        }
    }
    else
    {
        while (count-- > 0)
        {
            if ((pos = findmatchlimit(NULL, what, FM_FORWARD, 0)) == NULL)
            {
                break;
            }
            curwin->w_cursor = *pos;
            start_pos = *pos;
        }
    }
    p_cpo = save_cpo;

    if (pos == NULL || (end_pos = findmatch(NULL, other)) == NULL)
    {
        curwin->w_cursor = old_pos;
        return FAIL;
    }
    curwin->w_cursor = *end_pos;

    while (!include)
    {
        incl(&start_pos);
        sol = (curwin->w_cursor.col == 0);
        decl(&curwin->w_cursor);
        while (inindent(1))
        {
            sol = TRUE;
            if (decl(&curwin->w_cursor) != 0)
            {
                break;
            }
        }

        if ( (((start_pos).lnum == (*end_pos).lnum) && ((start_pos).col == (*end_pos).col) && ((start_pos).coladd == (*end_pos).coladd))  && VIsual_active)
        {
            curwin->w_cursor = old_pos;
            return FAIL;
        }

        if (! (((start_pos).lnum != (old_start).lnum)               ? (start_pos).lnum < (old_start).lnum                   : (start_pos).col != (old_start).col                        ? (start_pos).col < (old_start).col                     : (start_pos).coladd < (old_start).coladd)  && ! (((old_end).lnum != (curwin->w_cursor).lnum)               ? (old_end).lnum < (curwin->w_cursor).lnum                   : (old_end).col != (curwin->w_cursor).col                        ? (old_end).col < (curwin->w_cursor).col                     : (old_end).coladd < (curwin->w_cursor).coladd)  && ! (((start_pos).lnum == (curwin->w_cursor).lnum) && ((start_pos).col == (curwin->w_cursor).col) && ((start_pos).coladd == (curwin->w_cursor).coladd))  && VIsual_active)
        {
            curwin->w_cursor = old_start;
            decl(&curwin->w_cursor);
            if ((pos = findmatch(NULL, what)) == NULL)
            {
                curwin->w_cursor = old_pos;
                return FAIL;
            }
            start_pos = *pos;
            curwin->w_cursor = *pos;
            if ((end_pos = findmatch(NULL, other)) == NULL)
            {
                curwin->w_cursor = old_pos;
                return FAIL;
            }
            curwin->w_cursor = *end_pos;
        }
        else
        {
            break;
        }
    }

    if (VIsual_active)
    {
        if (*p_sel == 'e')
        {
            inc(&curwin->w_cursor);
        }
        if (sol && gchar_cursor() != NUL)
        {
            inc(&curwin->w_cursor);
        }
        VIsual = start_pos;
        VIsual_mode = 'v';
        redraw_curbuf_later(UPD_INVERTED);
        showmode();
    }
    else
    {
        oap->start = start_pos;
        oap->motion_type = MCHAR;
        oap->inclusive = FALSE;
        if (sol)
        {
            incl(&curwin->w_cursor);
        }
        else if ( ( (((start_pos).lnum != (curwin->w_cursor).lnum)               ? (start_pos).lnum < (curwin->w_cursor).lnum                   : (start_pos).col != (curwin->w_cursor).col                        ? (start_pos).col < (curwin->w_cursor).col                     : (start_pos).coladd < (curwin->w_cursor).coladd)  ||  (((start_pos).lnum == (curwin->w_cursor).lnum) && ((start_pos).col == (curwin->w_cursor).col) && ((start_pos).coladd == (curwin->w_cursor).coladd)) ) )
        {
            oap->inclusive = TRUE;
        }
        else
        {
            curwin->w_cursor = start_pos;
        }
    }

    return OK;
}

    static int
find_next_quote(char_u      *line, int         col, int         quotechar, char_u      *escape)
{
    int         c;

    for (;;)
    {
        c = line[col];
        if (c == NUL)
        {
            return -1;
        }
        else if (escape != NULL && vim_strchr(escape, c))
        {
            ++col;
            if (line[col] == NUL)
            {
                return -1;
            }
        }
        else if (c == quotechar)
        {
            break;
        }
        col += utfc_ptr2len(line + col);
    }
    return col;
}

    static int
find_prev_quote(char_u      *line, int         col_start, int         quotechar, char_u      *escape)
{
    int         n;

    while (col_start > 0)
    {
        --col_start;
        col_start -= utf_head_off(line, line + col_start);
        n = 0;
        if (escape != NULL)
        {
            while (col_start - n > 0 && vim_strchr(escape, line[col_start - n - 1]) != NULL)
            {
            ++n;
            }
        }
        if (n & 1)
        {
            col_start -= n;
        }
        else if (line[col_start] == quotechar)
        {
            break;
        }
    }
    return col_start;
}

    static int
current_quote(oparg_T     *oap, long        count, int         include, int         quotechar)
{
    char_u      *line = ml_get_curline();
    int         col_end;
    int         col_start = curwin->w_cursor.col;
    int         inclusive = FALSE;
    int         vis_empty = TRUE;
    int         vis_bef_curs = FALSE;
    int         did_exclusive_adj = FALSE;
    int         inside_quotes = FALSE;
    int         selected_quote = FALSE;
    int         i;
    int         restore_vis_bef = FALSE;

    if (VIsual_active)
    {
        if (VIsual.lnum != curwin->w_cursor.lnum)
        {
            return FALSE;
        }

        vis_bef_curs =  (((VIsual).lnum != (curwin->w_cursor).lnum)               ? (VIsual).lnum < (curwin->w_cursor).lnum                   : (VIsual).col != (curwin->w_cursor).col                        ? (VIsual).col < (curwin->w_cursor).col                     : (VIsual).coladd < (curwin->w_cursor).coladd) ;
        vis_empty =  (((VIsual).lnum == (curwin->w_cursor).lnum) && ((VIsual).col == (curwin->w_cursor).col) && ((VIsual).coladd == (curwin->w_cursor).coladd)) ;
        if (*p_sel == 'e')
        {
            if (vis_bef_curs)
            {
                dec_cursor();
                did_exclusive_adj = TRUE;
            }
            else if (!vis_empty)
            {
                dec(&VIsual);
                did_exclusive_adj = TRUE;
            }
            vis_empty =  (((VIsual).lnum == (curwin->w_cursor).lnum) && ((VIsual).col == (curwin->w_cursor).col) && ((VIsual).coladd == (curwin->w_cursor).coladd)) ;
            if (!vis_bef_curs && !vis_empty)
            {
                pos_T t = curwin->w_cursor;

                curwin->w_cursor = VIsual;
                VIsual = t;
                vis_bef_curs = TRUE;
                restore_vis_bef = TRUE;
            }
        }
    }

    if (!vis_empty)
    {
        if (vis_bef_curs)
        {
            inside_quotes = VIsual.col > 0
                        && line[VIsual.col - 1] == quotechar
                        && line[curwin->w_cursor.col] != NUL
                        && line[curwin->w_cursor.col + 1] == quotechar;
            i = VIsual.col;
            col_end = curwin->w_cursor.col;
        }
        else
        {
            inside_quotes = curwin->w_cursor.col > 0
                        && line[curwin->w_cursor.col - 1] == quotechar
                        && line[VIsual.col] != NUL
                        && line[VIsual.col + 1] == quotechar;
            i = curwin->w_cursor.col;
            col_end = VIsual.col;
        }

        while (i <= col_end)
        {
            if (line[i] == NUL)
            {
                break;
            }
            if (line[i++] == quotechar)
            {
                selected_quote = TRUE;
                break;
            }
        }
    }

    if (!vis_empty && line[col_start] == quotechar)
    {
        if (vis_bef_curs)
        {
            col_start = find_next_quote(line, col_start + 1, quotechar, NULL);
            if (col_start < 0)
            {
                goto abort_search;
            }
            col_end = find_next_quote(line, col_start + 1, quotechar, curbuf->b_p_qe);
            if (col_end < 0)
            {
                col_end = col_start;
                col_start = curwin->w_cursor.col;
            }
        }
        else
        {
            col_end = find_prev_quote(line, col_start, quotechar, NULL);
            if (line[col_end] != quotechar)
            {
                goto abort_search;
            }
            col_start = find_prev_quote(line, col_end, quotechar, curbuf->b_p_qe);
            if (line[col_start] != quotechar)
            {
                col_start = col_end;
                col_end = curwin->w_cursor.col;
            }
        }
    }
    else
    {
    if (line[col_start] == quotechar || !vis_empty)
    {
        int     first_col = col_start;

        if (!vis_empty)
        {
            if (vis_bef_curs)
            {
                first_col = find_next_quote(line, col_start, quotechar, NULL);
            }
            else
            {
                first_col = find_prev_quote(line, col_start, quotechar, NULL);
            }
        }

        col_start = 0;
        for (;;)
        {
            col_start = find_next_quote(line, col_start, quotechar, NULL);
            if (col_start < 0 || col_start > first_col)
            {
                goto abort_search;
            }
            col_end = find_next_quote(line, col_start + 1, quotechar, curbuf->b_p_qe);
            if (col_end < 0)
            {
                goto abort_search;
            }
            if (col_start <= first_col && first_col <= col_end)
            {
                break;
            }
            col_start = col_end + 1;
        }
    }
    else
    {
        col_start = find_prev_quote(line, col_start, quotechar, curbuf->b_p_qe);
        if (line[col_start] != quotechar)
        {
            col_start = find_next_quote(line, col_start, quotechar, NULL);
            if (col_start < 0)
            {
                goto abort_search;
            }
        }

        col_end = find_next_quote(line, col_start + 1, quotechar, curbuf->b_p_qe);
        if (col_end < 0)
        {
            goto abort_search;
        }
    }
    }

    if (include)
    {
        if ( ((line[col_end + 1]) == ' ' || (line[col_end + 1]) == '\t') )
        {
            while ( ((line[col_end + 1]) == ' ' || (line[col_end + 1]) == '\t') )
            {
                ++col_end;
            }
        }
        else
        {
            while (col_start > 0 &&  ((line[col_start - 1]) == ' ' || (line[col_start - 1]) == '\t') )
            {
                --col_start;
            }
        }
    }

    if (!include && count < 2 && (vis_empty || !inside_quotes))
    {
        ++col_start;
    }
    curwin->w_cursor.col = col_start;
    if (VIsual_active)
    {
        if (vis_empty || (vis_bef_curs && !selected_quote && (inside_quotes || (line[VIsual.col] != quotechar && (VIsual.col == 0 || line[VIsual.col - 1] != quotechar)))))
        {
            VIsual = curwin->w_cursor;
            redraw_curbuf_later(UPD_INVERTED);
        }
    }
    else
    {
        oap->start = curwin->w_cursor;
        oap->motion_type = MCHAR;
    }

    curwin->w_cursor.col = col_end;
    if ((include || count > 1 || (!vis_empty && inside_quotes)) && inc_cursor() == 2)
    {
        inclusive = TRUE;
    }
    if (VIsual_active)
    {
        if (vis_empty || vis_bef_curs)
        {
            if (*p_sel != 'e')
            {
                dec_cursor();
            }
        }
        else
        {
            if (inside_quotes || (!selected_quote && line[VIsual.col] != quotechar && (line[VIsual.col] == NUL || line[VIsual.col + 1] != quotechar)))
            {
                dec_cursor();
                VIsual = curwin->w_cursor;
            }
            curwin->w_cursor.col = col_start;
        }
        if (VIsual_mode == 'V')
        {
            VIsual_mode = 'v';
            redraw_cmdline = TRUE;
        }
    }
    else
    {
        oap->inclusive = inclusive;
    }

    return OK;

abort_search:
    if (VIsual_active && *p_sel == 'e')
    {
        if (did_exclusive_adj)
        {
            inc_cursor();
        }
        if (restore_vis_bef)
        {
            pos_T t = curwin->w_cursor;

            curwin->w_cursor = VIsual;
            VIsual = t;
        }
    }
    return FALSE;
}

