    static int
ui_inchar(char_u      *buf, int         maxlen, long        wtime, int         tb_change_cnt)
{
    int         retval = 0;

    if (wtime == -1 || wtime > 100L)
    {
        (void)vim_handle_signal( (-2) );

        if ((mapped_ctrl_c | curbuf->b_mapped_ctrl_c) & get_real_state())
        {
            ctrl_c_interrupts = FALSE;
        }
    }

        retval = mch_inchar(buf, maxlen, wtime, tb_change_cnt);

    if (wtime == -1 || wtime > 100L)
    {
        (void)vim_handle_signal( (-1) );
    }

    ctrl_c_interrupts = TRUE;

    return retval;
}

    static int
inchar_loop(char_u      *buf, int         maxlen, long        wtime, int         tb_change_cnt, int         (*wait_func)(long wtime, int *interrupted, int ignore_input), int         (*resize_func)(int check_only))
{
    int         len;
    int         interrupted = FALSE;
    int         did_call_wait_func = FALSE;
    long        wait_time;
    long        elapsed_time = 0;
    elapsed_T   start_tv;

     gettimeofday(&(start_tv), NULL) ;

    for (;;)
    {
        if (resize_func != NULL)
        {
            resize_func(FALSE);
        }

        if (wtime < 0)
        {
            wait_time = -1;
        }
        else
        {
            elapsed_time =  elapsed(&(start_tv)) ;
            wait_time = wtime - elapsed_time;

            if (wait_time <= 0 && did_call_wait_func)
            {
                return 0;
            }
        }

        did_call_wait_func = TRUE;
        if (wait_func(wait_time, &interrupted, FALSE))
        {
            if (typebuf_changed(tb_change_cnt))
            {
                return 0;
            }

            if (buf == NULL)
            {
                return input_available();
            }

            len = read_from_input_buf(buf, (long)maxlen);
            if (len > 0)
            {
                return len;
            }
            continue;
        }

        if ((resize_func != NULL && resize_func(TRUE)) || wait_time > 0)
        {
            continue;
        }

        break;
    }
    return 0;
}

