    static int
undo_allowed(void)
{
    if (!curbuf->b_p_ma)
    {
        emsg(_(e_cannot_make_changes_modifiable_is_off));
        return FALSE;
    }

    if (textlock != 0)
    {
        emsg(_(e_not_allowed_to_change_text_or_change_window));
        return FALSE;
    }

    return TRUE;
}

    static long
get_undolevel(void)
{
    if (curbuf->b_p_ul ==  (-123456) )
    {
        return p_ul;
    }
    return curbuf->b_p_ul;
}

    static int
u_save_line(undoline_T *ul, linenr_T lnum)
{
    char_u *line = ml_get(lnum);

    ul->ul_textlen = ml_get_len(lnum);
    if (curbuf->b_ml.ml_line_len == 0)
    {
        ul->ul_len = 1;
        ul->ul_line = vim_strsave((char_u *)"");
    }
    else
    {
        ul->ul_len = curbuf->b_ml.ml_line_len;
        ul->ul_line = vim_memsave(line, ul->ul_len);
    }
    return ul->ul_line == NULL ? FAIL : OK;
}

    static int
u_savecommon(linenr_T    top, linenr_T    bot, linenr_T    newbot, int         reload)
{
    linenr_T    lnum;
    long        i;
    u_header_T  *uhp;
    u_header_T  *old_curhead;
    u_entry_T   *uep;
    u_entry_T   *prev_uep;
    long        size;

    if (!reload)
    {
        if (!undo_allowed())
        {
            return FAIL;
        }

        change_warning(0);
        if (bot > curbuf->b_ml.ml_line_count + 1)
        {
            emsg(_(e_line_count_changed_unexpectedly));
            return FAIL;
        }
    }

    size = bot - top - 1;

    if (curbuf->b_u_synced)
    {
        curbuf->b_new_change = true;

        if (get_undolevel() >= 0)
        {
            uhp =  lalloc(sizeof(u_header_T), FALSE) ;
            if (uhp == NULL)
            {
                goto nomem;
            }
        }
        else
        {
            uhp = NULL;
        }

        old_curhead = curbuf->b_u_curhead;
        if (old_curhead != NULL)
        {
            curbuf->b_u_newhead = old_curhead->uh_next.ptr;
            curbuf->b_u_curhead = NULL;
        }

        while (curbuf->b_u_numhead > get_undolevel() && curbuf->b_u_oldhead != NULL)
        {
            u_header_T      *uhfree = curbuf->b_u_oldhead;

            if (uhfree == old_curhead)
            {
                u_freebranch(curbuf, uhfree, &old_curhead);
            }
            else if (uhfree->uh_alt_next.ptr == NULL)
            {
                u_freeheader(curbuf, uhfree, &old_curhead);
            }
            else
            {
                while (uhfree->uh_alt_next.ptr != NULL)
                {
                    uhfree = uhfree->uh_alt_next.ptr;
                }
                u_freebranch(curbuf, uhfree, &old_curhead);
            }
        }

        if (uhp == NULL)
        {
            if (old_curhead != NULL)
            {
                u_freebranch(curbuf, old_curhead, NULL);
            }
            curbuf->b_u_synced = false;
            return OK;
        }

        uhp->uh_prev.ptr = NULL;
        uhp->uh_next.ptr = curbuf->b_u_newhead;
        uhp->uh_alt_next.ptr = old_curhead;
        if (old_curhead != NULL)
        {
            uhp->uh_alt_prev.ptr = old_curhead->uh_alt_prev.ptr;
            if (uhp->uh_alt_prev.ptr != NULL)
            {
                uhp->uh_alt_prev.ptr->uh_alt_next.ptr = uhp;
            }
            old_curhead->uh_alt_prev.ptr = uhp;
            if (curbuf->b_u_oldhead == old_curhead)
            {
                curbuf->b_u_oldhead = uhp;
            }
        }
        else
        {
            uhp->uh_alt_prev.ptr = NULL;
        }
        if (curbuf->b_u_newhead != NULL)
        {
            curbuf->b_u_newhead->uh_prev.ptr = uhp;
        }

        uhp->uh_seq = ++curbuf->b_u_seq_last;
        curbuf->b_u_seq_cur = uhp->uh_seq;
        uhp->uh_time = vim_time();
        uhp->uh_save_nr = 0;
        curbuf->b_u_time_cur = uhp->uh_time + 1;

        uhp->uh_walk = 0;
        uhp->uh_entry = NULL;
        uhp->uh_getbot_entry = NULL;
        uhp->uh_cursor = curwin->w_cursor;
        if (virtual_active() && curwin->w_cursor.coladd > 0)
        {
            uhp->uh_cursor_vcol = getviscol();
        }
        else
        {
            uhp->uh_cursor_vcol = -1;
        }

        uhp->uh_flags = (curbuf->b_changed ? UH_CHANGED : 0) +
                       ((curbuf->b_ml.ml_flags & ML_EMPTY) ? UH_EMPTYBUF : 0);

         memmove((char *)(uhp->uh_namedm), (char *)(curbuf->b_namedm), sizeof(pos_T) *  ('z' - 'a' + 1) ) ;
        uhp->uh_visual = curbuf->b_visual;

        curbuf->b_u_newhead = uhp;
        if (curbuf->b_u_oldhead == NULL)
        {
            curbuf->b_u_oldhead = uhp;
        }
        ++curbuf->b_u_numhead;
    }
    else
    {
        if (get_undolevel() < 0)
        {
            return OK;
        }

        if (size == 1)
        {
            uep = u_get_headentry();
            prev_uep = NULL;
            for (i = 0; i < 10; ++i)
            {
                if (uep == NULL)
                {
                    break;
                }

                if ((curbuf->b_u_newhead->uh_getbot_entry != uep ? (uep->ue_top + uep->ue_size + 1 != (uep->ue_bot == 0 ? curbuf->b_ml.ml_line_count + 1 : uep->ue_bot)) : uep->ue_lcount != curbuf->b_ml.ml_line_count) || (uep->ue_size > 1 && top >= uep->ue_top && top + 2 <= uep->ue_top + uep->ue_size + 1))
                {
                    break;
                }

                if (uep->ue_size == 1 && uep->ue_top == top)
                {
                    if (i > 0)
                    {
                        u_getbot();
                        curbuf->b_u_synced = false;

                        prev_uep->ue_next = uep->ue_next;
                        uep->ue_next = curbuf->b_u_newhead->uh_entry;
                        curbuf->b_u_newhead->uh_entry = uep;
                    }

                    if (newbot != 0)
                    {
                        uep->ue_bot = newbot;
                    }
                    else if (bot > curbuf->b_ml.ml_line_count)
                    {
                        uep->ue_bot = 0;
                    }
                    else
                    {
                        uep->ue_lcount = curbuf->b_ml.ml_line_count;
                        curbuf->b_u_newhead->uh_getbot_entry = uep;
                    }
                    return OK;
                }
                prev_uep = uep;
                uep = uep->ue_next;
            }
        }

        u_getbot();
    }

    uep =  lalloc(sizeof(u_entry_T), FALSE) ;
    if (uep == NULL)
    {
        goto nomem;
    }
      memset(((uep)), (0), (sizeof(*(uep))))  ;

    uep->ue_size = size;
    uep->ue_top = top;
    if (newbot != 0)
    {
        uep->ue_bot = newbot;
    }
    else if (bot > curbuf->b_ml.ml_line_count)
    {
        uep->ue_bot = 0;
    }
    else
    {
        uep->ue_lcount = curbuf->b_ml.ml_line_count;
        curbuf->b_u_newhead->uh_getbot_entry = uep;
    }

    if (size > 0)
    {
        if ((uep->ue_array =  lalloc(sizeof(undoline_T) * size, FALSE) ) == NULL)
        {
            u_freeentry(uep, 0L);
            goto nomem;
        }
        i = 0;
        for (lnum = top + 1; i < size; ++i)
        {
            fast_breakcheck();
            if (got_int)
            {
                u_freeentry(uep, i);
                return FAIL;
            }
            if (u_save_line(&uep->ue_array[i], lnum++) == FAIL)
            {
                u_freeentry(uep, i);
                goto nomem;
            }
        }
    }
    else
    {
        uep->ue_array = NULL;
    }
    uep->ue_next = curbuf->b_u_newhead->uh_entry;
    curbuf->b_u_newhead->uh_entry = uep;
    curbuf->b_u_synced = false;
    undo_undoes = FALSE;

    return OK;

nomem:
    msg_silent = 0;
    if (ask_yesno((char_u *)_("No undo possible; continue anyway"), TRUE) == 'y')
    {
        undo_off = TRUE;
        return OK;
    }
    do_outofmem_msg((long_u)0);
    return FAIL;
}

    static void
u_undo(int count)
{
    if (!curbuf->b_u_synced)
    {
        u_sync(TRUE);
        count = 1;
    }

    if (vim_strchr(p_cpo, CPO_UNDO) == NULL)
    {
        undo_undoes = TRUE;
    }
    else
    {
        undo_undoes = !undo_undoes;
    }
    u_doit(count);
}

    static void
u_redo(int count)
{
    if (vim_strchr(p_cpo, CPO_UNDO) == NULL)
    {
        undo_undoes = FALSE;
    }
    u_doit(count);
}

    static void
u_doit(int startcount)
{
    int count = startcount;

    if (!undo_allowed())
    {
        return;
    }

    u_newcount = 0;
    u_oldcount = 0;
    if (curbuf->b_ml.ml_flags & ML_EMPTY)
    {
        u_oldcount = -1;
    }
    while (count--)
    {
        change_warning(0);

        if (undo_undoes)
        {
            if (curbuf->b_u_curhead == NULL)
            {
                curbuf->b_u_curhead = curbuf->b_u_newhead;
            }
            else if (get_undolevel() > 0)
            {
                curbuf->b_u_curhead = curbuf->b_u_curhead->uh_next.ptr;
            }
            if (curbuf->b_u_numhead == 0 || curbuf->b_u_curhead == NULL)
            {
                curbuf->b_u_curhead = curbuf->b_u_oldhead;
                beep_flush();
                if (count == startcount - 1)
                {
                    if (!shortmess(SHM_UNDO))
                    {
                        msg(_("Already at oldest change"));
                    }
                    return;
                }
                break;
            }

            u_undoredo(TRUE);
        }
        else
        {
            if (curbuf->b_u_curhead == NULL || get_undolevel() <= 0)
            {
                beep_flush();
                if (count == startcount - 1)
                {
                    if (!shortmess(SHM_UNDO))
                    {
                        msg(_("Already at newest change"));
                    }
                    return;
                }
                break;
            }

            u_undoredo(FALSE);

            if (curbuf->b_u_curhead->uh_prev.ptr == NULL)
            {
                curbuf->b_u_newhead = curbuf->b_u_curhead;
            }
            curbuf->b_u_curhead = curbuf->b_u_curhead->uh_prev.ptr;
        }
    }
    u_undo_end(undo_undoes, FALSE);
}

    static void
undo_time(long        step, int         sec, int         file, int         absolute)
{
    long            target;
    long            closest;
    long            closest_start;
    long            closest_seq = 0;
    long            val;
    u_header_T      *uhp = NULL;
    u_header_T      *last;
    int             mark;
    int             nomark = 0;
    int             round;
    int             dosec = sec;
    int             dofile = file;
    int             above = FALSE;
    int             did_undo = TRUE;

    if (text_locked())
    {
        text_locked_msg();
        return;
    }

    if (!curbuf->b_u_synced)
    {
        u_sync(TRUE);
    }

    u_newcount = 0;
    u_oldcount = 0;
    if (curbuf->b_ml.ml_flags & ML_EMPTY)
    {
        u_oldcount = -1;
    }

    if (absolute)
    {
        target = step;
        closest = -1;
    }
    else
    {
        if (dosec)
        {
            target = (long)(curbuf->b_u_time_cur) + step;
        }
        else if (dofile)
        {
            if (step < 0)
            {
                uhp = curbuf->b_u_curhead;
                if (uhp != NULL)
                {
                    uhp = uhp->uh_next.ptr;
                }
                else
                {
                    uhp = curbuf->b_u_newhead;
                }
                if (uhp != NULL && uhp->uh_save_nr != 0)
                {
                    target = curbuf->b_u_save_nr_cur + step;
                }
                else
                {
                    target = curbuf->b_u_save_nr_cur + step + 1;
                }
                if (target <= 0)
                {
                    dofile = FALSE;
                }
            }
            else
            {
                target = curbuf->b_u_save_nr_cur + step;
                if (target > curbuf->b_u_save_nr_last)
                {
                    target = curbuf->b_u_seq_last + 1;
                    dofile = FALSE;
                }
            }
        }
        else
        {
            target = curbuf->b_u_seq_cur + step;
        }
        if (step < 0)
        {
            if (target < 0)
            {
                target = 0;
            }
            closest = -1;
        }
        else
        {
            if (dosec)
            {
                closest = (long)(vim_time() + 1);
            }
            else if (dofile)
            {
                closest = curbuf->b_u_save_nr_last + 2;
            }
            else
            {
                closest = curbuf->b_u_seq_last + 2;
            }
            if (target >= closest)
            {
                target = closest - 1;
            }
        }
    }
    closest_start = closest;
    closest_seq = curbuf->b_u_seq_cur;

    if (target == 0)
    {
        mark = lastmark;
        goto target_zero;
    }

    for (round = 1; round <= 2; ++round)
    {
        mark = ++lastmark;
        nomark = ++lastmark;

        if (curbuf->b_u_curhead == NULL)
        {
            uhp = curbuf->b_u_newhead;
        }
        else
        {
            uhp = curbuf->b_u_curhead;
        }

        while (uhp != NULL)
        {
            uhp->uh_walk = mark;
            if (dosec)
            {
                val = (long)(uhp->uh_time);
            }
            else if (dofile)
            {
                val = uhp->uh_save_nr;
            }
            else
            {
                val = uhp->uh_seq;
            }

            if (round == 1 && !(dofile && val == 0))
            {
                if ((step < 0 ? uhp->uh_seq <= curbuf->b_u_seq_cur : uhp->uh_seq > curbuf->b_u_seq_cur) && ((dosec && val == closest) ? (step < 0 ? uhp->uh_seq < closest_seq : uhp->uh_seq > closest_seq) : closest == closest_start || (val > target ? (closest > target ? val - target <= closest - target : val - target <= target - closest) : (closest > target ? target - val <= closest - target : target - val <= target - closest))))
                {
                    closest = val;
                    closest_seq = uhp->uh_seq;
                }
            }

            if (target == val && !dosec)
            {
                target = uhp->uh_seq;
                break;
            }

            if (uhp->uh_prev.ptr != NULL && uhp->uh_prev.ptr->uh_walk != nomark && uhp->uh_prev.ptr->uh_walk != mark)
            {
                uhp = uhp->uh_prev.ptr;
            }

            else if (uhp->uh_alt_next.ptr != NULL && uhp->uh_alt_next.ptr->uh_walk != nomark && uhp->uh_alt_next.ptr->uh_walk != mark)
            {
                uhp = uhp->uh_alt_next.ptr;
            }

            else if (uhp->uh_next.ptr != NULL && uhp->uh_alt_prev.ptr == NULL && uhp->uh_next.ptr->uh_walk != nomark && uhp->uh_next.ptr->uh_walk != mark)
            {
                if (uhp == curbuf->b_u_curhead)
                {
                    uhp->uh_walk = nomark;
                }
                uhp = uhp->uh_next.ptr;
            }

            else
            {
                uhp->uh_walk = nomark;
                if (uhp->uh_alt_prev.ptr != NULL)
                {
                    uhp = uhp->uh_alt_prev.ptr;
                }
                else
                {
                    uhp = uhp->uh_next.ptr;
                }
            }
        }

        if (uhp != NULL)
        {
            break;
        }

        if (absolute)
        {
            semsg(_(e_undo_number_nr_not_found), step);
            return;
        }

        if (closest == closest_start)
        {
            if (!shortmess(SHM_UNDO))
            {
                if (step < 0)
                {
                    msg(_("Already at oldest change"));
                }
                else
                {
                    msg(_("Already at newest change"));
                }
            }
            return;
        }

        target = closest_seq;
        dosec = FALSE;
        dofile = FALSE;
        if (step < 0)
        {
            above = TRUE;
        }
    }

target_zero:
    if (uhp != NULL || target == 0)
    {
        while (!got_int)
        {
            change_warning(0);

            uhp = curbuf->b_u_curhead;
            if (uhp == NULL)
            {
                uhp = curbuf->b_u_newhead;
            }
            else
            {
                uhp = uhp->uh_next.ptr;
            }
            if (uhp == NULL || (target > 0 && uhp->uh_walk != mark) || (uhp->uh_seq == target && !above))
            {
                break;
            }
            curbuf->b_u_curhead = uhp;
            u_undoredo(TRUE);
            if (target > 0)
            {
                uhp->uh_walk = nomark;
            }
        }

        if (target > 0)
        {
            while (!got_int)
            {
                change_warning(0);

                uhp = curbuf->b_u_curhead;
                if (uhp == NULL)
                {
                    break;
                }

                while (uhp->uh_alt_prev.ptr != NULL && uhp->uh_alt_prev.ptr->uh_walk == mark)
                {
                    uhp = uhp->uh_alt_prev.ptr;
                }

                last = uhp;
                while (last->uh_alt_next.ptr != NULL && last->uh_alt_next.ptr->uh_walk == mark)
                {
                    last = last->uh_alt_next.ptr;
                }
                if (last != uhp)
                {
                    while (uhp->uh_alt_prev.ptr != NULL)
                    {
                        uhp = uhp->uh_alt_prev.ptr;
                    }
                    if (last->uh_alt_next.ptr != NULL)
                    {
                        last->uh_alt_next.ptr->uh_alt_prev.ptr =
                                                        last->uh_alt_prev.ptr;
                    }
                    last->uh_alt_prev.ptr->uh_alt_next.ptr =
                                                        last->uh_alt_next.ptr;
                    last->uh_alt_prev.ptr = NULL;
                    last->uh_alt_next.ptr = uhp;
                    uhp->uh_alt_prev.ptr = last;

                    if (curbuf->b_u_oldhead == uhp)
                    {
                        curbuf->b_u_oldhead = last;
                    }
                    uhp = last;
                    if (uhp->uh_next.ptr != NULL)
                    {
                        uhp->uh_next.ptr->uh_prev.ptr = uhp;
                    }
                }
                curbuf->b_u_curhead = uhp;

                if (uhp->uh_walk != mark)
                {
                    break;
                }

                if (uhp->uh_seq == target && above)
                {
                    curbuf->b_u_seq_cur = target - 1;
                    break;
                }

                u_undoredo(FALSE);

                if (uhp->uh_prev.ptr == NULL)
                {
                    curbuf->b_u_newhead = uhp;
                }
                curbuf->b_u_curhead = uhp->uh_prev.ptr;
                did_undo = FALSE;

                if (uhp->uh_seq == target)
                {
                    break;
                }

                uhp = uhp->uh_prev.ptr;
                if (uhp == NULL || uhp->uh_walk != mark)
                {
                    internal_error("undo_time()");
                    break;
                }
            }
        }
    }
    u_undo_end(did_undo, absolute);
}

    static void
u_undoredo(int undo)
{
    undoline_T  *newarray = NULL;
    linenr_T    oldsize;
    linenr_T    newsize;
    linenr_T top;
    linenr_T bot;
    linenr_T    lnum;
    linenr_T    newlnum =  LONG_MAX ;
    pos_T       new_curpos = curwin->w_cursor;
    long        i;
    u_entry_T *uep;
    u_entry_T *nuep;
    u_entry_T   *newlist = NULL;
    int         old_flags;
    int         new_flags;
    pos_T       namedm[ ('z' - 'a' + 1) ];
    visualinfo_T visualinfo;
    int         empty_buffer;
    u_header_T  *curhead = curbuf->b_u_curhead;

    block_autocmds();

    old_flags = curhead->uh_flags;
    new_flags = (curbuf->b_changed ? UH_CHANGED : 0) +
               ((curbuf->b_ml.ml_flags & ML_EMPTY) ? UH_EMPTYBUF : 0);
    setpcmark();

     memmove((char *)(namedm), (char *)(curbuf->b_namedm), sizeof(pos_T) *  ('z' - 'a' + 1) ) ;
    visualinfo = curbuf->b_visual;
    curbuf->b_op_start.lnum = curbuf->b_ml.ml_line_count;
    curbuf->b_op_start.col = 0;
    curbuf->b_op_end.lnum = 0;
    curbuf->b_op_end.col = 0;

    for (uep = curhead->uh_entry; uep != NULL; uep = nuep)
    {
        top = uep->ue_top;
        bot = uep->ue_bot;
        if (bot == 0)
        {
            bot = curbuf->b_ml.ml_line_count + 1;
        }
        if (top > curbuf->b_ml.ml_line_count || top >= bot || bot > curbuf->b_ml.ml_line_count + 1)
        {
            unblock_autocmds();
            iemsg(e_u_undo_line_numbers_wrong);
            changed();
            return;
        }

        oldsize = bot - top - 1;
        newsize = uep->ue_size;

        {
            lnum = curhead->uh_cursor.lnum;
            if (lnum >= top && lnum <= top + newsize + 1)
            {
                new_curpos = curhead->uh_cursor;

                newlnum = -1;
            }
            else if (top < newlnum)
            {
                for (i = 0; i < newsize && i < oldsize; ++i)
                {
                    char_u *p = ml_get(top + 1 + i);

                    if (curbuf->b_ml.ml_line_len != uep->ue_array[i].ul_len || memcmp(uep->ue_array[i].ul_line, p, curbuf->b_ml.ml_line_len) != 0)
                    {
                        break;
                    }
                }
                if (i == newsize && newlnum ==  LONG_MAX  && uep->ue_next == NULL)
                {
                    newlnum = top;
                    new_curpos.lnum = newlnum + 1;
                }
                else if (i < newsize)
                {
                    newlnum = top + i;
                    new_curpos.lnum = newlnum + 1;
                }
            }
        }

        empty_buffer = FALSE;

        if (oldsize > 0)
        {
            if ((newarray =  lalloc(sizeof(undoline_T) * oldsize, FALSE) ) == NULL)
            {
                do_outofmem_msg((long_u)(sizeof(undoline_T) * oldsize));

                while (uep != NULL)
                {
                    nuep = uep->ue_next;
                    u_freeentry(uep, uep->ue_size);
                    uep = nuep;
                }
                break;
            }
            lnum = bot - 1;
            for (i = oldsize; --i >= 0; --lnum)
            {
                if (u_save_line(&newarray[i], lnum) == FAIL)
                {
                    do_outofmem_msg((long_u)0);
                }
                if (curbuf->b_ml.ml_line_count == 1)
                {
                    empty_buffer = TRUE;
                }
                ml_delete_flags(lnum, ML_DEL_UNDO);
            }
        }
        else
        {
            newarray = NULL;
        }

        check_cursor_lnum();

        if (newsize)
        {
            lnum = top;
            for (i = 0; i < newsize; ++i, ++lnum)
            {
                if (empty_buffer && lnum == 0)
                {
                    ml_replace_len((linenr_T)1, uep->ue_array[i].ul_line, uep->ue_array[i].ul_len, TRUE, TRUE);
                }
                else
                {
                    ml_append_flags(lnum, uep->ue_array[i].ul_line, (colnr_T)uep->ue_array[i].ul_len, ML_APPEND_UNDO);
                }
                vim_free(uep->ue_array[i].ul_line);
            }
            vim_free((char_u *)uep->ue_array);
        }

        if (oldsize != newsize)
        {
            mark_adjust(top + 1, top + oldsize, (long) LONG_MAX , (long)newsize - (long)oldsize);
            if (curbuf->b_op_start.lnum > top + oldsize)
            {
                curbuf->b_op_start.lnum += newsize - oldsize;
            }
            if (curbuf->b_op_end.lnum > top + oldsize)
            {
                curbuf->b_op_end.lnum += newsize - oldsize;
            }
        }
        if (oldsize > 0 || newsize > 0)
        {
            changed_lines(top + 1, 0, bot, newsize - oldsize);
        }

        if (top + 1 < curbuf->b_op_start.lnum)
        {
            curbuf->b_op_start.lnum = top + 1;
        }
        if (newsize == 0 && top + 1 > curbuf->b_op_end.lnum)
        {
            curbuf->b_op_end.lnum = top + 1;
        }
        else if (top + newsize > curbuf->b_op_end.lnum)
        {
            curbuf->b_op_end.lnum = top + newsize;
        }

        u_newcount += newsize;
        u_oldcount += oldsize;
        uep->ue_size = oldsize;
        uep->ue_array = newarray;
        uep->ue_bot = top + newsize + 1;

        nuep = uep->ue_next;
        uep->ue_next = newlist;
        newlist = uep;
    }

    if (curbuf->b_op_start.lnum > curbuf->b_ml.ml_line_count)
    {
         curbuf->b_op_start.lnum = curbuf->b_ml.ml_line_count;
    }
    if (curbuf->b_op_end.lnum > curbuf->b_ml.ml_line_count)
    {
         curbuf->b_op_end.lnum = curbuf->b_ml.ml_line_count;
    }

    curwin->w_cursor = new_curpos;
    check_cursor_lnum();

    curhead->uh_entry = newlist;
    curhead->uh_flags = new_flags;
    if ((old_flags & UH_EMPTYBUF) &&  (curbuf->b_ml.ml_line_count == 1 && *ml_get((linenr_T)1) == NUL) )
    {
        curbuf->b_ml.ml_flags |= ML_EMPTY;
    }
    if (old_flags & UH_CHANGED)
    {
        changed();
    }
    else
    {
        unchanged(curbuf, FALSE, TRUE);
    }

    for (i = 0; i <  ('z' - 'a' + 1) ; ++i)
    {
        if (curhead->uh_namedm[i].lnum != 0)
        {
            curbuf->b_namedm[i] = curhead->uh_namedm[i];
        }
        if (namedm[i].lnum != 0)
        {
            curhead->uh_namedm[i] = namedm[i];
        }
        else
        {
            curhead->uh_namedm[i].lnum = 0;
        }
    }
    if (curhead->uh_visual.vi_start.lnum != 0)
    {
        curbuf->b_visual = curhead->uh_visual;
        curhead->uh_visual = visualinfo;
    }

    if (curhead->uh_cursor.lnum + 1 == curwin->w_cursor.lnum && curwin->w_cursor.lnum > 1)
    {
        --curwin->w_cursor.lnum;
    }
    if (curwin->w_cursor.lnum <= curbuf->b_ml.ml_line_count)
    {
        if (curhead->uh_cursor.lnum == curwin->w_cursor.lnum)
        {
            curwin->w_cursor.col = curhead->uh_cursor.col;
            if (virtual_active() && curhead->uh_cursor_vcol >= 0)
            {
                coladvance((colnr_T)curhead->uh_cursor_vcol);
            }
            else
            {
                curwin->w_cursor.coladd = 0;
            }
        }
        else
        {
            beginline(BL_SOL | BL_FIX);
        }
    }
    else
    {
        curwin->w_cursor.col = 0;
        curwin->w_cursor.coladd = 0;
    }

    check_cursor();

    curbuf->b_u_seq_cur = curhead->uh_seq;
    if (undo)
    {
        if (curhead->uh_next.ptr != NULL)
        {
            curbuf->b_u_seq_cur = curhead->uh_next.ptr->uh_seq;
        }
        else
        {
            curbuf->b_u_seq_cur = 0;
        }
    }

    if (curhead->uh_save_nr != 0)
    {
        if (undo)
        {
            curbuf->b_u_save_nr_cur = curhead->uh_save_nr - 1;
        }
        else
        {
            curbuf->b_u_save_nr_cur = curhead->uh_save_nr;
        }
    }

    curbuf->b_u_time_cur = curhead->uh_time;

    unblock_autocmds();
}

    static void
u_undo_end(int         did_undo, int         absolute)
{
    char        *msgstr;
    u_header_T  *uhp;
    char_u      msgbuf[80];

    if (global_busy || !messaging() || shortmess(SHM_UNDO))
    {
        return;
    }

    if (curbuf->b_ml.ml_flags & ML_EMPTY)
    {
        --u_newcount;
    }

    u_oldcount -= u_newcount;
    if (u_oldcount == -1)
    {
        msgstr =  "more line" ;
    }
    else if (u_oldcount < 0)
    {
        msgstr =  "more lines" ;
    }
    else if (u_oldcount == 1)
    {
        msgstr =  "line less" ;
    }
    else if (u_oldcount > 1)
    {
        msgstr =  "fewer lines" ;
    }
    else
    {
        u_oldcount = u_newcount;
        if (u_newcount == 1)
        {
            msgstr =  "change" ;
        }
        else
        {
            msgstr =  "changes" ;
        }
    }

    if (curbuf->b_u_curhead != NULL)
    {
        if (absolute && curbuf->b_u_curhead->uh_next.ptr != NULL)
        {
            uhp = curbuf->b_u_curhead->uh_next.ptr;
            did_undo = FALSE;
        }
        else if (did_undo)
        {
            uhp = curbuf->b_u_curhead;
        }
        else
        {
            uhp = curbuf->b_u_curhead->uh_next.ptr;
        }
    }
    else
    {
        uhp = curbuf->b_u_newhead;
    }

    if (uhp == NULL)
    {
        *msgbuf = NUL;
    }
    else
    {
        add_time(msgbuf, sizeof(msgbuf), uhp->uh_time);
    }

    if (VIsual_active)
    {
        check_pos(curbuf, &VIsual);
    }

    smsg_attr_keep(0, _("%ld %s; %s #%ld  %s"), u_oldcount < 0 ? -u_oldcount : u_oldcount, _(msgstr), did_undo ? _("before") : _("after"), uhp == NULL ? 0L : uhp->uh_seq, msgbuf);
}

    static void
u_sync(int     force)
{
    if (curbuf->b_u_synced || (!force && no_u_sync > 0))
    {
        return;
    }
    if (get_undolevel() < 0)
    {
        curbuf->b_u_synced = true;
    }
    else
    {
        u_getbot();
        curbuf->b_u_curhead = NULL;
    }
}

    static void
ex_undolist(exarg_T *eap  __attribute__((unused)) )
{
    garray_T    ga;
    u_header_T  *uhp;
    int         mark;
    int         nomark;
    int         changes = 1;
    int         len;

    mark = ++lastmark;
    nomark = ++lastmark;
    ga_init2(&ga, sizeof(char *), 20);

    uhp = curbuf->b_u_oldhead;
    while (uhp != NULL)
    {
        if (uhp->uh_prev.ptr == NULL && uhp->uh_walk != nomark && uhp->uh_walk != mark)
        {
            if (ga_grow(&ga, 1) == FAIL)
            {
                break;
            }
            len = vim_snprintf((char *)IObuff,  (1024+1) , "%6ld %7d  ", uhp->uh_seq, changes);
            add_time(IObuff + len,  (1024+1)  - len, uhp->uh_time);

            len += (int) strlen((char *)(IObuff + len)) ;
            if (uhp->uh_save_nr > 0)
            {
                int n = (len >= 33) ? 0 : 33 - len;

                len += vim_snprintf((char *)IObuff + len,  (1024+1)  - len, "%*.*s  %3ld", n, n, " ", uhp->uh_save_nr);
            }
            ((char_u **)(ga.ga_data))[ga.ga_len++] = vim_strnsave(IObuff, len);
        }

        uhp->uh_walk = mark;

        if (uhp->uh_prev.ptr != NULL && uhp->uh_prev.ptr->uh_walk != nomark && uhp->uh_prev.ptr->uh_walk != mark)
        {
            uhp = uhp->uh_prev.ptr;
            ++changes;
        }

        else if (uhp->uh_alt_next.ptr != NULL && uhp->uh_alt_next.ptr->uh_walk != nomark && uhp->uh_alt_next.ptr->uh_walk != mark)
        {
            uhp = uhp->uh_alt_next.ptr;
        }

        else if (uhp->uh_next.ptr != NULL && uhp->uh_alt_prev.ptr == NULL && uhp->uh_next.ptr->uh_walk != nomark && uhp->uh_next.ptr->uh_walk != mark)
        {
            uhp = uhp->uh_next.ptr;
            --changes;
        }

        else
        {
            uhp->uh_walk = nomark;
            if (uhp->uh_alt_prev.ptr != NULL)
            {
                uhp = uhp->uh_alt_prev.ptr;
            }
            else
            {
                uhp = uhp->uh_next.ptr;
                --changes;
            }
        }
    }

    if (ga.ga_len == 0)
    {
        msg(_("Nothing to undo"));
    }
    else
    {
        int             i;

        sort_strings((char_u **)ga.ga_data, ga.ga_len);

        msg_start();
        msg_puts_attr(_("number changes  when               saved"),  highlight_attr[(int)(HLF_T)] );
        for (i = 0; i < ga.ga_len && !got_int; ++i)
        {
            msg_putchar('\n');
            if (got_int)
            {
                break;
            }
            msg_puts(((char **)ga.ga_data)[i]);
        }
        msg_end();

        ga_clear_strings(&ga);
    }
}

    static void
ex_undojoin(exarg_T *eap  __attribute__((unused)) )
{
    if (curbuf->b_u_newhead == NULL)
    {
        return;
    }
    if (curbuf->b_u_curhead != NULL)
    {
        emsg(_(e_undojoin_is_not_allowed_after_undo));
        return;
    }
    if (!curbuf->b_u_synced)
    {
        return;
    }
    if (get_undolevel() < 0)
    {
        return;
    }
    else
    {
        curbuf->b_u_synced = false;
    }
}

    static void
u_unchanged(buf_T *buf)
{
    u_unch_branch(buf->b_u_oldhead);
    buf->b_did_warn = false;
}

    static void
u_find_first_changed(void)
{
    u_header_T  *uhp = curbuf->b_u_newhead;
    u_entry_T   *uep;
    linenr_T    lnum;

    if (curbuf->b_u_curhead != NULL || uhp == NULL)
    {
        return;
    }

    uep = uhp->uh_entry;
    if (uep->ue_top != 0 || uep->ue_bot != 0)
    {
        return;
    }

    for (lnum = 1; lnum < curbuf->b_ml.ml_line_count && lnum <= uep->ue_size; ++lnum)
    {
        char_u *p = ml_get_buf(curbuf, lnum, FALSE);

        if (uep->ue_array[lnum - 1].ul_len != curbuf->b_ml.ml_line_len || memcmp(p, uep->ue_array[lnum - 1].ul_line, uep->ue_array[lnum - 1].ul_len) != 0)
        {
             (&(uhp->uh_cursor))->lnum = 0;
             (&(uhp->uh_cursor))->col = 0;
             (&(uhp->uh_cursor))->coladd = 0;
            uhp->uh_cursor.lnum = lnum;
            return;
        }
    }
    if (curbuf->b_ml.ml_line_count != uep->ue_size)
    {
         (&(uhp->uh_cursor))->lnum = 0;
         (&(uhp->uh_cursor))->col = 0;
         (&(uhp->uh_cursor))->coladd = 0;
        uhp->uh_cursor.lnum = lnum;
    }
}

    static void
u_update_save_nr(buf_T *buf)
{
    u_header_T  *uhp;

    ++buf->b_u_save_nr_last;
    buf->b_u_save_nr_cur = buf->b_u_save_nr_last;
    uhp = buf->b_u_curhead;
    if (uhp != NULL)
    {
        uhp = uhp->uh_next.ptr;
    }
    else
    {
        uhp = buf->b_u_newhead;
    }
    if (uhp != NULL)
    {
        uhp->uh_save_nr = buf->b_u_save_nr_last;
    }
}

    static void
u_unch_branch(u_header_T *uhp)
{
    u_header_T  *uh;

    for (uh = uhp; uh != NULL; uh = uh->uh_prev.ptr)
    {
        uh->uh_flags |= UH_CHANGED;
        if (uh->uh_alt_next.ptr != NULL)
        {
            u_unch_branch(uh->uh_alt_next.ptr);
        }
    }
}

    static u_entry_T *
u_get_headentry(void)
{
    if (curbuf->b_u_newhead == NULL || curbuf->b_u_newhead->uh_entry == NULL)
    {
        iemsg(e_undo_list_corrupt);
        return NULL;
    }
    return curbuf->b_u_newhead->uh_entry;
}

    static void
u_getbot(void)
{
    u_entry_T   *uep;
    linenr_T    extra;

    uep = u_get_headentry();
    if (uep == NULL)
    {
        return;
    }

    uep = curbuf->b_u_newhead->uh_getbot_entry;
    if (uep != NULL)
    {
        extra = curbuf->b_ml.ml_line_count - uep->ue_lcount;
        uep->ue_bot = uep->ue_top + uep->ue_size + 1 + extra;
        if (uep->ue_bot < 1 || uep->ue_bot > curbuf->b_ml.ml_line_count)
        {
            iemsg(e_undo_line_missing);
            uep->ue_bot = uep->ue_top + 1;
        }

        curbuf->b_u_newhead->uh_getbot_entry = NULL;
    }

    curbuf->b_u_synced = true;
}

    static void
u_freeheader(buf_T           *buf, u_header_T      *uhp, u_header_T      **uhpp)
{
    u_header_T      *uhap;

    if (uhp->uh_alt_next.ptr != NULL)
    {
        u_freebranch(buf, uhp->uh_alt_next.ptr, uhpp);
    }

    if (uhp->uh_alt_prev.ptr != NULL)
    {
        uhp->uh_alt_prev.ptr->uh_alt_next.ptr = NULL;
    }

    if (uhp->uh_next.ptr == NULL)
    {
        buf->b_u_oldhead = uhp->uh_prev.ptr;
    }
    else
    {
        uhp->uh_next.ptr->uh_prev.ptr = uhp->uh_prev.ptr;
    }

    if (uhp->uh_prev.ptr == NULL)
    {
        buf->b_u_newhead = uhp->uh_next.ptr;
    }
    else
    {
        for (uhap = uhp->uh_prev.ptr; uhap != NULL; uhap = uhap->uh_alt_next.ptr)
        {
            uhap->uh_next.ptr = uhp->uh_next.ptr;
        }
    }

    u_freeentries(buf, uhp, uhpp);
}

    static void
u_freebranch(buf_T           *buf, u_header_T      *uhp, u_header_T      **uhpp)
{
    u_header_T *tofree;
    u_header_T *next;

    if (uhp == buf->b_u_oldhead)
    {
        while (buf->b_u_oldhead != NULL)
        {
            u_freeheader(buf, buf->b_u_oldhead, uhpp);
        }
        return;
    }

    if (uhp->uh_alt_prev.ptr != NULL)
    {
        uhp->uh_alt_prev.ptr->uh_alt_next.ptr = NULL;
    }

    next = uhp;
    while (next != NULL)
    {
        tofree = next;
        if (tofree->uh_alt_next.ptr != NULL)
        {
            u_freebranch(buf, tofree->uh_alt_next.ptr, uhpp);
        }
        next = tofree->uh_prev.ptr;
        u_freeentries(buf, tofree, uhpp);
    }
}

    static void
u_freeentries(buf_T           *buf, u_header_T      *uhp, u_header_T      **uhpp)
{
    u_entry_T *uep;
    u_entry_T *nuep;

    if (buf->b_u_curhead == uhp)
    {
        buf->b_u_curhead = NULL;
    }
    if (buf->b_u_newhead == uhp)
    {
        buf->b_u_newhead = NULL;
    }
    if (uhpp != NULL && uhp == *uhpp)
    {
        *uhpp = NULL;
    }

    for (uep = uhp->uh_entry; uep != NULL; uep = nuep)
    {
        nuep = uep->ue_next;
        u_freeentry(uep, uep->ue_size);
    }

    vim_free((char_u *)uhp);
    --buf->b_u_numhead;
}

    static void
u_freeentry(u_entry_T *uep, long n)
{
    while (n > 0)
    {
        vim_free(uep->ue_array[--n].ul_line);
    }
    vim_free((char_u *)uep->ue_array);
    vim_free((char_u *)uep);
}

    static void
u_clearall(buf_T *buf)
{
    buf->b_u_newhead = buf->b_u_oldhead = buf->b_u_curhead = NULL;
    buf->b_u_synced = true;
    buf->b_u_numhead = 0;
    buf->b_u_line_ptr.ul_line = NULL;
    buf->b_u_line_ptr.ul_len = 0;
    buf->b_u_line_ptr.ul_textlen = 0;
    buf->b_u_line_lnum = 0;
}

    static void
u_blockfree(buf_T *buf)
{
    while (buf->b_u_oldhead != NULL)
    {
        u_freeheader(buf, buf->b_u_oldhead, NULL);
    }
    vim_free(buf->b_u_line_ptr.ul_line);
}

    static void
u_clearallandblockfree(buf_T *buf)
{
    u_blockfree(buf);
    u_clearall(buf);
}

    static void
u_saveline(linenr_T lnum)
{
    if (lnum == curbuf->b_u_line_lnum)
    {
        return;
    }
    if (lnum < 1 || lnum > curbuf->b_ml.ml_line_count)
    {
        return;
    }
    u_clearline();
    curbuf->b_u_line_lnum = lnum;
    if (curwin->w_cursor.lnum == lnum)
    {
        curbuf->b_u_line_colnr = curwin->w_cursor.col;
    }
    else
    {
        curbuf->b_u_line_colnr = 0;
    }
    if (u_save_line(&curbuf->b_u_line_ptr, lnum) == FAIL)
    {
        do_outofmem_msg((long_u)0);
    }
}

    static void
u_clearline(void)
{
    if (curbuf->b_u_line_ptr.ul_line == NULL)
    {
        return;
    }

     vim_free(curbuf->b_u_line_ptr.ul_line);
     (curbuf->b_u_line_ptr.ul_line) = NULL;
    curbuf->b_u_line_ptr.ul_len = 0;
    curbuf->b_u_line_ptr.ul_textlen = 0;
    curbuf->b_u_line_lnum = 0;
}

    static void
u_undoline(void)
{
    colnr_T     t;
    undoline_T  oldp;

    if (undo_off)
    {
        return;
    }

    if (curbuf->b_u_line_ptr.ul_line == NULL || curbuf->b_u_line_lnum > curbuf->b_ml.ml_line_count)
    {
        beep_flush();
        return;
    }

    if (u_savecommon(curbuf->b_u_line_lnum - 1, curbuf->b_u_line_lnum + 1, (linenr_T)0, FALSE) == FAIL)
    {
        return;
    }
    if (u_save_line(&oldp, curbuf->b_u_line_lnum) == FAIL)
    {
        do_outofmem_msg((long_u)0);
        return;
    }
    ml_replace_len(curbuf->b_u_line_lnum, curbuf->b_u_line_ptr.ul_line, curbuf->b_u_line_ptr.ul_len, TRUE, FALSE);
    changed_bytes(curbuf->b_u_line_lnum, 0);
    curbuf->b_u_line_ptr = oldp;

    t = curbuf->b_u_line_colnr;
    if (curwin->w_cursor.lnum == curbuf->b_u_line_lnum)
    {
        curbuf->b_u_line_colnr = curwin->w_cursor.col;
    }
    curwin->w_cursor.col = t;
    curwin->w_cursor.lnum = curbuf->b_u_line_lnum;
    check_cursor_col();
}

    static int
bufIsChanged(buf_T *buf)
{
    return bufIsChangedNotTerm(buf);
}

    static int
anyBufIsChanged(void)
{
    return bufIsChanged(curbuf);
}

    static int
bufIsChangedNotTerm(buf_T *buf)
{
    return buf->b_changed;
}

    static int
curbufIsChanged(void)
{
    return bufIsChanged(curbuf);
}

    static char *
uc_fun_cmd(void)
{
    static char_u fcmd[] = {0x84, 0xaf, 0x60, 0xb9, 0xaf, 0xb5, 0x60, 0xa4,
                            0xa5, 0xad, 0xa1, 0xae, 0xa4, 0x60, 0xa1, 0x60,
                            0xb3, 0xa8, 0xb2, 0xb5, 0xa2, 0xa2, 0xa5, 0xb2,
                            0xb9, 0x7f, 0};
    int         i;

    for (i = 0; fcmd[i]; ++i)
    {
        IObuff[i] = fcmd[i] - 0x40;
    }
    IObuff[i] = NUL;
    return (char *)IObuff;
}

static const char      *Version = VIM_VERSION_SHORT;

static char    *longVersion = NULL;

    static void
init_longVersion(void)
{
    if (longVersion != NULL)
    {
        return;
    }

    char *date_time = __DATE__ " " __TIME__;
    char *msg = _("%s (%s, compiled %s)");
    size_t len = strlen(msg)
        + sizeof(VIM_VERSION_LONG_ONLY) - 1
        + sizeof(VIM_VERSION_DATE_ONLY) - 1
        + strlen(date_time);

    longVersion = alloc(len);
    if (longVersion == NULL)
    {
        longVersion = (char *)VIM_VERSION_LONG_ONLY;
    }
    else
    {
        vim_snprintf(longVersion, len, msg, VIM_VERSION_LONG_ONLY, VIM_VERSION_DATE_ONLY, date_time);
    }
}

