static_assert(sizeof(cmdnames) / sizeof(cmdnames[0]) == CMD_SIZE, "cmdnames[] and enum CMD_index have drifted apart");

static void frame_comp_pos(frame_T *topfrp, int *row, int *col);
static void frame_setheight(frame_T *curfrp, int height);
static void frame_setwidth(frame_T *curfrp, int width);
static void win_fix_scroll(int resize);
static void win_fix_cursor(int normal);
static void frame_new_height(frame_T *topfrp, int height, int topfirst, int wfh, int set_ch);
static void frame_new_width(frame_T *topfrp, int width, int leftfirst, int wfw);
static int win_alloc_firstwin(win_T *oldwin);
static void new_frame(win_T *wp);
static tabpage_T *alloc_tabpage(void);
static int frame_minheight(frame_T *topfrp, win_T *next_curwin);
static int win_enter_ext(win_T *wp, int flags);
static void frame_add_height(frame_T *frp, int n);
static void last_status_rec(frame_T *fr, int statusline);

static int frame_check_height(frame_T *topfrp, int height);
static int frame_check_width(frame_T *topfrp, int width);

static win_T *win_alloc(win_T *after, int hidden);

enum { WEE_UNDO_SYNC = 0x01 };
enum { WEE_CURWIN_INVALID = 0x02 };
enum { WEE_TRIGGER_NEW_AUTOCMDS = 0x04 };
enum { WEE_TRIGGER_ENTER_AUTOCMDS = 0x08 };
enum { WEE_TRIGGER_LEAVE_AUTOCMDS = 0x10 };

    static int
win_valid(win_T *win)
{
    return win != NULL && win == curwin;
}

    static int
win_valid_any_tab(win_T *win)
{
    return win != NULL && win == curwin;
}

    static void
win_init_empty(win_T *wp)
{
    redraw_win_later(wp, UPD_NOT_VALID);
    wp->w_lines_valid = 0;
    wp->w_cursor.lnum = 1;
    wp->w_curswant = wp->w_cursor.col = 0;
    wp->w_cursor.coladd = 0;
    wp->w_pcmark.lnum = 1;
    wp->w_pcmark.col = 0;
    wp->w_prev_pcmark.lnum = 0;
    wp->w_prev_pcmark.col = 0;
    wp->w_topline = 1;
    wp->w_botline = 2;
    wp->w_valid = 0;
}

    static void
curwin_init(void)
{
    win_init_empty(curwin);
}

    static void
snapshot_windows_scroll_size(void)
{
    win_T *wp;
     wp = curwin;
    wp->w_last_topline = wp->w_topline;
    wp->w_last_leftcol = wp->w_leftcol;
    wp->w_last_skipcol = wp->w_skipcol;
    wp->w_last_width = wp->w_width;
    wp->w_last_height = wp->w_height;
}

static int did_initial_scroll_size_snapshot = FALSE;

    static void
may_make_initial_scroll_size_snapshot(void)
{
    if (!did_initial_scroll_size_snapshot)
    {
        did_initial_scroll_size_snapshot = TRUE;
        snapshot_windows_scroll_size();
    }
}

static int min_set_ch = 1;

    static void
frame_new_height(frame_T     *topfrp, int         height, int         topfirst, int         wfh, int         set_ch)
{
    if (set_ch)
    {
        int new_ch = MAX(min_set_ch, p_ch + topfrp->fr_height - height);
        int save_ch = min_set_ch;
        if (new_ch != p_ch)
        {
            set_option_value((char_u *)"cmdheight", new_ch, NULL, 0);
        }
        min_set_ch = save_ch;
        height = MIN(height,  (Rows - p_ch) );
    }
    win_new_height(topfrp->fr_win, height - topfrp->fr_win->w_status_height -  0 );
    topfrp->fr_height = height;
}

    static void
frame_new_width(frame_T     *topfrp, int         width, int         leftfirst, int         wfw)
{
    win_T       *wp;

    wp = topfrp->fr_win;
    wp->w_vsep_width = 0;
    win_new_width(wp, width - wp->w_vsep_width);
    topfrp->fr_width = width;
}

    static int
frame_minheight(frame_T *topfrp, win_T *next_curwin)
{
    int         m;

    if (topfrp->fr_win == next_curwin)
    {
        m = p_wh + topfrp->fr_win->w_status_height;
    }
    else
    {
        m = p_wmh + topfrp->fr_win->w_status_height;
        if (topfrp->fr_win == curwin && next_curwin == NULL)
        {
            if (p_wmh == 0)
            {
                ++m;
            }
            m +=  0 ;
        }
    }

    return m;
}

    static void
unuse_tabpage(tabpage_T *tp)
{
    tp->tp_topframe = topframe;
    tp->tp_curwin = curwin;
}

static int command_frame_height = TRUE;

    static int
win_alloc_first(void)
{
    if (win_alloc_firstwin(NULL) == FAIL)
    {
        return FAIL;
    }

    curtab = alloc_tabpage();
    if (curtab == NULL)
    {
        return FAIL;
    }
    unuse_tabpage(curtab);

    return OK;
}

    static int
win_alloc_firstwin(win_T *oldwin)
{
    curwin = win_alloc(NULL, FALSE);
    if (curwin == NULL)
    {
        return FAIL;
    }
    curbuf = buflist_new(NULL, NULL, 1L, BLN_LISTED);
    if (curbuf == NULL)
    {
        return FAIL;
    }
    curwin->w_buffer = curbuf;
    curbuf->b_nwindows = 1;
    curwin_init();

    new_frame(curwin);
    if (curwin->w_frame == NULL)
    {
        return FAIL;
    }
    topframe = curwin->w_frame;
    topframe->fr_width =  Columns ;
    topframe->fr_height = Rows - p_ch;

    return OK;
}

    static void
new_frame(win_T *wp)
{
    frame_T *frp =  (frame_T *)alloc_clear(sizeof(frame_T)) ;

    wp->w_frame = frp;
    if (frp == NULL)
    {
        return;
    }
    frp->fr_layout = FR_LEAF;
    frp->fr_win = wp;
}

    static void
win_init_size(void)
{
    curwin->w_height =  (Rows - p_ch) ;
    curwin->w_prev_height =  (Rows - p_ch) ;
    topframe->fr_height =  (Rows - p_ch) ;
    curwin->w_width = topframe->fr_width;
}

    static tabpage_T *
alloc_tabpage(void)
{
    tabpage_T   *tp;

    tp =  (tabpage_T *)alloc_clear(sizeof(tabpage_T)) ;
    if (tp == NULL)
    {
        return NULL;
    }

    tp->tp_ch_used = p_ch;

    return tp;
}

    static void
goto_tabpage_tp(tabpage_T   *tp, int         trigger_enter_autocmds, int         trigger_leave_autocmds)
{
    set_keep_msg(NULL, 0);

    skip_win_fix_scroll = TRUE;
    skip_win_fix_scroll = FALSE;
}

    static void
goto_tabpage_win(tabpage_T *tp, win_T *wp)
{
    goto_tabpage_tp(tp, TRUE, TRUE);
    if (curtab == tp && win_valid(wp))
    {
        win_enter(wp, TRUE);
    }
}

    static void
win_enter(win_T *wp, int undo_sync)
{
    (void)win_enter_ext(wp, (undo_sync ? WEE_UNDO_SYNC : 0) | WEE_TRIGGER_ENTER_AUTOCMDS | WEE_TRIGGER_LEAVE_AUTOCMDS);
}

    static int
win_enter_ext(win_T *wp, int flags)
{
    int         other_buffer = FALSE;
    int         curwin_invalid = (flags & WEE_CURWIN_INVALID);
    int         did_decrement = FALSE;

    if (wp == curwin && curwin_invalid == 0)
    {
        return FALSE;
    }

    if (curwin_invalid == 0 && (flags & WEE_TRIGGER_LEAVE_AUTOCMDS))
    {
        if (wp->w_buffer != curbuf)
        {
            other_buffer = TRUE;
            if (!win_valid(wp))
            {
                return FALSE;
            }
        }
        if (!win_valid(wp))
        {
            return FALSE;
        }
    }

    if ((flags & WEE_UNDO_SYNC) && curbuf != wp->w_buffer)
    {
        u_sync(FALSE);
    }

    if (*p_spk == 'c' && curwin_invalid == 0)
    {
        update_topline();
    }

    if (wp->w_buffer != curbuf)
    {
        buf_copy_options(wp->w_buffer, BCO_ENTER | BCO_NOHELP);
    }
    if (curwin_invalid == 0)
    {
        curwin->w_redr_status = true;
    }
    curwin = wp;
    curbuf = wp->w_buffer;
    check_cursor();
    if (!virtual_active())
    {
        curwin->w_cursor.coladd = 0;
    }
    if (*p_spk == 'c')
    {
        changed_line_abv_curs();
    }
    else
    {
        win_fix_cursor(get_real_state() & (MODE_NORMAL|MODE_CMDLINE|MODE_TERMINAL));
    }

    if (flags & WEE_TRIGGER_NEW_AUTOCMDS)
    {
    }
    if (flags & WEE_TRIGGER_ENTER_AUTOCMDS)
    {
        if (other_buffer)
        {
        }
    }

    curwin->w_redr_status = true;
    redraw_tabline = TRUE;
    redraw_vseps = TRUE;
    redraw_later(UPD_VALID);
    if (restart_edit)
    {
        redraw_later(UPD_VALID);
    }

    if (curwin->w_height < p_wh)
    {
        win_setheight((int)p_wh);
    }
    else if (curwin->w_height == 0)
    {
        win_setheight(1);
    }

    if (curwin->w_width < p_wiw)
    {
        win_setwidth((int)p_wiw);
    }

    return did_decrement;
}

    static win_T *
win_alloc(win_T *after, int hidden)
{
    win_T       *new_wp;

    new_wp =  (win_T *)alloc_clear(sizeof(win_T)) ;
    if (new_wp == NULL)
    {
        return NULL;
    }

    if (win_alloc_lines(new_wp) == FAIL)
    {
        vim_free(new_wp);
        return NULL;
    }

    block_autocmds();

    new_wp->w_wincol =  0 ;
    new_wp->w_width =  Columns ;

    new_wp->w_topline = 1;
    new_wp->w_botline = 2;
    new_wp->w_cursor.lnum = 1;
    new_wp->w_scbind_pos = 1;

    new_wp->w_allbuf_opt.wo_so = new_wp-> w_onebuf_opt.wo_so  = -1;
    new_wp->w_allbuf_opt.wo_sop = new_wp-> w_onebuf_opt.wo_sop  = -1;
    new_wp->w_allbuf_opt.wo_siso = new_wp-> w_onebuf_opt.wo_siso  = -1;

    new_wp->w_fraction = 0;
    new_wp->w_prev_fraction_row = -1;

    unblock_autocmds();
    new_wp->w_next_match_id = 1000;
    return new_wp;
}

