enum { FRACTION_MULT = 16384L };

    static void
set_fraction(win_T *wp)
{
    if (wp->w_height > 1)
    {
        wp->w_fraction = ((long)wp->w_wrow * FRACTION_MULT + FRACTION_MULT / 2) / (long)wp->w_height;
    }
}

    static void
win_fix_scroll(int resize)
{
    if (*p_spk == 'c')
    {
        return;
    }

    skip_update_topline = TRUE;
    win_T       *wp;
     wp = curwin;
    if (wp->w_height != wp->w_prev_height)
    {
        wp->w_do_win_fix_cursor = true;

        if (*p_spk == 's' && wp->w_winrow != wp->w_prev_winrow && wp->w_botline - 1 <= wp->w_buffer->b_ml.ml_line_count)
        {
            int diff = (wp->w_winrow - wp->w_prev_winrow)
                                      + (wp->w_height - wp->w_prev_height);
            pos_T cursor = wp->w_cursor;
            linenr_T topline = wp->w_topline;
            colnr_T skipcol = wp->w_skipcol;

            wp->w_cursor.lnum = wp->w_botline - 1;

            if (diff > 0)
            {
                cursor_down_inner(wp, diff);
            }
            else
            {
                cursor_up_inner(wp, -diff);
            }

            wp->w_fraction = FRACTION_MULT;
            scroll_to_fraction(wp, wp->w_prev_height);

            wp->w_cursor = cursor;
            if (wp->w_topline == topline)
            {
                wp->w_skipcol = skipcol;
            }
            wp->w_valid &= ~VALID_WCOL;
        }
        else if (wp == curwin)
        {
            wp->w_valid &= ~VALID_CROW;
        }

        invalidate_botline_win(wp);
        validate_botline_win(wp);
    }
    wp->w_prev_height = wp->w_height;
    wp->w_prev_winrow = wp->w_winrow;
    skip_update_topline = FALSE;
    if (!(get_real_state() & (MODE_NORMAL|MODE_CMDLINE|MODE_TERMINAL)))
    {
        win_fix_cursor(FALSE);
    }
    else if (resize)
    {
        win_fix_cursor(TRUE);
    }
}

    static void
win_fix_cursor(int normal)
{
    win_T       *wp = curwin;

    if (skip_win_fix_cursor || !wp->w_do_win_fix_cursor || wp->w_buffer->b_ml.ml_line_count < wp->w_height)
    {
        return;
    }

    wp->w_do_win_fix_cursor = false;
    long so = MIN(wp->w_height / 2, get_scrolloff_value());
    linenr_T lnum = wp->w_cursor.lnum;

    wp->w_cursor.lnum = wp->w_topline;
    cursor_down_inner(wp, so);
    linenr_T top = wp->w_cursor.lnum;

    wp->w_cursor.lnum = wp->w_botline - 1;
    cursor_up_inner(wp, so);
    linenr_T bot = wp->w_cursor.lnum;

    wp->w_cursor.lnum = lnum;

    linenr_T nlnum = 0;
    if (lnum > bot && (wp->w_botline - wp->w_buffer->b_ml.ml_line_count) != 1)
    {
        nlnum = bot;
    }
    else if (lnum < top && wp->w_topline != 1)
    {
        nlnum = (so == wp->w_height / 2) ? bot : top;
    }

    if (nlnum != 0)
    {
        if (normal)
        {
            setmark('\'');
            wp->w_cursor.lnum = nlnum;
        }
        else
        {
            wp->w_fraction = (nlnum == bot) ? FRACTION_MULT : 0;
            scroll_to_fraction(wp, wp->w_prev_height);
            validate_botline();
        }
    }
}

    static void
win_new_height(win_T *wp, int height)
{
    int         prev_height = wp->w_height;

    if (height < 0)
    {
        height = 0;
    }
    if (wp->w_height == height)
    {
        return;
    }

    if (wp->w_height > 0)
    {
        if (wp == curwin && *p_spk == 'c')
        {
            validate_cursor();
        }
        if (wp->w_height != prev_height)
        {
            return;
        }
        if (wp->w_wrow != wp->w_prev_fraction_row)
        {
            set_fraction(wp);
        }
    }

    wp->w_height = height;
    wp->w_redr_status = true;
    win_comp_scroll(wp);

    if (!exiting && *p_spk == 'c')
    {
        if (!wp-> w_onebuf_opt.wo_sms )
        {
            wp->w_skipcol = 0;
        }
        scroll_to_fraction(wp, prev_height);
    }
}

    static void
scroll_to_fraction(win_T *wp, int prev_height)
{
    linenr_T    lnum;
    int sline;
    int line_size;
    int         height = wp->w_height;

    if (height > 0 && (height < wp->w_buffer->b_ml.ml_line_count || wp->w_topline > 1))
    {
        lnum = wp->w_cursor.lnum;
        if (lnum < 1)
        {
            lnum = 1;
        }
        wp->w_wrow = ((long)wp->w_fraction * (long)height - 1L)
                                                               / FRACTION_MULT;
        line_size = plines_win_col(wp, lnum, (long)(wp->w_cursor.col)) - 1;
        sline = wp->w_wrow - line_size;

        if (sline >= 0)
        {
            int rows = plines_win(wp, lnum, FALSE);

            if (sline > wp->w_height - rows)
            {
                sline = wp->w_height - rows;
                wp->w_wrow -= rows - line_size;
            }
        }

        if (sline < 0)
        {
            int         want_row = wp->w_wrow;

            wp->w_wrow = line_size;
            if (wp->w_wrow >= wp->w_height && (wp->w_width - win_col_off(wp)) > 0)
            {
                colnr_T skipcol = wp->w_width - win_col_off(wp);

                --wp->w_wrow;
                while (wp->w_wrow > want_row)
                {
                    skipcol += wp->w_width - win_col_off(wp) + win_col_off2(wp);
                    --wp->w_wrow;
                }
                wp->w_skipcol = skipcol;
            }
        }
        else if (sline > 0)
        {
            while (sline > 0 && lnum > 1)
            {
                --lnum;
                    line_size = plines_win(wp, lnum, TRUE);
                sline -= line_size;
            }

            if (sline < 0)
            {
                lnum++;
                wp->w_wrow -= line_size + sline;
            }
            else if (sline > 0)
            {
                lnum = 1;
                wp->w_wrow -= sline;
            }
        }
        set_topline(wp, lnum);
    }

    if (wp == curwin)
    {
        curs_columns(FALSE);
    }

    if (prev_height > 0)
    {
        wp->w_prev_fraction_row = wp->w_wrow;
    }

    redraw_win_later(wp, UPD_SOME_VALID);
    invalidate_botline_win(wp);
}

    static void
win_new_width(win_T *wp, int width)
{
    wp->w_width = width < 0 ? 0 : width;
    wp->w_lines_valid = 0;
    changed_line_abv_curs_win(wp);
    invalidate_botline_win(wp);

    if (wp == curwin && *p_spk == 'c')
    {
        curs_columns(TRUE);
    }

    redraw_win_later(wp, UPD_NOT_VALID);
    wp->w_redr_status = true;
}

    static void
win_comp_scroll(win_T *wp)
{
    wp-> w_onebuf_opt.wo_scr  = ((unsigned)wp->w_height >> 1);
    if (wp-> w_onebuf_opt.wo_scr  == 0)
    {
        wp-> w_onebuf_opt.wo_scr  = 1;
    }
}

    static void
command_height(void)
{
    int         old_p_ch = curtab->tp_ch_used;
    frame_T     *frp = curwin->w_frame;

    if (p_ch > old_p_ch && command_frame_height)
    {
        int h = MIN(p_ch - old_p_ch, frp->fr_height - frame_minheight(frp, NULL));
        frame_add_height(frp, -h);
        old_p_ch += h;
    }
    if (p_ch < old_p_ch && command_frame_height)
    {
        frame_add_height(frp, (int)(old_p_ch - p_ch));
    }

    win_comp_pos();
    win_fix_scroll(true);
    cmdline_row = Rows - p_ch;
    redraw_cmdline = TRUE;

    if (msg_scrolled == 0 && full_screen)
    {
        screen_fill(cmdline_row, (int)Rows, 0, (int)Columns, ' ', ' ', 0);
        msg_row = cmdline_row;
    }

    curtab->tp_ch_used = p_ch;
    min_set_ch = p_ch;
}

    static void
frame_add_height(frame_T *frp, int n)
{
    frame_new_height(frp, frp->fr_height + n, FALSE, FALSE, FALSE);
}

    static void
last_status(int         morewin)
{
    last_status_rec(topframe, last_stl_height(morewin) > 0);
}

    static void
last_status_rec(frame_T *fr, int statusline)
{
    win_T       *wp;

    wp = fr->fr_win;
    if (wp->w_status_height != 0 && !statusline)
    {
        win_new_height(wp, wp->w_height + wp->w_status_height);
        wp->w_status_height = 0;
        comp_col();
    }
    else if (wp->w_status_height == 0 && statusline)
    {
        if (fr->fr_height <= frame_minheight(fr, NULL))
        {
            emsg(_(e_not_enough_room));
            return;
        }
        wp->w_status_height = statusline_height(wp);
        win_new_height(wp, wp->w_height - wp->w_status_height);
        comp_col();
        redraw_all_later(UPD_SOME_VALID);
    }
    if (abs(wp->w_height - wp->w_prev_height) == 1)
    {
        wp->w_prev_height = wp->w_height;
    }
}

    static int
statusline_height(win_T *wp  __attribute__((unused)) )
{
    int stl_height = 1;

    return stl_height;
}

    static int
last_stl_height(int         morewin)
{
    return (p_ls == 2 || (p_ls == 1 && (morewin || ! TRUE )))
                ? STATUS_HEIGHT : 0;
}

    static int
min_rows(void)
{
    if (curwin == NULL)
    {
        return MIN_LINES;
    }

    return frame_minheight(curtab->tp_topframe, NULL) + MIN_CMDHEIGHT;
}

    static int
min_rows_for_all_tabpages(void)
{
    int         total;
    tabpage_T   *tp;
    int         n;

    if (curwin == NULL)
    {
        return MIN_LINES;
    }

    total = 0;
     tp = curtab;
    n = frame_minheight(tp->tp_topframe, NULL);
    if (total < n)
    {
        total = n;
    }
    total += MIN_CMDHEIGHT;
    return total;
}

    static void
check_lnums_both(int do_curwin, int nested)
{
    win_T       *wp;

     wp = curwin;
if ((do_curwin || wp != curwin) && wp->w_buffer == curbuf)
{
    int need_adjust;

    if (!nested)
    {
        wp->w_save_cursor.w_cursor_save = wp->w_cursor;
        wp->w_save_cursor.w_topline_save = wp->w_topline;
    }

    need_adjust = wp->w_cursor.lnum > curbuf->b_ml.ml_line_count;
    if (need_adjust)
    {
        wp->w_cursor.lnum = curbuf->b_ml.ml_line_count;
    }
    if (need_adjust || !nested)
    {
        wp->w_save_cursor.w_cursor_corr = wp->w_cursor;
    }

    need_adjust = wp->w_topline > curbuf->b_ml.ml_line_count;
    if (need_adjust)
    {
        wp->w_topline = curbuf->b_ml.ml_line_count;
    }
    if (need_adjust || !nested)
    {
        wp->w_save_cursor.w_topline_corr = wp->w_topline;
    }
}
}

    static void
check_lnums(int do_curwin)
{
    check_lnums_both(do_curwin, FALSE);
}

