static oparg_T  *current_oap = NULL;

    static int
op_pending(void)
{
    return !(current_oap != NULL && !finish_op && current_oap->prev_opcount == 0 && current_oap->prev_count0 == 0 && current_oap->op_type == OP_NOP && current_oap->regname == NUL);
}

    static int
is_safe_now(void)
{
    return stuff_empty()
        && typebuf.tb_len == 0
        && scriptin[curscript] == NULL
        && !global_busy;
}

    static void
may_trigger_safestate(int safe)
{
    int is_safe = safe && is_safe_now();

    if (is_safe)
    {
    }
}

    static int
work_pending(void)
{
    return op_pending() || !is_safe_now();
}

    static void
may_trigger_deferred_events(void)
{
    static bool recursive = false;

    if (recursive)
    {
        return;
    }
    recursive = true;

    update_topline();
    validate_cursor();

    if (!finish_op)
    {
    }

    recursive = false;
}

    static void
main_loop(int         cmdwin, int         noexmode)
{
    oparg_T     oa;
    oparg_T     *prev_oap;
    volatile int previous_got_int = FALSE;

    prev_oap = current_oap;
    current_oap = &oa;

    clear_oparg(&oa);
    while (!cmdwin)
    {
        if (stuff_empty())
        {
            if (need_wait_return)
            {
                wait_return(FALSE);
            }
            if (need_start_insertmode && goto_im() && !VIsual_active)
            {
                need_start_insertmode = FALSE;
                stuffReadbuff((char_u *)"i");
                need_fileinfo = FALSE;
            }
        }

        if (got_int)
        {
            if (noexmode && global_busy && !exmode_active && previous_got_int)
            {
                exmode_active = EXMODE_NORMAL;
                State = MODE_NORMAL;
            }
            else if (!global_busy || !exmode_active)
            {
                if (!quit_more)
                {
                    (void)vgetc();
                }
                got_int = FALSE;
            }
            previous_got_int = TRUE;
        }
        else
        {
            previous_got_int = FALSE;
        }

        if (!exmode_active)
        {
            msg_scroll = FALSE;
        }
        quit_more = FALSE;

        if (skip_redraw || exmode_active)
        {
            skip_redraw = FALSE;
            setcursor();
            cursor_on();
        }
        else if (do_redraw || stuff_empty())
        {
            may_trigger_deferred_events();

            may_trigger_safestate(!op_pending() && restart_edit == 0);

            update_topline();
            validate_cursor();

            if (VIsual_active)
            {
                update_curbuf(UPD_INVERTED);
            }
            else if (must_redraw)
            {
                  ;
                update_screen(0);
                  ;
            }
            else if (redraw_cmdline || clear_cmdline || redraw_mode)
            {
                showmode();
            }
            redraw_statuslines();
            if (keep_msg != NULL)
            {
                char_u *p = vim_strsave(keep_msg);

                if (p != NULL)
                {
                    msg_hist_off = TRUE;
                    msg_attr((char *)p, keep_msg_attr);
                    msg_hist_off = FALSE;
                    vim_free(p);
                }
            }
            if (need_fileinfo)
            {
                fileinfo(FALSE, TRUE, FALSE);
                need_fileinfo = FALSE;
            }

            emsg_on_display = FALSE;
            did_emsg = FALSE;
            msg_didany = FALSE;
            may_clear_sb_text();
            showruler(FALSE);

            setcursor();
            cursor_on();

            do_redraw = FALSE;

            may_make_initial_scroll_size_snapshot();
        }

        may_send_t_RK();

        update_curswant();

        if (exmode_active)
        {
            if (noexmode)
            {
                goto theend;
            }
            do_exmode(exmode_active == EXMODE_VIM);
        }
        else
        {
            {
                normal_cmd(&oa, TRUE);
            }
        }
    }

theend:
    current_oap = prev_oap;
}

    static void
getout(int exitval)
{
    exiting = TRUE;

    if (exmode_active)
    {
        exitval += ex_exitval;
    }

    windgoto((int)Rows - 1, 0);

    if (v_dying <= 1)
    {
        buf_T           *buf;

        if (curwin->w_buffer != NULL && buf_valid(curwin->w_buffer))
        {
            buf = curwin->w_buffer;
            if ( ((buf)->b_ct_di.di_tv.vval.v_number)  != -1)
            {
                bufref_T bufref;

                set_bufref(&bufref, buf);
                if (bufref_valid(&bufref))
                {
                     ((buf)->b_ct_di.di_tv.vval.v_number)  = -1;
                }
            }
        }

        if (curbuf->b_ml.ml_mfp != NULL)
        {
            bufref_T bufref;

            set_bufref(&bufref, curbuf);
        }

    }

    if (v_dying <= 1)
    {

    }

    if (did_emsg)
    {
        no_wait_return = FALSE;
        wait_return(FALSE);
    }

    windgoto((int)Rows - 1, 0);

    term_disable_dec();

    mch_exit(exitval);
}

    static void
command_line_scan(mparm_T *parmp)
{
    int         argc = parmp->argc;
    char        **argv = parmp->argv;
    int         argv_idx;
    int         had_minmin = FALSE;
    int         want_argument;
    int         c;
    char_u      *p = NULL;

    --argc;
    ++argv;
    argv_idx = 1;
    while (argc > 0)
    {
        if (argv[0][0] == '+' && !had_minmin)
        {
            if (parmp->n_commands >= MAX_ARG_CMDS)
            {
                mainerr(ME_EXTRA_CMD, NULL);
            }
            argv_idx = -1;
            if (argv[0][1] == NUL)
            {
                parmp->commands[parmp->n_commands++] = (char_u *)"$";
            }
            else
            {
                parmp->commands[parmp->n_commands++] = (char_u *)&(argv[0][1]);
            }
        }

        else if (argv[0][0] == '-' && !had_minmin)
        {
            want_argument = FALSE;
            c = argv[0][argv_idx++];
            switch (c)
            {
            case NUL:
                if (exmode_active)
                {
                    silent_mode = TRUE;
                }
                else
                {
                    if (parmp->edit_type != EDIT_NONE)
                    {
                        mainerr(ME_TOO_MANY_ARGS, (char_u *)argv[0]);
                    }
                    parmp->edit_type = EDIT_STDIN;
                    read_cmd_fd = 2;
                }
                argv_idx = -1;
                break;

            case '-':
                if ( strncasecmp((char *)(argv[0] + argv_idx), (char *)("ttyfail"), (7))  == 0)
                {
                    parmp->tty_fail = TRUE;
                }
                else
                {
                    if (argv[0][argv_idx])
                    {
                        mainerr(ME_UNKNOWN_OPTION, (char_u *)argv[0]);
                    }
                    had_minmin = TRUE;
                }
                argv_idx = -1;
                break;

            case 'e':
                exmode_active = EXMODE_NORMAL;
                break;

            case 'E':
                exmode_active = EXMODE_VIM;
                break;

            case 's':
                if (exmode_active)
                {
                    silent_mode = TRUE;
                }
                else
                {
                    mainerr(ME_UNKNOWN_OPTION, (char_u *)argv[0]);
                }
                break;

            case 'v':
                exmode_active = 0;
                break;

            case 'T':
                want_argument = TRUE;
                break;

            default:
                mainerr(ME_UNKNOWN_OPTION, (char_u *)argv[0]);
            }

            if (want_argument)
            {
                if (argv[0][argv_idx] != NUL)
                {
                    mainerr(ME_GARBAGE, (char_u *)argv[0]);
                }

                --argc;
                if (argc < 1)
                {
                    mainerr_arg_missing((char_u *)argv[0]);
                }
                ++argv;
                argv_idx = -1;

                switch (c)
                {
                case 'T':
                        parmp->term = (char_u *)argv[0];
                    break;

                }
            }
        }

        else
        {
            argv_idx = -1;

            if (parmp->edit_type != EDIT_NONE)
            {
                mainerr(ME_TOO_MANY_ARGS, (char_u *)argv[0]);
            }
            parmp->edit_type = EDIT_FILE;

            if ((p = vim_strsave((char_u *)argv[0])) == NULL)
            {
                mch_exit(2);
            }

            (void)buflist_add(p, BLN_CURBUF | BLN_LISTED);

        }

        if (argv_idx <= 0 || argv[0][argv_idx] == NUL)
        {
            --argc;
            ++argv;
            argv_idx = 1;
        }
    }

}

    static void
check_tty(mparm_T *parmp)
{
    int         input_isatty;

    input_isatty = mch_input_isatty();
    if (exmode_active)
    {
        if (!input_isatty)
        {
            silent_mode = TRUE;
        }
    }
    else if (parmp->want_full_screen && (!stdout_isatty || !input_isatty))
    {
        if (!stdout_isatty)
        {
             fprintf(stderr, "%s", (_("Vim: Warning: Output is not to a terminal\n"))) ;
        }
        if (!input_isatty)
        {
             fprintf(stderr, "%s", (_("Vim: Warning: Input is not from a terminal\n"))) ;
        }
        out_flush();
        if (parmp->tty_fail && (!stdout_isatty || !input_isatty))
        {
            exit(1);
        }
        if (scriptin[0] == NULL)
        {
            ui_delay(2005L, TRUE);
        }
    }
}

    static void
read_stdin(void)
{
    int     i;

    no_wait_return = TRUE;
    i = msg_didany;

    (void)open_buffer(TRUE, NULL, 0);

    no_wait_return = FALSE;
    msg_didany = i;

    close(0);
    vim_ignored = dup(2);
}

    static void
create_windows(mparm_T *parmp  __attribute__((unused)) )
{

    curbuf = curwin->w_buffer;
    if (curbuf->b_ml.ml_mfp == NULL)
    {
        (void)open_buffer(FALSE, NULL, 0);
    }
    ui_breakcheck();
    if (got_int)
    {
        (void)vgetc();
    }

    curbuf = curwin->w_buffer;
}

    static void
exe_commands(mparm_T *parmp)
{
    int         i;

    msg_scroll = TRUE;
    if (curwin->w_cursor.lnum <= 1)
    {
        curwin->w_cursor.lnum = 0;
    }
    estack_push(ETYPE_ARGS, (char_u *)"command line", 0);
    for (i = 0; i < parmp->n_commands; ++i)
    {
        do_cmdline_cmd(parmp->commands[i]);
        if (parmp->cmds_tofree[i])
        {
            vim_free(parmp->commands[i]);
        }
    }
    estack_pop();
    if (curwin->w_cursor.lnum == 0)
    {
        curwin->w_cursor.lnum = 1;
    }

    if (!exmode_active)
    {
        msg_scroll = FALSE;
    }

}

    static void
mainerr(int         n, char_u      *str)
{
    reset_signals();

    init_longVersion();
     fprintf(stderr, "%s", (longVersion)) ;
     fprintf(stderr, "%s", ("\n")) ;
     fprintf(stderr, "%s", (_(main_errors[n]))) ;
    if (str != NULL)
    {
         fprintf(stderr, "%s", (": \"")) ;
         fprintf(stderr, "%s", ((char *)str)) ;
         fprintf(stderr, "%s", ("\"")) ;
    }

    mch_exit(1);
}

    static void
mainerr_arg_missing(char_u *str)
{
    mainerr(ME_ARG_MISSING, str);
}

    int
main
(int argc, char **argv)
{

      memset((&(params)), (0), (sizeof(params)))  ;
    params.argc = argc;
    params.argv = argv;
    params.want_full_screen = TRUE;

    common_init_1();

    common_init_2(&params);

    command_line_scan(&params);

    ++RedrawingDisabled;

    mch_init();

    check_tty(&params);

    if (silent_mode)
    {
        s_vbuf = malloc(BUFSIZ);
        if (s_vbuf != NULL)
        {
            setvbuf(stdout, s_vbuf, _IOLBF, BUFSIZ);
        }
    }

    if (params.want_full_screen && !silent_mode)
    {
        termcapinit(params.term);
        screen_start();
    }

    ui_get_shellsize();
    win_init_size();

    cmdline_row = Rows - p_ch;
    cmdline_col_off = 0;
    cmdline_width = (int)Columns;
    msg_row = cmdline_row;
    msg_col = 0;
    screenalloc(FALSE);
    set_init_2();

    msg_scroll = TRUE;
    no_wait_return = TRUE;

    init_mappings();

    init_highlight(TRUE, FALSE);

    return vim_main2();
}
